import { MouseEvent, useCallback, useState } from 'react'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import { selectAIModels, selectCurrentHistory } from '../slice'
import { setAIModel } from 'src/pages/Chat/slice'

const useAIModels = () => {
  const dispatch = useBDMDispatch()
  const models = useBDMSelector(selectAIModels)
  const currentHistory = useBDMSelector(selectCurrentHistory)
  const [menuAnchorEl, setMenuAnchorEl] = useState<HTMLElement | null>(null)
  const [standaloneModel, setStandaloneModel] = useState('')
  const safeModels = Array.isArray(models) ? models : []

  const currentModel =
    currentHistory?.modelName ||
    standaloneModel ||
    safeModels.find(item => item.active)?.name ||
    'مدل پیش فرض'
  const canOpenMenu = safeModels.length > 0

  const handleMenuOpen = useCallback(
    (e: MouseEvent<HTMLElement>) => {
      if (canOpenMenu) {
        setMenuAnchorEl(e.currentTarget)
      }
    },
    [canOpenMenu, setMenuAnchorEl],
  )

  const handleMenuClose = useCallback(() => {
    setMenuAnchorEl(null)
  }, [setMenuAnchorEl])

  const menuItems = safeModels
    .filter(item => item.active)
    .map(({ active, name }) => ({
      title: name,
      active,
      action: () => {
        if (active) {
          if (currentHistory) {
            dispatch(setAIModel({ modelName: name }))
          } else {
            setStandaloneModel(name)
          }
          handleMenuClose()
        }
      },
    }))

  return {
    menuItems,
    currentHistory,
    showModelMenu: !!currentHistory,
    currentModel,
    handleMenuOpen,
    handleMenuClose,
    menuAnchorEl,
    canOpenMenu,
  }
}

export default useAIModels
