import React, { useRef } from 'react'
import { renderToStaticMarkup } from 'react-dom/server'
import './style.scss'
import Icons from './Icons'

type Props = {
    selectedColor: string
    selectedIcon: string
    isOpen: boolean
    onChange: (data: { color: string; icon: string }) => void
    setChosenSvg: React.Dispatch<React.SetStateAction<JSX.Element | null>>
}

const COLORS = [
    '#EF4444',
    '#F59E0B',
    '#10B981',
    '#6EE7B7',
    '#1F2937',
    '#3B82F6',
    '#F43F5E',
    '#C084FC',
    '#8B5CF6',
    '#1D4ED8',
    '#FBBF24',
    '#6B7280',
]


const CollectionAppearancePicker = ({
    selectedColor,
    selectedIcon,
    onChange,
    isOpen,
    setChosenSvg
}: Props) => {
  const ref = useRef<HTMLDivElement>(null)
    // const [chosenSvg, setChosenSvg] = useState<JSX.Element | null>(null);

    const handleIconSelect = (id: number) => {
        console.log('User chose:', id);
    };
    const handleSvg = (svg: JSX.Element) => {
        const coloredSvg = React.cloneElement(svg, {
            fill: selectedColor,
            style: { color: selectedColor, ...svg.props.style },
        });
        const icon = `data:image/svg+xml;utf8,${encodeURIComponent(renderToStaticMarkup(coloredSvg))}`

        setChosenSvg(coloredSvg);
    onChange({ color: selectedColor, icon });
  };

  const handleColorSelect = async (color: string) => {
    try {
      const response = await fetch(selectedIcon)
      if (!response.ok) throw new Error('Unable to load project icon')

      const coloredIcon = (await response.text())
        .replace(/fill=(["'])([^"']*)\1/g, (_match, quote, value) =>
          value === 'none' ? `fill=${quote}${value}${quote}` : `fill=${quote}${color}${quote}`,
        )
        .replace(/stroke=(["'])([^"']*)\1/g, (_match, quote, value) =>
          value === 'none' ? `stroke=${quote}${value}${quote}` : `stroke=${quote}${color}${quote}`,
        )
      const icon = `data:image/svg+xml;utf8,${encodeURIComponent(coloredIcon)}`

      setChosenSvg(<img src={icon} alt='' aria-hidden='true' />)
      onChange({ color, icon })
    } catch {
      // Keep the current icon if it cannot be converted to an inline SVG.
      onChange({ color, icon: selectedIcon })
    }
  }

  return (
        <div className='appearance-picker' ref={ref}>
            {isOpen && (
                <div className='appearance-picker__popover'>
                    <div className='appearance-picker__colors'>
                        {COLORS.map((color) => (
                            <button
                                key={color}
                                type='button'
                                className={`color-item 
                                    }`}
                                style={{ backgroundColor: color }}
                                onClick={() => handleColorSelect(color)}
                            />
                        ))}
                    </div>

                    <div className='appearance-picker__icons'>
                        <Icons onSelect={handleIconSelect} onSvgSelect={handleSvg} selectedColor={selectedColor} />
                    </div>
                </div>
            )}
        </div>
    )
}

export default CollectionAppearancePicker
