import { t } from 'i18next'
import { useCallback, useMemo } from 'react'
import { useBDMSelector } from 'src/lib/store/hooks'
import { selectDriveFiles } from 'src/lib/slice/fileManagement/fileSlice'
import { IFileItem } from 'src/types/FileManagement'

import Accordion from '../Accordion'
import FileCard from '../FileCard'

interface IProps {
  search?: string
}

const Files = ({ search = '' }: IProps) => {
  const files = useBDMSelector(selectDriveFiles)

  const filteredFiles = useMemo(() => {
    const searchValue = search.trim().toLowerCase()

    if (!searchValue) {
      return files
    }

    return files.filter(file => file.name.toLowerCase().includes(searchValue))
  }, [files, search])

  const renderItem = useCallback((item: IFileItem) => <FileCard file={item} />, [])

  return (
    <Accordion
      items={filteredFiles}
      title={t('file-manager-files-accordion-title')}
      renderItem={renderItem}
    />
  )
}

export default Files
