import './style.scss'

import { useEffect, useId, useRef, useState } from 'react'
import ReactDOM from 'react-dom'

export interface IDeleteConfirmDialogProps {
  isOpen: boolean
  kind: 'chat' | 'project'
  itemName: string
  /** Short facts about what will be lost, e.g. ['۵ گفتگو', '۳ فایل'] */
  stats?: string[]
  onConfirm: () => Promise<unknown> | unknown
  onClose: () => void
}

const COPY = {
  chat: {
    title: 'حذف گفتگو',
    subtitle: 'این گفتگو برای همیشه حذف می‌شود.',
    consequences: ['تمام پیام‌ها و پاسخ‌های این گفتگو پاک می‌شوند.', 'این کار قابل بازگشت نیست.'],
    confirm: 'حذف گفتگو',
  },
  project: {
    title: 'حذف پروژه',
    subtitle: 'با حذف پروژه، همه‌ی محتوای آن هم از بین می‌رود.',
    consequences: [
      'همه‌ی گفتگوهای داخل پروژه پاک می‌شوند.',
      'فایل‌های بارگذاری‌شده‌ی پروژه حذف می‌شوند.',
      'این کار قابل بازگشت نیست.',
    ],
    confirm: 'حذف پروژه',
  },
} as const

const normalize = (value: string) => value.trim().replace(/\s+/g, ' ')

const DeleteConfirmDialog = ({
  isOpen,
  kind,
  itemName,
  stats = [],
  onConfirm,
  onClose,
}: IDeleteConfirmDialogProps) => {
  const copy = COPY[kind]
  const titleId = useId()
  const [typedName, setTypedName] = useState('')
  const [isDeleting, setIsDeleting] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)
  const cancelRef = useRef<HTMLButtonElement>(null)
  const dialogRef = useRef<HTMLDivElement>(null)

  // Deleting a project is destructive enough to require typing its name.
  const requiresTyping = kind === 'project'
  const isNameMatched = !requiresTyping || normalize(typedName) === normalize(itemName)
  const canConfirm = isNameMatched && !isDeleting

  useEffect(() => {
    if (!isOpen) {
      return
    }

    setTypedName('')
    setIsDeleting(false)
    // Focus the safe option first so an accidental Enter never deletes.
    requestAnimationFrame(() => (requiresTyping ? inputRef : cancelRef).current?.focus())
  }, [isOpen, requiresTyping])

  const handleClose = () => {
    if (!isDeleting) {
      onClose()
    }
  }

  const handleConfirm = async () => {
    if (!canConfirm) {
      return
    }

    setIsDeleting(true)
    try {
      await onConfirm()
      onClose()
    } catch {
      // The delete thunk already toasted the error; keep the dialog open to retry.
      setIsDeleting(false)
    }
  }

  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'Escape') {
      event.stopPropagation()
      handleClose()
      return
    }

    if (event.key === 'Tab' && dialogRef.current) {
      const focusable = Array.from(
        dialogRef.current.querySelectorAll<HTMLElement>('input, button:not(:disabled)'),
      )
      const first = focusable[0]
      const last = focusable[focusable.length - 1]

      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault()
        last?.focus()
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault()
        first?.focus()
      }
    }
  }

  if (!isOpen) {
    return null
  }

  return ReactDOM.createPortal(
    <div className='delete-confirm' onMouseDown={handleClose} onKeyDown={handleKeyDown}>
      <div
        ref={dialogRef}
        className='delete-confirm__dialog'
        role='alertdialog'
        aria-modal='true'
        aria-labelledby={titleId}
        aria-busy={isDeleting}
        dir='rtl'
        onMouseDown={event => event.stopPropagation()}
      >
        <div className='delete-confirm__icon' aria-hidden='true'>
          <svg viewBox='0 0 24 24' width='28' height='28' fill='none' stroke='currentColor' strokeWidth='1.8' strokeLinecap='round' strokeLinejoin='round'>
            <path d='M3 6h18' />
            <path d='M8 6V4h8v2' />
            <path d='M19 6l-1 14H6L5 6' />
            <path d='M10 11v5M14 11v5' />
          </svg>
        </div>

        <h2 id={titleId} className='delete-confirm__title'>
          {copy.title}
        </h2>
        <p className='delete-confirm__subtitle'>{copy.subtitle}</p>

        <div className='delete-confirm__item'>
          <span className='delete-confirm__item-name' dir='auto' title={itemName}>
            {itemName}
          </span>
          {stats.length > 0 && (
            <div className='delete-confirm__stats'>
              {stats.map(stat => (
                <span key={stat} className='delete-confirm__stat'>
                  {stat}
                </span>
              ))}
            </div>
          )}
        </div>

        <ul className='delete-confirm__list'>
          {copy.consequences.map(line => (
            <li key={line}>{line}</li>
          ))}
        </ul>

        {requiresTyping && (
          <label className='delete-confirm__type'>
            <span>
              برای تأیید، نام پروژه را دقیقاً وارد کنید: <strong dir='auto'>{itemName}</strong>
            </span>
            <input
              ref={inputRef}
              value={typedName}
              onChange={event => setTypedName(event.target.value)}
              onKeyDown={event => {
                if (event.key === 'Enter') {
                  event.preventDefault()
                  handleConfirm()
                }
              }}
              disabled={isDeleting}
              dir='auto'
              autoComplete='off'
              spellCheck={false}
              className={`delete-confirm__input ${
                isNameMatched ? 'delete-confirm__input--matched' : ''
              }`}
            />
          </label>
        )}

        <div className='delete-confirm__actions'>
          <button
            type='button'
            className='delete-confirm__btn delete-confirm__btn--danger'
            onClick={handleConfirm}
            disabled={!canConfirm}
          >
            {isDeleting ? <span className='delete-confirm__spinner' aria-hidden='true' /> : null}
            {isDeleting ? 'در حال حذف…' : copy.confirm}
          </button>
          <button
            ref={cancelRef}
            type='button'
            className='delete-confirm__btn delete-confirm__btn--cancel'
            onClick={handleClose}
            disabled={isDeleting}
          >
            انصراف
          </button>
        </div>
      </div>
    </div>,
    (document.getElementById('portal') as HTMLElement | null) ?? document.body,
  )
}

export default DeleteConfirmDialog
