import type { CHAT_SELECTION_MODE } from 'src/types/NewChat'

export const createChatSubmitGuard = () => {
  let locked = false

  return {
    lock: () => {
      if (locked) {
        return false
      }
      locked = true
      return true
    },
    unlock: () => {
      locked = false
    },
  }
}

export const pendingFilesAfterSubmit = (files: File[], succeeded: boolean) =>
  succeeded ? [] : files

export const getMessageTextFields = (message: string, text = message) => {
  const manualText = text.trim()

  return {
    message: message.trim() || manualText,
    text,
  }
}

type AttachmentWithId = {
  _id?: string
  fileId?: string
}

type MessageWithAttachments = {
  attachments?: AttachmentWithId[]
}

/**
 * General chats are not backed by a collection, so every request must keep
 * referencing the files already uploaded to that history.  Prefer the
 * history-level file list (it survives message pagination) and supplement it
 * with attachments from the loaded messages for newly-created histories.
 */
export const getGeneralChatFileIds = (
  historyFiles: AttachmentWithId[] = [],
  messages: MessageWithAttachments[] = [],
) => {
  const ids = [
    ...historyFiles,
    ...messages.flatMap(message => message.attachments ?? []),
  ]
    .map(file => file.fileId || file._id)
    .filter(
      (fileId): fileId is string =>
        Boolean(fileId) && !(fileId ?? '').startsWith('pending-'),
    )

  return Array.from(new Set(ids))
}

export const getRequestFileIds = ({
  selectionMode,
  persistentGeneralFileIds,
  currentAttachmentIds,
  selectedSourceFileId,
}: {
  selectionMode: CHAT_SELECTION_MODE
  persistentGeneralFileIds: string[]
  currentAttachmentIds: Array<string | undefined>
  selectedSourceFileId?: string | null
}) => {
  const fileIds = [
    ...(selectionMode === 'rag' ? persistentGeneralFileIds : []),
    ...currentAttachmentIds,
    ...(selectedSourceFileId ? [selectedSourceFileId] : []),
  ].filter((fileId): fileId is string => Boolean(fileId))

  return Array.from(new Set(fileIds))
}
