export enum FILTER_FORMULA {
  G = '>',
  GE = '>=',
  E = '=',
  L = '<',
  LE = '<=',
}

export enum DATE_FORMULA {
  G = '>',
  GE = '>=',
  E = '=',
  L = '<',
  LE = '<=',
  R = 'dateRange',
  TIMEBEFORE = 'timeBefore', //  ex a second/minute/hour/day/week/year ago ...
}

export enum GIS_FILTER_FORMULA {
  WITHIN = 'within',
  INTERSECT = 'intersect',
  CONTAINS = 'contains',
  KNN = 'knn',
}

export enum IMAGE_FILTER_FORMULA {
  IMAGE_INCLUDES = 'imageIncludes',
}

export enum STRING_FILTER_FORMULA {
  SW = 'startsWith',
  EW = 'endsWith',
  E = 'equal',
  C = 'contains',
  R = 'regex',
  iSW = 'istartWith',
  iEW = 'iendsWith',
  iE = 'iequal',
  iC = 'icontains',
  iR = 'iregex',
}

export enum LICENSEPLATE_FILTER_FORMULA {
  E = 'plateequal',
}

export enum FILTER_TYPE_SELECTION {
  NORMAL = 1, // normal filter
  GIS = 2, // GIS filter
  IMAGE = 3, // Image fitler
}

export enum META_TYPES {
  INTEGER = 'Integer',
  DOUBLE = 'Double',
  DECIMAL18 = 'Decimal18',
  LONG = 'Long',
  FLOAT = 'Float',
  STRING = 'String',
  BOOLEAN = 'Boolean',
  POINT = 'Point',
  IMAGE = 'Image',
  DATE_TIME = 'Date',
  TIMESTAMP = 'Timestamp',
  EMBEDDING = 'embedding',
  LICENSEPLATE = 'LicensePlate',
  LINESTRING = 'LineString',
  POLYGON = 'Polygon',
  GEOMETRY = 'Geometry',
  BUFFER = 'Buffer',
  ARRAY_STRING = 'Array[String]',
}

/**
 * Cumulative Filter
 */
export type CUMULATIVE_FILTER_FORMULA = FILTER_FORMULA

export type CUMULATIVE_DATE_FORMULA = Exclude<
  DATE_FORMULA,
  DATE_FORMULA.R | DATE_FORMULA.TIMEBEFORE
>

// export type CUMULATIVE_STRING_FILTER_FORMULA = Pick<STRING_FILTER_FORMULA, STRING_FILTER_FORMULA.E>
export type CUMULATIVE_STRING_FILTER_FORMULA = STRING_FILTER_FORMULA.E

export type TCcumulativeConditionObject = {
  id: number
  Type: FILTER_TYPE.CCUMULATIVE_CONDITION
  BinaryFile: string
  FileId?: string
  Path: string | null
  FileDelivered?: boolean
  LeftSourceId?: number
  RightSourceId?: number
  LeftSourceName?: string
  RightSourceName?: string
  FileName?: string
  Conditions: Array<{
    LeftField: string
    RightField: string
    Operator: CUMULATIVE_FILTER_FORMULA | CUMULATIVE_DATE_FORMULA | CUMULATIVE_STRING_FILTER_FORMULA
  }>
  IsNot: boolean
  Formula: string
  FilterTypeSelection: FILTER_TYPE_SELECTION
  FileDataTypes: { [key: string]: META_TYPES }
  OrderdList: Array<{ field: string; order: number }>
  // FieldOrder: { [key: string]: number }
}

export type TConditionObject = {
  id: number
  Type: FILTER_TYPE.CONDITION
  NodeId?: number // or edge id!!! must use a better name
  FieldName?: string
  Value?: string
  IsNot: boolean
  FilterTypeSelection: FILTER_TYPE_SELECTION
  Formula:
  | FILTER_FORMULA
  | GIS_FILTER_FORMULA
  | STRING_FILTER_FORMULA
  | IMAGE_FILTER_FORMULA
  | DATE_FORMULA
  | LICENSEPLATE_FILTER_FORMULA
  Path?: string // when Image =>  on response path to file (server side)
  BinaryFile?: string //  when Image =>  Binary Image on client side
  Results?: Array<string> //  when Image =>  List of found Ids from server
  Threshold?: number // AI model threshold (0-1)
  Sensitivity?: number // AI model Sensitivity degree (0-1)
  ImageFile?: File // When Image, stores image temporarily (removed from condition before sending to server)
  FileName?: string // Image file name, since only binary data is sent to server, file name is requested bu server to detect file extention
  // plate?: IBDMLicensePlateType
}

export type TStatementObject = {
  id: number
  Type: FILTER_TYPE.STATEMENT
  Logic: FILTER_LOGIC
  IsNot: boolean
  Children: Array<TStatementObject | TConditionObject | TCcumulativeConditionObject>
}
export type TFilter = TStatementObject | TConditionObject | TCcumulativeConditionObject

export type IFilterCardStatus = 'RUNNING' | 'SUCCESS' | 'ERROR' | 'PENDING'

