import { useState, MouseEvent } from 'react';
import instructionIcon from 'src/assets/instructionIcon.svg';
import instructionIconHover from 'src/assets/instructionIconHover.svg';
import instructionIconSelected from 'src/assets/instructionIconSelected.svg';
import instructionIconWhite from 'src/assets/instructionIconWhite.svg';
import instructionIconHoverWhite from 'src/assets/instructionIconHoverWhite.svg';
import instructionIconSelectedWhite from 'src/assets/instructionIconSelectedWhite.svg';
import './style.scss'
import { useBDMSelector } from 'src/lib/store/hooks';
import { RootState } from 'src/lib/store';

interface Props {
    onToggle?: (active: boolean) => void;
    openInstruction: boolean
}

export const InstructionButton = ({ onToggle, openInstruction }: Props) => {
    const [hover, setHover] = useState(false);

    const handleClick = (e: MouseEvent<HTMLButtonElement>) => {
        e.stopPropagation();
        const next = !openInstruction;
        onToggle?.(next);
    };
    const mode = useBDMSelector((state: RootState) => state.theme.mode)
    return (
        <button
            type="button"
            className={`instruction-btn ${openInstruction ? 'active' : ''}`}
            onClick={handleClick}
            onMouseEnter={() => setHover(true)}
            onMouseLeave={() => setHover(false)}
            aria-pressed={openInstruction}
            aria-label={openInstruction ? 'Hide instructions' : 'Show instructions'}
        >
            <img
                src={
                    openInstruction
                        ? (mode === 'light' ? instructionIconSelected : instructionIconSelectedWhite)
                        : hover
                            ? (mode === 'light' ? instructionIconHover : instructionIconHoverWhite)
                            : (mode === 'light' ? instructionIcon : instructionIconWhite)
                }
                alt="Instruction"
            />
        </button>
    );
};