import { useEffect, useState, PropsWithChildren, useCallback } from 'react'
import { BDM_CONTEXT_ACTIONS } from 'src/lib/context/reducers'
import { useBDMContextDispatch } from 'src/lib/context'
import userAPIs from 'src/api/user'
import { logout, getToken } from 'src/lib/utils'

const AppInitializer = ({ children }: PropsWithChildren) => {
  const dispatch = useBDMContextDispatch()
  const [loading, setLoading] = useState<boolean>(true)

  const handleToken = useCallback(async () => {
    const token = getToken()
    if (!token) {
      return logout()
    }
    const { access_token, refresh_token } = token
    dispatch({ type: BDM_CONTEXT_ACTIONS.SET_ACCESS_TOKEN, payload: access_token })
    dispatch({ type: BDM_CONTEXT_ACTIONS.SET_REFRESH_TOKEN, payload: refresh_token })
  }, [dispatch])

  const handleUserInfo = useCallback(async () => {
    try {
      const res = await userAPIs.getProfile()
      if (!res?.data?.success) {
        if (res?.data?.status === 401) {
          logout()
        }
        return
      }
      dispatch({
        type: BDM_CONTEXT_ACTIONS.SET_USER,
        payload: res.data.profile,
      })

    } catch (error: any) {
      const status = error?.response?.status
      if (status === 401) {
        logout()
        return
      }
      // The shared API layer displays the backend response message.
    }
  }, [userAPIs, logout, dispatch])

  const initializer = useCallback(async () => {
    setLoading(true)
    await handleToken()
    await handleUserInfo()
    setLoading(false)
  }, [handleToken, handleUserInfo])

  useEffect(() => {
    initializer()
  }, [])

  return loading ? null : <>{children}</>
}

export default AppInitializer
