import { createSlice } from '@reduxjs/toolkit'
import {
  FileSystemItem,
  IFileItem,
  IFolderItem,
  FileAction,
  FileSource,
  IBreadcrumb,
  ISelectedFile,
  IUploadItem,
} from 'src/types/FileManagement'

import reducers from './reducers'
import extraReducers from './extraReducers'
import { RootState } from 'src/lib/store'

export interface IFileState {
  drive: FileSystemItem[]
  files: IFileItem[]
  folders: IFolderItem[]
  breadcrumb: IBreadcrumb[] // null for root,can also be used to find current location
  uploads: IUploadItem[]
  source: FileSource | null // where modal is opened
  fileTypes: string[]
  action: FileAction | null
  isOpen: boolean
  allowMultipleSelection: boolean
  selectedFiles: ISelectedFile[]
  selectedFolder: string | null
  loading: { driveFiles: boolean; submit: boolean }
  submittable: boolean
}

export const initialState: IFileState = {
  drive: [],
  files: [],
  folders: [],
  breadcrumb: [],
  uploads: [],
  fileTypes: [],
  selectedFiles: [],
  allowMultipleSelection: false,
  isOpen: false,
  source: null,
  action: null,
  selectedFolder: null,
  loading: { driveFiles: false, submit: false },
  submittable: false,
}

export const fileSlice = createSlice({
  name: 'file',
  initialState,
  reducers,
  extraReducers,
})

export const {
  openDrive,
  closeDrive,
  resetStore,
  removeFiles,
  selectFile,
  selectFolder,
  setSubmittable,
  setDriveCrumbs,
  addUpload,
  setUploadStatus,
  updateUploadProgress,
} = fileSlice.actions

export const selectDrive = (state: RootState) => state.file.drive
export const selectDriveFiles = (state: RootState) => state.file.files
export const selectDriveFolders = (state: RootState) => state.file.folders
export const selectDriveAction = (state: RootState) => state.file.action
export const selectDriveSelectedFolder = (state: RootState) => state.file.selectedFolder
export const selectDriveSelectedFiles = (state: RootState) => state.file.selectedFiles
export const selectDriveBreadcrumb = (state: RootState) => state.file.breadcrumb
export const selectDriveIsOpen = (state: RootState) => state.file.isOpen
export const selectDriveIsLoading = (state: RootState) => state.file.loading
export const selectDriveIsSubmittable = (state: RootState) => state.file.submittable
export const selectDriveUploads = (state: RootState) => state.file.uploads
// mutiple
// fileType

export default fileSlice.reducer
