import { toast } from 'react-toastify'
import { t } from 'i18next'
import HotToastMessage, { type THotToastVariant } from './HotToastMessage'

type TToastType = 'error' | 'info' | 'success' | 'warning' | 'default' | 'destructive'

const toastMetaByType: Record<TToastType, { titleKey: string; variant: THotToastVariant }> = {
  default: { titleKey: 'toast-info', variant: 'default' },
  info: { titleKey: 'toast-info', variant: 'default' },
  error: { titleKey: 'toast-error', variant: 'error' },
  destructive: { titleKey: 'toast-error', variant: 'destructive' },
  warning: { titleKey: 'toast-warning', variant: 'warning' },
  success: { titleKey: 'toast-success', variant: 'success' },
}

const showHotToast = (
  message: string,
  type: TToastType = 'default',
  options?: { duration?: number; toastId?: string },
) => {
  const meta = toastMetaByType[type]
  const toastId = options?.toastId ?? `${type}:${message}`

  if (toast.isActive(toastId)) {
    return toastId
  }

  return toast(
    toastParams => (
      <HotToastMessage
        id={toastParams.toastProps.toastId}
        message={message}
        onClose={toastParams.closeToast}
        variant={meta.variant}
        title={t<string>(meta.titleKey)}
      />
    ),
    {
      toastId,
      autoClose: options?.duration ?? 5000,
      closeButton: false,
    },
  )
}

const showAllToastStatesForTest = () => {
  showHotToast('You can add components to your app using the cli.', 'default')
  showHotToast('Your session has expired. Please log in again.', 'destructive')
  showHotToast('You can add components to your app using the cli.', 'warning')
  showHotToast('تاریخچه با موفقیت حذف شد.', 'success')
}

export type { TToastType }
export { showHotToast, showAllToastStatesForTest }
