import { useCallback, useEffect, useRef, useState } from 'react'
import chatAvatarIcon from 'src/assets/chatAvatarIcon.svg'
import sortArrowsIcon from 'src/assets/sortArrowsIcon.svg'
import sortArrowsIconWhite from 'src/assets/sortArrowsIconWhite.svg'
import settingIcon from 'src/assets/settingIcon.svg'
import settingIconWhite from 'src/assets/settingIconWhite.svg'
import helpIcon from 'src/assets/helpIcon.svg'
import helpIconWhite from 'src/assets/helpIconWhite.svg'
import moonIcon from 'src/assets/moonIcon.svg'
import moonIconWhite from 'src/assets/moonIconWhite.svg'
import logoutIcon from 'src/assets/logoutRed.svg'
import linkChart from 'src/assets/linkChart2.svg'
import DanaLogo from 'src/assets/danaLogo.svg'
import tagLogo from 'src/assets/tagLogo.svg'
import bdmLogo from 'src/assets/bdmLogo.svg'
import etlLogo from 'src/assets/etlLogo.svg'
import formMakerLogo from 'src/assets/formMakerLogo.svg'
import fimeManagementLogo from 'src/assets/fimeManagementLogo.svg'
import { logout } from 'src/lib/utils'
import './style.scss'
import { setModalsState } from 'src/pages/Chat/slice'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'

import { toggleTheme } from 'src/features/theme/themeSlice'
import { RootState } from 'src/lib/store'
import { t } from 'i18next'
import Tooltip from '@mui/material/Tooltip'
import { useBDMContext } from 'src/lib/context'
import { getModuleAccess, ModulePermission } from 'src/lib/utils/moduleAccess'

interface IProps {
  fullName: string
}

const UserMenu = ({ fullName }: IProps) => {
  const { accessToken } = useBDMContext()
  const userMenuRef = useRef<HTMLDivElement>(null)
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false)
  const [isModuleSelectOpen, setIsModuleSelectOpen] = useState(false)
  const [selectedModule, setSelectedModule] = useState({
    link: '/chat',
    title: 'chat-module-dana',
    logo: DanaLogo,
  })
  const moduleAccess = getModuleAccess(accessToken)
  const moduleItems: Array<{
    link: string
    title: string
    logo: string
    permission: ModulePermission
  }> = [
    { link: '/lc/', title: 'chat-module-link-chart', logo: linkChart, permission: 'lc' },
    {
      link: '/label/user/login/',
      title: 'chat-module-labeling',
      logo: tagLogo,
      permission: 'label',
    },
    { link: '/bdm/', title: 'chat-module-big-data', logo: bdmLogo, permission: 'bdm' },
    {
      link: '/etl/',
      title: 'chat-module-preprocessing',
      logo: etlLogo,
      permission: 'etl',
    },
    {
      link: '/dm/',
      title: 'chat-module-data-management',
      logo: fimeManagementLogo,
      permission: 'dm',
    },
    {
      link: '/fm/',
      title: 'chat-module-form-builder',
      logo: formMakerLogo,
      permission: 'fm',
    },
  ]
  const dispatch = useBDMDispatch()
  const handleOpenProfileModal = useCallback(() => {
    dispatch(setModalsState({ openProfileModal: true }))
  }, [dispatch])
  const handleOpenSettingsModal = useCallback(() => {
    dispatch(setModalsState({ openSettingsModal: true }))
  }, [dispatch])
  useEffect(() => {
    const handleOutsideClick = (e: MouseEvent) => {
      if (!userMenuRef.current?.contains(e.target as Node)) {
        setIsUserMenuOpen(false)
        setIsModuleSelectOpen(false)
      }
    }

    document.addEventListener('mousedown', handleOutsideClick)
    return () => document.removeEventListener('mousedown', handleOutsideClick)
  }, [])

  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const isLargeFont = localStorage.getItem('chat-font-size') === 'large'
  return (
    <div className='chat-chatbox-sidebar__user-wrap' ref={userMenuRef}>
      {isUserMenuOpen && (
        <div className='chat-chatbox-sidebar__user-menu'>
          <div className='chat-chatbox-sidebar__user-menu-header' onClick={handleOpenProfileModal}>
            <img src={chatAvatarIcon} className='chat-chatbox-sidebar__user-avatar' />
            <span className='chat-chatbox-sidebar__user-menu-name'>
              {fullName || t('chat-user-default-name')}
            </span>
          </div>
          <div className='chat-chatbox-sidebar__user-menu-items'>
            <div className='chat-chatbox-sidebar__module-select'>
              <button
                className='chat-chatbox-sidebar__user-menu-select-items'
                type='button'
                onClick={() => setIsModuleSelectOpen(prev => !prev)}
              >
                <div className='chat-chatbox-sidebar__user-menu-title-icon'>
                  <div className='chat-chatbox-sidebar__module-select-option-img'>
                    <img src={selectedModule.logo} />
                  </div>
                  <Tooltip
                    title={isLargeFont ? t(selectedModule.title) : ''}
                    placement='top'
                    disableInteractive
                  >
                    <span className='chat-chatbox-sidebar__select-value'>
                      {t(selectedModule.title)}
                    </span>
                  </Tooltip>
                </div>
                <span
                  className={`chat-chatbox-sidebar__select-arrow ${
                    isModuleSelectOpen ? 'is-open' : ''
                  }`}
                />
              </button>

              {/* {isModuleSelectOpen && ( */}
              <div
                className={`chat-chatbox-sidebar__module-select-dropdown ${
                  isModuleSelectOpen ? 'is-open' : ''
                }`.trim()}
              >
                <p className='chat-chatbox-sidebar__module-select-title'>
                  {t('chat-modules-title')}
                </p>
                {moduleItems.map(item => {
                  const hasAccess = moduleAccess[item.permission]
                  return (
                    <button
                      key={item.title}
                      className={`chat-chatbox-sidebar__module-select-option ${
                        hasAccess ? '' : 'is-disabled'
                      }`.trim()}
                      type='button'
                      disabled={!hasAccess}
                      onClick={() => {
                        setSelectedModule(item)
                        setIsModuleSelectOpen(false)
                        const absoluteUrl = item.link.startsWith('http')
                          ? item.link
                          : `${window.location.origin}${item.link.startsWith('/') ? '' : '/'}${
                              item.link
                            }`
                        window.location.replace(absoluteUrl)
                      }}
                    >
                      <div className='chat-chatbox-sidebar__module-select-option-img'>
                        <img src={item.logo} />
                      </div>
                      <Tooltip
                        title={isLargeFont ? t(item.title) : ''}
                        placement='top'
                        disableInteractive
                      >
                        <span className='chat-chatbox-sidebar__module-select-option-label'>
                          {t(item.title)}
                        </span>
                      </Tooltip>
                    </button>
                  )
                })}
              </div>
              {/* )} */}
            </div>
            <button
              className='chat-chatbox-sidebar__user-menu-item'
              type='button'
              onClick={handleOpenSettingsModal}
            >
              <img src={mode === 'light' ? settingIcon : settingIconWhite} />
              {t('chat-user-menu-settings')}
            </button>
            <button
              className='chat-chatbox-sidebar__user-menu-item chat-chatbox-sidebar__user-menu-item--switch'
              type='button'
              onClick={() => dispatch(toggleTheme())}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                <img src={mode === 'light' ? moonIcon : moonIconWhite} />
                {t('chat-user-menu-dark-mode')}
              </div>
              <span className={`chat-chatbox-sidebar__switch ${mode === 'dark' ? 'active' : ''}`}>
                <span className='chat-chatbox-sidebar__switch-thumb' />
              </span>
            </button>
            <button
              className='chat-chatbox-sidebar__user-menu-item'
              type='button'
              onClick={() => window.location.replace(`${window.location.origin}/document/dana`)}
            >
              <img src={mode === 'light' ? helpIcon : helpIconWhite} />
              {t('chat-user-menu-help')}
            </button>
          </div>
          <button className='chat-chatbox-sidebar__user-menu-logout' type='button' onClick={logout}>
            <img src={logoutIcon} />
            {t('chat-user-menu-logout')}
          </button>
        </div>
      )}
      <button
        className='chat-chatbox-sidebar__user'
        type='button'
        onClick={() => setIsUserMenuOpen(prev => !prev)}
      >
        <div className='chat-chatbox-sidebar__user__avatar'>
          <img src={chatAvatarIcon} className='chat-chatbox-sidebar__user-avatar' />
          <div className='chat-chatbox-sidebar__user-info'>
            <p className='chat-chatbox-sidebar__user-name'>
              {fullName || t('chat-user-default-name')}
            </p>
          </div>
        </div>
        <img src={mode === 'light' ? sortArrowsIcon : sortArrowsIconWhite} />
      </button>
    </div>
  )
}

export default UserMenu
