import './style.scss'
import { t } from 'i18next'
import { useCallback, useEffect, useRef, useState } from 'react'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import {
  selectBackgroundDraftSettings,
  selectBackgroundSettings,
  selectModalsState,
  setBackgroundDraftSettings,
  setBackgroundSettings,
  setModalsState,
} from 'src/pages/Chat/slice'

import Modal from '@mui/material/Modal'
import Button from 'src/components/Button'
import closeIcon from 'src/assets/closeIcon.svg'
import closeIconWhite from 'src/assets/closeIconWhite.svg'
import colorsIcon from 'src/assets/colorsIcon.svg'
import colorsIconHover from 'src/assets/colorsIconHover.svg'
import defaultBackground from 'src/assets/defaultBackground.svg'
import dayBackground from 'src/assets/dayBackground.svg'
import nightBackground from 'src/assets/nightBackground.svg'
import monitorIcon from 'src/assets/monitorIcon.svg'
import sunMediumIcon from 'src/assets/sunMediumIcon.svg'
import moonIcon2 from 'src/assets/moonIcon2.svg'
import monitorIconSecondry from 'src/assets/monitorIconSecondry.svg'
import sunMediumIconSecondry from 'src/assets/sunMediumIconSecondry.svg'
import moonIcon2Secondry from 'src/assets/moonIcon2Secondry.svg'
import { Divider } from '@mui/material'
import ThemeCustomizer from './ThemeCustomizer'
import ConversationColors, { CONVERSATION_DRAFT_SETTINGS_KEY } from './ConversationColors'
import { RootState } from 'src/lib/store'
import { setTheme } from 'src/features/theme/themeSlice'
import { applyTheme } from 'src/shared/theme/applyTheme'
import ChatAPIs from 'src/api/chat'
import { addAToast } from 'src/lib/context'

type AppearanceMode = 'system' | 'light' | 'dark'

const APPEARANCE_OPTIONS: Array<{
  id: AppearanceMode
  title: string
  preview: string
  icon: {
    light: string
    dark: string
  }
}> = [
    {
      id: 'system',
      title: 'chat-appearance-system',
      preview: defaultBackground,
      icon: { light: monitorIcon, dark: monitorIconSecondry },
    },
    {
      id: 'light',
      title: 'chat-appearance-light',
      preview: dayBackground,
      icon: { light: sunMediumIcon, dark: sunMediumIconSecondry },
    },
    {
      id: 'dark',
      title: 'chat-appearance-dark',
      preview: nightBackground,
      icon: { light: moonIcon2, dark: moonIcon2Secondry },
    },
  ]

const BackgroundModal = () => {
  const dispatch = useBDMDispatch()
  const isOpen = useBDMSelector(selectModalsState).openBackgroundModal
  const backgroundSettings = useBDMSelector(selectBackgroundSettings)
  const backgroundDraftSettings = useBDMSelector(selectBackgroundDraftSettings)
  const contentRef = useRef<HTMLFormElement>(null)
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const [selectedAppearanceMode, setSelectedAppearanceMode] = useState<AppearanceMode>(mode)
  const handleClose = useCallback(() => {
    dispatch(setModalsState({ openBackgroundModal: false }))
  }, [dispatch, setModalsState])

  const handleSubmit = useCallback(async () => {
    try {
      const conversationDraft = localStorage.getItem(CONVERSATION_DRAFT_SETTINGS_KEY)
      const conversationSettings = conversationDraft ? JSON.parse(conversationDraft) : null
      const nextBackgroundSettings = {
        ...backgroundDraftSettings,
        userMessageBackgroundColor:
          conversationSettings?.backgroundColor ?? backgroundDraftSettings.userMessageBackgroundColor,
        userMessageTextColor:
          conversationSettings?.textColor ?? backgroundDraftSettings.userMessageTextColor,
      }
      const nextBackgroundData = {
        enabled: nextBackgroundSettings.enabled,
        fit: nextBackgroundSettings.fit,
        overlay: nextBackgroundSettings.overlay,
        blur: nextBackgroundSettings.blur,
        applyToAll: nextBackgroundSettings.applyToAll,
        userMessageBackgroundColor: nextBackgroundSettings.userMessageBackgroundColor,
        userMessageTextColor: nextBackgroundSettings.userMessageTextColor,
      }
      const response = await ChatAPIs().updateBackground(nextBackgroundData)
      if (!response.data?.success) {
        throw new Error(response.data?.message || 'ذخیره تصویر پس‌زمینه ناموفق بود')
      }

      dispatch(setBackgroundSettings(nextBackgroundSettings))
      if (conversationDraft) {
        localStorage.setItem('chat-conversation-settings', conversationDraft)
        window.dispatchEvent(new Event('chat-conversation-change'))
      }
      handleClose()
    } catch (error) {
      addAToast(
        error instanceof Error ? error.message : 'ذخیره تصویر پس‌زمینه ناموفق بود',
        'error',
      )
    }
  }, [backgroundDraftSettings, dispatch, handleClose])

  const handleAppearanceChange = (appearanceMode: AppearanceMode) => {
    setSelectedAppearanceMode(appearanceMode)
    const nextMode =
      appearanceMode === 'system'
        ? window.matchMedia('(prefers-color-scheme: dark)').matches
          ? 'dark'
          : 'light'
        : appearanceMode

    dispatch(setTheme(nextMode))
    applyTheme(nextMode)
  }

  useEffect(() => {
    if (isOpen) {
      setSelectedAppearanceMode(mode)
      dispatch(setBackgroundDraftSettings(backgroundSettings))
      contentRef.current?.focus()
    }
  }, [backgroundSettings, dispatch, isOpen, mode])
  return (
    <Modal
      open={isOpen}
      onClose={handleClose}
      className='background-modal'
      BackdropProps={{
        sx: {
          backdropFilter: 'blur(5px)',
          backgroundColor: '#09090B4D',
        },
      }}
    >
      <form className='background-modal__content' ref={contentRef} tabIndex={-1}>
        <div className='background-modal__header'>
          <div className='background-modal__title'>
            <img src={mode === 'light' ? colorsIcon : colorsIconHover} />
            <p className='background-modal__title-p'>{t('chat-sidebar-background-title')}</p>
          </div>
          <button
            type='button'
            className='background-modal__close'
            onClick={handleClose}
            aria-label={t('close')}
          >
            <img src={mode === 'light' ? closeIcon : closeIconWhite} alt='close' />
          </button>
        </div>
        <Divider className='divider-modals' sx={{ marginBottom: '16px' }} />

        {/* body */}
        <div className='background-modal__body'>
          <div className='wrapper-inputs'>
            {/* font size */}
            <div className='background-item'>
              <div>
                <div className='background-item__text'>
                  <p className='title'>{t('chat-appearance-title')}</p>
                  <p className='desc'>{t('chat-appearance-description')}</p>
                </div>
                <div className='background-item__images'>
                  {APPEARANCE_OPTIONS.map(option => (
                    <div
                      key={option.id}
                      className={`background-item__image-card ${selectedAppearanceMode === option.id ? 'is-active' : ''
                        }`}
                      onClick={() => handleAppearanceChange(option.id)}
                    >
                      <img className='img-default' src={option.preview} />
                      <span className='footer-img'>
                        <img src={mode === 'light' ? option.icon.light : option.icon.dark} />
                        {t(option.title)}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <Divider className='divider-modals' />
            <ThemeCustomizer />
            <Divider className='divider-modals' />
            <ConversationColors />
          </div>
        </div>
        {/* actions */}
        <div className='background-modal__btns'>
          <Button
            title={t('chat-background-modal-btn-cancel')}
            onClick={handleClose}
            className='background-modal__btns__cancel'
            type='button'
            tabIndex={1}
          />
          <Button
            title={t('chat-background-modal-btn-confirm')}
            onClick={handleSubmit}
            className='background-modal__btns__confirm'
            type='button'
            tabIndex={1}
          />
        </div>
      </form>
    </Modal>
  )
}

export default BackgroundModal
