import React, { useContext, useMemo, useRef, useState } from 'react';
import './style.scss';
import Markdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import rehypeRaw from 'rehype-raw';

const TableContext = React.createContext(false);
// react-markdown v9 no longer passes `inline` to `code`; block code is the only kind wrapped in <pre>.
const PreContext = React.createContext(false);

const ARABIC_CHAR_REGEX =
    /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/g;
const LATIN_CHAR_REGEX = /[A-Za-z]/g;

const normalizeLatexArrows = (value: string) => {
    const replacements: Array<[RegExp, string]> = [
        [/(?:\\?\$)?\\Leftrightarrow(?:\\?\$)?/g, '⇔'],
        [/(?:\\?\$)?\\Rightarrow(?:\\?\$)?/g, '⇒'],
        [/(?:\\?\$)?\\Leftarrow(?:\\?\$)?/g, '⇐'],
        [/(?:\\?\$)?\\leftrightarrow(?:\\?\$)?/g, '↔'],
        [/(?:\\?\$)?\\rightarrow(?:\\?\$)?/g, '→'],
        [/(?:\\?\$)?\\leftarrow(?:\\?\$)?/g, '←'],
        [/(?:\\?\$)?\\longrightarrow(?:\\?\$)?/g, '⟶'],
        [/(?:\\?\$)?\\longleftarrow(?:\\?\$)?/g, '⟵'],
        [/(?:\\?\$)?\\to(?:\\?\$)?/g, '→'],
    ];

    // Do not change code examples; arrow commands can be meaningful inside code.
    return value.split(/(```[\s\S]*?```|`[^`]*`)/g).map(segment => {
        if (segment.startsWith('```') || segment.startsWith('`')) return segment;
        return replacements.reduce((result, [pattern, arrow]) => result.replace(pattern, arrow), segment);
    }).join('');
};

const getTextContent = (node: React.ReactNode): string => {
    if (node === null || node === undefined || typeof node === 'boolean') {
        return '';
    }
    if (typeof node === 'string' || typeof node === 'number') {
        return String(node);
    }
    if (Array.isArray(node)) {
        return node.map(getTextContent).join('');
    }
    if (React.isValidElement(node)) {
        return getTextContent(node.props.children);
    }
    return '';
};

const detectDirection = (text: string) => {
    const arabicCount = (text.match(ARABIC_CHAR_REGEX) || []).length;
    const latinCount = (text.match(LATIN_CHAR_REGEX) || []).length;
    if (arabicCount === 0 && latinCount === 0) {
        return 'rtl';
    }
    return arabicCount >= latinCount ? 'rtl' : 'ltr';
};

const extractTableText = (node: React.ReactNode): string => {
    const rows: string[] = [];

    const walk = (n: React.ReactNode) => {
        if (n === null || n === undefined || typeof n === 'boolean') {
            return;
        }
        if (Array.isArray(n)) {
            n.forEach(walk);
            return;
        }
        if (React.isValidElement(n)) {
            if (typeof n.type === 'string' && n.type === 'tr') {
                const cells: string[] = [];
                React.Children.forEach(n.props.children, child => {
                    if (
                        React.isValidElement<React.PropsWithChildren>(child) &&
                        typeof child.type === 'string' &&
                        (child.type === 'td' || child.type === 'th')
                    ) {
                        const text = getTextContent(child.props.children).trim();
                        cells.push(text);
                    }
                });
                rows.push(cells.join('\t'));
                return;
            }
            walk(n.props.children);
        }
    };

    walk(node);
    return rows.filter(row => row.length > 0).join('\n');
};

const extractTableFromElement = (table: HTMLTableElement | null): string => {
    if (!table) {
        return '';
    }
    const rows = Array.from(table.rows).map(row =>
        Array.from(row.cells)
            .map(cell => (cell.textContent || '').trim())
            .join('\t')
    );
    return rows.filter(row => row.length > 0).join('\n');
};

const copyTextToClipboard = async (text: string, onSuccess: () => void) => {
    if (!navigator.clipboard?.writeText) {
        const el = document.createElement('textarea');
        el.value = text;
        el.style.position = 'fixed';
        document.body.appendChild(el);
        el.select();
        try {
            document.execCommand('copy');
            onSuccess();
        } catch (e) {
            console.error('Fallback copy failed', e);
        }
        document.body.removeChild(el);
        return;
    }

    try {
        await navigator.clipboard.writeText(text);
        onSuccess();
    } catch (err) {
        console.error('Copy failed', err);
    }
};

/* ----------  تابع برجسته‌سازی کامنت‌ها  ---------- */
const highlightSyntax = (code = '') => {
    let html = code
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');

    const stringStore: string[] = [];
    const commentStore: string[] = [];

    const restoreStrings = (text: string, wrap: boolean) =>
        text.replace(/___STRING_(\d+)___/g, (match, index) => {
            const value = stringStore[Number(index)];
            if (!value) {
                return match;
            }
            return wrap ? `<span class="token string">${value}</span>` : value;
        });

    // 1️⃣ extract strings
    html = html.replace(/(["'`])(?:\\.|(?!\1).)*\1/g, match => {
        const key = `___STRING_${stringStore.length}___`;
        stringStore.push(match);
        return key;
    });

    // 2️⃣ comments (force comment to start on new line)
    html = html.replace(
        /(\/\/[^\n\r]*|\/\*[\s\S]*?\*\/)/g,
        match => {
            const key = `___COMMENT_${commentStore.length}___`;
            commentStore.push(restoreStrings(match, false));
            return key;
        }
    );

    // 3️⃣ numbers
    html = html.replace(
        /\b\d+(\.\d+)?\b/g,
        '<span class="token number">$&</span>'
    );

    // 4️⃣ keywords
    html = html.replace(
        /\b(const|let|var|function|return|if|else|for|while|import|from|export|new|extends|async|await|try|catch|throw)\b/g,
        '<span class="token keyword">$1</span>'
    );


    html = html.replace(
        /(?<!<[^>]{0,200})\bclass\b/g,
        '<span class="token keyword class-keyword">class</span>'
    );


    // 5️⃣ booleans
    html = html.replace(
        /\b(true|false|null|undefined)\b/g,
        '<span class="token boolean">$1</span>'
    );

    // 6️⃣ restore strings
    html = restoreStrings(html, true);


    html = html.replace(
        /(?<![:=])\s*#(?![0-9A-Fa-f]{3,6}\b)[^\n\r]*/g, // Changed regex to handle '#' comments
        match => {
            const key = `___COMMENT_${commentStore.length}___`;
            commentStore.push(restoreStrings(match, false));
            return key;
        }
    );


    // 7️⃣ restore comments (kept separate to avoid corrupting tags)
    html = html.replace(/___COMMENT_(\d+)___/g, (match, index) => {
        const value = commentStore[Number(index)];
        if (!value) {
            return match;
        }
        return `\n<span class="token comment">${value}</span>`;
    });

    return html;
};

type CodeProps = React.ComponentPropsWithoutRef<'code'> & {
    inline?: boolean;
};

const CodeBlock: React.FC<CodeProps> = ({ inline, children, className }) => {
    const rawCode = String(children ?? '').replace(/\n$/, '');
    const inPre = useContext(PreContext);

    if (inline ?? !inPre) {
        return <code className="inline-code">{rawCode}</code>;
    }

    // const language = className?.replace('language-', '') || '';
    const language = className?.startsWith('language-')
        ? className.replace('language-', '')
        : '';

    if (!language) {
        return <b>{rawCode}</b>
    }

    const looksLikePlainText = !language || language === 'text';
    const codePattern = /[{}();=<>[\]]|const|let|function|=>/;
    // const codePattern = /[{}();=<>[\]]|const|let|function|=>|@Injectable|constructor/;
    const isRealCode = codePattern.test(rawCode);
    if (looksLikePlainText && !isRealCode) {
        return <b>{rawCode}</b>
    }
    const inTable = useContext(TableContext);
    const [copied, setCopied] = useState(false);

    const fallbackCopy = (t: string) => {
        const el = document.createElement('textarea');
        el.value = t;
        el.style.position = 'fixed';
        document.body.appendChild(el);
        el.select();
        try {
            document.execCommand('copy');
            setCopied(true);
        } catch (e) {
            console.error('Fallback copy failed', e);
        }
        document.body.removeChild(el);
    };

    const handleCopy = async () => {
        if (!navigator.clipboard?.writeText) {
            fallbackCopy(rawCode);
            setTimeout(() => {
                setCopied(false);
            }, 1200);
            return;
        }
        try {
            await navigator.clipboard.writeText(rawCode);
            setCopied(true);
        } catch (err) {
            fallbackCopy(rawCode);
        }
        setTimeout(() => {
            setCopied(false);
        }, 1200);
    };

    const highlighted = highlightSyntax(rawCode);

    if (inTable) {
        return (
            <div className="table-code" dir="ltr">
                <div className="table-code-lang">{language}</div>
                <pre>
                    <code dangerouslySetInnerHTML={{ __html: highlighted }} />
                </pre>
            </div>
        );
    }

    return (
        <div className="warapper-box-copy">
            <div className="box-copy-icon-msg">
                <button className="icon-copy-msg" onClick={handleCopy} type="button">
                    {copied ? 'Copied' : 'Copy'}
                    <svg
                        xmlns="http://www.w3.org/2000/svg"
                        width="16"
                        height="16"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth={2}
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        aria-hidden="true"
                    >
                        <rect x="9" y="9" width="13" height="13" rx="2" />
                        <path d="M5 15H4a2 2 0 0 1-2-2V4
           a2 2 0 0 1 2-2h9
           a2 2 0 0 1 2 2v1" />
                    </svg>
                </button>
                <div className="code-language">{language}</div>
            </div>
            <pre>
                <code dangerouslySetInnerHTML={{ __html: highlighted }} />
            </pre>
        </div>
    );
};

const containsCodeBlock = (node: React.ReactNode): boolean => {
    if (node === null || node === undefined || typeof node === 'boolean') {
        return false;
    }
    if (Array.isArray(node)) {
        return node.some(containsCodeBlock);
    }
    if (React.isValidElement(node)) {
        if (node.type === CodeBlock && node.props && node.props.inline === false) {
            const language = node.props.className?.replace('language-', '') || 'text';
            return language !== 'text';
        }
        return containsCodeBlock(node.props.children);
    }
    return false;
};

interface BDMMarkdownProps {
    text: string;
    className?: string;
}

const BDMMarkdown: React.FC<BDMMarkdownProps> = ({ text, className }) => {
    const [copied, setCopied] = useState(false);
    const displayText = useMemo(() => normalizeLatexArrows(text), [text]);

    const handleCopyAll = async () => {
        if (!navigator.clipboard?.writeText) {
            const el = document.createElement('textarea');
            el.value = displayText;
            el.style.position = 'fixed';
            document.body.appendChild(el);
            el.select();
            document.execCommand('copy');
            document.body.removeChild(el);
            setCopied(true);
            setTimeout(() => setCopied(false), 1000);
            return;
        }

        try {
            await navigator.clipboard.writeText(displayText);
            setCopied(true);
            setTimeout(() => setCopied(false), 1000);
        } catch (err) {
            console.error(err);
        }
    };

    const tableCell = (Tag: 'td' | 'th') =>
        ({ children }: { children?: React.ReactNode }) => {
            const text = useMemo(() => getTextContent(children), [children]);
            const hasCode = useMemo(() => containsCodeBlock(children), [children]);
            const dir = hasCode ? 'ltr' : detectDirection(text);
            const classNameCell = hasCode ? 'table-cell is-ltr' : `table-cell is-${dir}`;
            return (
                <Tag dir={dir} className={classNameCell}>
                    {children}
                </Tag>
            );
        };

    const Table = ({ children, ...props }: React.ComponentPropsWithoutRef<'table'>) => {
        const [copied, setCopied] = useState(false);
        const tableRef = useRef<HTMLTableElement | null>(null);
        const tableText = useMemo(() => extractTableText(children), [children]);

        const handleCopyTable = async () => {
            const text = tableText || extractTableFromElement(tableRef.current);
            await copyTextToClipboard(text, () => {
                setCopied(true);
                setTimeout(() => setCopied(false), 1200);
            });
        };
        return (
            <div className="table-wrapper">
                <div className='button-wrapper'>
                    <button className="table-copy-btn" onClick={handleCopyTable} type="button">
                        {copied ? 'Copied' : <>
                            <svg
                                xmlns="http://www.w3.org/2000/svg"
                                width="16"
                                height="16"
                                viewBox="0 0 24 24"
                                fill="none"
                                stroke="currentColor"
                                strokeWidth={2}
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                aria-hidden="true"
                            >
                                <rect x="9" y="9" width="13" height="13" rx="2" />
                                <path d="M5 15H4a2 2 0 0 1-2-2V4
           a2 2 0 0 1 2-2h9
           a2 2 0 0 1 2 2v1" />
                            </svg>
                        </>}
                    </button>
                </div>
                <TableContext.Provider value={true}>
                    <table {...props} ref={tableRef}>
                        {children}
                    </table>
                </TableContext.Provider>
            </div>
        );
    };

    return (
        <div className="bdm-markdown-wrapper">
            <Markdown
                className={`bdm-markdown ${className ? className : ''}`}
                rehypePlugins={[rehypeRaw]}
                remarkPlugins={[remarkGfm]}
                components={{
                    code: CodeBlock,
                    pre: ({ children, className }) => (
                        <PreContext.Provider value={true}>
                            <pre className={className}>{children}</pre>
                        </PreContext.Provider>
                    ),
                    table: Table,
                    td: tableCell('td'),
                    th: tableCell('th'),
                    a: ({ href, children }) => (
                        <a href={href || '#'} target="_blank" rel="noopener noreferrer">
                            {children}
                        </a>
                    ),
                }}
            >
                {displayText}
            </Markdown>
            <button onClick={handleCopyAll} className="copy-all-btn" type="button">
                {copied ? (
                    <span className="copy-all-ok">Copied</span>
                ) : (
                    <>
                        <svg
                            xmlns="http://www.w3.org/2000/svg"
                            width="16"
                            height="16"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth={2}
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            aria-hidden="true"
                        >
                            <rect x="9" y="9" width="13" height="13" rx="2" />
                            <path d="M5 15H4a2 2 0 0 1-2-2V4
           a2 2 0 0 1 2-2h9
           a2 2 0 0 1 2 2v1" />
                        </svg>
                    </>
                )}
            </button>
        </div>
    );
};

export default BDMMarkdown;
