import { FormEvent, useCallback, useEffect, useState } from 'react'
import { useLocation, useNavigate, useParams } from 'react-router-dom'
import ExcelAssistantAPIs from 'src/api/excelAssistant'
import { IWorkbookAnalysisDTO, IWorkbookSheet } from 'src/api/excelAssistant/types'
import collectionOpenCardIcon from 'src/assets/chatSidebarDefaultIcon.svg'
// import closeIcon from 'src/assets/closeIcon.svg'
import chatSubmitActiveIcon from 'src/assets/chatSubmitActiveIcon.svg'
import WhiteStar from 'src/assets/WhiteStar.svg'
import ChatHeader from 'src/pages/Chat/ChatBox/components/ChatHeader'
import Sidebar from 'src/pages/Chat/ChatBox/components/Siderbar'
import {
  getCollectionLessHistories,
  getCollections,
  setSidebarState,
} from 'src/pages/Chat/slice'
import { useBDMDispatch } from 'src/lib/store/hooks'
import WorkbookGrid from '../WorkbookGrid'
import { IExcelAssistantRouteState, WorkbookPreviewRow } from '../../types'
import { Divider } from '@mui/material'
import { addAToast } from 'src/lib/context'
import aiBlueIcon from 'src/assets/aiIBlueIcon.svg'

const SHEETS_POLL_INTERVAL = 1000
const SHEETS_POLL_ATTEMPTS = 30
const ANALYSIS_POLL_INTERVAL = 1000
const FAILED_ANALYSIS_STATUSES = new Set(['failed', 'error', 'cancelled', 'canceled'])
const TERMINAL_ANALYSIS_STATUSES = new Set([
  'completed',
  'complete',
  'succeeded',
  'success',
  'ready',
  'failed',
  'error',
  'cancelled',
  'canceled',
])

const wait = (delay: number) => new Promise(resolve => setTimeout(resolve, delay))

const getAnalysisErrorMessage = (
  data: IWorkbookAnalysisDTO,
  fallback: string,
) =>
  data.error ||
  data.detail ||
  data.analysis?.error ||
  data.analysis?.detail ||
  data.message ||
  data.analysis?.message ||
  fallback

const getRequestErrorMessage = (error: unknown, fallback: string) => {
  const requestError = error as {
    message?: string
    response?: {
      data?: {
        message?: string
        detail?: string
        error?: string
      }
    }
  }

  return requestError.response?.data?.error ||
    requestError.response?.data?.detail ||
    requestError.response?.data?.message ||
    requestError.message ||
    fallback
}

const WorkbookWorkspace = () => {
  const dispatch = useBDMDispatch()
  const navigate = useNavigate()
  const { workbookId = '' } = useParams()
  const location = useLocation()
  const routeState = (location.state ?? {}) as IExcelAssistantRouteState
  const [sheets, setSheets] = useState<IWorkbookSheet[]>([])
  const [activeSheetId, setActiveSheetId] = useState('')
  const [sheetRows, setSheetRows] = useState<WorkbookPreviewRow[]>([])
  const [isRowsLoading, setIsRowsLoading] = useState(false)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState('')
  const [selectionAddress, setSelectionAddress] = useState('')
  const [selectionResetKey, setSelectionResetKey] = useState(0)
  const [prompt, setPrompt] = useState('')
  const [versionId, setVersionId] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [analysisId, setAnalysisId] = useState('')
  const [analysisStatus, setAnalysisStatus] = useState('')
  const [isProjectsSidebarOpen, setIsProjectsSidebarOpen] = useState(false)

  const handleSelectionChange = useCallback((selection: string) => {
    setSelectionAddress(selection)
  }, [])

  const clearSelection = () => {
    setSelectionAddress('')
    setSelectionResetKey(current => current + 1)
  }

  const openProjectsSidebar = () => {
    dispatch(getCollections())
    dispatch(getCollectionLessHistories())
    dispatch(setSidebarState({ isOpen: true }))
    setIsProjectsSidebarOpen(true)
  }

  const closeProjectsSidebar = () => {
    dispatch(setSidebarState({ isOpen: false }))
    setIsProjectsSidebarOpen(false)
  }

  const handleSidebarNavigate = () => {
    setIsProjectsSidebarOpen(false)
    dispatch(setSidebarState({ isOpen: true }))
    navigate('/')
  }

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const question = prompt.trim()

    if (!question || isSubmitting) {
      return
    }

    if (!versionId) {
      addAToast('نسخه workbook هنوز آماده نشده است.', 'error')
      return
    }

    setIsSubmitting(true)
    try {
      const response = await ExcelAssistantAPIs().createWorkbookAnalysis(workbookId, {
        versionId,
        question,
        chartRequested: true,
        selectedCells: selectionAddress,
      })
      const responseStatus = (
        response.data.status || response.data.analysis?.status || ''
      ).toLowerCase()
      const hasResponseError =
        response.data.success === false ||
        Boolean(response.data.error || response.data.detail) ||
        Boolean(response.data.analysis?.error || response.data.analysis?.detail) ||
        FAILED_ANALYSIS_STATUSES.has(responseStatus)

      if (hasResponseError) {
        addAToast(
          getAnalysisErrorMessage(response.data, 'ارسال درخواست تحلیل ناموفق بود.'),
          'error',
        )
        return
      }

      const nextAnalysisId =
        response.data.analysisId ||
        response.data.analysis_id ||
        response.data.analysis?.analysisId ||
        response.data.analysis?.analysis_id

      if (!nextAnalysisId) {
        throw new Error('شناسه تحلیل از سرور دریافت نشد.')
      }

      setAnalysisId(nextAnalysisId)
      setAnalysisStatus(response.data.status || response.data.analysis?.status || 'queued')
      setPrompt('')
      clearSelection()
    } catch (error) {
      addAToast(
        getRequestErrorMessage(error, 'ارسال درخواست تحلیل ناموفق بود.'),
        'error',
      )
    } finally {
      setIsSubmitting(false)
    }
  }

  useEffect(() => {
    if (!analysisId) {
      return
    }

    let active = true
    let timer: number | undefined

    const pollAnalysis = async () => {
      try {
        const response = await ExcelAssistantAPIs().getAnalysis(analysisId)
        if (!active) {
          return
        }

        const nextStatus = response.data.status || response.data.analysis?.status || ''
        const normalizedStatus = nextStatus.toLowerCase()
        if (nextStatus) {
          setAnalysisStatus(nextStatus)
        }

        const hasResponseError =
          response.data.success === false ||
          Boolean(response.data.error || response.data.detail) ||
          Boolean(response.data.analysis?.error || response.data.analysis?.detail) ||
          FAILED_ANALYSIS_STATUSES.has(normalizedStatus)

        if (hasResponseError) {
          addAToast(
            getAnalysisErrorMessage(response.data, 'پردازش تحلیل ناموفق بود.'),
            'error',
          )
          return
        }

        if (!TERMINAL_ANALYSIS_STATUSES.has(normalizedStatus)) {
          timer = window.setTimeout(pollAnalysis, ANALYSIS_POLL_INTERVAL)
        }
      } catch (error) {
        if (active) {
          setAnalysisStatus('error')
          addAToast(
            getRequestErrorMessage(error, 'دریافت وضعیت تحلیل ناموفق بود.'),
            'error',
          )
        }
      }
    }

    timer = window.setTimeout(pollAnalysis, ANALYSIS_POLL_INTERVAL)

    return () => {
      active = false
      if (timer !== undefined) {
        window.clearTimeout(timer)
      }
    }
  }, [analysisId])

  useEffect(() => {
    let active = true

    const api = ExcelAssistantAPIs()

    const getReadySheets = async (attempt = 0): Promise<IWorkbookSheet[]> => {
      const sheetsResponse = await api.getWorkbookSheets(workbookId)
      const sheetsData = Array.isArray(sheetsResponse.data)
        ? sheetsResponse.data
        : sheetsResponse.data?.sheets

      if (sheetsData?.length) {
        return sheetsData
      }

      if (!active || attempt >= SHEETS_POLL_ATTEMPTS - 1) {
        throw new Error('آماده‌سازی sheet بیشتر از حد انتظار طول کشید.')
      }

      await wait(SHEETS_POLL_INTERVAL)
      return getReadySheets(attempt + 1)
    }

    const loadWorkbook = async () => {
      const workbookResponse = await api.getWorkbook(workbookId)

      if (!workbookResponse?.data?.workbook) {
        throw new Error('اطلاعات workbook دریافت نشد.')
      }

      const nextSheets = await getReadySheets()
      return {
        nextSheets,
        versionId: workbookResponse.data.workbook.version_id,
      }
    }

    loadWorkbook()
      .then(({ nextSheets, versionId: nextVersionId }) => {
        if (!active) {
          return
        }
        setVersionId(nextVersionId)
        setSheets(nextSheets)
        const firstSheet = nextSheets[0]
        setActiveSheetId(firstSheet?.sheet_id || firstSheet?.id || '')
      })
      .catch(error => {
        if (active) {
          setError(error instanceof Error ? error.message : 'دریافت workbook ناموفق بود.')
        }
      })
      .finally(() => active && setIsLoading(false))

    return () => {
      active = false
    }
  }, [workbookId])

  useEffect(() => {
    if (!activeSheetId) {
      return
    }

    let active = true
    setIsRowsLoading(true)

    ExcelAssistantAPIs()
      .getSheetRows(activeSheetId, 0, 100)
      .then(response => {
        if (!active) {
          return
        }
        const rows = Array.isArray(response.data) ? response.data : response.data?.rows
        setSheetRows(
          (rows ?? []).map(row => {
            const rowValues =
              row.values && typeof row.values === 'object' && !Array.isArray(row.values)
                ? row.values as Record<string, unknown>
                : row

            return Object.fromEntries(
              Object.entries(rowValues).map(([key, value]) => [
                key,
                value === null || value === undefined
                  ? ''
                  : typeof value === 'string'
                    ? value
                    : JSON.stringify(value),
              ]),
            )
          }),
        )
      })
      .catch(() => active && setSheetRows([]))
      .finally(() => active && setIsRowsLoading(false))

    return () => {
      active = false
    }
  }, [activeSheetId])

  return (
    <main className='excel-workspace'>
      <ChatHeader
        modelAlwaysVisible
        rightContent={
          <div className='excel-workspace__workbook-title'>کتاب‌کار جدید</div>
        }
        centerContent={
          <div className='excel-workspace__header-actions'>
            <button type='button' className='is-active'>
              هوش مصنوعی
              <img src={WhiteStar} alt='' />
            </button>
            <button
              type='button'
              onClick={openProjectsSidebar}
              aria-expanded={isProjectsSidebarOpen}
            >
              پروژه‌ها
              <img src={collectionOpenCardIcon} alt='' />
            </button>
          </div>
        }
      />
      {isProjectsSidebarOpen && (
        <div
          className='excel-workspace__sidebar-overlay'
          role='presentation'
          onMouseDown={closeProjectsSidebar}
        >
          <div
            className='excel-workspace__sidebar-panel'
            onMouseDown={event => event.stopPropagation()}
          >
            <Sidebar onClose={closeProjectsSidebar} onNavigate={handleSidebarNavigate} />
          </div>
        </div>
      )}
      <div className='excel-workspace__body'>
        <section className='excel-workspace__sheet'>
          <nav className='excel-workspace__tabs'>
            {(sheets.length > 0 ? sheets : [{ name: 'Sheet1' }]).map((sheet, index) => (
              <button
                type='button'
                className={
                  (sheet.sheet_id || sheet.id) === activeSheetId ? 'is-active' : ''
                }
                key={sheet.sheet_id || sheet.id || sheet.name || index}
                onClick={() => setActiveSheetId(sheet.sheet_id || sheet.id || '')}
              >
                {sheet.name || sheet.title || `Sheet${index + 1}`}
              </button>
            ))}
            {/* <button type='button' aria-label='افزودن sheet'>+</button> */}
          </nav>
          {error ? (
            <div className='excel-workbook-grid__state is-error'>{error}</div>
          ) : (
            <WorkbookGrid
              rows={sheetRows.length > 0 ? sheetRows : routeState.previewRows ?? []}
              isLoading={isLoading || isRowsLoading}
              onSelectionChange={handleSelectionChange}
              selectionResetKey={selectionResetKey}
            />
          )}
        </section>

        <aside className='excel-workspace__assistant'>
          <div className='excel-workspace__assistant-empty'>
            <div className='excel-workspace__assistant-empty__header-icon'>
              <img src={aiBlueIcon} />
            </div>
            <div className='excel-workspace__assistant-empty__header'>چگونه می‌توانم کمک کنم؟</div>
            یک سلول انتخاب کنید و دستور ویرایش بنویسید.
            {analysisStatus && (
              <span className='excel-workspace__analysis-status'>
                وضعیت تحلیل: {analysisStatus}
              </span>
            )}
          </div>
          <Divider />
          <form className='excel-workspace__prompt' onSubmit={handleSubmit}>
            {selectionAddress && (
              <div className='excel-workspace__selection-chip'>
                <span>{selectionAddress}</span>
                <button type='button' aria-label='حذف محدوده انتخاب‌شده' onClick={clearSelection}>
                  x
                </button>
              </div>
            )}
            <input
              value={prompt}
              placeholder='گفتگو خود را ایجاد کنید......'
              onChange={event => setPrompt(event.target.value)}
            />
            <button
              className='excel-workspace__prompt-submit'
              type='submit'
              aria-label='ارسال'
              disabled={!prompt.trim() || !versionId || isSubmitting}
            >
              <img src={chatSubmitActiveIcon} alt='' />
            </button>
          </form>
        </aside>
      </div>
    </main>
  )
}

export default WorkbookWorkspace
