import './style.scss'

import { getRecentFiles } from 'src/lib/slice/fileManagement/thunks'
import { useBDMDispatch } from 'src/lib/store/hooks'

import Folders from '../components/Folders'
import Files from '../components/Files'
import PanelTitle from '../components/PanelTitle'
import { t } from 'i18next'
import { useEffect } from 'react'

interface IProps {
  search: string
}

const DrivePanel = ({ search }: IProps) => {
  const dispatch = useBDMDispatch()

  useEffect(() => {
    dispatch(getRecentFiles({}))
  }, [dispatch])

  return (
    <div className='file-manager__drive'>
      <PanelTitle title={t('file-manager-drive-panel-title')} />

      <Folders search={search} />

      <Files search={search} />
    </div>
  )
}

export default DrivePanel