import { useLocation } from 'react-router'
import { t } from 'i18next'
import { RoutesV2 } from 'src/lib/constants'

const useNavigationBar = () => {
  const location = useLocation()

  const navigationItems = RoutesV2()
    // TODO: fix type error later
    // @ts-ignore
    .filter(nav => !nav.isDisabled && nav.showOnNavbar)
    // @ts-ignore
    .map(nav => ({
      id: nav.id,
      path: nav.link,
      label: t<string>(nav.title),
      icon: nav.navbarIcon,
      disabledIcon: nav.navbardisabledIcon,
      enable: true,
      isSelected: location.pathname === '/' + nav.link,
      tab: nav.tab,
    }))

  return { navigationItems }
}

export default useNavigationBar
