import './style.scss'
import { t } from 'i18next'
import { useState, ChangeEvent, useCallback, useEffect, useRef } from 'react'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import { createCollection, selectModalsState, setModalsState } from 'src/pages/Chat/slice'

import Modal from '@mui/material/Modal'
import Button from 'src/components/Button'
import InfoIcon from 'src/components/InfoIcon'
import TextNewInput from 'src/components/TextNewInput'
import closeIcon from 'src/assets/closeIcon.svg'
import stickerIcon from 'src/assets/stickerIcon.svg'
import stickerIconWhite from 'src/assets/stickerIconWhite.svg'
import newInfoIcon from 'src/assets/newInfoIcon.svg'
import addProjectIcon from 'src/assets/addProjectIcon.svg'
import addProjectIconWhite from 'src/assets/addProjectIconWhite.svg'
import collectionCloseCard from 'src/assets/collectionCloseCardIcon.svg'
// import edgeIcon from 'src/assets/edgeIcon2.svg'
// import nodeIcon from 'src/assets/nodeIcon2.svg'
import lockIcon from 'src/assets/lockIcon2.svg'
import starIcon from 'src/assets/star2.svg'
import abstractIcon from 'src/assets/abstractIcon2.svg'
import CollectionAppearancePicker from './CollectionAppearancePicker'
import closeIconWhite from 'src/assets/closeIconWhite.svg'
import { RootState } from 'src/lib/store'

const QUICK_COLLECTION_TAGS = [
  { id: 'new-project', title: 'chat-quick-tag-new-project', icon: addProjectIcon },
  // { id: 'edge', title: 'یال', icon: edgeIcon },
  // { id: 'node', title: 'گره', icon: nodeIcon },
  { id: 'private', title: 'chat-quick-tag-private', icon: lockIcon },
  { id: 'ai', title: 'chat-quick-tag-ai', icon: starIcon },
  { id: 'abstract', title: 'chat-quick-tag-summarize', icon: abstractIcon },
]

const NewCollectionModal = () => {
  const dispatch = useBDMDispatch()
  const isOpen = useBDMSelector(selectModalsState).createCollection
  const [collectionName, setCollectionName] = useState('')
  const contentRef = useRef<HTMLFormElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const [selectedColor, setSelectedColor] = useState('#3B82F6')
  const [selectedIcon, setSelectedIcon] = useState(stickerIcon)
  const [openCollectionApperace, setOpenCollectionApperace] = useState(false)
  const [chosenSvg, setChosenSvg] = useState<JSX.Element | null>(null)
  const [activeQuickTagId, setActiveQuickTagId] = useState<string | null>(null)
  const pickerRef = useRef<HTMLDivElement>(null)
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const handleClose = useCallback(() => {
    setCollectionName('')
    setSelectedIcon(stickerIcon)
    setChosenSvg(null)
    setActiveQuickTagId(null)
    setOpenCollectionApperace(false)
    dispatch(setModalsState({ createCollection: false }))
  }, [dispatch, setModalsState])

  const handleSubmit = useCallback(() => {
    if (collectionName) {
      const icon = selectedIcon === stickerIcon ? collectionCloseCard : selectedIcon
      dispatch(
        createCollection({
          name: collectionName,
          color: selectedColor,
          icon,
        }),
      )
      handleClose()
    }
  }, [collectionName, selectedColor, selectedIcon, dispatch, createCollection, handleClose])

  useEffect(() => {
    if (isOpen) {
      contentRef.current?.focus()
      requestAnimationFrame(() => inputRef.current?.focus())
    }
  }, [isOpen])

  const handleQuickTagsWheel = (e: React.WheelEvent<HTMLDivElement>) => {
    const container = e.currentTarget
    if (Math.abs(e.deltaY) <= Math.abs(e.deltaX)) {
      return
    }
    e.preventDefault()
    container.scrollLeft += e.deltaY
  }

  const handleQuickTagSelect = (tag: typeof QUICK_COLLECTION_TAGS[number]) => {
    setCollectionName(t<string>(tag.title))
    setSelectedIcon(tag.icon)
    setChosenSvg(<img src={tag.icon} alt='' aria-hidden='true' />)
    setActiveQuickTagId(tag.id)
    setOpenCollectionApperace(false)
    requestAnimationFrame(() => inputRef.current?.focus())
  }

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        openCollectionApperace &&
        pickerRef.current &&
        !pickerRef.current.contains(event.target as Node)
      ) {
        setOpenCollectionApperace(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [openCollectionApperace])

  return (
    <Modal
      open={isOpen}
      onClose={handleClose}
      className='new-collection-modal'
      BackdropProps={{
        sx: {
          backdropFilter: 'blur(5px)',
          backgroundColor: '#09090B4D',
        },
      }}
    >
      <form className='new-collection-modal__content' ref={contentRef} tabIndex={-1}>
        <div className='new-collection-modal__header'>
          <p className='new-collection-modal__title'>
            <img src={mode === 'light' ? addProjectIcon : addProjectIconWhite} />
            {t('chat-sidebar-new-collection-title')}
          </p>
          <button
            type='button'
            className='new-collection-modal__close'
            onClick={handleClose}
            aria-label='close'
          >
            <img src={mode === 'light' ? closeIcon : closeIconWhite} alt='close' />
          </button>
        </div>

        {/* body */}
        <div className='new-collection-modal__body'>
          <InfoIcon
            title={t('chat-new-collection-modal-info')}
            placement='left'
            className='new-collection-modal__info'
          />
          <div className='chat-new-collection-modal__wrapper-input'>
            <span
              className='appearance-picker__preview'
              onClick={() => setOpenCollectionApperace(prev => !prev)}
            >
              {chosenSvg ? (
                chosenSvg
              ) : (
                <img src={mode === 'light' ? stickerIcon : stickerIconWhite} />
              )}
              {/* {chosenSvg} */}
            </span>
            <TextNewInput
              label=''
              placeholder={t('chat-new-collection-modal-input-placeholder')}
              value={collectionName}
              onChange={(e: ChangeEvent<HTMLInputElement>) => {
                setCollectionName(e.target.value)
                setActiveQuickTagId(null)
                setOpenCollectionApperace(false)
              }}
              className='new-collection-modal__input'
              dir='auto'
              tabIndex={1}
              inputRef={inputRef}
              autoFocus
            />
          </div>
          <div ref={pickerRef}>
            <CollectionAppearancePicker
              selectedColor={selectedColor}
              selectedIcon={selectedIcon}
              isOpen={openCollectionApperace}
              setChosenSvg={setChosenSvg}
              onChange={({ color, icon }) => {
                setSelectedColor(color)
                setSelectedIcon(icon)
                setActiveQuickTagId(null)
              }}
            />
          </div>
        </div>
        <div
          className='new-collection-modal__quick-tags'
          aria-label='project-options'
          onWheel={handleQuickTagsWheel}
        >
          {QUICK_COLLECTION_TAGS.map(tag => (
            <button
              key={tag.id}
              type='button'
              className={`new-collection-modal__tag ${activeQuickTagId === tag.id ? 'new-collection-modal__tag--active' : ''
                }`}
              onClick={() => handleQuickTagSelect(tag)}
            >
              <img src={tag.icon} alt='' aria-hidden='true' />
              {t(tag.title)}
            </button>
          ))}
        </div>
        {/* info */}
        <div className='new-collection-modal__information'>
          <div>
            <img src={newInfoIcon} />
            {t('chat-projects-space-title')}
          </div>
          <p>
            {t('chat-projects-space-description')}
          </p>
        </div>
        {/* actions */}
        <div className='new-collection-modal__btns'>
          <Button
            title={t('chat-new-collection-modal-btn-cancel')}
            onClick={handleClose}
            className='new-collection-modal__btns__cancel'
            type='button'
            tabIndex={1}
          />
          <Button
            title={t('chat-new-collection-modal-btn-confirm')}
            onClick={handleSubmit}
            className='new-collection-modal__btns__confirm'
            disabled={!collectionName}
            type='submit'
            tabIndex={1}
          />
        </div>
      </form>
    </Modal>
  )
}

export default NewCollectionModal
