import { sizeFormatter } from 'src/lib/utils'
import LinearProgress, { linearProgressClasses } from '@mui/material/LinearProgress'

const getFileType = (name: string, mimeType: string) => {
  const extension = name.split('.').pop()?.toLowerCase()

  if (extension === 'csv' || mimeType === 'text/csv') return 'csv'
  if (['xls', 'xlsx'].includes(extension ?? '')) return 'excel'
  if (extension === 'pdf' || mimeType === 'application/pdf') return 'pdf'
  if (extension === 'parquet') return 'parquet'
  if (['yaml', 'yml'].includes(extension ?? '')) return 'yaml'
  if (['mp4', 'mov', 'avi', 'mkv', 'webm'].includes(extension ?? '') || mimeType.startsWith('video/')) {
    return 'video'
  }
  if (
    ['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg'].includes(extension ?? '') ||
    mimeType.startsWith('image/')
  ) {
    return 'image'
  }
  if (['txt', 'md', 'markdown', 'json'].includes(extension ?? '') || mimeType === 'text/plain') {
    return 'text'
  }

  return 'unknown'
}

interface IProps {
  name: string
  type: string
  progress: number
  size: number
  error: boolean
  onSelect?: () => void
  onDelete?: () => void
}

const FileItem = ({ name, type, progress, error, size, onSelect, onDelete }: IProps) => {
  const progressStatus = error ? 'error' : progress === 100 ? 'done' : 'progress'
  const fileType = getFileType(name, type)

  return (
    <div
      className={`chat-chatbox-file-item ${progressStatus}`}
      role={onSelect ? 'button' : undefined}
      tabIndex={onSelect ? 0 : undefined}
      onClick={onSelect}
      onKeyDown={event => {
        if (onSelect && (event.key === 'Enter' || event.key === ' ')) {
          event.preventDefault()
          onSelect()
        }
      }}
    >
      <div className={`chat-chatbox-file-icon ${fileType} ${progressStatus}`}></div>
      <p className='chat-chatbox-file-name'>
        <span>&nbsp;({sizeFormatter(size)}) </span>
        <span>{name}&nbsp;</span>
      </p>
      {progress >= 100 ? (
        <button
          type='button'
          className={`chat-chatbox-file-close ${progressStatus}`}
          onClick={event => {
            event.stopPropagation()
            onDelete?.()
          }}
          aria-label={`حذف ${name}`}
        />
      ) : (<>{progress}%</>)}
      {progress < 100 && (
        <div className='chat-chatbox-file-porgress'>
          <LinearProgress
            variant='determinate'
            value={progress}
            dir='rtl'
            sx={{
              transform: 'scaleX(-1)',
              borderRadius: '0 0 4px 4px',
              [`&.${linearProgressClasses.colorPrimary}`]: {
                backgroundColor: 'transparent',
              },
              [`& .${linearProgressClasses.bar}`]: {
                borderRadius: 5,
                backgroundColor: '#3685B5',
              },
            }}
          />
        </div>
      )}
    </div>
  )
}

export default FileItem
