import './style.scss'

import Drawer from '@mui/material/Drawer'
import CircularProgress from '@mui/material/CircularProgress'
import { useEffect, useMemo, useState } from 'react'
import { t } from 'i18next'

import closeIcon from 'src/assets/closeIcon.svg'
import closeIconWhite from 'src/assets/closeIconWhite.svg'
import ChatAPIs from 'src/api/chat'
import { useBDMSelector } from 'src/lib/store/hooks'
import { RootState } from 'src/lib/store'
import { IChatSessionFileUploadItem } from 'src/types/NewChat'
import { IPreviewFileDTO } from 'src/types/NewChat/api'
import BDMMarkdown from 'src/components/MarkDown'

type PreviewRow = Record<string, unknown>

interface IProps {
  file: IChatSessionFileUploadItem | null
  collectionId?: string | null
  open: boolean
  onClose: () => void
}

const textMimeTypes = [
  'text/plain',
  'text/csv',
  'text/markdown',
  'text/x-markdown',
  'application/json',
  'application/markdown',
]
const imageMimeTypes = ['image/png', 'image/jpeg', 'image/jpg', 'image/webp', 'image/gif']

const getFileExtension = (fileName: string) => fileName.split('.').pop()?.toLowerCase() ?? ''

const isTextPreview = (mimeType: string, fileName: string) => {
  const extension = getFileExtension(fileName)
  return (
    textMimeTypes.includes(mimeType) || ['txt', 'csv', 'json', 'md', 'markdown'].includes(extension)
  )
}

const isMarkdownPreview = (mimeType: string, fileName: string) => {
  const extension = getFileExtension(fileName)
  return (
    ['text/markdown', 'text/x-markdown', 'application/markdown'].includes(mimeType) ||
    ['md', 'markdown'].includes(extension)
  )
}

const isImagePreview = (mimeType: string, fileName: string) => {
  const extension = getFileExtension(fileName)
  return (
    imageMimeTypes.includes(mimeType) || ['png', 'jpg', 'jpeg', 'webp', 'gif'].includes(extension)
  )
}

const isPdfPreview = (mimeType: string, fileName: string) => {
  return mimeType === 'application/pdf' || getFileExtension(fileName) === 'pdf'
}

const getPreviewColumns = (rows: PreviewRow[]) => {
  return Array.from(new Set(rows.flatMap(row => Object.keys(row))))
}

const stringifyPreviewValue = (value: unknown) => {
  if (typeof value === 'string') {
    return value
  }

  return JSON.stringify(value, null, 2)
}

const FilePreviewDrawer = ({ file, collectionId, open, onClose }: IProps) => {
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const [objectUrl, setObjectUrl] = useState('')
  const [textContent, setTextContent] = useState('')
  const [previewColumns, setPreviewColumns] = useState<string[]>([])
  const [previewRows, setPreviewRows] = useState<PreviewRow[]>([])
  const [previewMeta, setPreviewMeta] = useState<Pick<IPreviewFileDTO, 'mimeType'> | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState('')

  const fileName = file?.filename || file?.originalName || ''
  const mimeType = file?.mimeType || ''
  // Session artifacts (including OCR and letter-writer outputs) must always use
  // the attachment's own historyId in the URL, even when a collectionId exists.
  const previewHistoryId = file?.historyId || undefined
  const previewCollectionId = previewHistoryId ? undefined : file?.collectionId || collectionId
  const canRenderText = useMemo(() => isTextPreview(mimeType, fileName), [fileName, mimeType])
  const canRenderMarkdown = useMemo(
    () => isMarkdownPreview(previewMeta?.mimeType || mimeType, fileName),
    [fileName, mimeType, previewMeta?.mimeType],
  )
  const canRenderImage = useMemo(() => isImagePreview(mimeType, fileName), [fileName, mimeType])
  const canRenderPdf = useMemo(() => isPdfPreview(mimeType, fileName), [fileName, mimeType])

  useEffect(() => {
    if (!open || !file) {
      return
    }

    if (!fileName) {
      setError(t<string>('chat-preview-file-name-unavailable'))
      return
    }

    let isMounted = true
    let url = ''

    const loadPreview = async () => {
      setIsLoading(true)
      setError('')
      setTextContent('')
      setPreviewColumns([])
      setPreviewRows([])
      setObjectUrl('')

      const fileId = file.fileId || file._id

      if (fileId) {
        const preview = previewCollectionId
          ? await ChatAPIs().previewFile({
              collectionId: previewCollectionId,
              fileId,
              fileName,
              limit: 300,
              offset: 0,
            })
          : await ChatAPIs().previewSessionFile({
              historyId: previewHistoryId as string,
              fileId,
              fileName,
              limit: 300,
              offset: 0,
            })

        if (!isMounted) {
          return
        }

        setPreviewMeta({ mimeType: preview.mimeType })

        if (preview.type === 'text') {
          setTextContent(preview.data)
          setIsLoading(false)
          return
        }

        if (preview.type === 'image' || preview.type === 'pdf') {
          url = preview.objectUrl
          setObjectUrl(preview.objectUrl)
          setIsLoading(false)
          return
        }

        if (preview.type === 'rows') {
          const rows = preview.data
          setPreviewRows(rows)
          setPreviewColumns(preview.columns?.length ? preview.columns : getPreviewColumns(rows))
          setIsLoading(false)
          return
        }
      }

      setIsLoading(false)
    }

    loadPreview().catch(error => {
      if (isMounted) {
        setError(
          error instanceof Error && error.message
            ? error.message
            : t<string>('chat-preview-load-error'),
        )
        setIsLoading(false)
      }
    })

    return () => {
      isMounted = false
      if (url) {
        URL.revokeObjectURL(url)
      }
    }
  }, [file, fileName, open, previewCollectionId, previewHistoryId])

  useEffect(() => {
    if (!open) {
      setObjectUrl('')
      setTextContent('')
      setPreviewColumns([])
      setPreviewRows([])
      setPreviewMeta(null)
      setError('')
      setIsLoading(false)
    }
  }, [open])

  const renderPreview = () => {
    if (isLoading) {
      return (
        <div className='chat-file-preview__state'>
          <CircularProgress size={28} />
          <span>در حال آماده سازی پیش نمایش</span>
        </div>
      )
    }

    if (error) {
      return <div className='chat-file-preview__state'>{error}</div>
    }

    if (canRenderImage || previewMeta?.mimeType.startsWith('image/')) {
      if (!objectUrl) {
        return (
          <div className='chat-file-preview__state'>پیش نمایش تصویری برای این فایل دریافت نشد.</div>
        )
      }

      return <img src={objectUrl} alt={fileName} className='chat-file-preview__image' />
    }

    if (canRenderPdf || previewMeta?.mimeType === 'application/pdf') {
      if (!objectUrl) {
        return (
          <div className='chat-file-preview__state'>پیش نمایش PDF برای این فایل دریافت نشد.</div>
        )
      }

      return <iframe src={objectUrl} title={fileName} className='chat-file-preview__pdf' />
    }

    if (previewRows.length > 0 || previewColumns.length > 0) {
      return (
        <div className='chat-file-preview__table-wrapper'>
          <table className='chat-file-preview__table'>
            <thead>
              <tr>
                {previewColumns.map(column => (
                  <th key={column}>{column}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {previewRows.map((row, rowIndex) => (
                <tr key={rowIndex}>
                  {previewColumns.map(column => (
                    <td key={column}>{stringifyPreviewValue(row[column])}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )
    }

    if (canRenderText || textContent) {
      if (!textContent.trim()) {
        return <div className='chat-file-preview__state'>محتوایی برای نمایش در این فایل وجود ندارد.</div>
      }

      if (canRenderMarkdown) {
        return (
          <div className='chat-file-preview__markdown' dir='auto'>
            <BDMMarkdown text={textContent} />
          </div>
        )
      }

      return (
        <pre className='chat-file-preview__text' dir='auto'>
          {textContent}
        </pre>
      )
    }

    return <div className='chat-file-preview__state'>داده ای برای نمایش وجود ندارد.</div>
  }

  return (
    <Drawer
      anchor='right'
      open={open}
      onClose={onClose}
      className='chat-file-preview-wrapper'
      PaperProps={{ className: 'chat-file-preview-paper' }}
    >
      <div className='chat-file-preview'>
        <div className='chat-file-preview__header'>
          <button type='button' className='chat-file-preview__close' onClick={onClose}>
            <img src={mode === 'light' ? closeIcon : closeIconWhite} alt='close' />
          </button>
          <div className='chat-file-preview__title'>
            <span dir='auto'>{fileName || t('chat-file-preview')}</span>
            {mimeType && <small>{mimeType}</small>}
          </div>
        </div>
        <div className='chat-file-preview__body'>{renderPreview()}</div>
      </div>
    </Drawer>
  )
}

export default FilePreviewDrawer
