import './style.scss'
import { t } from 'i18next'
import { ReactNode, useState } from 'react'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import {
  // selectSidebarState,
  // setSidebarState,
  selectCurrentHistory,
  selectCurrentCollection,
  selectModalsState,
  setModalsState,
  pinSession,
  // toggleExpanded,
  // toggleLayoutLock,
  // selectlayoutState,
} from 'src/pages/Chat/slice'
import { InstructionButton } from './InstructionButton';
import { PinButton } from './PinButton';

// import Tooltip from '@mui/material/Tooltip'
import ModelBox from './ModelBox'
import { Button } from '@mui/material'
import Tooltip from '@mui/material/Tooltip'
import BackgroundModal from './BackgroundModal'
import { RootState } from 'src/lib/store'
interface ChatHeaderProps {
  centerContent?: ReactNode
  rightContent?: ReactNode
  modelAlwaysVisible?: boolean
}

const ChatSidebar = ({ centerContent, rightContent, modelAlwaysVisible }: ChatHeaderProps) => {
  const dispatch = useBDMDispatch()
  // const dispatch = useBDMDispatch()
  // const isSidebarOpen = useBDMSelector(selectSidebarState).isOpen
  const currentHistory = useBDMSelector(selectCurrentHistory)
  const currentCollection = useBDMSelector(selectCurrentCollection)
  const openInstruction = useBDMSelector(selectModalsState).openInstruction
  const [pinLoading, setPinLoading] = useState(false)
  // const { isLocked } = useBDMSelector(selectlayoutState)

  const handleTogglePinStatus = async () => {
    if (!currentHistory || pinLoading) {
      return
    }

    setPinLoading(true)
    try {
      await dispatch(
        pinSession({
          historyId: currentHistory.historyId,
          collectionId: currentHistory.collectionId,
        }),
      ).unwrap()
    } finally {
      setPinLoading(false)
    }
  }
  // const handleOpenSidebar = useCallback(() => {
  //   dispatch(setSidebarState({ isOpen: true }))
  // }, [dispatch])

  // const handleToggleExpand = useCallback(() => {
  //   dispatch(toggleExpanded())
  // }, [dispatch])

  // const handleToggleLayoutLock = useCallback(
  //   (e: MouseEvent<HTMLButtonElement>) => {
  //     e.stopPropagation()
  //     e.preventDefault()
  //     dispatch(toggleLayoutLock())
  //   },
  //   [dispatch],
  // )
  const handleInstructionToggle = () => {
    dispatch(setModalsState({ openInstruction: true }));
  };

  const onPenBackgroundModal = () => {
    dispatch(setModalsState({ openBackgroundModal: true }));
  }
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const isLargeFont = localStorage.getItem('chat-font-size') === 'large'

  return (
    <div className='chat-chatbox-header'>
      {rightContent && (
        <div className='chat-chatbox-header__right'>{rightContent}</div>
      )}
      {centerContent && (
        <div className='chat-chatbox-header__center'>{centerContent}</div>
      )}
      <div className='chat-chatbox-header__model'>
        {/* <button
          className={`chat-chatbox-header__sidebar-toggle ${isSidebarOpen ? 'hide' : ''}`}
          onClick={handleOpenSidebar}
        /> */}
        <div>
          <ModelBox alwaysVisible={modelAlwaysVisible} />
        </div>
        <div className='chat-chatbox-header__wrapper-left-item'>
          <Tooltip title={isLargeFont ? t('chat-sidebar-background-title') : ''} placement='bottom' disableInteractive>
            <Button className={`chat-chatbox-header__btn-background ${mode === 'light' ? '' : 'chat-chatbox-header__btn-background-dark'}`} onClick={onPenBackgroundModal}>
              {t('chat-sidebar-background-title')}
            </Button>
          </Tooltip>
          {currentHistory && (
            <PinButton
              active={Boolean(currentHistory.pinned ?? currentHistory.isPinned)}
              loading={pinLoading}
              onToggle={handleTogglePinStatus}
            />
          )}
          {currentCollection && (
            <InstructionButton openInstruction={openInstruction} onToggle={handleInstructionToggle} />
          )}
          <BackgroundModal />
        </div>
      </div>
      <div className='chat-chatbox-header__layout-options'>
        {/* {currentHistory && icon && (
          <div className='chat-chatbox-header__bot-icon'>
            <img src={icon} alt={title} />
            <p>{`${t(title)}${currentHistory.abstractor ? '' : ' (پاسخ گسترده)'}`.trim()}</p>
          </div>
        )} */}
        {/* <Tooltip title='تمام صفحه' placement='bottom'>
          <button
            className='chat-chatbox-header__expand-toggle'
            onClick={handleToggleExpand}
            tabIndex={1}
          />
        </Tooltip> */}

        {/* <Tooltip title=' قفل ویرایش چینش' placement='bottom'>
          <button
            className={`chat-chatbox-header__layout-lock-toggle no-drag ${isLocked ? '' : 'active'
              }`}
            onClick={handleToggleLayoutLock}
            tabIndex={1}
          />
        </Tooltip> */}
      </div>
    </div >
  )
}

export default ChatSidebar
