import './style.scss'

import Menu from '@mui/material/Menu'
import editIcon from 'src/assets/editIcon2.svg'
import editIcon2White from 'src/assets/editIcon2White.svg'
import uploadIcon from 'src/assets/uploadIcon.svg'
import uploadIconWhite from 'src/assets/uploadIconWhite.svg'
import messageIcon from 'src/assets/chatIcon2.svg'
import messageIconWhite from 'src/assets/chatIcon2White.svg'
import pinIcon from 'src/assets/pinIcon.svg'
import pinIconWhite from 'src/assets/pinIconWhite.svg'
import deleteIcon from 'src/assets/trashIcon.svg'
import doneBlueIcon from 'src/assets/doneBlueIcon.svg'
import {
  deleteCollection,
  editCollection,
  selectCurrentCollection,
  selectCollections,
  setCurrentCollection,
  setModalsState,
  pinCollection,
} from 'src/pages/Chat/slice'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import { RootState } from 'src/lib/store'
import { FormEvent, useEffect, useRef, useState } from 'react'
import { t } from 'i18next'
import DeleteConfirmDialog from '../DeleteConfirmDialog'

interface IProps {
  menuAnchorEl: HTMLElement | null
  menuIds: { collectionId?: string; historyId?: string }
  onClose: () => void
  collectionId?: string
  historyId?: string
}

const ChatCardMenu = ({ menuAnchorEl, menuIds: { historyId, collectionId }, onClose }: IProps) => {
  const dispatch = useBDMDispatch()
  const currentCollection = useBDMSelector(selectCurrentCollection)
  const collections = useBDMSelector(selectCollections)
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const renameInputRef = useRef<HTMLInputElement>(null)
  const [isRenaming, setIsRenaming] = useState(false)
  const [renameValue, setRenameValue] = useState('')
  const [pinLoading, setPinLoading] = useState(false)
  // Captured on click because the parent clears menuIds as soon as the menu closes.
  const [deleteTarget, setDeleteTarget] = useState<{
    collectionId: string
    name: string
    stats: string[]
  } | null>(null)

  const resolvedCollectionId = collectionId ?? currentCollection?.collectionId
  const collection = resolvedCollectionId
    ? collections[resolvedCollectionId] ?? currentCollection
    : currentCollection

  const handleDelete = () => {
    if (!historyId && collectionId) {
      const target = collections[collectionId] ?? collection
      const historyCount = target?.collectionHistory?.length ?? 0
      const fileCount = target?.files?.length ?? 0
      setDeleteTarget({
        collectionId,
        name: target?.collectionName ?? '',
        stats: [
          `${historyCount.toLocaleString('fa-IR')} گفتگو`,
          ...(fileCount > 0 ? [`${fileCount.toLocaleString('fa-IR')} فایل`] : []),
        ],
      })
    }

    onClose()
  }

  const handleOpenUpload = () => {
    if (!resolvedCollectionId) {
      onClose()
      return
    }

    dispatch(setCurrentCollection(resolvedCollectionId))
    dispatch(setModalsState({ uploadFile: true }))
    onClose()
  }

  const handleCreateConversation = () => {
    if (!resolvedCollectionId) {
      onClose()
      return
    }

    dispatch(setCurrentCollection(resolvedCollectionId))
    dispatch(setModalsState({ createCollectionSession: true }))
    onClose()
  }

  const handleOpenRename = () => {
    if (!resolvedCollectionId || !collection) {
      onClose()
      return
    }

    setRenameValue(collection.collectionName)
    setIsRenaming(true)
  }

  const handleTogglePin = async () => {
    if (!resolvedCollectionId || pinLoading) return

    setPinLoading(true)
    try {
      await dispatch(pinCollection(resolvedCollectionId)).unwrap()
      onClose()
    } finally {
      setPinLoading(false)
    }
  }

  const handleRenameCollection = (event?: FormEvent) => {
    event?.preventDefault()

    if (!resolvedCollectionId || !collection) {
      onClose()
      return
    }

    const name = renameValue.trim()

    if (!name) {
      return
    }

    if (name === collection.collectionName) {
      setIsRenaming(false)
      onClose()
      return
    }

    dispatch(
      editCollection({
        collectionId: resolvedCollectionId,
        collectionData: { name },
      }),
    )
    onClose()
  }

  useEffect(() => {
    if (!menuAnchorEl) {
      setIsRenaming(false)
    }
  }, [menuAnchorEl])

  useEffect(() => {
    if (isRenaming) {
      renameInputRef.current?.focus()
      renameInputRef.current?.select()
    }
  }, [isRenaming])

  return (
    <>
    <Menu
      anchorEl={menuAnchorEl}
      open={Boolean(menuAnchorEl)}
      onClose={onClose}
      anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      transformOrigin={{ vertical: 'top', horizontal: 'right' }}
      sx={{ boxShadow: 'none !important' }}
      className='chat-sidebar-card-toggle-wrapper'
    >
      <div className='chat-sidebar-card-toggle'>
        {isRenaming ? (
          <form className='chat-sidebar-card-toggle__rename' onSubmit={handleRenameCollection}>
            <input
              ref={renameInputRef}
              value={renameValue}
              onChange={event => setRenameValue(event.target.value)}
              className='chat-sidebar-card-toggle__rename-input'
              dir='auto'
            />
            <button
              type='submit'
              className='chat-sidebar-card-toggle__rename-submit'
              aria-label={t('chat-confirm-project-name')}
            >
              <img src={doneBlueIcon} alt='' />
            </button>
          </form>
        ) : (
          <button type='button' className='chat-sidebar-card-toggle__item' onClick={handleOpenRename}>
            <img src={mode === 'light' ? editIcon : editIcon2White} className='chat-sidebar-card-toggle__item-icon' />
            <span>{t('chat-rename-project')}</span>
          </button>
        )}
        <button
          type='button'
          className='chat-sidebar-card-toggle__item'
          onClick={handleOpenUpload}
        >
          <img src={mode === 'light' ? uploadIcon : uploadIconWhite} className='chat-sidebar-card-toggle__item-icon' />
          <span>{t('chat-collection-upload-file-card-title')}</span>
        </button>
        <button
          type='button'
          className='chat-sidebar-card-toggle__item'
          onClick={handleCreateConversation}
        >
          <img src={mode === 'light' ? messageIcon : messageIconWhite} className='chat-sidebar-card-toggle__item-icon' />
          <span>{t('chat-create-conversation')}</span>
        </button>
        <button
          type='button'
          className='chat-sidebar-card-toggle__item'
          onClick={handleTogglePin}
          disabled={pinLoading}
        >
          <img src={mode === 'light' ? pinIcon : pinIconWhite} className='chat-sidebar-card-toggle__item-icon' />
          <span>{t(collection?.pinned ?? collection?.isPinned ? 'chat-unpin' : 'chat-pin')}</span>
        </button>
        <div className='chat-sidebar-card-toggle__divider' />
        <button
          type='button'
          className='chat-sidebar-card-toggle__item chat-sidebar-card-toggle__item--danger'
          onClick={handleDelete}
        >
          <img src={deleteIcon} className='chat-sidebar-card-toggle__item-icon' />
          <span>{t('delete')}</span>
        </button>
      </div>
    </Menu>
    <DeleteConfirmDialog
      isOpen={Boolean(deleteTarget)}
      kind='project'
      itemName={deleteTarget?.name ?? ''}
      stats={deleteTarget?.stats}
      onConfirm={() =>
        deleteTarget ? dispatch(deleteCollection(deleteTarget.collectionId)).unwrap() : undefined
      }
      onClose={() => setDeleteTarget(null)}
    />
    </>
  )
}

export default ChatCardMenu
