import { Dispatch, SetStateAction, useEffect, useRef } from 'react'
import PlusIcon from 'src/assets/PlusIcon.svg'
import PlusIconWhite from 'src/assets/PlusIconWhite.svg'
// import reasoningSelectIcon from 'src/assets/reasoningSelectIcon.svg'
// import reasoningSelectIconWhite from 'src/assets/reasoningSelectIconWhite.svg'
import textIcon from 'src/assets/textIcon.svg'
import textIconWhite from 'src/assets/textIconWhite.svg'
import csvIcon from 'src/assets/csvIcon.svg'
import uploadIcon from 'src/assets/uplaodBlackIcon.svg'
import './style.scss'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import {
    getUploadFiles,
    selectCollectionList,
    selectCurrentCollection,
    selectModalsState,
} from 'src/pages/Chat/slice'
import { getCollectionFileDisplayName } from 'src/pages/Chat/lib/utils'
import { RootState } from 'src/lib/store'
import { TQuickAction } from '../../serviceModes'
import { t } from 'i18next'
import { QUICK_ACTION_ITEMS } from '../../quickActionItems'

export interface ISecondarySourceItem {
    key: string
    title: string
    icon: string
}
export interface ITranslationLanguageItem {
    name: string
    enName: 'FA' | 'EN' | 'FR' | 'AR' | 'RU' | 'ZH' | 'HE'
}

const TRANSLATION_LANGUAGES: ITranslationLanguageItem[] = [
    { name: 'chat-language-persian', enName: 'FA' },
    { name: 'chat-language-english', enName: 'EN' },
    { name: 'chat-language-french', enName: 'FR' },
    { name: 'chat-language-arabic', enName: 'AR' },
    { name: 'chat-language-russian', enName: 'RU' },
    { name: 'chat-language-chinese', enName: 'ZH' },
    { name: 'chat-language-hebrew', enName: 'HE' },
]

interface IProps {
    isOpen: boolean
    setIsOpen: Dispatch<SetStateAction<boolean>>
    hasAtMention: boolean
    isSummarySourceOpen: boolean
    setIsSummarySourceOpen: Dispatch<SetStateAction<boolean>>
    isTranslationLangOpen: boolean
    setIsTranslationLangOpen: Dispatch<SetStateAction<boolean>>
    isTranslationSourceOpen: boolean
    setIsTranslationSourceOpen: Dispatch<SetStateAction<boolean>>
    onSelectAction: (action: TQuickAction) => void
    onSelectSecondarySource: (item: ISecondarySourceItem | null) => void
    onSelectTranslationLanguage: (lang: ITranslationLanguageItem) => void
    translationFileItems: ISecondarySourceItem[]
    onOpenAttachUpload: () => void
    selectedAction: TQuickAction | null
    isFileChatMode: boolean
    hasSelectedSecondarySource: boolean
    hasSelectedFile: boolean
    selectedFileIds: string[]
    fileSelectionDisabled: boolean
}

const QuickActions = ({
    isOpen,
    setIsOpen,
    hasAtMention,
    isSummarySourceOpen,
    setIsSummarySourceOpen,
    isTranslationLangOpen,
    setIsTranslationLangOpen,
    isTranslationSourceOpen,
    setIsTranslationSourceOpen,
    onSelectAction,
    onSelectSecondarySource,
    onSelectTranslationLanguage,
    translationFileItems,
    onOpenAttachUpload,
    selectedAction,
    isFileChatMode,
    hasSelectedSecondarySource,
    hasSelectedFile,
    selectedFileIds,
    fileSelectionDisabled,
}: IProps) => {
    const dispatch = useBDMDispatch()
    const quickActionsRef = useRef<HTMLDivElement>(null)
    const collectionList = useBDMSelector(selectCollectionList);
    const collectionId = useBDMSelector(selectCurrentCollection)?.collectionId;
    const isFileUploadOpen = useBDMSelector(selectModalsState).uploadFile

    const collection = collectionList.find(item => item.collectionId === collectionId)
    const fileList = collection?.files?.length
        ? collection.files.map(file => ({
            id: file.fileId,
            sourceId: file.fileId,
            label: getCollectionFileDisplayName(file),
        }))
        : (collection?.collectionGraph?.nodes ?? []).map(file => ({
            id: String(file.id),
            sourceId: String(file.nodeId ?? file.primaryKey ?? file.id),
            label: file.label,
        }))
    const selectableFileList = selectedAction === 'ocr'
        ? fileList?.filter(file => /\.(png|jpe?g|pdf|xls|xlsx)$/i.test(file.label))
        : selectedAction === 'reportGenerator'
            ? fileList?.filter(file => /\.(csv|xls|xlsx)$/i.test(file.label))
            : selectedAction === 'stt'
                ? fileList?.filter(file => /\.(mp3|wav|ogg|m4a|webm|flac|xls|xlsx)$/i.test(file.label))
                : fileList
    const canChooseAnotherFile = isFileChatMode || !hasSelectedFile
    // Project files are available as translation sources as well. Attachments
    // are the fallback for collection-less conversations.
    const translationSourceItems = fileList?.length
        ? fileList.map(file => ({ key: file.sourceId, title: file.label, icon: csvIcon }))
        : translationFileItems

    const mode = useBDMSelector((state: RootState) => state.theme.mode)

    const handleQuickActionSelect = (action: TQuickAction) => {
        onSelectAction(action)
        setIsOpen(false)
        setIsTranslationSourceOpen(false)
        onSelectSecondarySource(null)

        if (action === 'translation') {
            setIsSummarySourceOpen(false)
            setIsTranslationLangOpen(true)
            return
        }

        setIsTranslationLangOpen(false)
        setIsSummarySourceOpen(action !== 'letterWriter')
    }

    useEffect(() => {
        if (collectionId) {
            dispatch(getUploadFiles(collectionId))
        }
    }, [collectionId, dispatch])

    useEffect(() => {
        const handleOutsideClick = (e: MouseEvent) => {
            if (isFileChatMode && isFileUploadOpen) {
                return
            }

            if (!quickActionsRef.current?.contains(e.target as Node)) {
                setIsOpen(false)
                setIsSummarySourceOpen(false)
                setIsTranslationLangOpen(false)
                setIsTranslationSourceOpen(false)
            }
        }

        document.addEventListener('mousedown', handleOutsideClick)
        return () => document.removeEventListener('mousedown', handleOutsideClick)
    }, [isFileChatMode, isFileUploadOpen, setIsOpen, setIsSummarySourceOpen, setIsTranslationLangOpen])

    return (
        <div ref={quickActionsRef} className='chat-chatbox-plus-wrapper'>
            <button
                type='button'
                className={`chat-chatbox-plus-trigger ${isOpen ? 'active' : ''}`.trim()}
                onClick={e => {
                    e.stopPropagation()
                    setIsOpen(prev => !prev)
                    setIsSummarySourceOpen(false)
                    setIsTranslationLangOpen(false)
                    setIsTranslationSourceOpen(false)
                }}
            >
                {
                    mode === 'dark' ? <img src={PlusIconWhite} /> : <img src={PlusIcon} />
                }
            </button>
            <div
                className={`chat-chatbox-input-quick-actions ${isOpen ? 'is-open' : ''} ${hasAtMention ? 'is-open-secondry' : ''
                    }`.trim()}
                aria-hidden={!isOpen}
                onClick={e => e.stopPropagation()}
            >
                <div className='chat-chatbox-input-quick-actions-header'>
                    @
                    <span>CTRL + 2</span>
                </div>
                {QUICK_ACTION_ITEMS.map(item => (
                    <button
                        key={item.action}
                        type='button'
                        className='chat-chatbox-input-quick-actions__item'
                        onClick={() => handleQuickActionSelect(item.action)}
                    >
                        <img src={mode === 'light' ? item.icon : item.darkIcon} />
                        {t(item.labelKey)}
                    </button>
                ))}
                {/* <button
                    type='button'
                    className='chat-chatbox-input-quick-actions__item'
                    onClick={() => {
                        onSelectAction('reasoning')
                        setIsOpen(false)
                        setIsSummarySourceOpen(true)
                        setIsTranslationSourceOpen(false)
                        onSelectSecondarySource(null)
                    }}
                >
                    <img src={mode === 'light' ? reasoningSelectIcon : reasoningSelectIconWhite} />
                    استدلال
                </button> */}
            </div>
            <div
                className={`chat-chatbox-input-secondary-toggle ${isSummarySourceOpen ? 'is-open' : ''}`.trim()}
                aria-hidden={!isSummarySourceOpen}
                onClick={e => e.stopPropagation()}
            >
                {selectedAction !== 'ocr' && selectedAction !== 'stt' && !isFileChatMode && (
                    <button
                        type='button'
                        className='chat-chatbox-input-secondary-toggle__item-manual'
                        onClick={() => {
                            onSelectSecondarySource({ key: 'manual', title: t('chat-manual-text'), icon: textIcon })
                            setIsSummarySourceOpen(false)
                        }}
                    >
                        <img src={mode === 'light' ? textIcon : textIconWhite} />
                        {t('chat-manual-text')}
                    </button>
                )}
                {canChooseAnotherFile && !fileSelectionDisabled && (
                    <>
                        <div className='chat-chatbox-input-secondary-toggle__item-title'>{t('chat-files')}</div>
                        {selectableFileList?.map(file => (
                            <button
                                key={file.id}
                                type='button'
                                className={`chat-chatbox-input-secondary-toggle__item ${
                                    selectedFileIds.includes(file.sourceId) ? 'is-selected' : ''
                                }`.trim()}
                                aria-pressed={selectedFileIds.includes(file.sourceId)}
                                onClick={() => {
                                    onSelectSecondarySource({
                                        key: file.sourceId,
                                        title: file.label,
                                        icon: csvIcon,
                                    });
                                    if (!isFileChatMode) {
                                        setIsSummarySourceOpen(false);
                                    }
                                }}
                            >
                                <img src={csvIcon} alt={file.label} />
                                <span className='btn-truncate'>{file.label}</span>
                            </button>
                        ))}
                    </>
                )}
                {isSummarySourceOpen && canChooseAnotherFile && !fileSelectionDisabled && (
                    <button
                        type='button'
                        className='chat-chatbox-input-translation-source-upload-btn'
                        onClick={() => {
                            onOpenAttachUpload();
                            if (!isFileChatMode) {
                                setIsSummarySourceOpen(false);
                            }
                        }}
                    >
                        <img src={uploadIcon} />
                        {t('chat-upload-file')}
                    </button>
                )}
            </div>

            <div
                className={`chat-chatbox-input-translation-toggle ${isTranslationLangOpen ? 'is-open' : ''}`.trim()}
                aria-hidden={!isTranslationLangOpen}
                onClick={e => e.stopPropagation()}
            >
                <div className='chat-chatbox-input-translation-toggle__title'>{t('chat-languages')}</div>
                {TRANSLATION_LANGUAGES.map(language => (
                    <button
                        key={language.enName}
                        type='button'
                        className='chat-chatbox-input-translation-toggle__item'
                        onClick={() => {
                            onSelectTranslationLanguage(language)
                            setIsTranslationLangOpen(false)
                            setIsTranslationSourceOpen(!hasSelectedSecondarySource)
                        }}
                    >
                        <span>{t(language.name)}</span>
                        <span>{language.enName}</span>
                    </button>
                ))}
            </div>

            <div
                className={`chat-chatbox-input-translation-source-toggle ${isTranslationSourceOpen ? 'is-open' : ''
                    }`.trim()}
                aria-hidden={!isTranslationSourceOpen}
                onClick={e => e.stopPropagation()}
            >
                <button
                    type='button'
                    className='chat-chatbox-input-secondary-toggle__item-manual'
                    onClick={() => {
                        onSelectSecondarySource({ key: 'translation-manual', title: t('chat-manual-text'), icon: textIcon })
                        setIsTranslationSourceOpen(false)
                    }}
                >
                    <img src={mode === 'light' ? textIcon : textIconWhite} />
                    {t('chat-manual-text')}
                </button>
                <div className='chat-chatbox-input-secondary-toggle__item-title'>{t('chat-files')}</div>
                {translationSourceItems.map(file => (
                        <button
                            key={file.key}
                            type='button'
                            className='chat-chatbox-input-secondary-toggle__item'
                            onClick={() => {
                                onSelectSecondarySource(file)
                                setIsTranslationSourceOpen(false)
                            }}
                        >
                            <img src={file.icon} alt='' />
                            <span className='btn-truncate' title={file.title}>
                                {file.title}
                            </span>
                        </button>
                    ))}
                {isTranslationSourceOpen && (
                    <button
                        type='button'
                        className='chat-chatbox-input-translation-source-upload-btn'
                        onClick={() => {
                            onOpenAttachUpload()
                            setIsTranslationSourceOpen(false)
                        }}
                    >
                        <img src={uploadIcon} />
                        بارگذاری فایل
                    </button>
                )}
            </div>
        </div>
    )
}
export default QuickActions
