import { useState } from 'react'
import { t } from 'i18next'
import './style.scss'
import ThemeBlueColor from 'src/assets/ThemeBlueColor.svg'
import ThemeDarkColor from 'src/assets/ThemeDarkColor.svg'
import ThemeWhiteColor from 'src/assets/ThemeWhiteColor.svg'
import ThemeWhiteColor2 from 'src/assets/ThemeWhiteColor2.svg'

const colors = ['#6B46C1', '#3B82F6', '#F97316', '#F59E0B', '#10B981', '#9CA3AF', '#1F2937']
export const CONVERSATION_DRAFT_SETTINGS_KEY = 'chat-conversation-draft-settings'
type ConversationSettings = { enabled: boolean; backgroundColor: string; textColor: string; themeIndex: number; applyToAll: boolean }
const getSettings = (): ConversationSettings => {
  try { return { enabled: false, backgroundColor: colors[1], textColor: colors[6], themeIndex: 2, applyToAll: false, ...JSON.parse(localStorage.getItem(CONVERSATION_DRAFT_SETTINGS_KEY) ?? localStorage.getItem('chat-conversation-settings') ?? '{}') } } catch { return { enabled: false, backgroundColor: colors[1], textColor: colors[6], themeIndex: 2, applyToAll: false } }
}

const ConversationColors = () => {
  const initial = getSettings()
  const [isConversationColors, setIsConversationColors] = useState(initial.enabled)
  const [bgColor, setBgColor] = useState(initial.backgroundColor)
  const [textColor, setTextColor] = useState(initial.textColor)
  const [selectedThemeIndex, setSelectedThemeIndex] = useState(initial.themeIndex)
  const [applyToAll, setApplyToAll] = useState(initial.applyToAll)
  const themes = [ThemeWhiteColor, ThemeDarkColor, ThemeBlueColor]
  const saveDraft = (overrides: Partial<ConversationSettings> = {}) => localStorage.setItem(CONVERSATION_DRAFT_SETTINGS_KEY, JSON.stringify({ enabled: isConversationColors, backgroundColor: bgColor, textColor, themeIndex: selectedThemeIndex, applyToAll, ...overrides }))
  const selectTheme = (index: number) => {
    const palette = [{ backgroundColor: '#F8FAFC', textColor: '#1F2937' }, { backgroundColor: '#1F2937', textColor: '#F8FAFC' }, { backgroundColor: '#3B82F6', textColor: '#FFFFFF' }][index]
    setSelectedThemeIndex(index); setBgColor(palette.backgroundColor); setTextColor(palette.textColor); saveDraft({ themeIndex: index, ...palette })
  }
  return (
    <div className='conversation'>
      {/* Header */}
      <div className='background-item'>
        <div className='background-item__text'>
          <p className='title'>{t('chat-conversation-colors-title')}</p>
          <p className='desc'>{t('chat-conversation-colors-description')}</p>
        </div>

        <span
          onClick={() => setIsConversationColors(prev => { const next = !prev; saveDraft({ enabled: next }); return next })}
          className={`theme-toggle__switch ${isConversationColors ? 'active' : ''}`}
        >
          <span className='theme-toggle__switch-thumb' />
        </span>
      </div>

      {/* Content */}
      {isConversationColors && (
        <div className='conversation__content'>
          {/* Themes preview */}
          <div className='themes'>
            {themes.map((item, index) => (
              <button
                key={item}
                type='button'
                className={`theme-card ${selectedThemeIndex === index ? 'is-active' : ''}`}
                onClick={() => selectTheme(index)}
              >
                <img src={item} alt='' />
              </button>
            ))}
          </div>
          <div className='wrapper-color-section-preview'>
            {/* Preview */}
            <div className='preview'>
              <img src={ThemeWhiteColor2} style={{ backgroundColor: bgColor }} />
            </div>
            {/* Color Pickers */}
            <div className='color-section'>
              <div className='color-row border-b-row'>
                <span>{t('chat-message-background-color')}</span>
                <div className='colors'>
                  {colors.map((c, i) => (
                    <span
                      key={i}
                      style={{ background: c }}
                      className={bgColor === c ? 'active' : ''}
                      onClick={() => { setBgColor(c); saveDraft({ backgroundColor: c }) }}
                    />
                  ))}
                </div>
              </div>

              <div className='color-row border-b-row'>
                <span>{t('chat-message-text-color')}</span>
                <div className='colors'>
                  {colors.map((c, i) => (
                    <span
                      key={i}
                      style={{ background: c }}
                      className={textColor === c ? 'active' : ''}
                      onClick={() => { setTextColor(c); saveDraft({ textColor: c }) }}
                    />
                  ))}
                </div>
              </div>

              <div className='apply-all'>
                <span>{t('chat-apply-to-all')}</span>
                <span
                  className={`switch small ${applyToAll ? 'active' : ''}`}
                  onClick={() => setApplyToAll(prev => { const next = !prev; saveDraft({ applyToAll: next }); return next })}
                >
                  <span className='thumb' />
                </span>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

export default ConversationColors
