// Generates Long id (compatible with backend id system)
export default () => {
  const max = 100_000_000_000_000
  const min = 10_000_000_000_000
  const subNumber = Math.floor(Math.random() * (500000 - 100000) + 100000)
  return String(Math.floor(Math.random() * (max - min) + min + subNumber))
}
