import { useEffect } from 'react'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import {
  resetStore,
  selectStream,
  selectResponseWaitingSessions,
  updateMessage,
  syncSocketMessageAttachments,
  resolvePendingAttachments,
  setChatResponseLoadingState,
  addSessionResponseWaiting,
  removeSessionResponseWaiting,
  setChaStreamingLoadingState,
  setHistoryAnswerStatus,
  selectCurrentHistory,
  removeStreamSessions,
} from 'src/pages/Chat/slice'
import { useChatState } from '../lib/useChatState'
import { CHAT_ANSWER_STATUS, CHAT_HISTORY_STATE } from 'src/types/NewChat'
import { isAnswerPendingStatus, isAnswerPendingType } from './streamStatus'

const useChatStream = () => {
  const dispatch = useBDMDispatch()
  const stream = useBDMSelector(selectStream)
  const waitingList = useBDMSelector(selectResponseWaitingSessions)
  const historyId = useBDMSelector(selectCurrentHistory)?.historyId
  useChatState()

  useEffect(() => {
    const streamEntries = Object.entries(stream).filter(
      (entry): entry is [string, NonNullable<typeof stream[string]>] =>
        Array.isArray(entry[1]) && Boolean(entry[1][1]),
    )

    const loadingSessions = streamEntries
      .filter(
        ([, [, answer]]) =>
          answer.answerStatus === undefined
            ? isAnswerPendingType(answer.type)
            : isAnswerPendingStatus(answer.answerStatus),
      )
      .map(([sessionId]) => sessionId)

    if (loadingSessions.length > 0) {
      dispatch(addSessionResponseWaiting(loadingSessions))
    }

    const streamSessions = streamEntries
      .map(([sessionId]) => sessionId)
      .filter(session => !loadingSessions.includes(session))

    if (streamSessions.length > 0) {
      dispatch(removeSessionResponseWaiting(streamSessions))
    }

    if (!historyId) {
      return
    }

    const isStreaming = streamSessions.includes(historyId)
    const isWaiting = loadingSessions.includes(historyId)
    const streamItem = stream[historyId]
    const request = Array.isArray(streamItem) ? streamItem[0] : undefined
    const socketAnswer = Array.isArray(streamItem) ? streamItem[1] : undefined
    const uploadedFileIds = request?.attachments
      ?.map(attachment =>
        typeof attachment === 'string' ? attachment : attachment.fileId || attachment._id,
      )
      .filter((fileId): fileId is string => Boolean(fileId))

    if (request && uploadedFileIds?.length) {
      dispatch(resolvePendingAttachments(uploadedFileIds))
      dispatch(syncSocketMessageAttachments(request))
    }

    if (socketAnswer?.answerStatus) {
      dispatch(setHistoryAnswerStatus({ historyId, answerStatus: socketAnswer.answerStatus }))
    }

    dispatch(setChatResponseLoadingState(isWaiting))
    dispatch(setChaStreamingLoadingState(isStreaming))

    if (!isStreaming && !isWaiting) {
      dispatch(removeSessionResponseWaiting([historyId]))
      return
    }

    // A streaming socket event contains the current partial assistant answer.
    // Keep the message in Redux up to date on every event, rather than waiting
    // for the terminal `completed` event. `updateMessage` replaces the previous
    // version by id, so an accumulated stream stays a single chat bubble.
    if (isWaiting && socketAnswer) {
      dispatch(updateMessage(socketAnswer))
    }

    if (isStreaming) {
      const answer = socketAnswer

      if (answer) {
        dispatch(updateMessage(answer))
        dispatch(
          setHistoryAnswerStatus({
            historyId,
            answerStatus:
              answer.answerStatus ??
              (String(answer.type) === CHAT_HISTORY_STATE.FAILURE
                ? CHAT_ANSWER_STATUS.FAILED
                : CHAT_ANSWER_STATUS.COMPLETED),
          }),
        )
        dispatch(removeStreamSessions([historyId]))
        dispatch(setChaStreamingLoadingState(false))
      }
    }
  }, [historyId, JSON.stringify(stream)])

  useEffect(() => {
    if (!historyId) {
      return
    }
    const isWaiting = waitingList.includes(historyId)
    dispatch(setChatResponseLoadingState(isWaiting))
  }, [historyId, JSON.stringify(waitingList)])

  useEffect(() => {
    return () => {
      dispatch(resetStore())
    }
  }, [])
}

export default useChatStream
