import './style.scss'
import { ReactNode } from 'react'
import { t } from 'i18next'

type ExpandableListProps<T> = {
  items: T[]
  renderItem: (item: T, index: number) => ReactNode
  getItemId: (item: T) => string | number
}

export function ExpandableList<T>({
  items,
  renderItem,
  getItemId,
}: ExpandableListProps<T>) {
  if (items.length === 0) {
    return (
      <div className='chat-sidebar-expandable-list'>
        <p className='chat-sidebar-expandable-list__not-found'>{t('chat-no-items')}</p>
      </div>
    )
  }

  return (
    <div className='chat-sidebar-expandable-list'>
      <div className='chat-sidebar-expandable-items'>
        {items.slice().map((item, index) => (
          <div key={`${getItemId(item)}:${index}`}>{renderItem(item, index)}</div>
        ))}
      </div>
    </div>
  )
}

export default ExpandableList
