interface IProps {
  collection: IChatCollection
  isMenuOpen?: boolean
  onNavigate?: () => void
  menuAnchorEl: HTMLElement | null
  menuIds: { collectionId?: string; historyId?: string }
  onOpenMenu: (
    e: React.MouseEvent<HTMLElement>,
    menuIds: { collectionId?: string; historyId?: string },
  ) => void
}

const getFileTypeIcon = (file: IChatSessionFileUploadItem) => {
  const filename = file.filename || file.originalName || ''
  const extension = filename.split('.').pop()?.toLowerCase()

  if (extension === 'csv' || file.mimeType === 'text/csv') return csvFileIcon
  if (['xls', 'xlsx'].includes(extension ?? '')) return excelFileIcon
  if (extension === 'parquet') return parquetFileIcon
  if (extension === 'pdf' || file.mimeType === 'application/pdf') return pdfFileIcon
  if (['mp4', 'mov', 'avi', 'mkv', 'webm'].includes(extension ?? '') || file.mimeType?.startsWith('video/')) {
    return mp4FileIcon
  }
  if (['yaml', 'yml'].includes(extension ?? '')) return yamlFileIcon
  if (
    ['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg'].includes(extension ?? '') ||
    file.mimeType?.startsWith('image/')
  ) {
    return imageFileIcon
  }
  if (['txt', 'md', 'markdown', 'json'].includes(extension ?? '') || file.mimeType === 'text/plain') {
    return textFileIcon
  }

  return unknownFileIcon
}

const CollectionCard = ({
  onOpenMenu,
  collection,
  isMenuOpen = false,
  menuAnchorEl,
  menuIds,
  onNavigate,
}: IProps) => {
  const isLtr = document.documentElement.dir === 'ltr'
  const dispatch = useBDMDispatch()
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const currentCollection = useBDMSelector(selectCurrentCollection)
  const isFilesLoading = useBDMSelector(selectLoadingState).collectionFiles
  const isSelected = collection.collectionId === currentCollection?.collectionId

  const [expanded, setExpanded] = useState(() => isSelected)
  const [showHistoryList, setShowHistoryList] = useState(false)
  const [filesAnchorEl, setFilesAnchorEl] = useState<HTMLElement | null>(null)
  const [fileMenuAnchorEl, setFileMenuAnchorEl] = useState<HTMLElement | null>(null)
  const [activeFileName, setActiveFileName] = useState('')
  const [activeFileId, setActiveFileId] = useState<string>('')
  const [isDownloadingFile, setIsDownloadingFile] = useState(false)
  const [isRenamingFile, setIsRenamingFile] = useState(false)
  const [renameFileValue, setRenameFileValue] = useState('')
  const [isRenameFileLoading, setIsRenameFileLoading] = useState(false)
  const renameFileInputRef = useRef<HTMLInputElement>(null)
  const [previewFile, setPreviewFile] = useState<IChatSessionFileUploadItem | null>(null)

  // const isDone = collection.state === CHAT_COLLECTION_STATE.DONE
  const isFailure = collection.state === CHAT_COLLECTION_STATE.FAILURE
  const isPending = collection.state === CHAT_COLLECTION_STATE.PENDING
  const isPinned = Boolean(collection.pinned ?? collection.isPinned)
  const collectionIcon = collection.color && collection.icon ? collection.icon : collectionCloseCard

  const clss = `chat-chatbox-collection-card ${isSelected ? 'is-selected' : ''} ${isMenuOpen ? 'is-menu-open' : ''
    } ${isPending ? 'is-pending' : ''} ${isFailure ? 'is-failure' : ''}`

  const handleExpandAccordion = (_: React.SyntheticEvent, isExpanded: boolean) => {
    setExpanded(isExpanded)

    if (!isExpanded && isSelected) {
      dispatch(clearCurrentState())
      setShowHistoryList(false)
    }
  }

  const handleSelectCollection = (e: MouseEvent<HTMLDivElement>) => {
    e.preventDefault()
    e.stopPropagation()

    if (isSelected) {
      dispatch(clearCurrentState())
      setExpanded(false)
      setShowHistoryList(false)
      onNavigate?.()
      return
    }

    dispatch(setCurrentCollection(collection.collectionId))
    onNavigate?.()
  }

  const handleMenu = (e: MouseEvent<HTMLElement>) => {
    e.preventDefault()
    e.stopPropagation()
    onOpenMenu(e, { collectionId: collection.collectionId ?? undefined, historyId: undefined })
  }

  const handleToggleConversations = (e: MouseEvent<HTMLButtonElement>) => {
    e.preventDefault()
    e.stopPropagation()
    dispatch(setCurrentCollection(collection.collectionId))
    setShowHistoryList(prev => !prev)
  }

  useEffect(() => {
    setExpanded(isSelected)

    if (!isSelected) {
      setShowHistoryList(false)
    }
  }, [isSelected])

  const historyCount = collection.collectionHistory?.length ?? 0
  const graphFiles = collection.collectionGraph?.nodes ?? []

  function getFileDisplayName(file: (typeof graphFiles)[number]) {
    const location = file.dataLocation as unknown

    if (typeof location === 'string') {
      return location.split('/').filter(Boolean).pop() || file.label
    }

    if (
      location &&
      typeof location === 'object' &&
      'address' in location &&
      typeof (location as { address?: unknown }).address === 'string'
    ) {
      const address = (location as { address: string }).address
      return address.split('/').filter(Boolean).pop() || file.label
    }

    return file.label
  }

  const collectionFiles = collection.files?.length
    ? collection.files
    : graphFiles.map(file => ({
      _id: String(file.id),
      fileId: String(file.nodeId ?? file.id),
      filename: getFileDisplayName(file),
      originalName: getFileDisplayName(file),
      size: 0,
      mimeType: '',
      state: 'done',
      fullPath: typeof file.filePath === 'string' ? file.filePath : '',
      uploadedAt: '',
    }))
  const fileCount = collectionFiles.length

  useEffect(() => {
    if (fileCount === 0) {
      setFilesAnchorEl(null)
    }
  }, [fileCount])

  const handleOpenFiles = (e: MouseEvent<HTMLButtonElement>) => {
    e.preventDefault()
    e.stopPropagation()

    if (fileCount === 0) {
      return
    }

    dispatch(setCurrentCollection(collection.collectionId))

    if (filesAnchorEl) {
      setFilesAnchorEl(null)
      setFileMenuAnchorEl(null)
      // setActiveFileName('')
      setActiveFileId('')
      return
    }

    setFilesAnchorEl(e.currentTarget)
    dispatch(getUploadFiles(collection.collectionId))
  }

  const truncateWords = (value?: string | null, maxWords = 10) => {
    const safeValue = value?.trim() || t<string>('chat-unnamed-file')
    const words = safeValue.split(/\s+/)

    if (words.length <= maxWords) {
      return safeValue
    }

    return `${words.slice(0, maxWords).join(' ')}...`
  }

  const handleOpenFileMenu = (
    e: MouseEvent<HTMLButtonElement>,
    params: { id: string; name: string },
  ) => {
    e.preventDefault()
    e.stopPropagation()
    setActiveFileName(params.name)
    setActiveFileId(params.id)
    setFileMenuAnchorEl(e.currentTarget)
  }

  const handleCloseFileMenu = () => {
    setFileMenuAnchorEl(null)
    setActiveFileName('')
    setActiveFileId('')
    setIsRenamingFile(false)
    setRenameFileValue('')
  }

  const handleCloseFilesPopover = () => {
    setFilesAnchorEl(null)
    handleCloseFileMenu()
  }

  const handleFileQuickAction = async (action: TQuickAction) => {
    const file = collectionFiles.find(item => String(item.fileId) === activeFileId)

    if (!file) {
      addAToast(t('chat-selected-file-not-found'), 'error')
      handleCloseFileMenu()
      return
    }

    await dispatch(setCurrentCollection(collection.collectionId))
    dispatch(
      requestFileQuickAction({
        requestId: Date.now(),
        action,
        source: {
          key: String(file.fileId),
          title: file.filename || file.originalName || t('chat-unnamed-file'),
          mimeType: file.mimeType,
        },
      }),
    )
    handleCloseFilesPopover()
  }

  const handleCreateConversation = () => {
    dispatch(setCurrentCollection(collection.collectionId))
    dispatch(setModalsState({ createCollectionSession: true }))
    handleCloseFilesPopover()
  }

  const handleOpenFileRename = () => {
    setRenameFileValue(activeFileName)
    setIsRenamingFile(true)
  }

  const handleRenameFile = async (event: FormEvent) => {
    event.preventDefault()

    const filename = renameFileValue.trim()
    if (!activeFileId || !filename || isRenameFileLoading) {
      return
    }

    if (filename === activeFileName) {
      setIsRenamingFile(false)
      return
    }

    setIsRenameFileLoading(true)

    try {
      const response = await ChatAPIs().renameUploadFile({
        fileId: activeFileId,
        filename,
      })

      if (!response.data?.success) {
        throw new Error(response.data?.message || 'ویرایش نام فایل انجام نشد.')
      }

      await dispatch(getUploadFiles(collection.collectionId)).unwrap()
      addAToast(response.data.message || 'نام فایل با موفقیت ویرایش شد.', 'success')
      handleCloseFileMenu()
    } catch (error) {
      addAToast(error instanceof Error ? error.message : 'ویرایش نام فایل انجام نشد.', 'error')
    } finally {
      setIsRenameFileLoading(false)
    }
  }

  useEffect(() => {
    if (isRenamingFile) {
      renameFileInputRef.current?.focus()
      renameFileInputRef.current?.select()
    }
  }, [isRenamingFile])

  const handleDownloadFile = async () => {
    if (!activeFileId || isDownloadingFile) {
      return
    }

    setIsDownloadingFile(true)

    try {
      const response = await ChatAPIs().downloadUploadFile(activeFileId)
      const responseData = response.data as Blob | { message?: unknown }

      if (
        responseData instanceof Blob &&
        (response.status < 200 || response.status >= 300 || responseData.type.includes('json'))
      ) {
        let responseMessage: string | undefined

        try {
          const errorPayload = JSON.parse(await responseData.text()) as { message?: unknown }
          responseMessage =
            typeof errorPayload.message === 'string' ? errorPayload.message : undefined
        } catch {
          // The error response was not JSON; use the generic fallback below.
        }

        throw new Error(responseMessage || 'دانلود فایل ناموفق بود.')
      }

      if (!(responseData instanceof Blob)) {
        const responseMessage =
          typeof responseData?.message === 'string' ? responseData.message : undefined

        throw new Error(responseMessage || 'دانلود فایل ناموفق بود.')
      }

      const objectUrl = URL.createObjectURL(responseData)
      const link = document.createElement('a')
      link.href = objectUrl
      link.download = activeFileName || `file-${activeFileId}`
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(objectUrl)
      handleCloseFileMenu()
    } catch (error) {
      addAToast(error instanceof Error ? error.message : 'دانلود فایل ناموفق بود.', 'error')
    } finally {
      setIsDownloadingFile(false)
    }
  }

  const handleDeleteCollectionFile = async () => {
    if (!activeFileId) {
      handleCloseFileMenu()
      return
    }

    const res = await ChatAPIs().deleteCollectionFile({
      collectionId: collection.collectionId,
      fileId: activeFileId,
    })

    if (res.data?.success) {
      addAToast(res.data.message || 'فایل با موفقیت حذف شد.', 'success')
      await dispatch(getCollections())
      await dispatch(getUploadFiles(collection.collectionId))
      setPreviewFile(prev => prev?.fileId === activeFileId ? null : prev)
      handleCloseFileMenu()
      return
    }

    addAToast(res.data?.message || 'خطا در حذف فایل', 'error')
  }

  return (
    <div className={clss} onContextMenu={handleMenu}>
      <Accordion expanded={expanded} onChange={handleExpandAccordion}>
        <AccordionSummary onClick={handleSelectCollection} onContextMenu={handleMenu}>
          <div className='chat-chatbox-collection-card-info'>
            <div className='chat-chatbox-collection-card-expand-icon'>
              {/* <img
                src={expanded ? collectionOpenCard : collectionCloseCard}
                alt={expanded ? 'close' : 'open'}
              /> */}
              <img src={collectionIcon} alt='collection' />
            </div>
            <p>{collection.collectionName}</p>
            {isPinned && (
              <img
                className='chat-chatbox-collection-card-pin-icon'
                src={mode === 'light' ? pinIconActive : pinIconActiveWhite}
                width={14}
                height={14}
                alt={t('chat-pinned')}
              />
            )}
          </div>

          <span className='chat-chatbox-collection-card-meun-icon' onClick={handleMenu}>
            <img src={mode === 'light' ? dotsMenuIcon : dotsMenuIconWhite} width={16} height={16} alt='menu' loading='lazy' />
          </span>
          {isPending && <LinearProgress sx={{ color: '#000' }} />}
        </AccordionSummary>
        <AccordionDetails className='chat-chatbox-collection-card-detail'>
          <button
            type='button'
            className='chat-chatbox-collection-card-submenu'
            onClick={handleOpenFiles}
            disabled={fileCount === 0}
          >
            <div className='chat-chatbox-collection-card-submenu-wrapper'>
              <img src={mode === 'light' ? linkIcon : linkIconWhite} alt='files' className='chat-chatbox-collection-card-submenu-icon' />
              <span className='chat-chatbox-collection-card-submenu-title'>{t('chat-files')}</span>
            </div>
            <span className='chat-chatbox-collection-card-submenu-count'>{fileCount}</span>
          </button>

          <button
            type='button'
            className='chat-chatbox-collection-card-submenu'
            onClick={handleToggleConversations}
          >
            <div className='chat-chatbox-collection-card-submenu-wrapper'>
              <img src={mode === 'light' ? chatIcon : chatIcon2White} alt='conversations' className='chat-chatbox-collection-card-submenu-icon' />
              <span className='chat-chatbox-collection-card-submenu-title'>{t('chat-conversations')}</span>
            </div>
            <span className='chat-chatbox-collection-card-submenu-count'>{historyCount}</span>
          </button>

          {showHistoryList &&
            collection?.collectionHistory?.map(history => (
              <HistoryCard
                key={history.historyId}
                history={history}
                onNavigate={onNavigate}
                onOpenMenu={onOpenMenu}
                isMenuOpen={
                  Boolean(menuAnchorEl) &&
                  Boolean(menuIds.historyId) &&
                  menuIds.historyId === history.historyId
                }
              />
            ))}
        </AccordionDetails>
      </Accordion>

      <Menu
        anchorEl={filesAnchorEl}
        open={Boolean(filesAnchorEl)}
        onClose={handleCloseFilesPopover}
        anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
        transformOrigin={{ vertical: 'top', horizontal: 'right' }}
        className='chat-chatbox-collection-files-menu'
      >
        <div className='chat-chatbox-collection-files-menu__list'>
          {isFilesLoading && (
            <div className='chat-chatbox-collection-files-menu__loading'>
              <CircularProgress size={20} />
            </div>
          )}

          {!isFilesLoading &&
            collectionFiles.map(file => {
              const fullName = file.filename || file.originalName || t('chat-unnamed-file')
              const shortName = truncateWords(fullName, 10)

              return (
                <div
                  key={file.fileId}
                  className={`chat-chatbox-collection-files-menu__item ${activeFileId === String(file.fileId) ? 'is-active' : ''
                    }`}
                  onClick={() => {
                    setPreviewFile(file)
                    handleCloseFilesPopover()
                  }}
                >
                  <button
                    type='button'
                    className='chat-chatbox-collection-files-menu__item-dots'
                    onClick={e => {
                      e.stopPropagation()
                      handleOpenFileMenu(e, {
                        id: String(file.fileId),
                        name: fullName,
                      })
                    }}
                  >
                    <img src={mode === 'light' ? dotsMenuIcon : dotsMenuIconWhite} alt='actions' />
                  </button>
                  <Tooltip title={fullName} placement='top' arrow>
                    <span className='chat-chatbox-collection-files-menu__item-name' dir='auto'>
                      {shortName}
                    </span>
                  </Tooltip>
                  <img
                    src={getFileTypeIcon(file)}
                    alt='file'
                    className='chat-chatbox-collection-files-menu__item-type-icon'
                  />
                </div>
              )
            })}

          {!isFilesLoading && collectionFiles.length === 0 && (
            <div className='chat-chatbox-collection-files-menu__empty'>{t('chat-no-files')}</div>
          )}
        </div>
      </Menu>
      <FilePreviewDrawer
        file={previewFile}
        collectionId={collection.collectionId}
        open={Boolean(previewFile)}
        onClose={() => setPreviewFile(null)}
      />

      <Menu
        anchorEl={fileMenuAnchorEl}
        open={Boolean(fileMenuAnchorEl)}
        onClose={handleCloseFileMenu}
        anchorOrigin={{ vertical: 'top', horizontal: isLtr ? 'right' : 'left' }}
        transformOrigin={{ vertical: 'top', horizontal: isLtr ? 'left' : 'right' }}
        className={`chat-chatbox-collection-file-actions-menu ${isLtr ? 'is-ltr' : ''}`}
      >
        <div className='chat-chatbox-collection-file-actions-menu__list'>
          {isRenamingFile ? (
            <form
              className='chat-chatbox-collection-file-actions-menu__rename'
              onSubmit={handleRenameFile}
            >
              <input
                ref={renameFileInputRef}
                value={renameFileValue}
                onChange={event => setRenameFileValue(event.target.value)}
                className='chat-chatbox-collection-file-actions-menu__rename-input'
                dir='auto'
                disabled={isRenameFileLoading}
              />
              <button
                type='submit'
                className='chat-chatbox-collection-file-actions-menu__rename-submit'
                aria-label={t('chat-confirm-file-name')}
                disabled={!renameFileValue.trim() || isRenameFileLoading}
              >
                <img src={doneBlueIcon} alt='' />
              </button>
            </form>
          ) : (
            <button
              type='button'
              className='chat-chatbox-collection-file-actions-menu__item'
              onClick={handleOpenFileRename}
            >
              <span>{t('chat-rename-file')}</span>
              <img src={mode === 'light' ? editIcon : editIconWhite} alt='rename' />
            </button>
          )}
          <button
            type='button'
            className='chat-chatbox-collection-file-actions-menu__item'
            onClick={handleCreateConversation}
          >
            <span>{t('chat-create-conversation')}</span>
            <img src={mode === 'light' ? chatIcon : chatIcon2White} alt='create chat' />
          </button>
          <button
            type='button'
            className='chat-chatbox-collection-file-actions-menu__item'
            onClick={() => handleFileQuickAction('summarizing')}
          >
            <span>{t('chat-action-summarize')}</span>
            <img src={mode === 'light' ? summarizing : summarizingWhite} alt='summary' />
          </button>
          <button
            type='button'
            className='chat-chatbox-collection-file-actions-menu__item'
            onClick={() => handleFileQuickAction('keywords')}
          >
            <span>{t('chat-action-keywords')}</span>
            <img src={mode === 'light' ? keyIcon : keyIconWhite} alt='keywords' />
          </button>
          <button
            type='button'
            className='chat-chatbox-collection-file-actions-menu__item'
            onClick={() => handleFileQuickAction('meetingMinutes')}
          >
            <span>{t('chat-action-meeting-minutes')}</span>
            <img src={mode === 'light' ? meetingMinutes : meetingMinutesWhite} alt='minutes' />
          </button>
          {/* <button
            type='button'
            className='chat-chatbox-collection-file-actions-menu__item'
            onClick={() => handleFileQuickAction('reportGenerator')}
          >
            <span>{t('chat-action-report-generator')}</span>
            <img src={mode === 'light' ? reportIcon : reportIconWhite} alt='report' />
          </button> */}
          {QUICK_ACTION_ITEMS.filter(
            item =>
              !['summarizing', 'keywords', 'meetingMinutes', 'reportGenerator'].includes(
                item.action,
              ),
          ).map(item => (
            <button
              key={item.action}
              type='button'
              className='chat-chatbox-collection-file-actions-menu__item'
              onClick={() => handleFileQuickAction(item.action)}
            >
              <span>{t(item.labelKey)}</span>
              <img
                src={mode === 'light' ? item.icon : item.darkIcon}
                alt={t(item.labelKey)}
              />
            </button>
          ))}
          <button
            type='button'
            className='chat-chatbox-collection-file-actions-menu__item'
            onClick={handleDownloadFile}
            disabled={isDownloadingFile}
          >
            <span>{isDownloadingFile ? t('chat-downloading-file') : t('chat-download-file')}</span>
            <img
              src={mode === 'light' ? exportFileIcon : exportFileIconWhite}
              alt='download'
            />
          </button>
          <div className='chat-chatbox-collection-file-actions-menu__divider' />
          <button
            type='button'
            className='chat-chatbox-collection-file-actions-menu__item chat-chatbox-collection-file-actions-menu__item--danger'
            onClick={handleDeleteCollectionFile}
          >
            <span>{t('delete')}</span>
            <img src={deleteIcon} alt='delete' />
          </button>
        </div>
      </Menu>
    </div>
  )
}

export default CollectionCard
