import { persistor } from '../store'

export function deleteStorage() {
  sessionStorage.clear()
  localStorage.removeItem('bdm-token-dont-touch')
  localStorage.removeItem('bdm-map-search-box-history')
  localStorage.removeItem('bdm-navbar')
  localStorage.removeItem('bdm-table-view')
  localStorage.removeItem('bdm-tabs')
  localStorage.removeItem('bdm-graph-data')
  persistor.purge()
}

export async function logout() {
  deleteStorage()
  // await new Promise(resolve => setTimeout(resolve, 1000))
  window.location.href = '/'
}

export default logout
