import { useState, DragEvent, useCallback } from 'react'

interface IProps {
  handleFiles: (files: File[]) => void
  acceptTypes?: string[]
}

const useDragFile = ({ handleFiles, acceptTypes }: IProps) => {
  const [isDragging, setIsDragging] = useState(false)

  const onDragEnter = useCallback((e: DragEvent<HTMLElement>) => {
    e.preventDefault()
    setIsDragging(true)
  }, [])

  const onDragOver = useCallback((e: DragEvent<HTMLLabelElement>) => {
    e.preventDefault()
    setIsDragging(true)
  }, [])

  const onDragLeave = useCallback((e: DragEvent<HTMLLabelElement>) => {
    e.preventDefault()
    setIsDragging(false)
  }, [])

  const onDrop = useCallback(
    (e: DragEvent<HTMLLabelElement>) => {
      e.preventDefault()
      setIsDragging(false)
      if (!e.dataTransfer.files?.length) {
        return
      }

      let files = Array.from(e.dataTransfer.files)

      if (acceptTypes && acceptTypes.length > 0) {
        files = files.filter(
          file =>
            acceptTypes.includes(file.type) ||
            acceptTypes.some(type => file.name.toLowerCase().endsWith(type)),
        )
      }

      if (files.length > 0) {
        handleFiles(files)
      }

      e.dataTransfer.clearData()
    },
    [handleFiles, acceptTypes],
  )

  return { isDragging, setIsDragging, onDragEnter, onDragOver, onDragLeave, onDrop }
}

export default useDragFile
