import './style.scss'
import { t } from 'i18next'
import { useState, useCallback, useEffect, useRef } from 'react'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import { selectModalsState, setModalsState } from 'src/pages/Chat/slice'

import Modal from '@mui/material/Modal'
import Button from 'src/components/Button'
import TextNewInput from 'src/components/TextNewInput'
import closeIcon from 'src/assets/closeIcon.svg'
import closeIconWhite from 'src/assets/closeIconWhite.svg'
import userIcon from 'src/assets/userIcon2.svg'
import userIcon2White from 'src/assets/userIcon2White.svg'
// import pictureIcon from 'src/assets/pictureIcon.svg'
import chatAvatarIcon from 'src/assets/chatAvatarIcon.svg'
import { Divider } from '@mui/material'
import { RootState } from 'src/lib/store'
import userAPIs from 'src/api/user'

type Profile = {
  firstname: string
  lastname: string
  email: string
}

const ProfileModal = () => {
  const dispatch = useBDMDispatch()
  const isOpen = useBDMSelector(selectModalsState).openProfileModal
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const [profile, setProfile] = useState<Profile>({ firstname: '', lastname: '', email: '' })
  const contentRef = useRef<HTMLFormElement>(null)

  const handleClose = useCallback(() => {
    dispatch(setModalsState({ openProfileModal: false }))
  }, [dispatch])

  useEffect(() => {
    if (!isOpen) return

    let isMounted = true
    contentRef.current?.focus()

    userAPIs
      .getProfile()
      .then(response => {
        if (!isMounted || !response.data?.success || !response.data.profile) return

        const apiProfile = response.data.profile
        setProfile({
          firstname: apiProfile.firstname ?? apiProfile.first_name ?? '',
          lastname: apiProfile.lastname ?? apiProfile.last_name ?? '',
          email: apiProfile.email ?? '',
        })
      })
      .catch(error => console.error('Failed to load user profile', error))

    return () => {
      isMounted = false
    }
  }, [isOpen])

  return (
    <Modal
      open={isOpen}
      onClose={handleClose}
      className='profile-modal'
      BackdropProps={{
        sx: {
          backdropFilter: 'blur(5px)',
          backgroundColor: '#09090B4D',
        },
      }}
    >
      <form className='profile-modal__content' ref={contentRef} tabIndex={-1}>
        <div className='profile-modal__header'>
          <div className='profile-modal__title'>
            <img src={mode === 'light' ? userIcon : userIcon2White} />
            <p className='profile-modal__title-p'>{t('chat-sidebar-profile-title')}</p>
          </div>
          <button
            type='button'
            className='profile-modal__close'
            onClick={handleClose}
            aria-label='close'
          >
            <img src={mode === 'light' ? closeIcon : closeIconWhite} alt='close' />
          </button>
        </div>
        <Divider className='divider-modals' sx={{ marginBottom: '16px' }} />

        {/* body */}
        <div className='profile-modal__body'>
          <div className='profile-modal__wrapper-profile-img'>
            <div className='profile-modal__profile-img-icon'>
              <img src={chatAvatarIcon} />
              {/* <img className='profile-modal__picture-icon' src={pictureIcon} /> */}
            </div>
          </div>
          <div className='wrapper-inputs'>
            <TextNewInput
              label=''
              placeholder={t('chat-profile-modal-input-placeholder-firstname')}
              value={profile.firstname}
              className='profile-modal__input'
              dir='auto'
              disabled
            />
            <TextNewInput
              label=''
              placeholder={t('chat-profile-modal-input-placeholder-lastname')}
              value={profile.lastname}
              className='profile-modal__input'
              dir='auto'
              disabled
            />
            <TextNewInput
              label=''
              placeholder={t('chat-profile-modal-input-placeholder-email')}
              value={profile.email}
              className='profile-modal__input'
              dir='auto'
              disabled
            />
          </div>
        </div>
        {/* actions */}
        <div className='profile-modal__btns'>
          <Button
            title={t('chat-profile-modal-btn-cancel')}
            onClick={handleClose}
            className='profile-modal__btns__cancel'
            type='button'
            tabIndex={1}
          />
        </div>
      </form>
    </Modal>
  )
}

export default ProfileModal
