import {
  PointerEvent as ReactPointerEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from 'react'
import { WorkbookPreviewRow } from '../../types'

interface IProps {
  rows: WorkbookPreviewRow[]
  isLoading: boolean
  onSelectionChange?: (selection: string) => void
  selectionResetKey?: number
}

const getColumnName = (index: number) => {
  let name = ''
  let value = index + 1
  while (value > 0) {
    value -= 1
    name = String.fromCharCode(65 + (value % 26)) + name
    value = Math.floor(value / 26)
  }
  return name
}

interface CellPosition {
  row: number
  column: number
}

interface SelectionRange {
  start: CellPosition
  end: CellPosition
}

const getCellKey = ({ row, column }: CellPosition) => `${row}:${column}`

const formatCellAddress = ({ row, column }: CellPosition) =>
  `${getColumnName(column)}${row + 1}`

const formatRange = ({ start, end }: SelectionRange) => {
  const startAddress = formatCellAddress(start)
  const endAddress = formatCellAddress(end)
  return startAddress === endAddress ? startAddress : `${startAddress}:${endAddress}`
}

const WorkbookGrid = ({
  rows,
  isLoading,
  onSelectionChange,
  selectionResetKey,
}: IProps) => {
  const columns = rows.length > 0 ? Object.keys(rows[0]) : []
  const [selectedCells, setSelectedCells] = useState<Set<string>>(new Set())
  const [isSelecting, setIsSelecting] = useState(false)
  const selectionAnchor = useRef<CellPosition | null>(null)
  const selectionBase = useRef<Set<string>>(new Set())
  const selectionRanges = useRef<SelectionRange[]>([])
  const baseRanges = useRef<SelectionRange[]>([])

  const selectRange = useCallback((end: CellPosition) => {
    const start = selectionAnchor.current
    if (!start) {
      return
    }

    const nextSelection = new Set(selectionBase.current)
    const firstRow = Math.min(start.row, end.row)
    const lastRow = Math.max(start.row, end.row)
    const firstColumn = Math.min(start.column, end.column)
    const lastColumn = Math.max(start.column, end.column)
    const currentRange = {
      start: { row: firstRow, column: firstColumn },
      end: { row: lastRow, column: lastColumn },
    }

    for (let row = firstRow; row <= lastRow; row += 1) {
      for (let column = firstColumn; column <= lastColumn; column += 1) {
        nextSelection.add(getCellKey({ row, column }))
      }
    }

    setSelectedCells(nextSelection)
    selectionRanges.current = [...baseRanges.current, currentRange]
    onSelectionChange?.(selectionRanges.current.map(formatRange).join(', '))
  }, [onSelectionChange])

  useEffect(() => {
    const finishSelection = () => setIsSelecting(false)
    window.addEventListener('pointerup', finishSelection)
    return () => window.removeEventListener('pointerup', finishSelection)
  }, [])

  useEffect(() => {
    setSelectedCells(new Set())
    selectionRanges.current = []
    onSelectionChange?.('')
  }, [onSelectionChange, rows, selectionResetKey])

  const handlePointerDown = (
    position: CellPosition,
    event: ReactPointerEvent<HTMLTableCellElement>,
  ) => {
    event.preventDefault()
    selectionAnchor.current = position
    selectionBase.current = event.ctrlKey || event.metaKey
      ? new Set(selectedCells)
      : new Set()
    baseRanges.current = event.ctrlKey || event.metaKey
      ? [...selectionRanges.current]
      : []
    setIsSelecting(true)
    selectRange(position)
  }

  const handlePointerEnter = (position: CellPosition) => {
    if (isSelecting) {
      selectRange(position)
    }
  }

  if (isLoading) {
    return <div className='excel-workbook-grid__state'>در حال آماده‌سازی workbook...</div>
  }

  if (columns.length === 0) {
    return (
      <div className='excel-workbook-grid__state'>
        فایل آماده است. نمایش داده‌های XLS/XLSX با endpoint داده‌های sheet تکمیل می‌شود.
      </div>
    )
  }

  return (
    <div className='excel-workbook-grid'>
      <table>
        <thead>
          <tr className='excel-workbook-grid__letters'>
            <th className='excel-workbook-grid__letter-cell' aria-hidden='true' />
            {columns.map((column, index) => (
              <th
                key={column}
                scope='col'
                className={
                  [...selectedCells].some(cell => cell.endsWith(`:${index}`))
                    ? 'excel-workbook-grid__letter-cell is-selection-related'
                    : 'excel-workbook-grid__letter-cell'
                }
              >
                {getColumnName(index)}
              </th>
            ))}
          </tr>
          <tr>
            <th>#</th>
            {columns.map(column => <th key={column}>{column}</th>)}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, rowIndex) => (
            <tr key={rowIndex}>
              <th
                className={
                  [...selectedCells].some(cell => cell.startsWith(`${rowIndex}:`))
                    ? 'is-selection-related'
                    : ''
                }
              >
                {rowIndex + 1}
              </th>
              {columns.map((column, columnIndex) => {
                const position = { row: rowIndex, column: columnIndex }
                const isSelected = selectedCells.has(getCellKey(position))

                return (
                  <td
                    key={column}
                    className={isSelected ? 'is-selected' : ''}
                    aria-selected={isSelected}
                    onPointerDown={event => handlePointerDown(position, event)}
                    onPointerEnter={() => handlePointerEnter(position)}
                  >
                    {row[column] ?? ''}
                  </td>
                )
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

export default WorkbookGrid
