import { CHAT_SELECTION_MODE, TQuickAction } from 'src/types/NewChat'

export type { TQuickAction } from 'src/types/NewChat'

export const SERVICE_SELECTION_MODES: Partial<
  Record<TQuickAction, CHAT_SELECTION_MODE>
> = {
  summarizing: 'summarizer',
  translation: 'translator',
  namedEntities: 'ner',
  keywords: 'keywordExtractor',
  meetingMinutes: 'minutesGenerator',
  reportGenerator: 'reporter',
  letterWriter: 'letter',
  ocr: 'ocr',
  selectFile: 'rag',
  stt: 'stt',
}

/** Only file conversations can collect more than one source file. */
export const supportsMultipleFileSelection = (selectionMode?: CHAT_SELECTION_MODE) =>
  selectionMode === 'rag'

export const resolveSelectionMode = ({
  selectedMode,
  hasCurrentFileSelection,
  hasRagContext,
}: {
  selectedMode?: CHAT_SELECTION_MODE
  hasCurrentFileSelection: boolean
  hasRagContext: boolean
}): CHAT_SELECTION_MODE => {
  if (selectedMode) {
    return selectedMode
  }

  if (hasCurrentFileSelection || hasRagContext) {
    return 'rag'
  }

  return 'generalChat'
}

export const resolveRagContextAfterSend = ({
  sentMode,
  hadFileContext,
  hasCurrentFileSelection,
}: {
  sentMode: CHAT_SELECTION_MODE
  /** A file was uploaded or used earlier in this conversation. */
  hadFileContext: boolean
  /** A file is being attached to the message that was just sent. */
  hasCurrentFileSelection: boolean
}) => {
  // File context belongs to the session, not to the last selected quick
  // action.  Once a conversation has a file, subsequent unselected messages
  // must remain in RAG instead of falling back to generalChat.
  return hadFileContext || hasCurrentFileSelection || sentMode === 'rag'
}

export const EMPTY_SERVICE_MESSAGE_ACTIONS = new Set<TQuickAction>([
  'namedEntities',
  'keywords',
  'ocr',
  'stt',
])
