import { IBDMContext } from 'src/types'
import { initialState } from '.'

export enum BDM_CONTEXT_ACTIONS {
  SET_ACCESS_TOKEN = 'setAccessToken',
  SET_REFRESH_TOKEN = 'setRefreshToken',
  SET_USER = 'setUser',
  SET_LANG = 'setLang',
  SET_ADD_A_TOAST = 'setAddAToast',
  SET_SOCKER = 'setSocket',
  SET_LOADING = 'setLoading',
  SET_NAVBAR_OPEN = 'setNavbar',
  SET_HAS_NAVBAR = 'setHasNavbar',
  RESET = 'reset',
}

const bdmReducer: (
  prevState: IBDMContext,
  action: { type: BDM_CONTEXT_ACTIONS; payload?: any },
) => IBDMContext = (prevState, action) => {
  const { type, payload } = action
  switch (type) {
    case BDM_CONTEXT_ACTIONS.SET_ACCESS_TOKEN:
      return { ...prevState, accessToken: payload }
    case BDM_CONTEXT_ACTIONS.SET_REFRESH_TOKEN:
      return { ...prevState, refreshToken: payload }
    case BDM_CONTEXT_ACTIONS.SET_USER:
      return { ...prevState, user: payload }
    case BDM_CONTEXT_ACTIONS.SET_LANG:
      return { ...prevState, lang: payload }
    case BDM_CONTEXT_ACTIONS.SET_ADD_A_TOAST:
      return { ...prevState, addAToast: payload }
    case BDM_CONTEXT_ACTIONS.SET_SOCKER:
      return { ...prevState, socket: payload }
    case BDM_CONTEXT_ACTIONS.SET_NAVBAR_OPEN:
      return { ...prevState, isNavbarOpen: payload }
    case BDM_CONTEXT_ACTIONS.SET_HAS_NAVBAR:
      return { ...prevState, hasNavbar: payload }
    // case BDM_CONTEXT_ACTIONS.SET_LOADING:
    //   return { ...prevState, user: payload }
    case BDM_CONTEXT_ACTIONS.RESET:
      return initialState

    default:
      return prevState
  }
}

export default bdmReducer
