import './style.scss'

import { t } from 'i18next'
import { forwardRef, useEffect, useMemo, useRef, useState } from 'react'
import CollectionCard from './components/CollectionCard'
import HistoryCard from './components/HistoryCard'
import Divider from '@mui/material/Divider'
import Tooltip from '@mui/material/Tooltip'
import NewCollectionModal from './components/NewCollectionModel'
import DanaLogo from 'src/assets/danaLogo.svg'
import AddNewSession from 'src/assets/addNewSession.svg'
import AddNewSessionWhite from 'src/assets/addNewSessionWhite.svg'
import searchIcon from 'src/assets/searchIcon.svg'
import searchIconWhite from 'src/assets/searchIconWhite.svg'
import addProjectIcon from 'src/assets/addProjectIcon.svg'
import addProjectIconWhite from 'src/assets/addProjectIconWhite.svg'
import chatAvatarIcon from 'src/assets/chatAvatarIcon.svg'
import ChatCardMenu from './components/ChatCardMenu'
import HistoryCardMenu from './components/HistoryCardMenu'
import UserMenu from './components/UserMenu'

import { ExpandableList } from './components/ExpandableList'

import useSidebar from './logic'
import { useBDMContext } from 'src/lib/context'
import ProfileModal from './components/ProfileModal'
import SettingsModal from './components/SettingsModal'
import { useBDMSelector } from 'src/lib/store/hooks'
import { RootState } from 'src/lib/store'
// import { isChat } from 'src/lib/constants'

interface SidebarProps {
  onClose?: () => void
  onNavigate?: () => void
}

const Sidebar = forwardRef<HTMLDivElement, SidebarProps>(({ onClose, onNavigate }, ref) => {
  const {
    isSidebarOpen,
    collectionList,
    CLHistoryList,
    // handleCloseSidebar,
    handleNewSession,
    handleNewCollection,
    handleToggleSidebar,
    // todaysHistoryList,
    // menu
    menuAnchorEl,
    handleCloseMenu,
    handleOpenMenu,
    menuIds,
  } = useSidebar()
  const collapsedSidebarRef = useRef<HTMLDivElement>(null)
  const searchInputRef = useRef<HTMLInputElement>(null)
  const [isSearchOpen, setIsSearchOpen] = useState(false)
  const [searchQuery, setSearchQuery] = useState('')
  const { user } = useBDMContext()
  const fullName = [user?.firstname, user?.lastname].filter(Boolean).join(' ')

  useEffect(() => {
    if (!isSidebarOpen) {
      requestAnimationFrame(() => {
        collapsedSidebarRef.current?.focus()
      })
    }
  }, [isSidebarOpen])
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const isLargeFont = localStorage.getItem('chat-font-size') === 'large'
  const normalizedSearchQuery = searchQuery.trim().toLocaleLowerCase('fa')
  const filteredCollectionList = useMemo(() => {
    if (!normalizedSearchQuery) {
      return collectionList
    }

    return collectionList.filter(collection =>
      collection.collectionName.toLocaleLowerCase('fa').includes(normalizedSearchQuery) ||
      collection.collectionHistory?.some(history =>
        history.historyName.toLocaleLowerCase('fa').includes(normalizedSearchQuery),
      ),
    )
  }, [collectionList, normalizedSearchQuery])
  const filteredCLHistoryList = useMemo(() => {
    const namedHistories = CLHistoryList.filter(
      history => Boolean(history.historyId) && Boolean(history.historyName?.trim()),
    )

    if (!normalizedSearchQuery) {
      return namedHistories
    }

    return namedHistories.filter(history =>
      history.historyName.toLocaleLowerCase('fa').includes(normalizedSearchQuery),
    )
  }, [CLHistoryList, normalizedSearchQuery])

  const handleToggleSearch = () => {
    setIsSearchOpen(previous => {
      const next = !previous
      if (next) {
        requestAnimationFrame(() => searchInputRef.current?.focus())
      } else {
        setSearchQuery('')
      }
      return next
    })
  }
  const handleSidebarToggle = () => {
    handleToggleSidebar()
    if (isSidebarOpen) {
      onClose?.()
    }
  }
  const handleNewSessionNavigation = () => {
    handleNewSession()
    onNavigate?.()
  }
  const handleNewCollectionNavigation = () => {
    handleNewCollection()
    onNavigate?.()
  }

  return (
    <div className='chat-chatbox-sidebar-wrapper' ref={ref}>
      {isSidebarOpen ? (
        <div className='chat-chatbox-sidebar'>
          {/* header actions */}
          <div className='chat-chatbox-sidebar__header'>
            {/* <Tooltip title={t('chat-sidebar-new-chat-title')} placement='left'>
              <button className='chat-chatbox-sidebar__new-chat' onClick={handleNewSession} />
            </Tooltip> */}
            <button
              className='chat-chatbox-sidebar__logo-button'
              onClick={() => isSidebarOpen ? null : handleToggleSidebar}
              aria-label='Collapse sidebar'
            >
              <img src={DanaLogo} />
            </button>
            <button
              className={mode === 'light' ? 'chat-chatbox-sidebar__sidebar-toggle' : 'chat-chatbox-sidebar__sidebar-toggle-dark'}
              onClick={handleSidebarToggle}
            />
          </div>
          <div className='chat-chatbox-sidebar-sections'>
            <div className='chat-chatbox-add-session-project'>
              <div className='header-items' onClick={handleNewSessionNavigation}>
                <img src={mode === 'light' ? AddNewSession : AddNewSessionWhite} />
                <Tooltip title={isLargeFont ? t('chat-sidebar-new-chat-title') : ''} placement='top' disableInteractive>
                  <span className='header-items__label'>{t('chat-sidebar-new-chat-title')}</span>
                </Tooltip>
              </div>
              <div
                className={`header-items header-items--search ${isSearchOpen ? 'is-open' : ''}`.trim()}
                onFocus={isSearchOpen ? undefined : handleToggleSearch}
                tabIndex={isSearchOpen ? -1 : 0}
              >
                <img src={mode === 'light' ? searchIcon : searchIconWhite} />
                {isSearchOpen ? (
                  <>
                    <input
                      ref={searchInputRef}
                      value={searchQuery}
                      onChange={event => setSearchQuery(event.target.value)}
                      placeholder={t('chat-search-placeholder')}
                      aria-label={t('chat-search-placeholder')}
                      onKeyDown={event => {
                        if (event.key === 'Escape') {
                          handleToggleSearch()
                        }
                      }}
                    />
                    <button type='button' onClick={handleToggleSearch} aria-label={t('chat-search-close')}>
                      ×
                    </button>
                  </>
                ) : (
                  <Tooltip title={isLargeFont ? t('chat-search-prompt') : ''} placement='top' disableInteractive>
                    <span className='header-items__label'>{t('chat-search-prompt')}</span>
                  </Tooltip>
                )}
              </div>
              <div className='header-items' onClick={handleNewCollectionNavigation}>
                <img src={mode === 'light' ? addProjectIcon : addProjectIconWhite} />
                <Tooltip title={isLargeFont ? t('chat-sidebar-new-collection-title') : ''} placement='top' disableInteractive>
                  <span className='header-items__label'>{t('chat-sidebar-new-collection-title')}</span>
                </Tooltip>
              </div>
            </div>
            {/* collections */}
            {filteredCollectionList && filteredCollectionList.length > 0 &&
              <div className='chat-chatbox-section chat-chatbox-section--collections'>
                <div className='chat-chatbox-section__title'>
                  <p>{t('chat-sidebar-collections-title')}</p>
                  {/* {isChat && (
                  <Tooltip title={t('chat-sidebar-new-collection-title')} placement='left'>
                    <button
                      className='chat-chatbox-section__new-item'
                      onClick={handleNewCollection}
                    />
                  </Tooltip>
                )} */}
                </div>

                {/* <Divider
                className='chat-chatbox-sidebar__divider'
                orientation='horizontal'
                variant='middle'
                component='div'
              /> */}
                <div className='chat-chatbox-section__list'>
                  <ExpandableList
                    items={filteredCollectionList}
                    renderItem={collection => (
                      <CollectionCard
                        key={collection.collectionId}
                        collection={collection}
                        onNavigate={onNavigate}
                        onOpenMenu={handleOpenMenu}
                        menuAnchorEl={menuAnchorEl}
                        menuIds={menuIds}
                        isMenuOpen={
                          Boolean(menuAnchorEl) &&
                          menuIds.collectionId === collection.collectionId &&
                          !menuIds.historyId
                        }
                      />
                    )}
                    getItemId={collection => collection.collectionId}
                  />
                </div>
              </div>
            }
            {/* collection-less history list */}
            {filteredCLHistoryList && filteredCLHistoryList.length > 0 &&
              <div className='chat-chatbox-section chat-chatbox-section--histories'>
                <div className='chat-chatbox-section__title'>
                  <p>{t('chat-sidebar-collection-less-history')}</p>
                </div>

                <div className='chat-chatbox-section__list'>
                  <ExpandableList
                    items={filteredCLHistoryList}
                    renderItem={history => (
                      <HistoryCard
                        key={history.historyId}
                        history={history}
                        onNavigate={onNavigate}
                        onOpenMenu={handleOpenMenu}
                        isMenuOpen={
                          Boolean(menuAnchorEl) &&
                          Boolean(menuIds.historyId) &&
                          menuIds.historyId === history.historyId
                        }
                      />
                    )}
                    getItemId={history => history.historyId}
                  />
                </div>
              </div>
            }
            {/* today history */}
            {/* <div className='chat-chatbox-section'>
              <div className='chat-chatbox-section__title'>
                <p>{t('chat-sidebar-today-history')}</p>
              </div>

              <Divider
                className='chat-chatbox-sidebar__divider'
                orientation='horizontal'
                variant='middle'
                component='div'
              />

              <div className='chat-chatbox-section__list'>
                <ExpandableList
                  items={todaysHistoryList}
                  initiallyVisibleCount={5}
                  showMoreLabel={t('chat-sidebar-show-more')}
                  showLessLabel={t('chat-sidebar-show-less')}
                  renderItem={history => <HistoryCard key={history.historyId} history={history} />}
                />
              </div>
            </div> */}
          </div>
          <div className='chat-chatbox-sidebar__footer'>
            <Divider
              className='chat-chatbox-sidebar__divider'
              orientation='horizontal'
              variant='middle'
              component='div'
            />
            <UserMenu fullName={fullName} />
          </div>
        </div>
      ) : (
        <div
          className='chat-chatbox-sidebar chat-chatbox-sidebar--collapsed'
          ref={collapsedSidebarRef}
          tabIndex={-1}
        >
          <div className='chat-chatbox-sidebar__collapsed-logo-wrap'>
            <button className='chat-chatbox-sidebar__collapsed-logo' onClick={handleSidebarToggle}>
              <img src={DanaLogo} />
            </button>
            <button
              className={`chat-chatbox-sidebar__sidebar-toggle chat-chatbox-sidebar__sidebar-toggle--collapsed ${mode === 'dark' ? 'sidebar-toggle--collapsed-dark' : '' }`}
              onClick={handleSidebarToggle}
            />
          </div>
          <div className='chat-chatbox-sidebar__collapsed-actions'>
            <button className='chat-chatbox-sidebar__collapsed-action' onClick={handleNewSessionNavigation}>
              <img src={mode === 'light' ? AddNewSession : AddNewSessionWhite} />
            </button>
            <button className='chat-chatbox-sidebar__collapsed-action' onClick={handleNewSessionNavigation}>
              <img src={mode === 'light' ? searchIcon : searchIconWhite} />
            </button>
            <button className='chat-chatbox-sidebar__collapsed-action' onClick={handleNewCollectionNavigation}>
              <img src={mode === 'light' ? addProjectIcon : addProjectIconWhite} />
            </button>
          </div>
          <div className='chat-chatbox-sidebar__user'>
            <div className='chat-chatbox-sidebar__user__avatar'>
              <img src={chatAvatarIcon} className='chat-chatbox-sidebar__user-avatar' />
            </div>
          </div>
        </div>
      )}
      <NewCollectionModal />
      <ProfileModal />
      <SettingsModal />
      <ChatCardMenu
        menuAnchorEl={menuIds.historyId ? null : menuAnchorEl}
        menuIds={menuIds}
        onClose={handleCloseMenu}
      />
      <HistoryCardMenu
        menuAnchorEl={menuIds.historyId ? menuAnchorEl : null}
        menuIds={menuIds}
        onClose={handleCloseMenu}
      />
    </div>
  )
})
export default Sidebar
