import { PayloadAction } from '@reduxjs/toolkit'
import {
  CHAT_ANSWER_STATUS,
  IChatHistory,
  IChatMessage,
  IChatSessionFileUploadItem,
  IChatState,
} from 'src/types/NewChat'
import { initialState } from '.'

export const reducers = {
  requestFileQuickAction: (
    state: IChatState,
    action: PayloadAction<NonNullable<IChatState['quickActionRequest']>>,
  ) => {
    state.quickActionRequest = action.payload
  },
  clearQuickActionRequest: (state: IChatState) => {
    state.quickActionRequest = null
  },
  setSidebarState: (state: IChatState, action: PayloadAction<IChatState['sidebarState']>) => {
    state.sidebarState = action.payload
  },
  setModalsState: (
    state: IChatState,
    action: PayloadAction<Partial<IChatState['modalsState']>>,
  ) => {
    state.modalsState = { ...state.modalsState, ...action.payload }
  },
  addUploadFile: (
    state: IChatState,
    action: PayloadAction<{
      fileId: string
      filename: string
      filesize: string
      filetype: string
    }>,
  ) => {
    state.uploadFiles[action.payload.fileId] = { ...action.payload, progress: 0, error: false }
  },
  updateUploadFileProgress: (
    state: IChatState,
    action: PayloadAction<{ fileId: string; progress: number }>,
  ) => {
    const foundFile = state.uploadFiles[action.payload.fileId]

    if (!foundFile) {
      return
    }

    state.uploadFiles[action.payload.fileId] = {
      ...foundFile,
      progress: action.payload.progress,
    }
  },
  clearUploadFiles: (state: IChatState) => {
    state.uploadFiles = {}
  },
  setMouseLoc: (state: IChatState, action: PayloadAction<IChatState['mouseLoc']>) => {
    state.mouseLoc = action.payload
  },
  setContextMenuState: (
    state: IChatState,
    action: PayloadAction<IChatState['contextMenuState']>,
  ) => {
    state.contextMenuState = action.payload
  },
  updateMessage: (state: IChatState, action: PayloadAction<IChatMessage>) => {
    if (state.currentHistoryMessages.length === 0) {
      state.currentHistoryMessages = [action.payload]
      return
    }

    const foundIdx = state.currentHistoryMessages.findIndex(msg => msg.id === action.payload.id)

    if (foundIdx === -1) {
      state.currentHistoryMessages.push(action.payload)
      return
    }

    state.currentHistoryMessages = state.currentHistoryMessages.map(msg =>
      msg.id === action.payload.id ? action.payload : msg,
    )
  },
  setMessagesHidden: (
    state: IChatState,
    action: PayloadAction<{ messageIds: string[]; hidden: boolean }>,
  ) => {
    const { messageIds, hidden } = action.payload
    state.currentHistoryMessages.forEach(message => {
      if (messageIds.includes(message.id)) {
        message.hidden = hidden
      }
    })
  },
  updateEditedMessagePreview: (
    state: IChatState,
    action: PayloadAction<{ messageId: string; message: string }>,
  ) => {
    const editedMessageIndex = state.currentHistoryMessages.findIndex(
      message => message.id === action.payload.messageId,
    )
    const directAnswerIndex =
      editedMessageIndex === -1
        ? -1
        : state.currentHistoryMessages.findIndex(
            (message, index) => index > editedMessageIndex && message.bot,
          )

    state.currentHistoryMessages = state.currentHistoryMessages.map((message, index) => {
      if (message.id === action.payload.messageId) {
        return { ...message, message: action.payload.message }
      }

      const isReplyAnswer = message.reply?.some(reply => reply.messageId === action.payload.messageId)
      const isDirectAnswer = index === directAnswerIndex

      return isReplyAnswer || isDirectAnswer ? { ...message, hidden: true } : message
    })
    state.loadingState.chatResponse = true
  },
  setChatResponseLoadingState: (state: IChatState, action: PayloadAction<boolean>) => {
    state.loadingState.chatResponse = action.payload
  },
  addSessionResponseWaiting: (state: IChatState, action: PayloadAction<Array<string>>) => {
    const updateList = Array.from(new Set([...state.responseWaitingSessions, ...action.payload]))
    state.responseWaitingSessions = updateList
  },
  removeSessionResponseWaiting: (state: IChatState, action: PayloadAction<Array<string>>) => {
    if (action.payload.length === 0) {
      return
    }
    state.responseWaitingSessions = state.responseWaitingSessions.filter(
      sessionId => !action.payload.includes(sessionId),
    )
  },
  setChaStreamingLoadingState: (state: IChatState, action: PayloadAction<boolean>) => {
    state.loadingState.chatStreaming = action.payload
  },
  setHistoryAnswerStatus: (
    state: IChatState,
    action: PayloadAction<{ historyId: string; answerStatus: CHAT_ANSWER_STATUS }>,
  ) => {
    const { historyId, answerStatus } = action.payload
    const matchesHistory = (history: IChatHistory) =>
      history.historyId === historyId || history.sessionId === historyId
    const updateHistory = (history: IChatHistory) => ({ ...history, answerStatus })

    state.historyList = state.historyList.map(history =>
      matchesHistory(history) ? updateHistory(history) : history,
    )
    state.CLHistoryList = state.CLHistoryList.map(history =>
      matchesHistory(history) ? updateHistory(history) : history,
    )
    Object.entries(state.histories).forEach(([key, history]) => {
      if (matchesHistory(history)) state.histories[key] = updateHistory(history)
    })
    Object.entries(state.CLHistories).forEach(([key, history]) => {
      if (matchesHistory(history)) state.CLHistories[key] = updateHistory(history)
    })
    Object.entries(state.collections).forEach(([collectionId, collection]) => {
      state.collections[collectionId] = {
        ...collection,
        collectionHistory: collection.collectionHistory.map(history =>
          matchesHistory(history) ? updateHistory(history) : history,
        ),
      }
    })
    if (state.currentHistory && matchesHistory(state.currentHistory)) {
      state.currentHistory = updateHistory(state.currentHistory)
    }
  },
  // chat update via socket
  setStreamFromSocket: (state: IChatState, action: PayloadAction<IChatState['stream']>) => {
    state.stream = action.payload
  },
  removeStreamSessions: (state: IChatState, action: PayloadAction<Array<string>>) => {
    action.payload.forEach(sessionId => {
      delete state.stream[sessionId]
    })
  },
  // add a new / update a collection-less history via socket
  setCLHistoryListFromSocket: (state: IChatState, action: PayloadAction<IChatHistory>) => {
    const isProjectHistory =
      Boolean(action.payload.collectionId) || action.payload.scopeType?.toUpperCase() === 'COLLECTION'

    // The backend emits project histories through the same event as general
    // chats. Update their owning collection instead of dropping the update or
    // incorrectly adding it to the general-chat list.
    if (isProjectHistory) {
      const collectionId = action.payload.collectionId

      if (!collectionId) {
        return
      }

      const collection = state.collections[collectionId]

      if (!collection) {
        return
      }

      const hasSameHistoryId = (history: IChatHistory) =>
        [history.historyId, history.sessionId].some(
          id => id && [action.payload.historyId, action.payload.sessionId].includes(id),
        )
      const existingHistory = collection.collectionHistory.find(hasSameHistoryId)
      const updatedHistory = {
        ...existingHistory,
        ...action.payload,
        collectionId,
        collectionName: action.payload.collectionName ?? collection.collectionName,
      }
      const collectionHistory = existingHistory
        ? collection.collectionHistory.map(history =>
            hasSameHistoryId(history) ? updatedHistory : history,
          )
        : [...collection.collectionHistory, updatedHistory]
      const updatedCollection = { ...collection, collectionHistory }

      state.collections[collectionId] = updatedCollection
      state.collectionList = state.collectionList.map(item =>
        item.collectionId === collectionId ? updatedCollection : item,
      )
      state.histories[updatedHistory.historyId] = updatedHistory
      state.historyList = state.historyList.some(hasSameHistoryId)
        ? state.historyList.map(history => (hasSameHistoryId(history) ? updatedHistory : history))
        : [...state.historyList, updatedHistory]

      if (state.currentCollection?.collectionId === collectionId) {
        state.currentCollection = updatedCollection
      }
      if (state.currentHistory && hasSameHistoryId(state.currentHistory)) {
        state.currentHistory = { ...state.currentHistory, ...updatedHistory }
      }

      return
    }

    const existingHistory = state.CLHistories[action.payload.historyId]
    const currentHistory = state.currentHistory
    const isCurrentHistory = Boolean(
      currentHistory &&
        [currentHistory.historyId, currentHistory.sessionId].some(
          id => id && [action.payload.historyId, action.payload.sessionId].includes(id),
        ),
    )
    if (existingHistory) {
      state.CLHistories[action.payload.historyId] = { ...existingHistory, ...action.payload }
      state.CLHistoryList = state.CLHistoryList.map(history =>
        history.historyId === action.payload.historyId
          ? { ...history, ...action.payload }
          : history,
      )
    } else {
      state.CLHistories = { ...state.CLHistories, [action.payload.historyId]: action.payload }
      state.CLHistoryList = [...state.CLHistoryList, action.payload]
    }

    // The first request starts with a client-side sessionId and later receives
    // its server historyId. Keep that same session selected, but do not let an
    // unrelated socket update steal the active state.
    if (!currentHistory || isCurrentHistory) {
      state.currentCollection = null
      state.currentHistory = action.payload
      state.chatStateParams = {
        historyId: action.payload.historyId,
        collectionId: undefined,
        isParamsSynced: false,
      }
    }
  },
  syncSocketMessageAttachments: (state: IChatState, action: PayloadAction<IChatMessage>) => {
    const socketMessage = action.payload
    if (
      socketMessage.bot ||
      !Array.isArray(socketMessage.attachments) ||
      socketMessage.attachments.length === 0
    ) {
      return
    }

    const messagesFromNewest = state.currentHistoryMessages
      .map((message, index) => ({ message, index }))
      .reverse()
    const exactTarget = messagesFromNewest.find(
      ({ message }) =>
        !message.bot &&
        (message.id === socketMessage.id || message.message === socketMessage.message),
    )
    const pendingTarget = messagesFromNewest.find(
      ({ message }) =>
        !message.bot &&
        message.attachments.some(file => file.fileId?.startsWith('pending-')),
    )
    const targetIndex = (exactTarget ?? pendingTarget)?.index

    if (targetIndex === undefined) {
      return
    }

    const target = state.currentHistoryMessages[targetIndex]

    const normalizeSocketFile = (file: IChatSessionFileUploadItem) => ({
      ...file,
      _id: file._id || file.fileId,
      fileId: file.fileId || file._id,
      filename: file.filename || file.originalName,
      originalName: file.originalName || file.filename,
      state: file.state || 'done',
      fullPath: file.fullPath || '',
      uploadedAt: file.uploadedAt || socketMessage.createdAt,
    })

    // The socket payload is the current source of truth for this message.
    // Replace the complete array so additions/removals and the displayed
    // count are reflected immediately without waiting for a history reload.
    const attachments = socketMessage.attachments.map(normalizeSocketFile)

    state.currentHistoryMessages[targetIndex] = { ...target, attachments }
  },
  resolvePendingAttachments: (state: IChatState, action: PayloadAction<string[]>) => {
    const message = [...state.currentHistoryMessages]
      .reverse()
      .find(item => !item.bot && item.attachments.some(file => file.fileId.startsWith('pending-')))

    if (!message) {
      return
    }

    // `action.payload` is every fileId used as context for this turn (see
    // getGeneralChatFileIds), including files already attached to earlier
    // messages in this chat. Only the ids not already known belong to this
    // message's own (still-pending) uploads — using the full list
    // positionally would attach an earlier message's file here instead.
    const knownFileIds = new Set(
      state.currentHistoryMessages.flatMap(item =>
        item.attachments.map(file => file._id || file.fileId).filter(Boolean),
      ),
    )
    const fileIds = action.payload.filter(
      fileId => !fileId.startsWith('pending-') && !knownFileIds.has(fileId),
    )
    if (fileIds.length === 0) {
      return
    }

    let fileIndex = 0
    message.attachments = message.attachments.map(file => {
      if (!file.fileId.startsWith('pending-')) {
        return file
      }

      const fileId = fileIds[fileIndex++]
      return fileId ? { ...file, _id: fileId, fileId, state: 'done' } : file
    })
  },
  // used to clear current state (in ui, shows landing screen and user can create a new session)
  clearCurrentState: (state: IChatState) => {
    state.currentCollection = null
    state.currentHistory = null
    state.currentGraph = { nodes: [], links: [] }
    state.currentHistoryMessages = []
    state.loadingState.messages = false
    state.chatStateParams = {
      historyId: undefined,
      collectionId: undefined,
      isParamsSynced: false,
    }
  },
  setAppInitialized: (state: IChatState, action: PayloadAction<boolean>) => {
    state.appInitalized = action.payload
  },
  // expnad chatbox to get full-screen
  toggleExpanded: (state: IChatState) => {
    state.layoutState.isExpanded = !state.layoutState.isExpanded
    state.layoutState.layout = state.layoutState.isExpanded
      ? [{ i: 'chat', x: 0, y: 0, w: 12, h: 22 }]
      : initialState.layoutState.layout
  },
  // lock chat layout config
  toggleLayoutLock: (state: IChatState) => {
    state.layoutState.isLocked = !state.layoutState.isLocked
  },
  updateAttachment: (state: IChatState, action: PayloadAction<IChatSessionFileUploadItem>) => {
    const attachment = action.payload
    const alreadySelected = state.historyAttachments.some(
      item => item.fileId === attachment.fileId || item._id === attachment._id,
    )

    if (!alreadySelected) {
      state.historyAttachments.push(attachment)
    }
  },
  replaceAttachment: (state: IChatState, action: PayloadAction<IChatSessionFileUploadItem>) => {
    state.historyAttachments = [action.payload]
  },
  removeAttachment: (state: IChatState, action: PayloadAction<string | undefined>) => {
    if (!action.payload) {
      state.historyAttachments = []
      return
    }

    state.historyAttachments = state.historyAttachments.filter(
      item => item.fileId !== action.payload && item._id !== action.payload,
    )
  },
  setBackgroundSettings: (
    state: IChatState,
    action: PayloadAction<IChatState['backgroundSettings']>,
  ) => {
    state.backgroundSettings = action.payload
  },
  setBackgroundDraftSettings: (
    state: IChatState,
    action: PayloadAction<IChatState['backgroundDraftSettings']>,
  ) => {
    state.backgroundDraftSettings = action.payload
  },
  resetStore: () => initialState,
}

export default reducers
