import {
  IGetRecentFilesDTI,
  IGetRecentFilesDTO,
  ISubmitDanaCollectionsFilesDTI,
  ISubmitDanaCollectionsFilesDTO,
  IUploadFilesDTO,
} from 'src/types/FileManagement'
import axiosWrapper, { getHeaders } from '..'
import { AxiosProgressEvent } from 'axios'

const fileManagerAPIs = (signal?: AbortSignal) => ({
  getRecentFiles: (params: IGetRecentFilesDTI) => {
    return axiosWrapper<IGetRecentFilesDTO>({
      method: 'GET',
      url: '/fileManager/recent',
      headers: getHeaders(),
      signal,
      params,
    })
  },
  submitDanaCollectionsFiles: ({ collectionId, fileIds }: ISubmitDanaCollectionsFilesDTI) => {
    return axiosWrapper<ISubmitDanaCollectionsFilesDTO>({
      method: 'POST',
      url: `/fileManager/files/download/${collectionId}`,
      headers: getHeaders(),
      signal,
      data: { fileIds },
    })
  },
  uploadFiles: (data: FormData, onUploadProgress: (event: AxiosProgressEvent) => void) => {
    return axiosWrapper<IUploadFilesDTO>({
      method: 'POST',
      url: `/fileManager/files`,
      headers: getHeaders(),
      onUploadProgress,
      signal,
      data,
    })
  },
})

export default fileManagerAPIs
