import './style.scss'

import { toast } from 'react-toastify'
import successIcon from "src/assets/successIcon.svg";
import warningIcon from "src/assets/warningIcon.svg";
import errorIcon from "src/assets/errorIcon.svg";
type THotToastVariant = 'default' | 'destructive' | 'warning' | 'success' | 'error'

interface IProps {
  id: string | number
  message: string
  onClose?: () => void
  variant: THotToastVariant
  title: string
}

const iconByVariant: Record<THotToastVariant, string> = {
  default: '◌',
  destructive: '!',
  error: errorIcon,
  warning: warningIcon,
  success: successIcon,
}

const HotToastMessage = ({ id, message, onClose, variant, title }: IProps) => {
  return (
    <div className={`bdm-hot-toast bdm-hot-toast--${variant}`}>
      <button
        type='button'
        className='bdm-hot-toast__close'
        onClick={() => (onClose ? onClose() : toast.dismiss(id))}
        aria-label='close toast'
      >
        ×
      </button>
      <div className='bdm-hot-toast__content'>
        <div className='bdm-hot-toast__head'>
          <span className='bdm-hot-toast__title'>{title}</span>
          <span className='bdm-hot-toast__status-icon'>
            <img src={iconByVariant[variant]} />
          </span>
        </div>
        <p className='bdm-hot-toast__message'>{message}</p>
      </div>
    </div>
  )
}

export type { THotToastVariant }
export default HotToastMessage
