export const FILE_TYPES: Record<string, string> = {
  'text/csv': 'csv',
  'text/plain': 'text',
  'application/vnd.apache.parquet': 'parquet',
  'application/x-parquet': 'parquet',
  'application/pdf': 'pdf',
  'image/png': 'image',
  'image/jpeg': 'image',
  'image/jpg': 'image',
}

const FILE_SIZE_UNITS = ['B', 'KB', 'MB', 'GB', 'TB'] as const

export const formatFileSize = (size?: number | string) => {
  const numericSize = Number(size)

  if (!numericSize || !Number.isFinite(numericSize) || numericSize <= 0) {
    return ''
  }

  let value = numericSize
  let unitIndex = 0
  while (value >= 1000 && unitIndex < FILE_SIZE_UNITS.length - 1) {
    value /= 1000
    unitIndex++
  }

  const decimals = unitIndex === 0 ? 0 : value < 10 ? 1 : 0
  return `${value.toFixed(decimals)} ${FILE_SIZE_UNITS[unitIndex]}`
}

export const getFileType = (fileName: string) => fileName.split('.').pop()?.toUpperCase() || 'FILE'

export const getFileKind = (file: IChatSessionFileUploadItem, fileName: string) => {
  const extension = fileName.split('.').pop()?.toLowerCase()

  if (FILE_TYPES[file.mimeType]) {
    return FILE_TYPES[file.mimeType]
  }
  if (['png', 'jpg', 'jpeg', 'gif', 'webp'].includes(extension ?? '')) {
    return 'image'
  }
  if (extension === 'pdf') {
    return 'pdf'
  }
  if (extension === 'csv') {
    return 'csv'
  }
  if (extension === 'parquet') {
    return 'parquet'
  }
  if (['doc', 'docx'].includes(extension ?? '')) {
    return 'doc'
  }
  if (['zip', 'rar', '7z'].includes(extension ?? '')) {
    return 'zip'
  }
  if (['txt', 'md', 'markdown'].includes(extension ?? '')) {
    return 'text'
  }

  return 'unknown'
}

const AttachmentIcon = ({
  file,
  fileName,
}: {
  file: IChatSessionFileUploadItem
  fileName: string
}) => {
  const fileKind = getFileKind(file, fileName)
  const [thumbnailUrl, setThumbnailUrl] = useState('')

  useEffect(() => {
    const fileId = file.fileId || file._id
    if (fileKind !== 'image' || !fileId || fileId.startsWith('pending-')) {
      return
    }

    const controller = new AbortController()
    let objectUrl = ''

    ChatAPIs(controller.signal)
      .previewFile({
        collectionId: file.collectionId || '',
        fileId,
        fileName,
      })
      .then(preview => {
        if (preview.type !== 'image') {
          if ('objectUrl' in preview) {
            URL.revokeObjectURL(preview.objectUrl)
          }
          return
        }
        if (controller.signal.aborted) {
          URL.revokeObjectURL(preview.objectUrl)
          return
        }

        objectUrl = preview.objectUrl
        setThumbnailUrl(objectUrl)
      })
      .catch(() => {
        // Keep the file-type icon when a thumbnail is unavailable.
      })

    return () => {
      controller.abort()
      if (objectUrl) {
        URL.revokeObjectURL(objectUrl)
      }
    }
  }, [file.collectionId, file.fileId, file._id, fileKind, fileName])

  return (
    <div className={`chat-messsage-attachment__icon ${fileKind}`}>
      {thumbnailUrl && <img src={thumbnailUrl} alt='' loading='lazy' />}
    </div>
  )
}

