import { createContext, PropsWithChildren, useContext, useReducer } from 'react'
import bdmReducer from './reducers'
import { IBDMContext } from 'src/types'
import { showHotToast, type TToastType } from 'src/components/Toast/hotToast'

export const addAToast = (
  msg: string,
  type: TToastType,
) => {
  showHotToast(msg, type)
}

export const initialState: IBDMContext = {
  dispatch: () => null,
  user: undefined,
  accessToken: undefined,
  refreshToken: undefined,
  lang: 'fa',
  addAToast,
  hasNavbar: false,
  isNavbarOpen: false,
  socket: () => null,
}

export const BDMContext = createContext<IBDMContext>(initialState)
export const BDMDispatchContext = createContext<IBDMContext['dispatch']>(initialState['dispatch'])

const BDMContextProvider = ({ children }: PropsWithChildren) => {
  const [state, dispatch] = useReducer(bdmReducer, initialState)

  return (
    <BDMDispatchContext.Provider value={dispatch}>
      <BDMContext.Provider value={state}>{children}</BDMContext.Provider>
    </BDMDispatchContext.Provider>
  )
}

export default BDMContextProvider

export const useBDMContext = () => {
  const state = useContext(BDMContext)
  return state
}

export const useBDMContextDispatch = () => {
  const dispatch = useContext(BDMDispatchContext)
  return dispatch
}
