import { FILTER_TYPE, TFilter, IFilter } from 'src/types'

interface IProps {
  id: number
  filters: IFilter['RootStatement']
}

export const findFilterRule = ({ id, filters }: IProps): TFilter | undefined => {
  if (filters?.id === id) {
    return filters
  }
  if (filters?.Type !== FILTER_TYPE.STATEMENT || !filters.Children) {
    return undefined
  }

  for (const child of filters.Children) {
    if (child.id === id) {
      return child
    }
    if (child.Type === FILTER_TYPE.STATEMENT) {
      const res = findFilterRule({ id, filters: child })
      if (res?.id) {
        return res
      }
    }
  }
}

export default findFilterRule
