import './style.scss'

import { IFolderItem } from 'src/types/FileManagement'
import { useBDMSelector, useBDMDispatch } from 'src/lib/store/hooks'
import {
  selectDriveAction,
  selectDriveSelectedFolder,
  selectFolder,
} from 'src/lib/slice/fileManagement/fileSlice'

import folderIcon from 'src/assets/folderIcon.svg'
import { getRecentFiles } from 'src/lib/slice/fileManagement/thunks'

const FolderCard = (folder: IFolderItem) => {
  const dispatch = useBDMDispatch()

  const action = useBDMSelector(selectDriveAction)
  const selectedFolder = useBDMSelector(selectDriveSelectedFolder)

  const selectable = action === 'upload'
  const isSelected = selectedFolder === folder.id

  const onClick = () => {
    if (selectable) {
      dispatch(selectFolder(folder.id))
    }
  }

  const onDoubleClick = () => {
    dispatch(getRecentFiles({ folderId: folder.id }))
  }

  return (
    <div
      className={`file-manager-folder-card ${selectable ? 'selectable' : ''} ${
        isSelected ? 'selected' : ''
      } `}
      onClick={onClick}
      onDoubleClick={onDoubleClick}
    >
      <div className='file-manager-folder-card__icon'>
        <img src={folderIcon} alt='folder' />
      </div>
      <div className='file-manager-folder-card__title'>
        <p>{folder.name}</p>
      </div>
    </div>
  )
}

export default FolderCard
