import {
  CHAT_HISTORY_STATE,
  CHAT_MODELS_TYPES,
  IChatHistory,
  IChatState,
} from 'src/types/NewChat'

import {
  getCollections,
  createCollection,
  editCollection,
  uploadFile,
  setCurrentCollection,
  setCurrentHistory,
  getCollectionLessHistories,
  aiChatAssistant,
  editMessage,
  getTodaysHistories,
  setCollectionsFromSocket,
  setChatStateFromParams,
  setSessionTranslation,
  deleteCollection,
  deleteHistory,
  deleteCollectionistory,
  // deleteNode,
  createSession,
  getUploadFiles,
  updateSessionReasoning,
  updateCollectionPrompt,
  getModelsList,
  setAIModel,
  uploadHistoryFile,
  deleteSessionFile,
  deleteCollectionFile,
} from './thunks'
import { initialState } from './slice'
import { ActionReducerMapBuilder } from '@reduxjs/toolkit'

const isCurrentHistory = (state: IChatState, historyId: string) =>
  [
    state.currentHistory?.historyId,
    state.currentHistory?.sessionId,
    state.chatStateParams.historyId,
  ].some(id => id === historyId)

export default function (builder: ActionReducerMapBuilder<IChatState>) {
  builder
    // get collections
    .addCase(getCollections.pending, state => {
      state.loadingState.collections = true
    })
    .addCase(getCollections.fulfilled, (state, action) => {
      state.loadingState.collections = false
      state.collections = action.payload.collections
      state.collectionList = action.payload.collectionList
      state.historyList = action.payload.historyList
      state.histories = action.payload.histories

      if (action.payload.currentCollection !== undefined) {
        state.currentCollection = action.payload.currentCollection
      }

    })
    .addCase(getCollections.rejected, state => {
      state.loadingState.collections = false
      state.collectionList = []
      state.collections = {}
      state.historyList = []
      state.histories = {}
      state.currentCollection = null

      state.currentHistory = null
    })
    // get collection-less histories
    .addCase(getCollectionLessHistories.pending, state => {
      state.loadingState.collectionLessHistories = true
    })
    .addCase(getCollectionLessHistories.fulfilled, (state, action) => {
      state.loadingState.collectionLessHistories = false
      state.CLHistories = action.payload.CLHistories
      state.CLHistoryList = action.payload.CLHistoryList

      const activeIds = [
        state.currentHistory?.historyId,
        state.currentHistory?.sessionId,
        state.chatStateParams.historyId,
      ].filter(Boolean)
      const refreshedCurrentHistory = action.payload.CLHistoryList.find(history =>
        [history.historyId, history.sessionId].some(id => id && activeIds.includes(id)),
      )

      if (refreshedCurrentHistory) {
        state.currentHistory = refreshedCurrentHistory
        state.chatStateParams.historyId = refreshedCurrentHistory.historyId
      }
    })
    .addCase(getCollectionLessHistories.rejected, state => {
      state.loadingState.collectionLessHistories = false
      state.CLHistoryList = []
      state.CLHistories = {}
    })
    // create collection
    .addCase(createCollection.fulfilled, (state, action) => {
      const collectionId = action.payload.collectionId
      const socketCollection = state.collections[collectionId]
      const collection = socketCollection
        ? {
            ...socketCollection,
            ...action.payload,
            collectionHistory:
              action.payload.collectionHistory?.length > 0
                ? action.payload.collectionHistory
                : socketCollection.collectionHistory,
          }
        : action.payload
      const alreadyExists = state.collectionList.some(item => item.collectionId === collectionId)

      state.collectionList = alreadyExists
        ? state.collectionList.map(item => (item.collectionId === collectionId ? collection : item))
        : [...state.collectionList, collection]
      state.collections = { ...state.collections, [collectionId]: collection }
      state.currentCollection = collection

      state.historyAttachments = []
      state.currentGraph = { nodes: [], links: [] }
      state.currentHistory = null
      state.chatStateParams = {
        collectionId,
        historyId: undefined,
        isParamsSynced: false,
      }
    })
    .addCase(editCollection.fulfilled, (state, action) => {
      state.collections = action.payload.collections
      state.collectionList = action.payload.collectionList
      state.historyList = action.payload.historyList
      state.histories = action.payload.histories

      if (action.payload.currentCollection !== undefined) {
        state.currentCollection = action.payload.currentCollection
      }
    })
    // Upload File
    .addCase(uploadFile.fulfilled, (state, action) => {
      const fileIds = action.meta.arg.getAll('fileId') as string[]
      fileIds.forEach(fileId => {
        if (state.uploadFiles[fileId]) state.uploadFiles[fileId].progress = 100
      })
    })
    // Upload File
    .addCase(uploadFile.rejected, (state, action) => {
      const fileIds = action.meta.arg.getAll('fileId') as string[]
      fileIds.forEach(fileId => {
        if (state.uploadFiles[fileId]) {
          state.uploadFiles[fileId].error = true
          state.uploadFiles[fileId].progress = 100
        }
      })
    })
    // set current collection
    .addCase(setCurrentCollection.fulfilled, (state, action) => {
      state.currentCollection = action.payload.currentCollection
      state.historyAttachments = []
      state.currentHistory = null
      state.currentHistoryMessages = []
      state.chatStateParams = {
        collectionId: action.payload.currentCollection?.collectionId ?? undefined,
        historyId: undefined,
        isParamsSynced: false,
      }
    })
    // get history messages
    .addCase(setCurrentHistory.pending, (state, action) => {
      state.loadingState.messages = true
      // Record the requested target immediately. A slower, earlier restore
      // must not be allowed to replace a chat the user has since left.
      state.chatStateParams = {
        collectionId: action.meta.arg.collectionId ?? undefined,
        historyId: action.meta.arg.historyId,
        isParamsSynced: false,
      }
    })
    // set current history
    .addCase(setCurrentHistory.fulfilled, (state, action) => {
      const requestedCollectionId = action.meta.arg.collectionId ?? undefined
      const isStillSelected =
        state.chatStateParams.historyId === action.meta.arg.historyId &&
        state.chatStateParams.collectionId === requestedCollectionId

      if (!isStillSelected) {
        return
      }

      state.loadingState.messages = false
      state.currentCollection = action.payload.currentCollection
      state.currentHistory = action.payload.currentHistory
      state.historyState = action.payload.historyState
      // @ts-ignore TODO: fix returned data for messages
      state.currentHistoryMessages = action.payload.messages
      state.historyAttachments = []
      state.chatStateParams = {
        collectionId: action.payload.currentCollection?.collectionId,
        historyId: action.payload.currentHistory?.historyId,
        isParamsSynced: false,
      }
    })
    .addCase(setCurrentHistory.rejected, state => {
      state.loadingState.messages = false
    })
    // ai chat assistant
    // Insert the user's message before the request is sent. The socket can
    // deliver the assistant's response before this async thunk is fulfilled;
    // waiting until then reverses their visual order on fast failures.
    .addCase(aiChatAssistant.pending, (state, action) => {
      const message = action.meta.arg.payload.messageSchema.message

      if (!state.currentHistoryMessages.some(item => item.id === message.id)) {
        state.currentHistoryMessages.push(message)
      }
    })
    .addCase(aiChatAssistant.fulfilled, (state, action) => {
      state.loadingState.collectionLessHistories = false
      const message = action.payload.messageSchema.message
      const messageIndex = state.currentHistoryMessages.findIndex(item => item.id === message.id)

      if (messageIndex === -1) {
        state.currentHistoryMessages.push(message)
      } else {
        const currentMessage = state.currentHistoryMessages[messageIndex]
        const incomingHasPendingAttachments = message.attachments.some(file =>
          file.fileId?.startsWith('pending-'),
        )
        const currentHasResolvedAttachments = currentMessage.attachments.some(
          file => file.fileId && !file.fileId.startsWith('pending-'),
        )

        // A socket event can resolve the optimistic attachment before this
        // HTTP request finishes. Do not replace that fresh socket data with
        // the older pending placeholders carried by the request response.
        state.currentHistoryMessages[messageIndex] =
          incomingHasPendingAttachments && currentHasResolvedAttachments
            ? { ...message, attachments: currentMessage.attachments }
            : message
      }
      state.historyAttachments = []

      // `fileIds` already includes the ids of files uploaded with this request,
      // so a retry can resend the same files without uploading them again.
      const { historyId, sessionId, collectionId, fileIds, selectionMode, translate, letterOperation } =
        action.payload
      state.lastSentPayloads[historyId] = {
        historyId,
        sessionId,
        collectionId,
        fileIds,
        ...(selectionMode && { selectionMode }),
        ...(translate && { translate }),
        ...(letterOperation && { letterOperation }),
        messageSchema: { message },
      }

      if (!action.payload.collectionId) {
        const responseIds = [action.payload.historyId, action.payload.sessionId].filter(Boolean)
        const createdHistory = state.CLHistoryList.find(history =>
          [history.historyId, history.sessionId].some(id => id && responseIds.includes(id)),
        )

        if (createdHistory) {
          state.currentHistory = createdHistory
        }

        state.currentCollection = null
        state.chatStateParams = {
          historyId: createdHistory?.historyId ?? action.payload.historyId,
          collectionId: undefined,
          isParamsSynced: false,
        }
      } else {
        // A project chat must not clear the active project while its history
        // is being created/refreshed asynchronously.
        const collectionId = action.payload.collectionId
        const collection = state.collections[collectionId]
        const responseIds = [action.payload.historyId, action.payload.sessionId].filter(Boolean)
        const existingHistory = collection?.collectionHistory?.find(history =>
          [history.historyId, history.sessionId].some(id => id && responseIds.includes(id)),
        )

        if (collection && !existingHistory) {
          const message = action.payload.messageSchema.message
          const historyName = (message.text || message.message || 'گفتگوی جدید').trim()
          const optimisticHistory: IChatHistory = {
            historyId: action.payload.historyId,
            sessionId: action.payload.sessionId,
            historyName,
            historyCount: 0,
            historyType: CHAT_MODELS_TYPES.GENERAL,
            state: action.payload.waiting ? CHAT_HISTORY_STATE.PENDING : CHAT_HISTORY_STATE.DONE,
            waiting: action.payload.waiting,
            answerStatus: action.payload.answerStatus,
            total: 1,
            createdAt: message.createdAt || new Date().toISOString(),
            abstractor: false,
            translate: [],
            reasoning: false,
            modelName: '',
            collectionId,
            collectionName: collection.collectionName,
            files: [],
            messages: [message],
          }
          const updatedCollection = {
            ...collection,
            collectionHistory: [...(collection.collectionHistory || []), optimisticHistory],
          }

          state.histories[action.payload.historyId] = optimisticHistory
          state.historyList.push(optimisticHistory)
          state.collections[collectionId] = updatedCollection
          state.collectionList = state.collectionList.map(item =>
            item.collectionId === collectionId ? updatedCollection : item,
          )
          state.currentCollection = updatedCollection
          state.currentHistory = optimisticHistory
        } else if (existingHistory) {
          state.currentHistory = existingHistory
        }

        state.chatStateParams = {
          historyId: existingHistory?.historyId ?? action.payload.historyId,
          collectionId,
          isParamsSynced: false,
        }
      }
    })
    .addCase(aiChatAssistant.rejected, (state, action) => {
      state.loadingState.collectionLessHistories = false
      const messageId = action.meta.arg.payload.messageSchema.message.id
      state.currentHistoryMessages = state.currentHistoryMessages.filter(
        message => message.id !== messageId,
      )
    })
    .addCase(editMessage.fulfilled, (state, action) => {
      state.currentHistoryMessages = action.payload.messages
      state.historyState = action.payload.historyState
      state.loadingState.chatResponse = true
    })
    // Create collection session
    .addCase(createSession.pending, state => {
      state.loadingState.createCollectionSession = true
    })
    .addCase(createSession.fulfilled, (state, action) => {
      state.loadingState.createCollectionSession = false
      state.modalsState = { ...state.modalsState, createCollectionSession: false }
      state.chatStateParams = {
        collectionId: action.payload.collectionId,
        historyId: action.payload.historyId,
        isParamsSynced: false,
      }
    })
    .addCase(createSession.rejected, state => {
      state.loadingState.createCollectionSession = false
      state.modalsState = { ...state.modalsState, createCollectionSession: false }
    })
    // todays histories
    .addCase(getTodaysHistories.pending, state => {
      state.loadingState.todaysHistories = true
    })
    .addCase(getTodaysHistories.fulfilled, (state, action) => {
      state.loadingState.todaysHistories = false
      state.todaysHistoryList = action.payload.todaysHistories
    })
    .addCase(getTodaysHistories.rejected, state => {
      state.loadingState.todaysHistories = false
      state.todaysHistoryList = []
    })
    // update collections
    .addCase(setCollectionsFromSocket.fulfilled, (state, action) => {
      state.collectionList = action.payload.collectionList
      state.collections = action.payload.collections
      state.histories = action.payload.histories
      state.historyList = action.payload.historyList
      // Socket snapshots can briefly omit the active collection while a new
      // history is being created. Keep the selection until it appears again.
      state.currentCollection = action.payload.currentCollection ?? state.currentCollection
      state.historyAttachments = []
      state.currentHistory = action.payload.currentHistory ?? state.currentHistory

      if (
        action.payload.newHistory &&
        action.payload.newHistory.collectionId === state.currentCollection?.collectionId
      ) {
        state.currentHistory = action.payload.newHistory
        state.chatStateParams = {
          isParamsSynced: true,
          collectionId: state.currentCollection.collectionId,
          historyId: action.payload.newHistory.historyId,
        }
      }
    })
    .addCase(setChatStateFromParams.fulfilled, (state, action) => {
      state.chatStateParams = action.payload
    })
    // upadate session translation
    .addCase(setSessionTranslation.fulfilled, (state, action) => {
      state.CLHistories = action.payload.CLHistories
      state.CLHistoryList = action.payload.CLHistoryList
      state.collectionList = action.payload.collectionList
      state.collections = action.payload.collections
      state.histories = action.payload.histories
      state.historyList = action.payload.historyList

      state.currentHistory = action.payload.currentHistory

      if (action.payload.currentCollection !== undefined) {
        state.currentCollection = action.payload.currentCollection
      }

    })
    //
    // delete
    //
    .addCase(deleteCollection.fulfilled, (state, action) => {
      state.collectionList = action.payload.collectionList
      state.collections = action.payload.collections
      state.histories = action.payload.histories
      state.historyList = action.payload.historyList

      state.historyAttachments = []

      // update cuyrrent state
      state.currentCollection = null
      state.currentGraph = initialState.currentGraph
      state.currentHistory = null
      state.currentHistoryMessages = []

      // update url
      state.chatStateParams = {
        isParamsSynced: true,
        collectionId: undefined,
        historyId: undefined,
      }
    })
    .addCase(deleteHistory.fulfilled, (state, action) => {
      state.CLHistories = action.payload.CLHistories
      state.CLHistoryList = action.payload.CLHistoryList

      // Deleting another session must not move the user away from the chat
      // they are currently viewing. Only clear the active state when that
      // exact history (or its server-side session id) was removed.
      if (!isCurrentHistory(state, action.meta.arg)) {
        return
      }

      state.historyAttachments = []

      // update cuyrrent state
      state.currentCollection = null
      state.currentGraph = initialState.currentGraph
      state.currentHistory = null
      state.currentHistoryMessages = []

      // update url
      state.chatStateParams = {
        isParamsSynced: false,
        collectionId: undefined,
        historyId: undefined,
      }
    })
    .addCase(deleteCollectionistory.fulfilled, (state, action) => {
      state.collections = action.payload.collections
      state.collectionList = action.payload.collectionList
      state.historyList = action.payload.historyList
      state.histories = action.payload.histories

      if (!isCurrentHistory(state, action.meta.arg.historyId)) {
        return
      }

      state.historyAttachments = []

      // update current state
      state.currentCollection = null
      state.currentGraph = initialState.currentGraph
      state.currentHistory = null
      state.currentHistoryMessages = []

      // update url
      state.chatStateParams = {
        isParamsSynced: false,
        collectionId: undefined,
        historyId: undefined,
      }
    })
    .addCase(getUploadFiles.pending, state => {
      state.loadingState.collectionFiles = true
    })
    .addCase(getUploadFiles.fulfilled, (state, action) => {
      state.loadingState.collectionFiles = false
      state.uploadFiles = action.payload.uploadFiles

      const { collectionId, collectionFiles } = action.payload
      const collection = state.collections[collectionId]
      if (collection) {
        const updatedCollection = { ...collection, files: collectionFiles }
        state.collections[collectionId] = updatedCollection
        state.collectionList = state.collectionList.map(item =>
          item.collectionId === collectionId ? updatedCollection : item,
        )

        if (state.currentCollection?.collectionId === collectionId) {
          state.currentCollection = updatedCollection
        }
      }
    })
    .addCase(getUploadFiles.rejected, state => {
      state.loadingState.collectionFiles = false
    })
    .addCase(updateSessionReasoning.fulfilled, (state, action) => {
      state.CLHistories = action.payload.CLHistories
      state.CLHistoryList = action.payload.CLHistoryList
      state.collectionList = action.payload.collectionList
      state.collections = action.payload.collections
      state.histories = action.payload.histories
      state.historyList = action.payload.historyList

      state.currentHistory = action.payload.currentHistory

      if (action.payload.currentCollection !== undefined) {
        state.currentCollection = action.payload.currentCollection
      }

    })
    .addCase(updateCollectionPrompt.fulfilled, state => state)
    .addCase(getModelsList.fulfilled, (state, action) => {
      state.aiModels = action.payload
    })
    .addCase(setAIModel.fulfilled, (state, action) => {
      state.CLHistories = action.payload.CLHistories
      state.CLHistoryList = action.payload.CLHistoryList
      state.collectionList = action.payload.collectionList
      state.collections = action.payload.collections
      state.histories = action.payload.histories
      state.historyList = action.payload.historyList

      state.currentHistory = action.payload.currentHistory

      if (action.payload.currentCollection !== undefined) {
        state.currentCollection = action.payload.currentCollection
      }

    })
    .addCase(uploadHistoryFile.fulfilled, (state, action) => {
      const attachment = action.payload
      const alreadySelected = state.historyAttachments.some(
        item => item.fileId === attachment.fileId || item._id === attachment._id,
      )

      if (!alreadySelected) {
        state.historyAttachments.push(attachment)
      }
    })
    .addCase(deleteSessionFile.fulfilled, (state, action) => {
      state.historyAttachments = state.historyAttachments.filter(
        file => file.fileId !== action.payload.fileId && file._id !== action.payload.fileId,
      )
      if (state.currentHistory?.files) {
        state.currentHistory.files = state.currentHistory.files.filter(
          file => file.fileId !== action.payload.fileId && file._id !== action.payload.fileId,
        )
      }
      state.currentHistoryMessages = state.currentHistoryMessages.map(message => ({
        ...message,
        attachments: message.attachments.filter(
          file => file.fileId !== action.payload.fileId && file._id !== action.payload.fileId,
        ),
      }))
    })
    .addCase(deleteCollectionFile.fulfilled, (state, action) => {
      state.historyAttachments = state.historyAttachments.filter(
        file => file.fileId !== action.payload.fileId && file._id !== action.payload.fileId,
      )
    })
}
