// Every file uploaded anywhere in the current chat so far (history-level
// files plus every message's own attachments), deduplicated by id. Used to
// show the running total instantly, without waiting on the backend to echo
// it back for a specific message.
export const selectAggregatedHistoryFiles = (state: RootState) => {
  const historyFiles = state.newChat.currentHistory?.files ?? []
  const messageFiles = state.newChat.currentHistoryMessages.flatMap(message => message.attachments)
  const seen = new Map<string, IChatSessionFileUploadItem>()

  for (const file of [...historyFiles, ...messageFiles]) {
    const id = file.fileId || file._id
    if (!id || seen.has(id)) {
      continue
    }
    seen.set(id, file)
  }

  return Array.from(seen.values())
}
