import './style.scss'

import { IChatMessage } from 'src/types/NewChat'
// import { timeFormatter } from 'src/pages/Chat/lib/utils'
import { KeyboardEvent, useEffect, useState } from 'react'
import AttachmentFiles from '../AttachmentFiles'
import MessageTypeBadge from '../../messageTypeBadge'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import { editMessage, selectCurrentHistory, updateEditedMessagePreview } from 'src/pages/Chat/slice'
import { t } from 'i18next'

const HumanMessage = ({ msg, isAnswering }: { msg: IChatMessage; isAnswering: boolean }) => {
  const dispatch = useBDMDispatch()
  const currentHistory = useBDMSelector(selectCurrentHistory)
  const [copied, setCopied] = useState(false)
  const [isEditing, setIsEditing] = useState(false)
  const [editText, setEditText] = useState(msg.message || '')
  const hasMessage = Boolean(msg.message?.trim())

  useEffect(() => {
    if (isAnswering) {
      setIsEditing(false)
    }
  }, [isAnswering])

  const handleCopy = async () => {
    const text = msg.message || ''
    if (!navigator.clipboard?.writeText) {
      const el = document.createElement('textarea')
      el.value = text
      el.style.position = 'fixed'
      document.body.appendChild(el)
      el.select()
      try {
        document.execCommand('copy')
        setCopied(true)
      } catch (e) {
        console.error('Fallback copy failed', e)
      }
      document.body.removeChild(el)
      setTimeout(() => setCopied(false), 1200)
      return
    }

    try {
      await navigator.clipboard.writeText(text)
      setCopied(true)
    } catch (err) {
      console.error('Copy failed', err)
    }
    setTimeout(() => setCopied(false), 1200)
  }

  const handleEdit = () => {
    setEditText(msg.message || '')
    setIsEditing(true)
  }

  const handleCancelEdit = () => {
    setEditText(msg.message || '')
    setIsEditing(false)
  }

  const handleSubmitEdit = () => {
    const message = editText.trim()

    if (!currentHistory || !message) {
      return
    }

    if (message === msg.message) {
      setIsEditing(false)
      return
    }

    dispatch(
      updateEditedMessagePreview({
        messageId: msg.id,
        message,
      }),
    )
    dispatch(
      editMessage({
        historyId: currentHistory.historyId,
        messageId: msg.id,
        message,
      }),
    )
    setIsEditing(false)
  }

  const handleEditKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key !== 'Enter' || event.shiftKey) {
      return
    }

    event.preventDefault()
    handleSubmitEdit()
  }

  return (
    <div className='chat-human-messsage'>
      <div className='chat-human-messsage-msg-box'>
        {hasMessage && <div className='chat-human-messsage-msg'>{msg.message}</div>}
        <AttachmentFiles files={msg.attachments} />
        {msg.attachments.length > 0 && msg.messageType !== 'rag' && (
          <MessageTypeBadge messageType={msg.messageType} attached />
        )}
        {hasMessage && isEditing && !isAnswering && (
          <div className='chat-human-messsage-edit-box'>
            <textarea
              className='chat-human-messsage-edit-input'
              value={editText}
              onChange={event => setEditText(event.target.value)}
              onKeyDown={handleEditKeyDown}
              dir='auto'
              autoFocus
            />
            <div className='chat-human-messsage-edit-actions'>
              <button
                type='button'
                className='chat-human-messsage-edit-btn chat-human-messsage-edit-btn--cancel'
                onClick={handleCancelEdit}
              >
                انصراف
              </button>
              <button
                type='button'
                className='chat-human-messsage-edit-btn chat-human-messsage-edit-btn--submit'
                onClick={handleSubmitEdit}
                disabled={!editText.trim()}
              >
                ثبت
              </button>
            </div>
          </div>
        )}
        {/* <div className='chat-human-messsage-msg-time'>{timeFormatter(msg.createdAt)}</div> */}
        {hasMessage && !isAnswering && (
          <div className='chat-human-messsage-actions'>
            <button
              className='chat-human-messsage-action-btn'
              onClick={handleCopy}
              type='button'
              aria-label={t('chat-copy-message')}
            >
              {copied ? (
                <svg
                  xmlns='http://www.w3.org/2000/svg'
                  width='14'
                  height='14'
                  viewBox='0 0 24 24'
                  fill='none'
                  stroke='currentColor'
                  strokeWidth='2'
                  strokeLinecap='round'
                  strokeLinejoin='round'
                  aria-hidden='true'
                >
                  <path d='M20 6 9 17l-5-5' />
                </svg>
              ) : (
                <svg
                  xmlns='http://www.w3.org/2000/svg'
                  width='14'
                  height='14'
                  viewBox='0 0 24 24'
                  fill='none'
                  stroke='currentColor'
                  strokeWidth='2'
                  strokeLinecap='round'
                  strokeLinejoin='round'
                  aria-hidden='true'
                >
                  <rect x='9' y='9' width='13' height='13' rx='2' />
                  <path
                    d='M5 15H4a2 2 0 0 1-2-2V4
           a2 2 0 0 1 2-2h9
           a2 2 0 0 1 2 2v1'
                  />
                </svg>
              )}
            </button>
            <button
              className='chat-human-messsage-action-btn'
              onClick={handleEdit}
              type='button'
              aria-label={t('chat-edit-message')}
            >
              <svg
                xmlns='http://www.w3.org/2000/svg'
                width='14'
                height='14'
                viewBox='0 0 24 24'
                fill='none'
                stroke='currentColor'
                strokeWidth='2'
                strokeLinecap='round'
                strokeLinejoin='round'
                aria-hidden='true'
              >
                <path d='M12 20h9' />
                <path d='M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z' />
              </svg>
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

export default HumanMessage
