import { useEffect, useState } from 'react'
import { io, Socket } from 'socket.io-client'
import { INotification, DownloadFiles, IBDMSession } from 'src/types'
import { SOCKET_BASE_URL } from 'src/lib/constants'
import { logout } from 'src/lib/utils'
import { useBDMDispatch } from 'src/lib/store/hooks'
import {
  setNotifications as setBDMNotifications,
  setDownloadFiles as setBDMDownloadFiles,
  setSessions as setBDMSessiosn,
} from 'src/lib/slice/bdm/bdmSlice'
import { useBDMContext, useBDMContextDispatch } from 'src/lib/context'
import { BDM_CONTEXT_ACTIONS } from 'src/lib/context/reducers'
import { IChatFLMessage } from 'src/types/ChatFL'
import {
  setStream as setChatStream,
  setSessions as setAiAssistantSessions,
} from 'src/pages/Chat/slice/oldVersion'

import {
  setStreamFromSocket,
  setCLHistoryListFromSocket,
  setCollectionsFromSocket,
  syncSocketMessageAttachments,
} from 'src/pages/Chat/slice'
import { IChatCollection, IChatHistory, IChatMessage } from 'src/types/NewChat'

const useSocket = () => {
  const dispatch = useBDMDispatch()
  const bdmContextDispatch = useBDMContextDispatch()
  const { accessToken, addAToast } = useBDMContext()

  const [socket, setSocket] = useState<Socket>()

  useEffect(() => {
    if (!accessToken && socket) {
      socket.emit('logOut')
      socket.disconnect()
    }
    if (accessToken && !socket?.connected) {
      const socketObject = io(SOCKET_BASE_URL, {
        auth: { token: accessToken },
        // path: window.__RUNTIME_CONFIG__.REACT_APP_LOCAL_VERSION ? '/bdm/socket.io/' : '/socket.io/',
        path: window.__RUNTIME_CONFIG__.REACT_APP_LOCAL_VERSION
          ? process.env.PUBLIC_URL === '/bdm'
            ? '/bdm/socket.io/'
            : '/chat/socket.io/'
          : '/socket.io/',
        transports: ['websocket'],
      })
      setSocket(socketObject)
      bdmContextDispatch({ type: BDM_CONTEXT_ACTIONS.SET_SOCKER, payload: socketObject })
    }
  }, [accessToken, socket?.connected, setSocket])

  useEffect(() => {
    if (!socket) {
      return
    }

    const onConnect = () => {
      console.log('connected')
    }

    const onMessage = (msg: string) => {
      return msg
    }

    const onDisconnect = () => {
      console.log('disconnected')
    }

    const onConnectError = (msg: string) => {
      console.log('error', { error: msg })
    }

    const onGetGraph = (graph: string) => {
      console.log('graph', { graph })
    }

    const onNotifications = (notifications: Array<INotification>, total = 0) => {
      console.log('notifications', { notifications })
      console.log('notifications total', total)

      if (!notifications) {
        return
      }

      dispatch(setBDMNotifications({ notifications, total }))
    }

    const onLogOutForce = () => {
      console.log('LogOut')
      logout()
    }

    const onGetDownloadFiles = (downloadList: Array<DownloadFiles>) => {
      console.log('getDownloadFiles', { downloadList })

      if (!downloadList) {
        return
      }

      const daownloads = downloadList.map((item: DownloadFiles, idx: number) => ({
        ...item,
        id: idx,
      }))
      dispatch(setBDMDownloadFiles(daownloads))
    }

    const onCurrentGraph = (data: any) => {
      console.log('currentGraph', data)
    }

    const onActiveFilters = (data: any) => {
      console.log('activeFilters', data)
    }

    const onSocketEventsStatus = (data: any) => {
      console.log('socketEventsStatus', data)
      const messages = Array.isArray(data) ? data : data?.messages
      if (!Array.isArray(messages)) {
        return
      }
      messages.forEach(msg => {
        if (!msg?.message) {
          return
        }

        const toastType = msg.type || 'info'
        const isImportant =
          msg.important === true ||
          toastType === 'error' ||
          toastType === 'warning' ||
          toastType === 'destructive'

        if (isImportant) {
          addAToast?.(msg.message, toastType)
        }
      })
    }

    const onAiAssistantSessionsList = (data: any) => {
      console.log('aiAssistantSessionsList', data)
      dispatch(setAiAssistantSessions(data))
    }

    const onActiveFilterStatus = (data: any) => {
      console.log('statusOfactiveFilters', data)
    }

    const onValidUsersBySession = (sessions: Array<IBDMSession>) => {
      console.log('validUsersBySession: ', sessions)
      dispatch(setBDMSessiosn(sessions))
    }

    const syncIncomingAttachments = (
      messages: Record<string, [IChatFLMessage, IChatFLMessage]>,
    ) => {
      Object.values(messages ?? {}).forEach(streamItem => {
        const request = Array.isArray(streamItem) ? streamItem[0] : undefined
        const attachments = request?.attachments?.filter(
          attachment => typeof attachment === 'object' && attachment !== null,
        )

        if (!request || !attachments?.length) {
          return
        }

        dispatch(
          syncSocketMessageAttachments({
            ...request,
            attachments,
          } as unknown as IChatMessage),
        )
      })
    }

    const onAiAssistantMessage = (messages: Record<string, [IChatFLMessage, IChatFLMessage]>) => {
      console.log('aiAssistantMessage', messages)
      dispatch(setChatStream(messages))
      // TODO: indexs are not compatible
      dispatch(setStreamFromSocket(messages as any))
      syncIncomingAttachments(messages)
    }

    const onAiAssistantMessageHistory = (
      messages: Record<string, [IChatFLMessage, IChatFLMessage]>,
    ) => {
      console.log('onAiAssistantMessageHistory', messages)
      dispatch(setChatStream(messages))
      // // TODO: indexs are not compatible
      dispatch(setStreamFromSocket(messages as any))
      syncIncomingAttachments(messages)
    }

    const onAiCollections = (data: { collections: IChatCollection[] }) => {
      if (!data || !data.collections) {
        return
      }
      console.log('onAiCollections', data.collections)
      dispatch(setCollectionsFromSocket(data.collections))
    }

    const onAiNewHistory = (newHistory: IChatHistory) => {
      console.log('onAiNewHistory', newHistory)
      dispatch(setCLHistoryListFromSocket(newHistory))
    }

    socket.on('graph', onGetGraph)
    socket.on('currentGraph', onCurrentGraph)
    socket.on('activeFilters', onActiveFilters)
    socket.on('msg', onMessage)
    socket.on('connect', onConnect)
    socket.on('connect-error', onConnectError)
    socket.on('disconnect', onDisconnect)
    socket.on('notifications', onNotifications)
    socket.on('getDownloadFiles', onGetDownloadFiles)
    socket.on('logOutForce', onLogOutForce)
    socket.on('socketEventsStatus', onSocketEventsStatus)
    socket.on('aiAssistantSessionsList', onAiAssistantSessionsList)
    socket.on('statusOfactiveFilters', onActiveFilterStatus)
    socket.on('validUsersBySession', onValidUsersBySession)
    socket.on('aiAssistantMessage', onAiAssistantMessage)
    socket.on('aiCollections', onAiCollections)
    socket.on('aiNewHistory', onAiNewHistory)
    socket.on('aiAssistantMessageHistory', onAiAssistantMessageHistory)

    return () => {
      socket.off('graph', onGetGraph)
      socket.off('currentGraph', onCurrentGraph)
      socket.off('activeFilters', onActiveFilters)
      socket.off('msg', onMessage)
      socket.off('notifications', onNotifications)
      socket.off('connect', onConnect)
      socket.off('disconnect', onDisconnect)
      socket.off('connect-error', onConnectError)
      socket.off('getDownloadFiles', onGetDownloadFiles)
      socket.off('logOutForce', onLogOutForce)
      socket.off('socketEventsStatus', onSocketEventsStatus)
      socket.off('aiAssistantSessionsList', onAiAssistantSessionsList)
      socket.off('statusOfactiveFilters', onActiveFilterStatus)
      socket.off('statusOfactiveFilters', onActiveFilterStatus)
      socket.off('validUsersBySession', onValidUsersBySession)
      socket.off('validUsersBySession', onValidUsersBySession)
      // ai chat
      socket.off('aiAssistantMessage', onAiAssistantMessage)
      socket.off('aiCollections', onAiCollections)
      socket.off('aiNewHistory', onAiNewHistory)
      socket.off('aiAssistantMessageHistory', onAiAssistantMessageHistory)
    }
  }, [socket?.connected])
}

export default useSocket
