import { ITabularPreviewDTO, TPreviewRowValue } from 'src/types/NewChat/api'

const DEFAULT_PREVIEW_LIMIT = 300
const MAX_BINARY_PREVIEW_BYTES = 64

const normalizeInteger = (value: number | undefined, fallback: number) => {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 ? value : fallback
}

const formatBinaryValue = (value: Uint8Array) => {
  const bytes = value.slice(0, MAX_BINARY_PREVIEW_BYTES)
  const hex = Array.from(bytes, byte => byte.toString(16).padStart(2, '0')).join('')
  const suffix = value.length > MAX_BINARY_PREVIEW_BYTES ? '…' : ''

  return `0x${hex}${suffix}`
}

const stringifyNestedValue = (value: object) => {
  try {
    return JSON.stringify(value, (_key, nestedValue) => {
      if (typeof nestedValue === 'bigint') {
        return nestedValue.toString()
      }

      if (nestedValue instanceof Uint8Array) {
        return formatBinaryValue(nestedValue)
      }

      return nestedValue
    })
  } catch {
    return String(value)
  }
}

export const normalizeParquetValue = (value: unknown): TPreviewRowValue => {
  if (value === null || value === undefined) {
    return null
  }

  if (typeof value === 'string' || typeof value === 'boolean') {
    return value
  }

  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : String(value)
  }

  if (typeof value === 'bigint') {
    return value.toString()
  }

  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? String(value) : value.toISOString()
  }

  if (value instanceof Uint8Array) {
    return formatBinaryValue(value)
  }

  if (typeof value === 'object') {
    return stringifyNestedValue(value) ?? String(value)
  }

  return String(value)
}

interface IParquetPreviewOptions {
  limit?: number
  offset?: number
  mimeType?: string
}

export const parseParquetPreview = async (
  file: ArrayBuffer,
  { limit, offset, mimeType }: IParquetPreviewOptions = {},
): Promise<ITabularPreviewDTO> => {
  const [{ parquetMetadataAsync, parquetReadObjects, parquetSchema }, { compressors }] =
    await Promise.all([import('hyparquet'), import('hyparquet-compressors')])
  const previewLimit = normalizeInteger(limit, DEFAULT_PREVIEW_LIMIT)
  const previewOffset = normalizeInteger(offset, 0)
  const metadata = await parquetMetadataAsync(file)
  const totalRowsBigInt = metadata.num_rows
  const totalRows =
    totalRowsBigInt > BigInt(Number.MAX_SAFE_INTEGER)
      ? Number.MAX_SAFE_INTEGER
      : Number(totalRowsBigInt)
  const rowEnd = Math.min(totalRows, previewOffset + previewLimit)
  const parquetSchemaTree = parquetSchema(metadata)
  const columns = parquetSchemaTree.children.map(column => column.element.name)
  const rawRows =
    previewOffset < totalRows && previewLimit > 0
      ? await parquetReadObjects({
          file,
          metadata,
          compressors,
          rowStart: previewOffset,
          rowEnd,
        })
      : []
  const rows = rawRows.map(row =>
    Object.fromEntries(
      Object.entries(row).map(([column, value]) => [column, normalizeParquetValue(value)]),
    ),
  )

  return {
    success: true,
    type: 'rows',
    data: rows,
    columns,
    shown: rows.length,
    limit: previewLimit,
    truncated: rowEnd < totalRows,
    url: '',
    mimeType: mimeType || 'application/vnd.apache.parquet',
    size: file.byteLength,
  }
}
