import Tooltip, { TooltipProps } from '@mui/material/Tooltip'

interface IProps {
  className?: string
  title: string
  placement?: TooltipProps['placement']
}

const InfoIcon = ({ title, placement = 'bottom', className }: IProps) => {
  return (
    <Tooltip title={title} placement={placement}>
      <div className={`bdm-info-btn ${className ? className : ''}`.trim()} />
    </Tooltip>
  )
}

export default InfoIcon
