import './style.scss'

import { IChatMessage } from 'src/types/NewChat'
// import { timeFormatter } from 'src/pages/Chat/lib/utils'

import BDMMarkdown from 'src/components/MarkDown'
import AttachmentFiles from '../AttachmentFiles'
import MessageTypeBadge from '../../messageTypeBadge'
import NerEntitiesTable, { parseNerResult } from '../NerEntitiesTable'

export const BotMessage = ({ msg }: { msg: IChatMessage }) => {
  const hasAttachments = msg.attachments.length > 0
  const messageType = msg.messageType ?? msg.type
  const nerResult = parseNerResult(msg.message)

  return (
    <div className='chat-bot-messsage'>
      <div className='chat-bot-messsage-box'>
        <div className='chat-bot-messsage-msg'>
          {nerResult ? (
            <NerEntitiesTable entities={nerResult.entities} />
          ) : (
            <BDMMarkdown text={msg.message} />
          )}
        </div>
        <AttachmentFiles files={msg.attachments} />
        {hasAttachments && <MessageTypeBadge messageType={messageType} attached />}
        {/* <div className='chat-bot-messsage-msg-time'>{timeFormatter(msg.createdAt)}</div> */}
      </div>
    </div>
  )
}

export default BotMessage
