import './style.scss'

import ChatInput from '../ChatInput'
import ChatHeader from '../ChatHeader'
import ChatOptions from '../ChatOptions'

const ChatProjectScreen = () => {
  return (
    <div style={{ width: '100%', height: '100%' }}>
      <ChatHeader />
      <div className='chat-screen-chat-box'>
        <div className='chat-screen-chat-box__input'>
          <ChatInput className='chat-project-screen-input' />
          <ChatOptions />
        </div>
      </div>
    </div>
  )
}

export default ChatProjectScreen
