import { ReactNode, SyntheticEvent, useCallback, useEffect, useMemo, useState } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'

export interface TabConfig {
  id: number
  title: string
  body: ReactNode
  active: boolean
  hash?: string
}

const getTabIndexFromHash = (tabsConfig: TabConfig[], hash: string): number => {
  const tab = tabsConfig.find(tab => tab.hash === hash && tab.active)
  return tab ? tab.id : tabsConfig.find(tab => tab.active)?.id ?? 0
}

const useTabs = (tabs: TabConfig[]) => {
  const navigate = useNavigate()
  const location = useLocation()

  const enabledTabs = useMemo(() => tabs.filter(tab => tab.active), [tabs])
  const hasHashTabs = useMemo(() => enabledTabs.some(tab => tab.hash), [enabledTabs])

  // initial selected tab
  const [selectedTab, setSelectedTab] = useState<number>(() =>
    hasHashTabs ? getTabIndexFromHash(enabledTabs, location.hash) : enabledTabs[0]?.id ?? 0,
  )

  const handleTabChange = useCallback(
    (_event: SyntheticEvent, newTabId: number) => {
      if (!enabledTabs.some(tab => tab.id === newTabId)) {
        return
      }

      setSelectedTab(newTabId)

      // only update URL if at least one tab has hash
      if (hasHashTabs) {
        const tabConfig = enabledTabs.find(tab => tab.id === newTabId)
        if (tabConfig?.hash) {
          navigate(tabConfig.hash)
        }
      }
    },
    [enabledTabs, hasHashTabs, navigate],
  )

  // sync with hash if using hash-based tabs
  useEffect(() => {
    if (!hasHashTabs) {
      return
    }

    const tabId = getTabIndexFromHash(enabledTabs, location.hash)
    if (tabId !== selectedTab) {
      setSelectedTab(tabId)
    }
  }, [location.hash, selectedTab, enabledTabs, hasHashTabs])

  return { tabs: enabledTabs, selectedTab, setSelectedTab, handleTabChange }
}

export default useTabs
