import { generateLongId } from 'src/lib/utils'
import type { IAIChatAssistantDTI } from 'src/types/NewChat/api'
import { CHAT_ANSWER_STATUS, type IChatHistory, type IChatMessage } from 'src/types/NewChat'

const isSameMessageText = (a: IChatMessage, b: IChatMessage) =>
  (a.text ?? a.message) === (b.text ?? b.message) && a.message === b.message

const getResolvedFileIds = (message: IChatMessage) =>
  message.attachments
    .map(file => file._id || file.fileId)
    .filter(fileId => fileId && !fileId.startsWith('pending-'))

/**
 * Builds the request for «تلاش مجدد»: the same payload the failed message was
 * sent with (mode, files, translate/letter options), under a fresh message id.
 * Already-uploaded files are referenced by id, so nothing is uploaded again.
 */
export const buildRetryPayload = ({
  history,
  failedMessage,
  lastSentPayload,
}: {
  history: Pick<IChatHistory, 'historyId' | 'collectionId'>
  failedMessage: IChatMessage
  lastSentPayload?: IAIChatAssistantDTI
}): IAIChatAssistantDTI => {
  // The stored payload is only trusted while it still describes the failed
  // message (e.g. not after the user edited its text). Otherwise the payload is
  // rebuilt from the message itself, which keeps its mode and attachments but
  // not the translate/letter options (those exist only in the original request).
  const storedMessage = lastSentPayload?.messageSchema.message
  const base: IAIChatAssistantDTI =
    lastSentPayload && storedMessage && isSameMessageText(storedMessage, failedMessage)
      ? lastSentPayload
      : {
          collectionId: history.collectionId ?? null,
          sessionId: history.historyId,
          fileIds: getResolvedFileIds(failedMessage),
          ...(failedMessage.messageType && { selectionMode: failedMessage.messageType }),
          messageSchema: { message: failedMessage },
        }
  const sourceMessage = base.messageSchema.message

  return {
    ...base,
    historyId: history.historyId,
    sessionId: history.historyId,
    collectionId: history.collectionId ?? base.collectionId ?? null,
    answerStatus: CHAT_ANSWER_STATUS.PENDING,
    fileIds: Array.from(new Set([...base.fileIds, ...getResolvedFileIds(failedMessage)])),
    messageSchema: {
      message: {
        ...sourceMessage,
        id: generateLongId(),
        createdAt: new Date().toISOString(),
        hidden: false,
      },
    },
  }
}
