import { ChangeEvent, DragEvent, useRef, useState } from 'react'
import { csvParse } from 'd3-dsv'
import { useNavigate } from 'react-router-dom'
import excelYarIcon from 'src/assets/excelYarIcon.svg'
import ExcelAssistantAPIs from 'src/api/excelAssistant'
import { addAToast } from 'src/lib/context'
import { WorkbookPreviewRow } from '../../types'

const ACCEPTED_EXTENSIONS = ['csv', 'xls', 'xlsx']

const WorkbookUpload = () => {
  const navigate = useNavigate()
  const inputRef = useRef<HTMLInputElement>(null)
  const [isDragging, setIsDragging] = useState(false)
  const [isUploading, setIsUploading] = useState(false)

  const upload = async (file?: File) => {
    if (!file || isUploading) {
      return
    }

    const extension = file.name.split('.').pop()?.toLowerCase() ?? ''
    if (!ACCEPTED_EXTENSIONS.includes(extension)) {
      addAToast('فقط فایل‌های CSV، XLS و XLSX قابل بارگذاری هستند.', 'error')
      return
    }

    setIsUploading(true)
    try {
      let previewRows: WorkbookPreviewRow[] = []
      if (extension === 'csv') {
        previewRows = csvParse(await file.text()).map(row => ({ ...row }))
      }

      const response = await ExcelAssistantAPIs().uploadWorkbook(file)
      if (!response?.data?.workbookId) {
        throw new Error('شناسه فایل اکسل از سرور دریافت نشد.')
      }

      navigate(`/excel-assistant/workbooks/${response.data.workbookId}`, {
        state: { fileName: file.name, previewRows },
      })
    } catch (error) {
      addAToast(error instanceof Error ? error.message : 'بارگذاری فایل ناموفق بود.', 'error')
    } finally {
      setIsUploading(false)
      if (inputRef.current) {
        inputRef.current.value = ''
      }
    }
  }

  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault()
    setIsDragging(false)
    upload(event.dataTransfer.files?.[0])
  }

  const handleInput = (event: ChangeEvent<HTMLInputElement>) => {
    upload(event.target.files?.[0])
  }

  return (
    <main className='excel-assistant-upload'>
      <section className='excel-assistant-upload__card'>
        <div className='excel-assistant-upload__brand'>
          <img src={excelYarIcon} alt='' />
          <div>
            <h1>اکسل یار</h1>
            <p>تحلیل و گفت‌وگو با داده‌های جدولی</p>
          </div>
        </div>

        <div
          className={`excel-assistant-upload__dropzone ${isDragging ? 'is-dragging' : ''}`}
          onDragOver={event => {
            event.preventDefault()
            setIsDragging(true)
          }}
          onDragLeave={() => setIsDragging(false)}
          onDrop={handleDrop}
        >
          <div className='excel-assistant-upload__drop-icon'>+</div>
          <h2>{isUploading ? 'در حال بارگذاری فایل...' : 'فایل اکسل را اینجا رها کنید'}</h2>
          <p>فرمت‌های CSV، XLS و XLSX</p>
          <button type='button' onClick={() => inputRef.current?.click()} disabled={isUploading}>
            انتخاب فایل
          </button>
          <input
            ref={inputRef}
            type='file'
            hidden
            accept='.csv,.xls,.xlsx'
            onChange={handleInput}
            disabled={isUploading}
          />
        </div>
      </section>
    </main>
  )
}

export default WorkbookUpload
