import 'src/theme/theme.scss'
import 'react-toastify/scss/main.scss'

import { I18nextProvider } from 'react-i18next'
import { Suspense, StrictMode } from 'react'
import { initI18n } from 'src/lib/utils'
import ChatApp from 'src/pages'
import BDMContextProvider from 'src/lib/context'
import ToastContainer from 'src/components/Toast/ToastContainer'
import { BrowserRouter } from 'react-router-dom'
import { createRoot } from 'react-dom/client'
import { store, persistor } from 'src/lib/store'
import { Provider } from 'react-redux'
import { PersistGate } from 'redux-persist/integration/react'
import AppInitializer from 'src/lib/hoc/AppInitializer'
import i18n from 'i18next'

initI18n()

declare global {
  interface Window {
    BDM_CONFIG: {
      projects: {
        parentURLOnBuild: string
        parentURLOnDevelopemnt: string
      }
      map: {
        url: Array<{
          name: string
          url: string
          iconName: string
        }>
        maxZoom: number
        minZoom: number
        initialState: {
          zoom: number
          lng: number
          lat: number
        }
      }
      graph: {
        maxZoom: number
        minZoom: number
        nodesMustFixOnStart: boolean
        forceCollide: number
        velocityDecay: number
        maxNodeCountOnGIS: number
        maxNodeCountOnGISAdmin: number
        maxFeatureOnGisPreview: number
      }
    }
    front_changes: {
      [key: string]: {
        title: string
        changes: Array<string>
      }
    }
    fa_dictionary: Record<string, string>
    en_dictionary?: Record<string, string>
    meta_data_dictionary?: Record<string, string>
    __RUNTIME_CONFIG__: Record<string, string>
  }
}

const root = createRoot(document.getElementById('root') as HTMLElement)

root.render(
  <StrictMode>
    <Suspense fallback='loading ...'>
      <BrowserRouter basename='/chat'>
        <I18nextProvider i18n={i18n}>
          <Provider store={store}>
            <PersistGate loading={null} persistor={persistor}>
              <BDMContextProvider>
                <ToastContainer />
                <AppInitializer>
                  <ChatApp />
                </AppInitializer>
              </BDMContextProvider>
            </PersistGate>
          </Provider>
        </I18nextProvider>
      </BrowserRouter>
    </Suspense>
  </StrictMode>,
)
