import { CHAT_MESSAGE_TYPES, IChatMessage } from 'src/types/NewChat'
import { CSSProperties, useEffect, useRef } from 'react'
import { t } from 'i18next'
import { useBDMSelector } from 'src/lib/store/hooks'
import { selectCurrentHistory } from 'src/pages/Chat/slice'

import BotMessage from './components/BotMessage'
import HumanMessage from './components/HumanMessage'
import LoadingMessage from './components/LoadingMessage'
import { isMessageLoading } from 'src/pages/Chat/lib/streamStatus'

const MESSAGE_MARGIN = 32

interface IProps {
  index: number
  data: IChatMessage
  setItemSize?: (index: number, size: number) => void
  style: CSSProperties
  isAnswering: boolean
}

const ChatMessage = ({ index, style, data: msg, setItemSize, isAnswering }: IProps) => {
  const messageRef = useRef<HTMLDivElement>(null)
  const currentHistory = useBDMSelector(selectCurrentHistory)
  // Streaming answers may already contain text. Show that partial text as it
  // arrives; only use the loading row while there is still nothing to render.
  const hasAnswerText = Boolean(msg.message || msg.text)
  const isLoadingMessage =
    isMessageLoading(msg.type, msg.answerStatus) && !(msg.bot && hasAnswerText)
  // The restored assistant placeholder can have a generic message type. Its
  // history still carries the selection mode, which is the source of the
  // correct loading label after a page refresh.
  const loadingType =
    msg.messageType ?? (msg.bot ? currentHistory?.selectionMode : undefined) ?? msg.type
  const loadingMessage =
    loadingType === CHAT_MESSAGE_TYPES.SUMMARIZING
      ? t('chat-loading-summarizing')
      : loadingType === CHAT_MESSAGE_TYPES.TRANSLATING
      ? t('chat-loading-translating')
      : loadingType === CHAT_MESSAGE_TYPES.KEYWORD_EXTRACTION
      ? t('chat-loading-keywords')
      : loadingType === CHAT_MESSAGE_TYPES.NER
      ? t('chat-loading-named-entities')
      : loadingType === CHAT_MESSAGE_TYPES.MINUTES_GENERATOR
      ? t('chat-loading-meeting-minutes')
      : loadingType === CHAT_MESSAGE_TYPES.REPORT_GENERATOR
      ? t('chat-loading-report')
      : loadingType === CHAT_MESSAGE_TYPES.OCR
      ? t('chat-loading-ocr')
      : loadingType === CHAT_MESSAGE_TYPES.LETTER_GENERATOR
      ? t('chat-loading-letter')
      : loadingType === CHAT_MESSAGE_TYPES.STT
      ? t('chat-loading-stt')
      : t('chat-loading-answering')

  useEffect(() => {
    const element = messageRef.current

    if (!element || !setItemSize) {
      return
    }

    const updateSize = () => {
      setItemSize(index, element.clientHeight + MESSAGE_MARGIN)
    }

    updateSize()

    const resizeObserver = new ResizeObserver(updateSize)
    resizeObserver.observe(element)

    return () => {
      resizeObserver.disconnect()
    }
  }, [index, setItemSize, msg.id, msg.message])

  return (
    <div style={{ ...style }}>
      <div ref={messageRef}>
        {isLoadingMessage ? (
          <div className='loading-message-chat'>
            <div className='dots'>
              {loadingMessage}
              <span>.</span>
              <span>.</span>
              <span>.</span>
            </div>
            <LoadingMessage />
          </div>
        ) : msg.bot ? (
          <BotMessage msg={msg} />
        ) : (
          <HumanMessage msg={msg} isAnswering={isAnswering} />
        )}
      </div>
    </div>
  )
}
export default ChatMessage
