import './style.scss'

import { ReactNode } from 'react'

interface Tabpanel {
  value: number
  index: number
  children?: ReactNode
}

const TabPanel = ({ value, index, children, ...props }: Tabpanel) => {
  if (value !== index) {
    return null
  }

  return (
    <div
      role='tabpanel'
      className='file-manager-tabpanel__item'
      hidden={value !== index}
      id={`file-manager-tabpanel-${index}`}
      aria-labelledby={`file-manager-tab-${index}`}
      {...props}
    >
      {children}
    </div>
  )
}

export default TabPanel
