import './style.scss'

import Menu from '@mui/material/Menu'
import editIcon from 'src/assets/editIcon2.svg'
import editIcon2White from 'src/assets/editIcon2White.svg'
import pinIcon from 'src/assets/pinIcon.svg'
import pinIconWhite from 'src/assets/pinIconWhite.svg'
import transferFolderIcon from 'src/assets/transferFolderIcon.svg'
import transferFolderIconWhite from 'src/assets/transferFolderIconWhite.svg'
import exportFileIcon from 'src/assets/exportFileIcon.svg'
import exportFileIconWhite from 'src/assets/exportFileIconWhite.svg'
import deleteIcon from 'src/assets/trashIcon.svg'
import arrowUpnIcon from 'src/assets/arrowUpnIcon.svg'
import arrowUpnIconWhite from 'src/assets/arrowUpnIconWhite.svg'
import doneBlueIcon from 'src/assets/doneBlueIcon.svg'
import chatIcon from 'src/assets/chatIcon2.svg'
import chatIconWhite from 'src/assets/chatIcon2White.svg'
import {
  deleteCollectionistory,
  deleteHistory,
  selectCLHistories,
  selectHistories,
  setSessionTranslation,
  pinSession,
  transferHistoryToCollection,
} from 'src/pages/Chat/slice'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import { FormEvent, useEffect, useRef, useState } from 'react'
import TransferProject from '../TransferProject'
import DeleteConfirmDialog from '../DeleteConfirmDialog'
import { RootState } from 'src/lib/store'
import ChatAPIs from 'src/api/chat'
import { addAToast } from 'src/lib/context'
import { TExportSessionFormat } from 'src/types/NewChat/api'
import { IChatMessage } from 'src/types/NewChat'
import { t } from 'i18next'
import { parseNerResult } from '../../../ChatMessage/components/NerEntitiesTable'
import {
  downloadChatAsPdf,
  downloadNerEntitiesAsPdf,
  formatChatAsText,
  formatNerEntitiesAsText,
} from '../../../ChatMessage/components/NerEntitiesTable/export'

interface IProps {
  menuAnchorEl: HTMLElement | null
  menuIds: { collectionId?: string; historyId?: string }
  onClose: () => void
}
const HistoryCardMenu = ({ menuAnchorEl, menuIds: { historyId, collectionId }, onClose }: IProps) => {
  const dispatch = useBDMDispatch()
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const histories = useBDMSelector(selectHistories)
  const CLHistories = useBDMSelector(selectCLHistories)
  const history = historyId ? (collectionId ? histories[historyId] : CLHistories[historyId]) : null
  const renameInputRef = useRef<HTMLInputElement>(null)
  const [isRenaming, setIsRenaming] = useState(false)
  const [renameValue, setRenameValue] = useState('')
  const [isExportOpen, setIsExportOpen] = useState(false)
  const [exportLoadingFormat, setExportLoadingFormat] = useState<TExportSessionFormat | null>(null)
  const [pinLoading, setPinLoading] = useState(false)
  // Captured on click because the parent clears menuIds as soon as the menu closes.
  const [deleteTarget, setDeleteTarget] = useState<{
    historyId: string
    collectionId?: string
    name: string
  } | null>(null)
  const [generalTransferLoading, setGeneralTransferLoading] = useState(false)
  const isLtr = document.documentElement.dir === 'ltr'

  const closeMenu = () => {
    setIsExportOpen(false)
    onClose()
  }

  const handleDelete = () => {
    if (historyId) {
      setDeleteTarget({ historyId, collectionId, name: history?.historyName ?? '' })
    }
    onClose()
  }

  const confirmDelete = () => {
    if (!deleteTarget) {
      return
    }

    return deleteTarget.collectionId
      ? dispatch(
          deleteCollectionistory({
            historyId: deleteTarget.historyId,
            collectionId: deleteTarget.collectionId,
          }),
        ).unwrap()
      : dispatch(deleteHistory(deleteTarget.historyId)).unwrap()
  }
  const handleTogglePin = async () => {
    if (!historyId || !history || pinLoading) {
      return
    }

    setPinLoading(true)
    try {
      await dispatch(pinSession({ historyId, collectionId: collectionId ?? null })).unwrap()
      closeMenu()
    } finally {
      setPinLoading(false)
    }
  }
  const [transferAnchorEl, setTransferAnchorEl] = useState<HTMLElement | null>(null)
  const handleTransferToProject = (e: React.MouseEvent<HTMLButtonElement>) => {
    setTransferAnchorEl(prev =>
      prev === e.currentTarget ? null : e.currentTarget
    )
  }

  const handleTransferToGeneral = async () => {
    if (!historyId || !collectionId || generalTransferLoading) {
      return
    }

    setGeneralTransferLoading(true)
    try {
      await dispatch(
        transferHistoryToCollection({
          historyId,
          sourceCollectionId: collectionId,
          targetCollectionId: '',
        }),
      ).unwrap()
      closeMenu()
    } finally {
      setGeneralTransferLoading(false)
    }
  }
  const handleToggleExport = () => {
    if (!historyId || !history) {
      onClose()
      return
    }

    setIsExportOpen(prev => !prev)
  }

  const getExportMessages = async (exportHistoryId: string): Promise<IChatMessage[]> => {
    if (!collectionId) {
      const response = await ChatAPIs().getCollectionLessHistoryMessages({
        historyId: exportHistoryId,
        limit: 100,
        offset: 0,
      })
      return (response.data.data as IChatMessage[] | undefined) ?? []
    }

    const total = Math.max(history?.total ?? 0, 1)
    const offsets = Array.from({ length: Math.ceil(total / 100) }, (_, index) => index * 100)
    const pages = await Promise.all(
      offsets.map(async offset => {
        const response = await ChatAPIs().getMessages({
          collectionId,
          historyId: exportHistoryId,
          limit: 100,
          offset,
        })
        return (response.data.data as IChatMessage[] | undefined) ?? []
      }),
    )
    const messages = pages.flat()

    return Array.from(new Map(messages.map(message => [message.id, message])).values())
  }

  const handleExportHistory = async (format: TExportSessionFormat) => {
    if (!historyId || !history) {
      onClose()
      return
    }

    const exportHistoryId = history.historyId ?? historyId

    setExportLoadingFormat(format)

    try {
      // Defined below so it can share the regular export's naming and error flow.
      // eslint-disable-next-line no-use-before-define
      const exportNerResult = await exportNerHistory(format, exportHistoryId)
      if (exportNerResult) {
        onClose()
        return
      }

      // eslint-disable-next-line no-use-before-define
      const exportChatResult = await exportChatHistory(format, exportHistoryId)
      if (exportChatResult) {
        onClose()
        return
      }

      const res = await ChatAPIs().exportSession({
        collectionId: collectionId ?? '',
        historyId: exportHistoryId,
        format,
        includeAttachments: true,
      })

      if (!(res.data instanceof Blob)) {
        throw new Error('Invalid export response')
      }

      const url = URL.createObjectURL(res.data)
      const link = document.createElement('a')
      const safeName = (history.historyName || exportHistoryId).replace(/[\\/:*?"<>|]/g, '-')
      link.href = url
      link.download = `${safeName}.${format}`
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(url)
      onClose()
    } catch (error) {
      const msg = error instanceof Error ? error.message : t('chat-export-error')
      addAToast(msg, 'error')
    } finally {
      setExportLoadingFormat(null)
    }
  }

  async function exportNerHistory(format: TExportSessionFormat, exportHistoryId: string) {
    if (history?.selectionMode !== 'ner') {
      return false
    }

    const messages = await getExportMessages(exportHistoryId)
    const entities =
      messages
        ?.filter(message => message.bot)
        .flatMap(message => parseNerResult(message.message)?.entities ?? []) ?? []

    if (entities.length === 0) {
      return false
    }

    const safeName = (history?.historyName || exportHistoryId).replace(/[\\/:*?"<>|]/g, '-')
    if (format === 'txt') {
      const file = new Blob([`\uFEFF${formatNerEntitiesAsText(entities)}`], {
        type: 'text/plain;charset=utf-8',
      })
      const url = URL.createObjectURL(file)
      const link = document.createElement('a')
      link.href = url
      link.download = `${safeName}.txt`
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(url)
      return true
    }

    await downloadNerEntitiesAsPdf({ entities, filename: safeName })
    return true
  }

  async function exportChatHistory(format: TExportSessionFormat, exportHistoryId: string) {
    const messages = await getExportMessages(exportHistoryId)
    if (messages.length === 0) {
      return false
    }

    const safeName = (history?.historyName || exportHistoryId).replace(/[\\/:*?"<>|]/g, '-')
    const title = history?.historyName || 'گفتگو'
    if (format === 'txt') {
      const file = new Blob([`\uFEFF${formatChatAsText({ title, messages })}`], {
        type: 'text/plain;charset=utf-8',
      })
      const url = URL.createObjectURL(file)
      const link = document.createElement('a')
      link.href = url
      link.download = `${safeName}.txt`
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(url)
      return true
    }

    await downloadChatAsPdf({ title, messages, filename: safeName })
    return true
  }

  const handleExportTxt = () => {
    handleExportHistory('txt')
  }

  const handleExportPdf = () => {
    handleExportHistory('pdf')
  }

  const handleExportKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault()
      handleExportTxt()
    }
  }

  const handleOpenRename = () => {
    if (!historyId || !history) {
      closeMenu()
      return
    }

    setRenameValue(history.historyName)
    setIsRenaming(true)
  }

  const handleRenameHistory = (event?: FormEvent) => {
    event?.preventDefault()

    if (!historyId || !history) {
      onClose()
      return
    }

    const historyName = renameValue.trim()

    if (!historyName) {
      return
    }

    if (historyName === history.historyName) {
      setIsRenaming(false)
      closeMenu()
      return
    }

    dispatch(
      setSessionTranslation({
        historyId,
        collectionId,
        data: { historyName },
      }),
    )
    closeMenu()
  }

  useEffect(() => {
    if (!menuAnchorEl) {
      setTransferAnchorEl(null)
      setIsRenaming(false)
      setIsExportOpen(false)
    }
  }, [menuAnchorEl])

  useEffect(() => {
    if (isRenaming) {
      renameInputRef.current?.focus()
      renameInputRef.current?.select()
    }
  }, [isRenaming])
  return (
    <>
      <Menu
        anchorEl={menuAnchorEl}
        open={Boolean(menuAnchorEl)}
        onClose={onClose}
        anchorOrigin={{ vertical: 'bottom', horizontal: isLtr ? 'left' : 'right' }}
        transformOrigin={{ vertical: 'top', horizontal: isLtr ? 'left' : 'right' }}
        sx={{ boxShadow: 'none !important' }}
        className={`chat-history-card-toggle-wrapper${isLtr ? ' is-ltr' : ''}`}
      >
        <div className='chat-history-card-toggle'>
          {isRenaming ? (
            <form className='chat-history-card-toggle__rename' onSubmit={handleRenameHistory}>
              <input
                ref={renameInputRef}
                value={renameValue}
                onChange={event => setRenameValue(event.target.value)}
                className='chat-history-card-toggle__rename-input'
                dir='auto'
              />
              <button
                type='submit'
                className='chat-history-card-toggle__rename-submit'
                aria-label={t('chat-rename-conversation')}
              >
                <img src={doneBlueIcon} alt='' />
              </button>
            </form>
          ) : (
            <button type='button' className='chat-history-card-toggle__item' onClick={handleOpenRename}>
              <img src={mode === 'light' ? editIcon : editIcon2White} className='chat-history-card-toggle__item-icon' />
              <span>{t('chat-rename-conversation')}</span>
            </button>
          )}
          <button
            type='button'
            className='chat-history-card-toggle__item'
            onClick={handleTogglePin}
            disabled={pinLoading}
          >
            <img src={mode === 'light' ? pinIcon : pinIconWhite} className='chat-history-card-toggle__item-icon' />
            <span>{t(history?.pinned ?? history?.isPinned ? 'chat-unpin' : 'chat-pin')}</span>
          </button>
          <button type='button' className='chat-history-card-toggle__item' onClick={handleTransferToProject}>
            <img src={mode === 'light' ? transferFolderIcon : transferFolderIconWhite} className='chat-history-card-toggle__item-icon' />
            <span className='chat-history-card-toggle__item-transfer'>
              {t('chat-transfer-to-project')}
              <img src={mode === 'light' ? arrowUpnIcon : arrowUpnIconWhite} alt='' />
            </span>
          </button>
          {collectionId && (
            <button
              type='button'
              className='chat-history-card-toggle__item'
              onClick={handleTransferToGeneral}
              disabled={generalTransferLoading}
            >
              <img
                src={mode === 'light' ? chatIcon : chatIconWhite}
                className='chat-history-card-toggle__item-icon'
              />
              <span>
                {generalTransferLoading ? t('chat-transferring') : t('chat-transfer-to-general')}
              </span>
            </button>
          )}
          <button type='button' className='chat-history-card-toggle__item' onClick={handleToggleExport}>
            <img src={mode === 'light' ? exportFileIcon : exportFileIconWhite} className='chat-history-card-toggle__item-icon' />
            <span className='chat-history-card-toggle__item-transfer'>
              {t('chat-export')}
              <img src={mode === 'light' ? arrowUpnIcon : arrowUpnIconWhite} alt='' />
            </span>
          </button>
          {isExportOpen && (
            <div
              className='chat-history-card-toggle__export-options'
              role='menu'
              tabIndex={-1}
              onKeyDown={handleExportKeyDown}
            >
              <button
                type='button'
                className='chat-history-card-toggle__export-option'
                onClick={handleExportTxt}
                disabled={Boolean(exportLoadingFormat)}
              >
                {exportLoadingFormat === 'txt' ? '...' : 'TXT'}
              </button>
              <button
                type='button'
                className='chat-history-card-toggle__export-option'
                onClick={handleExportPdf}
                disabled={Boolean(exportLoadingFormat)}
              >
                {exportLoadingFormat === 'pdf' ? '...' : 'PDF'}
              </button>
            </div>
          )}
          <div className='chat-history-card-toggle__divider' />
          <button
            type='button'
            className='chat-history-card-toggle__item chat-history-card-toggle__item--danger'
            onClick={handleDelete}
          >
            <img src={deleteIcon} className='chat-history-card-toggle__item-icon' />
            <span>{t('delete')}</span>
          </button>
        </div>
      </Menu>
      <TransferProject
        menuAnchorEl={transferAnchorEl}
        menuIds={{ historyId, collectionId }}
        onClose={() => setTransferAnchorEl(null)}
        onTransferred={closeMenu}
      />
      <DeleteConfirmDialog
        isOpen={Boolean(deleteTarget)}
        kind='chat'
        itemName={deleteTarget?.name ?? ''}
        onConfirm={confirmDelete}
        onClose={() => setDeleteTarget(null)}
      />
    </>
  )
}

export default HistoryCardMenu
