import { useEffect } from 'react'
import { useNavigate } from 'react-router-dom'

const RouteHOC = (props: {
  element: JSX.Element
  isPrivate: boolean
  token?: string
  accessLevel?: number
  minAccessLvl?: number
  redirectTo?: string
  redirectCondition?: boolean
}) => {
  const {
    element,
    isPrivate = false,
    token,
    accessLevel = 1,
    minAccessLvl = 0,
    redirectCondition,
    redirectTo,
  } = props
  const navigate = useNavigate()

  useEffect(() => {
    if (isPrivate && !token) {
      window.location.href = '/'
    } else if (redirectCondition && redirectTo) {
      navigate(redirectTo, { replace: true })
    } else if (accessLevel < minAccessLvl) {
      window.location.href = '/bdm/not-allowed'
    }
  }, [])

  return <>{element}</>
}

export default RouteHOC
