import './messageTypeBadge.scss'

import folderIcon from 'src/assets/folderIcon.svg'
import summarizing from 'src/assets/summarizing.svg'
import chatTranslateSelectIcon from 'src/assets/chatTranslateSelectIcon.svg'
import keywords from 'src/assets/keywords.svg'
import newInfoIcon from 'src/assets/newInfoIcon.svg'
import meetingMinutes from 'src/assets/meetingMinutes.svg'
import exportIcon from 'src/assets/exportIcon.svg'
import letterWriterIcon from 'src/assets/letterWriterIcon.svg'
import ocrIcon from 'src/assets/ocrIcon.svg'
import sttIcon from 'src/assets/sttIcon.svg'

export const MESSAGE_TYPE_BADGES: Record<string, { label: string; icon: string }> = {
  rag: { label: 'پاسخ بر اساس فایل‌های ارسالی', icon: folderIcon },
  summarizer: { label: 'خلاصه‌سازی فایل', icon: summarizing },
  translator: { label: 'ترجمه فایل', icon: chatTranslateSelectIcon },
  keywordExtractor: { label: 'استخراج کلمات کلیدی', icon: keywords },
  ner: { label: 'استخراج موجودیت‌های نامدار', icon: newInfoIcon },
  minutesGenerator: { label: 'صورتجلسه', icon: meetingMinutes },
  reporter: { label: 'گزارش‌ساز', icon: exportIcon },
  letter: { label: 'نامه‌نگاری', icon: letterWriterIcon },
  ocr: { label: 'تشخیص متن از تصویر', icon: ocrIcon },
  stt: { label: 'تبدیل صوت به متن', icon: sttIcon },
}

export const MessageTypeBadge = ({
  messageType,
  attached,
}: {
  messageType?: string
  attached?: boolean
}) => {
  const badge = messageType ? MESSAGE_TYPE_BADGES[messageType] : undefined

  if (!badge) {
    return null
  }

  return (
    <button
      type='button'
      className={`chat-messsage-type-badge ${
        attached ? 'chat-messsage-type-badge--attached' : ''
      }`.trim()}
    >
      <img src={badge.icon} alt='' />
      <span>{badge.label}</span>
      {/* <svg
        className='chat-messsage-type-badge__chevron'
        width='8'
        height='14'
        viewBox='0 0 8 14'
        fill='none'
      >
        <path
          d='M7 1L1 7L7 13'
          stroke='currentColor'
          strokeWidth='1.5'
          strokeLinecap='round'
          strokeLinejoin='round'
        />
      </svg> */}
    </button>
  )
}

export default MessageTypeBadge
