import { PayloadAction } from '@reduxjs/toolkit'
import { IFileState, initialState } from './fileSlice'
import { FileSource, IBreadcrumb, ISelectedFile, IUploadItem } from 'src/types/FileManagement'
import { sourceConfig } from './utils'

export const reducers = {
  openDrive: (state: IFileState, action: PayloadAction<{ source: FileSource }>) => {
    const config = sourceConfig[action.payload.source]

    if (config) {
      state.isOpen = true
      state.source = config.source
      state.fileTypes = config.fileTypes
      state.action = config.action
      state.allowMultipleSelection = config.allowMultipleSelection
    } else {
      console.warn(`No config found for source: ${action.payload.source}`)
    }
  },
  selectFile: (state: IFileState, action: PayloadAction<ISelectedFile>) => {
    const { id } = action.payload
    const alreadySelected = state.selectedFiles.some(file => file.id === id)

    state.selectedFiles = alreadySelected
      ? state.selectedFiles.filter(file => file.id !== id) // remove if already selected
      : state.allowMultipleSelection
      ? [...state.selectedFiles, action.payload] // add to list if multiple allowed
      : [action.payload] // replace if single selection only
  },
  removeFiles: (state: IFileState, action: PayloadAction<string[]>) => {
    const fileIdsToRemove = new Set(action.payload)
    state.selectedFiles = state.selectedFiles.filter(file => !fileIdsToRemove.has(file.id))
  },
  selectFolder: (state: IFileState, action: PayloadAction<string>) => {
    const folderId = action.payload
    state.selectedFolder = state.selectedFolder === folderId ? null : folderId
  },
  setSubmittable: (state: IFileState, action: PayloadAction<boolean>) => {
    state.submittable = action.payload
  },
  setDriveCrumbs: (state: IFileState, action: PayloadAction<IBreadcrumb[]>) => {
    state.breadcrumb = action.payload
  },
  // file upload
  addUpload: (state: IFileState, action: PayloadAction<IUploadItem[]>) => {
    state.uploads = [...state.uploads, ...action.payload]
  },
  updateUploadProgress: (
    state: IFileState,
    action: PayloadAction<{ id: string; progress: number }>,
  ) => {
    const item = state.uploads.find(u => u.id === action.payload.id)
    if (item) {
      item.progress = action.payload.progress
      if (item.status === 'pending') {
        item.status = 'uploading'
      }
    }
  },
  setUploadStatus: (
    state: IFileState,
    action: PayloadAction<{
      id: string
      status: IUploadItem['status']
      error?: string
      response?: any
      serverId?: string
    }>,
  ) => {
    const item = state.uploads.find(u => u.id === action.payload.id)
    if (item) {
      item.status = action.payload.status
      if (action.payload.error) {
        item.error = action.payload.error
      }
      if (action.payload.response) {
        item.response = action.payload.response
      }
      if (action.payload.id) {
        item.serverId = action.payload.serverId
      }
    }
  },
  closeDrive: () => initialState,
  resetStore: () => initialState,
}

export default reducers
