type TFileNameSource = Pick<IChatSessionFileUploadItem, 'filename' | 'originalName' | 'fullPath'>

const resolveCollectionFileName = (file: TFileNameSource) => {
  const rawFile = file as TFileNameSource & {
    id?: string
    objectName?: string
    name?: string
    fileName?: string
    originalFileName?: string
    original_filename?: string
    original_name?: string
    filePath?: string
    path?: string
  }
  const fallbackPathName = [file.fullPath, rawFile.filePath, rawFile.path]
    .find(Boolean)
    ?.split('/')
    .filter(Boolean)
    .pop()

  const filename = [
    file.filename,
    file.originalName,
    rawFile.fileName,
    rawFile.originalFileName,
    rawFile.original_filename,
    rawFile.original_name,
    rawFile.objectName,
    rawFile.name,
    fallbackPathName,
  ].find(value => value?.trim())

  return filename?.trim()
}

export const getCollectionFileDisplayName = (file: IChatSessionFileUploadItem) =>
  resolveCollectionFileName(file) || 'فایل بدون نام'

/**
 * The files endpoint also returns server-generated artifacts (e.g. OCR/extraction
 * outputs linked to their original via `sourceFileId`) which carry no name.
 * Only the user's own uploads belong in file pickers and project file lists.
 */
export const isUserUploadedFile = (
  file: TFileNameSource & Pick<IChatSessionFileUploadItem, 'sourceFileId'>,
) => !file.sourceFileId && Boolean(resolveCollectionFileName(file))

export const normalizeCollectionFile = (file: IChatSessionFileUploadItem): IChatSessionFileUploadItem => {
  const rawFile = file as IChatSessionFileUploadItem & { id?: string }
  const fileId = file.fileId ?? file._id ?? rawFile.id ?? ''
  const filename = getCollectionFileDisplayName(file)

  return {
    ...file,
    _id: file._id ?? fileId,
    fileId,
    filename,
    originalName: file.originalName?.trim() || filename,
  }
}

const mapCollectionFilesToGraphNodes = (files: IChatSessionFileUploadItem[]): IGraphNode[] => {
  return files.map((file, index) => ({
    id: index + 1,
    label: file.originalName,
    image: '',
    count: 0,
    UpdateState: 1,
    metaData: {},
    isNotRelationalNode: true,
    primaryKey: file.fileId,
    placeHolder: false,
    nodeField: {},
    dataIsValidated: true,
    dataLocation: {
      address: file.fullPath || file.originalName,
      ip: '',
      port: '',
    },
    connections: [],
    imagePath: undefined,
    filePath: file.fullPath,
    orderedList: [],
    nodeId: file.fileId,
    fx: 0,
    fy: 0,
  }))
}

export const timeFormatter = (value: string) => {
  return new Date(value).toLocaleString('fa-IR', {
    hour: 'numeric',
    minute: 'numeric',
    timeZone: DATE_TIME_ZONE,
  })
}

export const normalizeCollectionsData = (
  collectionsData: IChatCollection[],
  previousCollections: Record<string, IChatCollection> = {},
) => {
  const collections: Record<string, IChatCollection> = {}
  const histories: Record<string, IChatHistory> = {}
  let historyList: IChatHistory[] = []

  const collectionList: IChatCollection[] = collectionsData.map(collection => {
    const {
      collectionId,
      collectionName,
      collectionHistory = [],
      collectionGraph,
    } = collection
    // General collection snapshots are not authoritative for uploaded files:
    // while a chat is being created the backend can return either no `files`
    // field or `files: []`. Preserve known files in both cases. The dedicated
    // getUploadFiles endpoint remains responsible for explicitly clearing the
    // list after a deletion.
    const incomingFiles = Array.isArray(collection.files)
      ? collection.files.filter(isUserUploadedFile).map(normalizeCollectionFile)
      : []
    const previousFiles = previousCollections[collectionId]?.files ?? []
    const files = incomingFiles.length > 0 ? incomingFiles : previousFiles

    const normalizedHistories = collectionHistory.map(hst => ({
      ...hst,
      collectionId,
      collectionName,
      messages: hst.messages ?? [],
      files: hst.files?.map(normalizeCollectionFile) ?? [],
    }))

    // During creation the same chat can briefly arrive once with the client
    // sessionId and once with the final server historyId. Treat intersecting
    // identifiers as one history so socket/API races cannot duplicate the UI.
    const updatedHistories = normalizedHistories.reduce<IChatHistory[]>((result, history) => {
      const historyIds = [history.historyId, history.sessionId].filter(Boolean)
      const existingIndex = result.findIndex(item =>
        [item.historyId, item.sessionId].some(id => id && historyIds.includes(id)),
      )

      if (existingIndex === -1) {
        result.push(history)
      } else {
        result[existingIndex] = { ...result[existingIndex], ...history }
      }

      return result
    }, [])

    updatedHistories.forEach(history => {
      histories[history.historyId] = history
    })

    historyList = [...historyList, ...updatedHistories]

    const updatedCollection: IChatCollection = {
      ...collection,
      collectionHistory: updatedHistories,
      files,
      collectionGraph: {
        ...collectionGraph,
        nodes: collectionGraph?.nodes?.length
          ? collectionGraph.nodes
          : mapCollectionFilesToGraphNodes(files),
      },
    }

    collections[collectionId] = updatedCollection
    return updatedCollection
  })

  return {
    collectionList,
    collections,
    historyList,
    histories,
  }
}

// gets list of collection-less sessions and returns normalized list of histories
export const normalizeCollectionLessHistoryData = (CLHistoryList: IChatHistory[]) => {
  const CLHistories: Record<string, IChatHistory> = {}

  CLHistoryList.forEach(history => {
    CLHistories[history.historyId] = {
      ...history,
      // backend return [""] on removing translation item,
      // which is invalid. so cleaning meaningless data is required.
      translate: history.translate.filter(tr => !!tr),
      collectionId: null,
      collectionName: null,
    }
  })

  return {
    CLHistoryList,
    CLHistories,
  }
}

// return true, if date is today
export const isSameDay = (dateStr: string, serverNow: Date): boolean => {
  const date = new Date(dateStr)
  return (
    date.getUTCFullYear() === serverNow.getUTCFullYear() &&
    date.getUTCMonth() === serverNow.getUTCMonth() &&
    date.getUTCDate() === serverNow.getUTCDate()
  )
}

export const analyzeNewHistoryData = ({
  newHistory,
  oldHistory,
}: {
  newHistory: Record<string, IChatHistory>
  oldHistory: Record<string, IChatHistory>
}) => {
  const oldIds = new Set(Object.keys(oldHistory))
  const newIds = new Set(Object.keys(newHistory))

  const added: IChatHistory[] = []
  const removed: IChatHistory[] = []
  const changed: IChatHistory[] = []

  for (const id of newIds) {
    if (!oldIds.has(id)) {
      added.push(newHistory[id])
    } else if (JSON.stringify(oldHistory[id]) !== JSON.stringify(newHistory[id])) {
      changed.push(newHistory[id])
    }
  }

  for (const id of oldIds) {
    if (!newIds.has(id)) {
      removed.push(oldHistory[id])
    }
  }

  return {
    added,
    removed,
    changed,
  }
}

export const createMessage = ({
  id,
  message,
  text = message,
  attachments = [],
  analyse = [],
  reply,
  messageType,
}: {
  id?: string
  message: string
  text?: string
  attachments?: IChatSessionFileUploadItem[]
  analyse?: Array<string>
  reply?: { messageId?: string; message?: string }
  messageType?: CHAT_SELECTION_MODE
}) => {
  return {
    id: id ?? generateLongId(),
    type: 'text',
    messageType,
    message,
    text,
    createdAt: new Date().toISOString(),
    attachments,
    avatar: '',
    comment: '',
    liked: false,
    disLiked: false,
    starred: false,
    bot: false,
    unread: false,
    delivered: true,
    reply: [
      {
        ...(reply && reply),
        analyse: analyse,
        data: [],
      },
    ],
  } as any // TODO: fix type here and store
}

export const createFileMessage = (file: File, analyse?: Array<string>) => {
  return {
    id: generateLongId(),
    type: 'file',
    message: '',
    createdAt: new Date().toISOString(),
    attachments: [],
    avatar: '',
    comment: '',
    liked: false,
    disLiked: false,
    starred: false,
    bot: false,
    unread: false,
    delivered: true,
    reply: [{ analyse: analyse ?? [], data: [] }],
  } as any // TODO: fix type here and store
}
