import i18n from 'i18next'
import { initReactI18next } from 'react-i18next'

export type AppLanguage = 'fa' | 'en'

const LANGUAGE_STORAGE_KEY = 'app-language'

const getSavedLanguage = (): AppLanguage =>
  localStorage.getItem(LANGUAGE_STORAGE_KEY) === 'en' ? 'en' : 'fa'

const applyDocumentLanguage = (language: AppLanguage) => {
  document.documentElement.lang = language
  document.documentElement.dir = language === 'en' ? 'ltr' : 'rtl'
}

export const changeAppLanguage = (language: AppLanguage) => {
  localStorage.setItem(LANGUAGE_STORAGE_KEY, language)
  applyDocumentLanguage(language)
  return i18n.changeLanguage(language)
}

const initI18n = () => {
  const language = getSavedLanguage()
  applyDocumentLanguage(language)

  i18n.use(initReactI18next).init({
    resources: {
      fa: { translation: (window as any).fa_dictionary },
      en: { translation: (window as any).en_dictionary as Record<string, string> },
    },
    lng: language,
    fallbackLng: 'en',
    interpolation: { escapeValue: false },
  })
}

export default initI18n
