import type { INerEntity } from '.'

// Scraped page chrome that the model sometimes glues onto entity names.
const NOISE_PHRASES = ['لایک کن']

const LETTER = 'A-Za-zء-يٮ-ۓۺ-ۿݐ-ݿﭐ-﷿ﹰ-﻿'
const DIGIT = '0-9٠-٩۰-۹'
const NUMERIC_GROUPS = new Set(['money', 'date', 'time', 'percent'])

const LETTER_RE = new RegExp('[' + LETTER + ']', 'g')
const DIGIT_RE = new RegExp('[' + DIGIT + ']')
const EDGE_JUNK_RE = new RegExp('^[^' + LETTER + DIGIT + ']+|[^' + LETTER + DIGIT + ')]+$', 'g')
const TRAILING_DIGITS_RE = new RegExp('[\\s' + DIGIT + ']+$')

const countLetters = (value: string) => value.match(LETTER_RE)?.length ?? 0

const cleanWord = (word: string, entityGroup: string) => {
  let value = word.replace(/##/g, '')
  NOISE_PHRASES.forEach(phrase => {
    value = value.split(phrase).join(' ')
  })
  value = value.replace(/\s+/g, ' ').replace(EDGE_JUNK_RE, '')

  const open = (value.match(/\(/g) ?? []).length
  const close = (value.match(/\)/g) ?? []).length
  if (open !== close) value = value.replace(/[()]/g, '')

  // Like-counters (e.g. «میناب۹») stick to names; numbers only belong to numeric types.
  if (!NUMERIC_GROUPS.has(entityGroup)) value = value.replace(TRAILING_DIGITS_RE, '')

  return value.replace(EDGE_JUNK_RE, '').trim()
}

const isMeaningful = (entity: INerEntity, isSubword: boolean) => {
  const letters = countLetters(entity.word)
  if (NUMERIC_GROUPS.has(entity.entity_group)) return letters > 0 || DIGIT_RE.test(entity.word)
  if (letters > 2) return true
  // Short leftovers (e.g. «ک», «##f», «کن») are noise unless it is a confident whole word like «قم».
  return letters === 2 && !isSubword && entity.score >= 0.6
}

const dedupeKey = (entity: INerEntity) =>
  entity.entity_group + ':' + entity.word.replace(/[\s\u200c]/g, '')

/** Removes tokenizer artifacts, scraped noise and duplicates from raw NER entities. */
export const sanitizeEntities = (entities: INerEntity[]): INerEntity[] => {
  const byKey = new Map<string, INerEntity>()

  entities.forEach(raw => {
    const entity = { ...raw, word: cleanWord(raw.word, raw.entity_group) }
    if (!isMeaningful(entity, raw.word.trim().startsWith('##'))) return

    const key = dedupeKey(entity)
    const existing = byKey.get(key)
    if (!existing || entity.score > existing.score) byKey.set(key, entity)
  })

  return Array.from(byKey.values())
}
