import { ChangeEvent } from 'react'
import { Trans } from 'react-i18next'
import { addUpload, selectDriveAction } from 'src/lib/slice/fileManagement/fileSlice'
import { uploadFileItems } from 'src/lib/slice/fileManagement/thunks'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'

import uploadFileIcon from 'src/assets/upload-file-blue.svg'
import { IUploadItem } from 'src/types/FileManagement'
import useDragFile from 'src/lib/hooks/useDragFile'
import { normalizeUploadFile } from 'src/lib/utils'

const acceptFileTypes = ['.csv', '.txt', '.png', '.jpg', '.jpeg', '.parquet']

const UploadBox = () => {
  const dispatch = useBDMDispatch()
  const action = useBDMSelector(selectDriveAction)

  const handleFiles = (files: File[]) => {
    if (action !== 'download') {
      return
    }

    const uploadItems: IUploadItem[] = files.map(normalizeUploadFile).map(file => ({
      id: `${file.name}-${Date.now()}`,
      name: file.name,
      size: file.size,
      type: file.type,
      progress: 0,
      status: 'pending',
      error: '',
      file,
    }))

    dispatch(addUpload(uploadItems))
    dispatch(uploadFileItems(uploadItems))
  }

  const onUpload = (e: ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      handleFiles(Array.from(e.target.files))
    }
  }

  const { isDragging, onDragEnter, onDragLeave, onDragOver, onDrop } = useDragFile({
    handleFiles,
    acceptTypes: acceptFileTypes,
  })
  return (
    <>
      <label
        htmlFor='file-manager-input'
        className={`file-manager__upload__label ${isDragging ? 'dragging' : ''}`}
        onDragEnter={onDragEnter}
        onDragLeave={onDragLeave}
        onDragOver={onDragOver}
        onDrop={onDrop}
      >
        <img src={uploadFileIcon} alt='upload file' className='file-manager__upload__upload-icon' />
        <p className='file-manager__upload__input-description'>
          <Trans i18nKey='file-manager-upload-panel-input-description' />
        </p>
        <p className='file-manager__upload__input-limit'>
          <Trans i18nKey='file-manager-upload-panel-input-limit' as='p' />
        </p>
      </label>
      <input
        id='file-manager-input'
        type='file'
        accept={acceptFileTypes.join(', ')}
        multiple
        hidden
        onChange={onUpload}
      />
    </>
  )
}

export default UploadBox
