import { NodeObject, LinkObject, GraphData } from 'react-force-graph-2d'
import { IGraphNode } from 'src/types'

import type { Layout } from 'react-grid-layout'
import type { IAIChatAssistantDTI } from './api'

// Message
export enum CHAT_MESSAGE_TYPES {
  TEXT = 'text',
  GENERAL_CHAT = 'generalChat',
  RAG = 'rag',
  ANALYTICS = 'analytics',
  ERROR = 'error',
  LOADING = 'LOADING',
  SUMMARIZING = 'summarizer',
  TRANSLATING = 'translator',
  KEYWORD_EXTRACTION = 'keywordExtractor',
  NER = 'ner',
  MINUTES_GENERATOR = 'minutesGenerator',
  REPORT_GENERATOR = 'reporter',
  OCR = 'ocr',
  LETTER_GENERATOR = 'letter',
  STT = 'stt',
  FILE = 'file',
}
export type CHAT_SELECTION_MODE =
  | 'translator'
  | 'generalChat'
  | 'embedder'
  | 'keywordExtractor'
  | 'letter'
  | 'minutesGenerator'
  | 'ner'
  | 'ocr'
  | 'rag'
  | 'reporter'
  | 'sentimentAnalyzer'
  | 'stt'
  | 'summarizer'

export enum CHAT_ANSWER_STATUS {
  PENDING = 'pending',
  STREAMING = 'streaming',
  COMPLETED = 'completed',
  FAILED = 'failure',
}

export type TQuickAction =
  | 'summarizing'
  | 'translation'
  | 'namedEntities'
  | 'keywords'
  | 'meetingMinutes'
  | 'reportGenerator'
  | 'letterWriter'
  | 'ocr'
  | 'reasoning'
  | 'selectFile'
  | 'excelYar'
  | 'stt'
export type IChatChartTypes = 'barChart' | 'lineChart' | 'pieChart'

export interface IChatAnalyseData {
  data: { label: string; value: number }[]
  label_title: string
  chart_title: string
  value_title: string
}

export interface IChatMessageReply {
  message?: string
  messageId?: string
  analyse: IChatChartTypes[]
  data: IChatAnalyseData[]
}

export interface IChatSessionFileUploadItem {
  _id: string
  user_name?: string
  fileId: string
  filename: string
  originalName: string
  size: number
  mimeType: string
  state: string
  fullPath: string
  uploadedAt: string
  scopeType?: string
  collectionId?: string | null
  historyId?: string | null
  tag?: string
  sourceFileId?: string | null
}

export interface IChatMessage {
  id: string
  unread: boolean
  type: CHAT_MESSAGE_TYPES
  // the requested AI capability (summarizer, rag, translator, ...), separate
  // from `type` which describes the message's content shape (text/file)
  messageType?: CHAT_SELECTION_MODE
  message: string
  text?: string
  bot: boolean
  avatar: string
  liked: boolean
  disLiked: boolean
  starred: boolean
  createdAt: string
  attachments: Array<IChatSessionFileUploadItem>
  comment: string
  delivered: boolean
  reply: IChatMessageReply[]
  answerStatus?: CHAT_ANSWER_STATUS
  hidden?: boolean
}

export interface IChatBackgroundSettings {
  enabled: boolean
  image: string | null
  fit: 'cover' | 'contain' | 'repeat' | 'center'
  overlay: string
  blur: boolean
  applyToAll: boolean
  userMessageBackgroundColor: string
  userMessageTextColor: string
}

// History
export enum CHAT_HISTORY_STATE {
  DONE = 'done',
  PENDING = 'pending',
  FAILURE = 'failure',
}

export enum CHAT_MODELS_TYPES {
  ABSTRACTOR = 'abstractor',
  DANA = 'RAG',
  KNOWLEGE_GRAPH = 'knowlegeGraph',
  REPOERT_GENERATOR = 'reportGenerator',
  // TODO: check comptability
  GENERAL = 'GENERAL',
}

export enum CHAT_TRANSLATE_OPTIONS {
  ENGLISH = 'en',
  FARSI = 'fa',
}

export interface IBaseChatHistory {
  waiting: boolean
  historyId: string
  historyCount: number
  historyName: string
  state: CHAT_HISTORY_STATE
  historyType: CHAT_MODELS_TYPES
  total: number // total messages
  createdAt: string
  abstractor: boolean
  translate: CHAT_TRANSLATE_OPTIONS[]
  // ?
  reasoning: boolean
  modelName: string
  answerStatus?: CHAT_ANSWER_STATUS
}

export interface IChatHistory extends IBaseChatHistory {
  selectionMode?: CHAT_SELECTION_MODE
  pinned?: boolean
  isPinned?: boolean
  sessionId?: string
  nodeId?: string | null
  scopeType?: string
  collectionId: string | null
  collectionName: string | null
  isActive?: boolean
  files?: IChatSessionFileUploadItem[]
  messages?: IChatMessage[]
}

export enum CHAT_COLLECTION_STATE {
  DONE = 'done',
  PENDING = 'pending',
  FAILURE = 'failure',
}

export interface IChatCollection {
  collectionId: string
  collectionName: string
  pinned?: boolean
  isPinned?: boolean
  color?: string
  icon?: string
  collectionHistory: IChatHistory[]
  files?: IChatSessionFileUploadItem[]
  previewConfig?: unknown[]
  waiting: boolean
  state: CHAT_COLLECTION_STATE
  createdAt: string
  updatedAt: string
  collectionGraph?: {
    nodes?: IGraphNode[]
  }
  prompt: string
}

export interface IChatState {
  // app intialization (data are fetched)
  appInitalized: boolean

  // raw data list
  collectionList: IChatCollection[]
  historyList: IChatHistory[]

  // normalized data
  collections: Record<string, IChatCollection>
  histories: Record<string, IChatHistory>

  // current state
  currentCollection: IChatCollection | null
  currentHistory: IChatHistory | null
  currentGraph: GraphData

  // collection less histories
  CLHistoryList: IChatHistory[]
  CLHistories: Record<string, IChatHistory>

  // todays histories
  todaysHistoryList: IChatHistory[]

  // messages
  currentHistoryMessages: IChatMessage[]
  historyState: {
    initialized: boolean
    total: number // total messages
    hasMore: boolean // has more messages
    offset: number // start (index)
    limit: number // size
  }

  // loading states
  loadingState: {
    collections: boolean
    messages: boolean
    chatResponse: boolean
    chatStreaming: boolean
    collectionLessHistories: boolean
    createCollectionSession: boolean
    todaysHistories: boolean
    collectionFiles: boolean
  }

  // UI state
  sidebarState: { isOpen: boolean }
  modalsState: {
    createCollection: boolean
    createCollectionSession: boolean
    uploadFile: boolean
    allowMultipleAttachments: boolean
    openInstruction: boolean
    openProfileModal: boolean
    openSettingsModal: boolean
    openBackgroundModal: boolean
  }
  mouseLoc: { x: number; y: number }
  contextMenuState: { isOpen: boolean; node?: NodeObject | LinkObject }
  // Chat layout
  layoutState: {
    isExpanded: boolean
    isLocked: boolean
    layout: Layout[]
  }

  // State update
  stream: Record<string, [IChatMessage, IChatMessage]>
  responseWaitingSessions: Array<string>

  uploadFiles: Record<
    string,
    {
      fileId: string
      filesize: string
      filetype: string
      filename: string
      progress: number
      error: boolean
    }
  >
  // from url
  chatStateParams: { historyId?: string; collectionId?: string; isParamsSynced: boolean }

  // AI Models
  aiModels: { name: string; active: boolean; reasoning: boolean }[]

  // chat attachment
  historyAttachments: IChatSessionFileUploadItem[]
  quickActionRequest: {
    requestId: number
    action: TQuickAction
    source: {
      key: string
      title: string
      mimeType?: string
    }
  } | null
  // last accepted send request per history, so a failed answer can be retried with the exact same payload
  lastSentPayloads: Record<string, IAIChatAssistantDTI>
  backgroundSettings: IChatBackgroundSettings
  backgroundDraftSettings: IChatBackgroundSettings
}
