import React, { useState, MouseEvent } from 'react';
import pinIcon from 'src/assets/pinIcon.svg';
import pinIconHover from 'src/assets/pinIconHover.svg';
import pinIconActive from 'src/assets/pinIconActive.svg';
import pinIconWhite from 'src/assets/pinIconWhite.svg';
import pinIconHoverWhite from 'src/assets/pinIconHoverWhite.svg';
import pinIconActiveWhite from 'src/assets/pinIconActiveWhite.svg';
import './style.scss';
import { RootState } from 'src/lib/store';
import { useBDMSelector } from 'src/lib/store/hooks';

interface Props {
  active: boolean
  loading?: boolean
  onToggle: () => void
}

/* دکمه‌ی Pin – رفتار و استایل مشابه InstructionButton */
export const PinButton = ({ active, loading = false, onToggle }: Props) => {
  const [hover, setHover] = useState(false);
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const handleClick = (e: MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    onToggle();
  };

  return (
    <button
      type="button"
      className={`pin-btn ${active ? 'active' : ''}`}
      onClick={handleClick}
      disabled={loading}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      aria-pressed={active}
      aria-label={active ? 'Unpin' : 'Pin'}
    >
      <img
        src={active ? (mode === 'light' ? pinIconActive : pinIconActiveWhite) : hover ? (mode === 'light' ? pinIconHover : pinIconHoverWhite) : (mode === 'light' ? pinIcon : pinIconWhite)}
        alt="Pin"
      />
    </button>
  );
};
