type Props = {
    selectedColor: string
    onSelect: (id: number) => void;
    onSvgSelect: (svg: JSX.Element) => void;

}

type IconInfo = {
    id: number;
    svg: JSX.Element;
};

const colorizeSvg = (svg: JSX.Element, color: string) => {
    return cloneElement(
        svg as ReactElement,
        {},
        React.Children.map((svg as ReactElement).props.children, child => {
            if (!React.isValidElement(child)) {
                return child
            }

            const childProps = child.props as { fill?: string; stroke?: string }
            return cloneElement(child as ReactElement, {
                ...(childProps.fill && childProps.fill !== 'none' ? { fill: color } : {}),
                ...(childProps.stroke && childProps.stroke !== 'none' ? { stroke: color } : {}),
            })
        }),
    )
}


