import Axios, { AxiosInstance, AxiosPromise, AxiosResponse, AxiosProgressEvent } from 'axios'
import { BASE_URL } from 'src/lib/constants'
import { logout } from 'src/lib/utils'
import axiosRetry from 'axios-retry'
import { showHotToast } from 'src/components/Toast/hotToast'
import { isCanceledRequest } from './requestErrors'

import { t } from 'i18next'

let axiosInstance: AxiosInstance

export const InitialToken = () => {
  const savedToken = localStorage.getItem('login')
  if (!savedToken) {
    return ''
  }
  const { access_token } = JSON.parse(savedToken)
  return access_token ? 'Bearer ' + access_token : ''
}

export const getHeaders = () => {
  const headers = { Authorization: InitialToken() }
  return headers
}

const destroy = () => {
  logout()
}

const CreateAxiosInstance = () => {
  if (!!axiosInstance || false) {
    return
  }

  axiosInstance = Axios.create({
    baseURL: BASE_URL,
    timeout: 100000,
    maxRedirects: 5,
    timeoutErrorMessage: t<string>('check-connection'),
  })

  axiosRetry(axiosInstance, { retries: 3, retryDelay: axiosRetry.exponentialDelay })

  axiosInstance.interceptors.request.use(
    function (config) {
      return config
    },
    function (error) {
      return Promise.reject(error)
    },
  )

  axiosInstance.interceptors.response.use(
    function (response) {
      return response
    },
    function (error) {
      // Aborting effects during unmount (and React StrictMode's development
      // remount check) is expected. It must not be reported as an API failure.
      if (isCanceledRequest(error)) {
        return Promise.reject(error)
      }

      const isUnauthorized =
        error?.response?.data?.status === 401 || error?.response?.status === 401

      if (isUnauthorized) {
        destroy()
        return Promise.reject(error?.response || error)
      }

      if (error?.response?.data?.status === 402) {
        let errors = {}
        error?.response?.data?.data?.forEach((item: { name: string; message: string }) => {
          errors = Object.assign(errors, { [item.name]: item.message })
        })
        if (Object.keys(errors).length !== 0) {
          return Promise.reject(errors)
        } else {
          return Promise.reject(error.response)
        }
      }

      const backendMessage = error?.response?.data?.message
      const isDisplayableMessage =
        typeof backendMessage === 'string' &&
        backendMessage.trim().length > 0 &&
        backendMessage.length <= 200
      if (isDisplayableMessage) {
        showHotToast(backendMessage, 'error')
      }

      if (
        process.env.NODE_ENV === 'development' &&
        (!error?.response?.status || Math.floor(error?.response?.status / 100) === 5)
      ) {
        console.error(error)
      }

      return Promise.reject(error?.response || error)
    },
  )
}

function axiosWrapper<T>(axiosArgument: {
  url: string
  data?: unknown
  params?: unknown
  method: 'GET' | 'POST' | 'PATCH' | 'DELETE' | 'PUT'
  headers?: Record<string, string>
  hasToast?: boolean
  responseType?: AxiosResponse['config']['responseType']
  signal?: AbortSignal
  onUploadProgress?: (progressEvent: AxiosProgressEvent) => void
}): AxiosPromise<T> {
  // if bdm app, generate randon id for every request to  server

  return new Promise(resolve => {
    CreateAxiosInstance()
    axiosInstance(axiosArgument)
      .then(response => {
        resolve(response)
      })
      .catch(error => {
        resolve(error)
      })
  })
}

export default axiosWrapper
