const getAccessiblePreviewUrl = (previewUrl: string) => {
  const apiUrl = new URL(BASE_URL, window.location.origin)
  const url = new URL(previewUrl, apiUrl.origin)

  if (['localhost', '127.0.0.1', '0.0.0.0'].includes(url.hostname)) {
    url.protocol = apiUrl.protocol
    url.host = apiUrl.host
  }

  return url.toString()
}

const isPreviewRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value)

const toPreviewNumber = (value: unknown, fallback: number) =>
  typeof value === 'number' && Number.isFinite(value) ? value : fallback

export const normalizePreviewResponse = async (
  payload: unknown,
  responseMimeType: string,
): Promise<IPreviewFileDTO> => {
  if (!isPreviewRecord(payload)) {
    throw new Error('پاسخ پیش نمایش فایل معتبر نیست')
  }

  const root = payload

  if (root.success === false) {
    throw new Error(
      typeof root.message === 'string' ? root.message : 'دریافت پیش نمایش فایل ناموفق بود',
    )
  }

  const preview =
    root.type === undefined && isPreviewRecord(root.data)
      ? root.data
      : root

  const nestedData = isPreviewRecord(preview.data) ? preview.data : undefined
  const nestedRows = nestedData?.rows
  const nestedRowsData = nestedData?.data
  const nestedColumns = nestedData?.columns
  const rawRows = [
    Array.isArray(preview.rows) ? preview.rows : undefined,
    Array.isArray(preview.data) ? preview.data : undefined,
    Array.isArray(nestedRows) ? nestedRows : undefined,
    Array.isArray(nestedRowsData) ? nestedRowsData : undefined,
  ].find(Boolean)

  if (preview.type === 'rows' || rawRows) {
    const rows = (rawRows ?? []).filter(isPreviewRecord)
    const rawColumns = Array.isArray(preview.columns)
      ? preview.columns
      : Array.isArray(nestedColumns)
      ? nestedColumns
      : []
    const columns = rawColumns.filter((column): column is string => typeof column === 'string')
    const mimeType =
      typeof preview.mimeType === 'string' ? preview.mimeType : responseMimeType

    return {
      success: true,
      type: 'rows',
      data: rows as Record<string, TPreviewRowValue>[],
      columns,
      shown: toPreviewNumber(preview.shown, rows.length),
      limit: toPreviewNumber(preview.limit, rows.length),
      truncated: preview.truncated === true,
      url: typeof preview.url === 'string' ? preview.url : '',
      mimeType,
      size: toPreviewNumber(preview.size, 0),
    }
  }

  if (preview.type === 'url' && typeof preview.url === 'string') {
    const mimeType = typeof preview.mimeType === 'string' ? preview.mimeType : responseMimeType
    const response = await fetch(getAccessiblePreviewUrl(preview.url), {
      headers: {
        ...getHeaders(),
        Authorization: InitialToken(),
      },
    })

    if (!response.ok) {
      throw new Error('دریافت محتوای پیش نمایش فایل ناموفق بود')
    }

    if (mimeType.startsWith('text/') || mimeType === 'application/markdown') {
      return {
        type: 'text',
        data: await response.text(),
        mimeType,
      }
    }

    const blob = await response.blob()
    return {
      type: mimeType.startsWith('image/') ? 'image' : 'pdf',
      objectUrl: URL.createObjectURL(blob),
      mimeType,
    }
  }

  if (preview.type !== 'text') {
    return preview as unknown as IPreviewFileDTO
  }

  const text = [
    typeof preview.data === 'string' ? preview.data : undefined,
    preview.content,
    preview.text,
    preview.markdown,
    nestedData?.content,
    nestedData?.text,
    nestedData?.markdown,
  ].find(value => typeof value === 'string')

  return {
    type: 'text',
    data: typeof text === 'string' ? text : '',
    mimeType: typeof preview.mimeType === 'string' ? preview.mimeType : responseMimeType,
  }
}

const parseParquetResponse = async (
  response: Response,
  contentType: string,
  limit?: number,
  offset?: number,
): Promise<IPreviewFileDTO> => {
  const file = await response.arrayBuffer()
  const magicBytes = new Uint8Array(file, 0, Math.min(file.byteLength, 4))
  const isParquetBinary =
    magicBytes.length === 4 &&
    magicBytes[0] === 0x50 &&
    magicBytes[1] === 0x41 &&
    magicBytes[2] === 0x52 &&
    magicBytes[3] === 0x31

  if (isParquetBinary) {
    try {
      return await parseParquetPreview(file, { limit, offset, mimeType: contentType })
    } catch {
      throw new Error('فایل Parquet معتبر نیست یا امکان خواندن آن وجود ندارد')
    }
  }

  try {
    const payload = JSON.parse(new TextDecoder().decode(file))

    return await normalizePreviewResponse(payload, contentType || 'application/json')
  } catch (error) {
    if (error instanceof SyntaxError) {
      throw new Error('فایل Parquet معتبر نیست یا امکان خواندن آن وجود ندارد')
    }

    throw error
  }
}

export const sendChatMessage = ({ payload, files }: ISendChatMessageDTI, signal?: AbortSignal) => {
  if (!files?.length) {
    return axiosWrapper<IAIChatAssistantDTO>({
      method: 'POST',
      headers: { ...getHeaders(), 'Content-Type': 'application/json' },
      url: '/ai-chat-assistant',
      signal,
      data: payload,
    })
  }

  const formData = new FormData()
  formData.append('payload', JSON.stringify(payload))
  files.forEach(file => formData.append('files', file))

  return axiosWrapper<IAIChatAssistantDTO>({
    method: 'POST',
    headers: getHeaders(),
    url: '/ai-chat-assistant',
    signal,
    data: formData,
  })
}

