    const response = await fetch(`${BASE_URL.replace(/\/$/, '')}/background/image`, {
      method: 'GET',
      headers: getHeaders(),
      signal,
    })

    // The API returns 409 when background settings are enabled but no image
    // has been uploaded. This is an empty state, not an application error.
    if (response.status === 404 || response.status === 409 || response.status === 204) {
      return null
    }

    if (!response.ok) {
      throw new Error('دریافت تصویر پس‌زمینه ناموفق بود')
    }

    const image = await response.blob()
    return image.size ? URL.createObjectURL(image) : null
