import './style.scss'
import { ChatRoutes } from 'src/lib/constants'
import { Suspense, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { Routes, Route } from 'react-router-dom'
import Header from 'src/components/Header'

import PageLoading from 'src/components/PageLoading'
import { useBDMContext } from 'src/lib/context'
import useSocket from 'src/lib/hooks/useSocket'
import RouteHOC from 'src/lib/hoc/RouteHOC'

function ChatApp() {
  useTranslation()
  const { accessToken } = useBDMContext()
  useSocket()

  const rotues = useMemo(() => ChatRoutes(), [])

  return (
    <>
      <div className='app-container__width-error'>
        please use a display with higher width resolution
      </div>
      <div className='app-container'>
        <Header />
        {/* <Loading isActive={loading} /> */}
        <div className='app-container__content'>
          <Suspense fallback={<PageLoading />}>
            <Routes>
              {rotues.map(route => (
                <Route
                  key={route.id}
                  path={route.route}
                  element={
                    <RouteHOC
                      element={route.page}
                      accessLevel={route.accessLevel}
                      token={accessToken}
                      isPrivate={route.isPrivate}
                    />
                  }
                />
              ))}
            </Routes>
          </Suspense>
        </div>
      </div>
    </>
  )
}

export default ChatApp
