import './style.scss'

import ChatMessage from '../ChatMessage'
import { useRef, useEffect, useLayoutEffect, useState, useCallback } from 'react'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import {
  aiChatAssistant,
  getCollectionLessHistories,
  getCollections,
  selectCLHistories,
  selectCurrentHistory,
  selectHistories,
  selectLastSentPayloads,
  selectMessages,
  selectLoadingState,
  setMessagesHidden,
} from 'src/pages/Chat/slice'
import MessageListSkeleton from './MessageListSkeleton'
import { buildRetryPayload } from './retry'
import { CHAT_HISTORY_STATE, CHAT_MESSAGE_TYPES, IChatMessage } from 'src/types/NewChat'
import {
  isAnswerFailure,
  isHistoryWaitingForAnswer,
  isMessageLoading,
} from 'src/pages/Chat/lib/streamStatus'
import { t } from 'i18next'

interface IProps {
  className?: string
}

const MessageList = ({ className }: IProps) => {
  const isRtl = document.documentElement.dir === 'rtl'
  const messages = (useBDMSelector(selectMessages) || []).filter(message => !message.hidden)
  const loadingState = useBDMSelector(selectLoadingState)
  const currentHistory = useBDMSelector(selectCurrentHistory)
  const histories = useBDMSelector(selectHistories)
  const CLHistories = useBDMSelector(selectCLHistories)
  const lastSentPayloads = useBDMSelector(selectLastSentPayloads)
  const dispatch = useBDMDispatch()

  const scrollRef = useRef<HTMLDivElement>(null)
  const contentRef = useRef<HTMLDivElement>(null)
  const isFirstRender = useRef(true)
  const shouldFollowBottomRef = useRef(true)
  const [isAtBottom, setIsAtBottom] = useState(true)
  const [isRetrying, setIsRetrying] = useState(false)
  const [retriedHistoryId, setRetriedHistoryId] = useState<string | null>(null)
  const [retriedMessageId, setRetriedMessageId] = useState<string | null>(null)
  const [stalledHistoryId, setStalledHistoryId] = useState<string | null>(null)
  const wasAnsweringRef = useRef(false)
  const refreshTimeoutRef = useRef<ReturnType<typeof setTimeout>>()

  const lastHumanMessage = [...messages].reverse().find(message => !message.bot)
  // The sidebar lists are refreshed live, while `currentHistory` is a copy taken at
  // selection time, so a failure is detected from either of them.
  const currentHistoryId = currentHistory?.historyId
  const liveHistory = currentHistoryId
    ? histories[currentHistoryId] ?? CLHistories[currentHistoryId]
    : undefined
  const lastMessage = messages[messages.length - 1]
  // A failed answer from Get History is a normal text message with
  // `answerStatus: failure`; it must still terminate any loading UI.
  const isLastMessageError =
    Boolean(lastMessage?.bot) &&
    isAnswerFailure({
      answerStatus: lastMessage?.answerStatus,
      messageType: lastMessage?.type,
    })
  // A history refresh can arrive before the backend exposes `answerStatus`.
  // In that case, its persisted `waiting`/`pending` state keeps the indicator
  // visible when the user leaves and returns before the answer is ready.
  const activeHistory = liveHistory ?? currentHistory
  const isHistoryAnswerPending = isHistoryWaitingForAnswer({
    answerStatus: activeHistory?.answerStatus,
    waiting: activeHistory?.waiting,
    state: activeHistory?.state,
  })
  // A pending assistant message can already be present from the socket or the
  // restored history. In that case it is the loading row; appending another
  // synthetic row would render the indicator twice.
  const hasPendingAssistantMessage = messages.some(
    message => message.bot && isMessageLoading(message.type, message.answerStatus),
  )
  // A socket failure is terminal and must override loading flags that may remain
  // true for one more render after the stream finishes.
  const showLoadingMessage =
    (loadingState.chatResponse || isHistoryAnswerPending) &&
    !isLastMessageError &&
    !hasPendingAssistantMessage
  const isAnswering =
    (loadingState.chatResponse || loadingState.chatStreaming || isHistoryAnswerPending) &&
    !isLastMessageError
  const displayedMessages = showLoadingMessage
    ? [
        ...messages,
        {
          id: 'loading',
          // The message's selection mode uses the same values as the loading
          // message types (summarizer, translator, OCR, ...). Messages loaded
          // after a refresh may not include `messageType`, so use the persisted
          // history selection mode as the fallback.
          type:
            lastHumanMessage?.messageType ??
            activeHistory?.selectionMode ??
            CHAT_MESSAGE_TYPES.LOADING,
        },
      ]
    : messages
  // Real-time signal that does not depend on the payload the backend sends on a
  // failure: the answer was being awaited/streamed, stopped, and the last message
  // is still the user's own, so no answer ever arrived.
  const isStalled = stalledHistoryId !== null && stalledHistoryId === currentHistoryId
  const isFailedHistory =
    isStalled ||
    currentHistory?.state === CHAT_HISTORY_STATE.FAILURE ||
    liveHistory?.state === CHAT_HISTORY_STATE.FAILURE ||
    isLastMessageError
  const isLastMessageFromUser = Boolean(lastMessage) && !lastMessage.bot
  // After a retry the FAILURE state lingers until the lists refresh, so the box
  // stays hidden once the retried message got an answer (last message is the bot's).
  const wasAnsweredAfterRetry =
    retriedHistoryId === currentHistoryId && !isLastMessageFromUser && !isLastMessageError
  // Between the retry request and the socket's first event the old FAILURE state is
  // still around; only the real-time signals (stall / error message) count then.
  const isAwaitingRetryAnswer =
    retriedMessageId !== null &&
    lastHumanMessage?.id === retriedMessageId &&
    isLastMessageFromUser &&
    !isStalled
  const showErrorMessage =
    isFailedHistory &&
    !wasAnsweredAfterRetry &&
    !isAwaitingRetryAnswer &&
    !isAnswering &&
    !isRetrying

  useEffect(() => {
    if (isAnswering) {
      clearTimeout(refreshTimeoutRef.current)
      wasAnsweringRef.current = true
      setStalledHistoryId(null)
      return
    }

    if (wasAnsweringRef.current) {
      wasAnsweringRef.current = false
      if (isLastMessageFromUser && currentHistoryId) {
        setStalledHistoryId(currentHistoryId)
      }

      // Ask the server for the history's real state (the same data a refresh
      // loads) so a failure shows up without reloading the page.
      const refreshHistories = () => {
        if (currentHistory?.collectionId) {
          dispatch(getCollections())
        } else {
          dispatch(getCollectionLessHistories())
        }
      }
      refreshHistories()
      refreshTimeoutRef.current = setTimeout(refreshHistories, 2000)
    }
  }, [isAnswering])

  const handleRetry = async () => {
    if (!currentHistory || !lastHumanMessage || isRetrying) {
      return
    }

    setIsRetrying(true)
    setRetriedHistoryId(currentHistory.historyId)
    setStalledHistoryId(null)

    // Resend through the same endpoint with the original payload (mode, files,
    // options). The failed attempt is hidden so the question is not shown twice.
    const payload = buildRetryPayload({
      history: currentHistory,
      failedMessage: lastHumanMessage,
      lastSentPayload:
        lastSentPayloads[currentHistory.historyId] ??
        (currentHistory.sessionId ? lastSentPayloads[currentHistory.sessionId] : undefined),
    })
    const failedMessageIds = messages
      .slice(messages.indexOf(lastHumanMessage))
      .map(message => message.id)

    setRetriedMessageId(payload.messageSchema.message.id)
    dispatch(setMessagesHidden({ messageIds: failedMessageIds, hidden: true }))
    try {
      // The loading indicator is driven by the socket stream, exactly like a normal
      // send. Forcing it on here raced with the stream (which may already have
      // started, e.g. «در حال استخراج متن») and left a second «در حال پاسخ» stuck.
      const result = await dispatch(aiChatAssistant({ payload, files: [] }))
      if (!aiChatAssistant.fulfilled.match(result)) {
        dispatch(setMessagesHidden({ messageIds: failedMessageIds, hidden: false }))
      }
    } finally {
      setIsRetrying(false)
    }
  }

  const updateIsAtBottom = useCallback(() => {
    const el = scrollRef.current
    if (!el) {
      return
    }
    const threshold = 80
    const distanceFromBottom = el.scrollHeight - el.scrollTop - el.clientHeight
    const nextIsAtBottom = distanceFromBottom <= threshold
    shouldFollowBottomRef.current = nextIsAtBottom
    setIsAtBottom(nextIsAtBottom)
  }, [])

  useLayoutEffect(() => {
    if (isFirstRender.current) {
      const el = scrollRef.current
      if (el) {
        el.scrollTop = el.scrollHeight
      }
      isFirstRender.current = false
    }
  }, [displayedMessages.length])

  useEffect(() => {
    const content = contentRef.current
    if (!content) {
      return
    }

    const resizeObserver = new ResizeObserver(() => {
      const el = scrollRef.current
      if (el && shouldFollowBottomRef.current) {
        // ResizeObserver runs before paint, so a growing streaming response is
        // anchored to the bottom without exposing an intermediate frame.
        el.scrollTop = el.scrollHeight
      }
    })

    resizeObserver.observe(content)
    return () => resizeObserver.disconnect()
  }, [loadingState.messages])

  useLayoutEffect(() => {
    const el = scrollRef.current
    if (el && shouldFollowBottomRef.current) {
      el.scrollTop = el.scrollHeight
    }
  }, [displayedMessages.length, loadingState.chatResponse, loadingState.chatStreaming])

  const handleScrollToBottom = () => {
    const el = scrollRef.current
    if (el) {
      shouldFollowBottomRef.current = true
      setIsAtBottom(true)
      el.scrollTo({ top: el.scrollHeight, behavior: 'smooth' })
    }
  }

  const showScrollToBottom = !isAtBottom && displayedMessages.length > 0

  if (loadingState.messages) {
    return <MessageListSkeleton />
  }

  return (
    <div className={`chat-msg-list-wrapper ${className ?? ''}`.trim()}>
      <div ref={scrollRef} className='chat-msg-list' onScroll={updateIsAtBottom}>
        <div ref={contentRef} className='chat-msg-list__content'>
          {displayedMessages.map((message, index) => (
            <ChatMessage
              key={message.id}
              index={index}
              style={{}}
              data={message as IChatMessage}
              isAnswering={isAnswering}
            />
          ))}
          {showErrorMessage && (
            <div
              className={`chat-msg-error ${isRtl ? 'is-rtl' : 'is-ltr'}`}
              role='alert'
              dir={isRtl ? 'rtl' : 'ltr'}
            >
              <div className='chat-msg-error__text'>
                <strong>{t('chat-answer-failed-title')}</strong>
                <span>{t('chat-answer-failed-description')}</span>
              </div>
              {lastHumanMessage && (
                <button type='button' className='chat-msg-error__retry' onClick={handleRetry}>
                  {t('chat-retry')}
                </button>
              )}
            </div>
          )}
        </div>
      </div>
      {showScrollToBottom && (
        <button
          className='chat-scroll-to-bottom'
          type='button'
          onClick={handleScrollToBottom}
          aria-label='Scroll to bottom'
        >
          <span className='chat-scroll-to-bottom__icon' />
        </button>
      )}
    </div>
  )
}

export default MessageList
