import { useEffect } from 'react'
import {
  selectDriveAction,
  selectDriveIsLoading,
  selectDriveSelectedFiles,
  selectDriveSelectedFolder,
  setSubmittable,
} from 'src/lib/slice/fileManagement/fileSlice'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'

const useCheckSubmittable = () => {
  const dispatch = useBDMDispatch()

  const selectedFiles = useBDMSelector(selectDriveSelectedFiles)
  const selectedFolder = useBDMSelector(selectDriveSelectedFolder)
  const action = useBDMSelector(selectDriveAction)
  const isLoading = useBDMSelector(selectDriveIsLoading)

  useEffect(() => {
    const userHasSelectedItems =
      action === 'download'
        ? selectedFiles.length > 0
        : action === 'upload'
        ? !!selectedFolder
        : false

    const submittable = userHasSelectedItems && !isLoading.driveFiles && !isLoading.submit

    dispatch(setSubmittable(submittable))
  }, [action, selectedFiles, selectedFolder, isLoading, dispatch])
}

export default useCheckSubmittable
