import { t } from 'i18next'
import { useCallback, useMemo } from 'react'
import { useBDMSelector } from 'src/lib/store/hooks'
import { selectDriveFolders } from 'src/lib/slice/fileManagement/fileSlice'
import { IFolderItem } from 'src/types/FileManagement'

import Accordion from '../Accordion'
import FolderCard from '../FolderCard'

interface IProps {
  search?: string
}

const Folders = ({ search = '' }: IProps) => {
  const folders = useBDMSelector(selectDriveFolders)

  const filteredFolders = useMemo(() => {
    const searchValue = search.trim().toLowerCase()

    if (!searchValue) {
      return folders
    }

    return folders.filter(folder => folder.name.toLowerCase().includes(searchValue))
  }, [folders, search])

  const renderItem = useCallback((item: IFolderItem) => <FolderCard {...item} />, [])

  return <Accordion items={filteredFolders} title={t<string>('پوشه ها')} renderItem={renderItem} />
}

export default Folders
