import { IChatHistory } from 'src/types/NewChat'

interface IChatRestoreLoadingParams {
  requestedHistoryId?: string
  appInitialized: boolean
  messagesLoading: boolean
  currentHistory: IChatHistory | null
}

export const shouldShowChatRestoreLoading = ({
  requestedHistoryId,
  appInitialized,
  messagesLoading,
  currentHistory,
}: IChatRestoreLoadingParams): boolean => {
  if (!requestedHistoryId) {
    return false
  }

  const isRequestedHistorySelected = Boolean(
    currentHistory &&
      [currentHistory.historyId, currentHistory.sessionId].some(id => id === requestedHistoryId),
  )

  return !appInitialized || messagesLoading || !isRequestedHistorySelected
}
