import { IFileState, initialState } from './fileSlice'
import { getRecentFiles, submitDanaFiles } from './thunks'
import { ActionReducerMapBuilder } from '@reduxjs/toolkit'

export default function (builder: ActionReducerMapBuilder<IFileState>) {
  builder
    // get list of all files and folders
    .addCase(getRecentFiles.pending, state => {
      state.loading.driveFiles = true
    })
    .addCase(getRecentFiles.fulfilled, (state, action) => {
      state.loading.driveFiles = false
      state.drive = action.payload.data
      state.files = action.payload.files
      state.folders = action.payload.folders
      if (action.payload.breadcrumb) {
        state.breadcrumb.push(action.payload.breadcrumb)
      }
    })
    .addCase(getRecentFiles.rejected, state => {
      state.loading.driveFiles = false
      state.drive = []
    })
    // get list of all files and folders
    .addCase(submitDanaFiles.pending, state => {
      state.loading.submit = true
    })
    .addCase(submitDanaFiles.fulfilled, () => initialState)
    .addCase(submitDanaFiles.rejected, () => initialState)
}
