export const isDev = process.env.NODE_ENV === 'development'
export const targetApp = process.env.PUBLIC_URL
export const isChat = targetApp === '/chat'
export const runtime = window.__RUNTIME_CONFIG__

/**
 * App base URL.
 * @constant
 */
export const BASE_URL = targetApp === '/chat'
  ? isDev
    ? runtime.REACT_APP_CHAT_BASE_URL_ON_DEVELOPE_AT_CAMPUS
    : runtime.REACT_APP_CHAT_BASE_URL_ON_BUILD
  : ''

/**
 * App socket base URL.
 * @constant
 */
export const SOCKET_BASE_URL = targetApp === '/chat'
  ? isDev
    ? runtime.REACT_APP_CHAT_SOCKET_BASE_URL_ON_DEVELOPE_AT_CAMPUS
    : runtime.REACT_APP_CHAT_SOCKET_URL_ON_BUILD
  : ''

