import axiosWrapper, { getHeaders } from 'src/api'
import {
  ICreateWorkbookAnalysisRequest,
  ISheetRowsDTO,
  IUploadWorkbookDTO,
  IWorkbookDTO,
  IWorkbookAnalysisDTO,
  IWorkbookSheetsDTO,
} from './types'

const ExcelAssistantAPIs = (signal?: AbortSignal) => ({
  uploadWorkbook: (file: File) => {
    const formData = new FormData()
    formData.append('file', file)

    return axiosWrapper<IUploadWorkbookDTO>({
      method: 'POST',
      headers: getHeaders(),
      url: 'excel-assistant/workbooks',
      signal,
      data: formData,
    })
  },
  getWorkbook: (workbookId: string) =>
    axiosWrapper<IWorkbookDTO>({
      method: 'GET',
      headers: getHeaders(),
      url: `excel-assistant/workbooks/${workbookId}`,
      signal,
    }),
  getWorkbookSheets: (workbookId: string) =>
    axiosWrapper<IWorkbookSheetsDTO>({
      method: 'GET',
      headers: getHeaders(),
      url: `excel-assistant/workbooks/${workbookId}/sheets`,
      signal,
    }),
  getSheetRows: (sheetId: string, offset = 0, limit = 100) =>
    axiosWrapper<ISheetRowsDTO>({
      method: 'GET',
      headers: getHeaders(),
      url: `excel-assistant/sheets/${sheetId}/rows`,
      params: { offset, limit },
      signal,
    }),
  createWorkbookAnalysis: (
    workbookId: string,
    data: ICreateWorkbookAnalysisRequest,
  ) =>
    axiosWrapper<IWorkbookAnalysisDTO>({
      method: 'POST',
      headers: getHeaders(),
      url: `excel-assistant/workbooks/${workbookId}/analyses`,
      signal,
      data,
    }),
  getAnalysis: (analysisId: string) =>
    axiosWrapper<IWorkbookAnalysisDTO>({
      method: 'GET',
      headers: getHeaders(),
      url: `excel-assistant/analyses/${analysisId}`,
      signal,
    }),
})

export default ExcelAssistantAPIs
