import './style.scss'

import ChatBox from './ChatBox'

import useChatInit from './lib/useChatInit'
import useChatStream from './lib/useChatStream'
import { useThemeSync } from '../../shared/theme/useTheme'
import { useBDMDispatch } from 'src/lib/store/hooks'
import { toggleTheme } from 'src/features/theme/themeSlice'
const Dashboard = () => {
  const dispatch = useBDMDispatch()
  useThemeSync()
  useChatInit()
  useChatStream()
  window.matchMedia('(prefers-color-scheme: dark)')
    .addEventListener('change', () => {
      dispatch(toggleTheme())
    })
  return (
    <div className='chat-screen'>
      <div className='chat-layout-box'>
        <ChatBox />
      </div>
    </div>
  )
}

export default Dashboard
