import { CHAT_ANSWER_STATUS, CHAT_HISTORY_STATE, CHAT_MESSAGE_TYPES } from 'src/types/NewChat'

const ANSWER_PENDING_TYPES = new Set<string>([
  CHAT_MESSAGE_TYPES.LOADING,
  CHAT_MESSAGE_TYPES.GENERAL_CHAT,
  CHAT_MESSAGE_TYPES.RAG,
])

// These message types are emitted by the socket while a file action is still
// running. They are actual loading rows, not completed assistant messages.
const ACTION_LOADING_TYPES = new Set<string>([
  CHAT_MESSAGE_TYPES.SUMMARIZING,
  CHAT_MESSAGE_TYPES.TRANSLATING,
  CHAT_MESSAGE_TYPES.KEYWORD_EXTRACTION,
  CHAT_MESSAGE_TYPES.NER,
  CHAT_MESSAGE_TYPES.MINUTES_GENERATOR,
  CHAT_MESSAGE_TYPES.REPORT_GENERATOR,
  CHAT_MESSAGE_TYPES.OCR,
  CHAT_MESSAGE_TYPES.LETTER_GENERATOR,
  CHAT_MESSAGE_TYPES.STT,
])

export const isAnswerPendingType = (type: unknown): boolean =>
  typeof type === 'string' && ANSWER_PENDING_TYPES.has(type)

export const isLoadingMessageType = (type: unknown): boolean =>
  isAnswerPendingType(type) || (typeof type === 'string' && ACTION_LOADING_TYPES.has(type))

export const isAnswerPendingStatus = (status: unknown): boolean =>
  status === CHAT_ANSWER_STATUS.PENDING || status === CHAT_ANSWER_STATUS.STREAMING

/** A terminal failure can be reported on a message, a history, or both. */
export const isAnswerFailure = ({
  answerStatus,
  messageType,
  historyState,
}: {
  answerStatus: unknown
  messageType?: unknown
  historyState?: unknown
}): boolean =>
  answerStatus === CHAT_ANSWER_STATUS.FAILED ||
  messageType === CHAT_HISTORY_STATE.FAILURE ||
  historyState === CHAT_HISTORY_STATE.FAILURE

/**
 * The history list is refreshed independently of the live socket stream. When
 * revisiting a chat, `waiting`/`state` are therefore the fallback for an
 * answerStatus that has not been returned by the API yet.
 */
export const isHistoryWaitingForAnswer = ({
  answerStatus,
  waiting,
  state,
}: {
  answerStatus: unknown
  waiting: unknown
  state: unknown
}): boolean => {
  // Terminal data is authoritative, even if a stale history snapshot still
  // says `waiting: true`.
  if (isAnswerFailure({ answerStatus, historyState: state }) || state === CHAT_HISTORY_STATE.DONE) {
    return false
  }

  if (answerStatus !== undefined) {
    return isAnswerPendingStatus(answerStatus)
  }

  return waiting === true || state === 'pending'
}

/** A persisted terminal status always wins over a legacy loading message type. */
export const isMessageLoading = (type: unknown, answerStatus: unknown): boolean =>
  answerStatus === undefined ? isLoadingMessageType(type) : isAnswerPendingStatus(answerStatus)
