import './FileGroupCard.scss'

import { useState } from 'react'
import { IChatSessionFileUploadItem } from 'src/types/NewChat'
import { formatFileSize, getFileKind } from './index'
import csvFileIcon from 'src/assets/CsvIcon.svg'
import pdfFileIcon from 'src/assets/PdfIcon.svg'
import textFileIcon from 'src/assets/TextIcon.svg'
import zipFileIcon from 'src/assets/zipIcon.svg'
import imageFileIcon from 'src/assets/ImageIcon.svg'
import helpIcon from 'src/assets/helpIcon.svg'

const MAX_PREVIEW_FILES = 6

const FILE_KIND_ICONS: Record<string, string> = {
  csv: csvFileIcon,
  pdf: pdfFileIcon,
  doc: textFileIcon,
  text: textFileIcon,
  zip: zipFileIcon,
  image: imageFileIcon,
  unknown: helpIcon,
}

const totalFilesSize = (files: IChatSessionFileUploadItem[]) =>
  files.reduce((sum, file) => {
    const size = Number(file.size)
    return sum + (Number.isFinite(size) ? size : 0)
  }, 0)

const ChevronIcon = ({ expanded }: { expanded: boolean }) => (
  <svg
    className={`chat-file-group-card__chevron ${expanded ? 'is-expanded' : ''}`}
    width='14'
    height='9'
    viewBox='0 0 14 9'
    fill='none'
  >
    <path
      d='M1 1L7 7L13 1'
      stroke='currentColor'
      strokeWidth='1.6'
      strokeLinecap='round'
      strokeLinejoin='round'
    />
  </svg>
)

const StackedFilesIcon = () => (
  <svg width='32' height='28' viewBox='0 0 32 28' fill='none' xmlns='http://www.w3.org/2000/svg'>
    <g opacity='0.5'>
      <rect x='8' width='18' height='22' rx='3' fill='#8C9398' />
    </g>
    <g opacity='0.8'>
      <rect x='4' y='3' width='18' height='22' rx='3' fill='#576269' />
    </g>
    <rect y='6' width='18' height='22' rx='3' fill='#3685B5' />
    <line x1='3' y1='15.25' x2='15' y2='15.25' stroke='#FEFEFE' stroke-width='1.5' />
    <line x1='3' y1='19.25' x2='11' y2='19.25' stroke='#FEFEFE' stroke-width='1.5' />
  </svg>
)

const FileTypeIcon = ({ kind }: { kind: string }) => (
  <img
    className='chat-file-group-item__icon'
    src={FILE_KIND_ICONS[kind] ?? FILE_KIND_ICONS.unknown}
    alt=''
  />
)

interface IProps {
  files: IChatSessionFileUploadItem[]
  onPreviewFile: (file: IChatSessionFileUploadItem) => void
}

const FileGroupCard = ({ files, onPreviewFile }: IProps) => {
  const [isExpanded, setIsExpanded] = useState(false)
  const previewFiles = files.slice(0, MAX_PREVIEW_FILES)
  const remainingCount = files.length - previewFiles.length

  return (
    <div className={`chat-file-group-card ${isExpanded ? 'is-expanded' : ''}`}>
      <button
        type='button'
        className='chat-file-group-card__header'
        onClick={() => setIsExpanded(previous => !previous)}
        aria-expanded={isExpanded}
      >
        <StackedFilesIcon />
        <div className='chat-file-group-card__title-box'>
          <span className='chat-file-group-card__title'>{files.length} فایل آپلود شده</span>
          <span className='chat-file-group-card__subtitle'>
            مجموع حجم: {formatFileSize(totalFilesSize(files)) || '0 B'}
          </span>
        </div>
        <ChevronIcon expanded={isExpanded} />
      </button>

      {isExpanded && (
        <div className='chat-file-group-card__body'>
          <div className='chat-file-group-card__grid'>
            {previewFiles.map(file => {
              const fileName = file.filename || file.originalName
              const fileKind = getFileKind(file, fileName)

              return (
                <button
                  type='button'
                  key={file._id || file.fileId || fileName}
                  className='chat-file-group-item'
                  onClick={() => onPreviewFile(file)}
                >
                  <FileTypeIcon kind={fileKind} />
                  <div className='chat-file-group-item__details'>
                    <span className='chat-file-group-item__name' dir='auto' title={fileName}>
                      {fileName}
                    </span>
                    <span className='chat-file-group-item__meta'>{formatFileSize(file.size)}</span>
                  </div>
                </button>
              )
            })}
          </div>
          {remainingCount > 0 && (
            <div className='chat-file-group-card__footer'>
              + {remainingCount} فایل دیگر در این گفتگو
            </div>
          )}
        </div>
      )}
    </div>
  )
}

export default FileGroupCard
