import './style.scss'
import { t } from 'i18next'
import { useState, useCallback, useEffect, useRef } from 'react'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import {
    getCollectionLessHistories,
    selectModalsState,
    setModalsState,
} from 'src/pages/Chat/slice'

import Modal from '@mui/material/Modal'
import Button from 'src/components/Button'
import closeIcon from 'src/assets/closeIcon.svg'
import closeIconWhite from 'src/assets/closeIconWhite.svg'
import settingIcon from 'src/assets/settingIcon.svg'
import settingIconWhite from 'src/assets/settingIconWhite.svg'
import trashIcon from 'src/assets/whiteTrashIcon.svg'
import { Divider, Grow } from '@mui/material'
import { RootState } from 'src/lib/store'
import { AppLanguage, changeAppLanguage } from 'src/lib/utils/i18n'
import ChatAPIs from 'src/api/chat'
import { addAToast } from 'src/lib/context'

type FontSize = 'small' | 'medium' | 'large'

const FONT_SIZE_STORAGE_KEY = 'chat-font-size'
const LANGUAGE_STORAGE_KEY = 'app-language'
const FONT_SIZE_SCALE: Record<FontSize, string> = {
    small: '0.7',
    medium: '1',
    large: '1.4',
}

const getSavedFontSize = (): FontSize => {
    const savedFontSize = localStorage.getItem(FONT_SIZE_STORAGE_KEY)
    return savedFontSize === 'small' || savedFontSize === 'large' ? savedFontSize : 'medium'
}

const getSavedLanguage = (): AppLanguage =>
    localStorage.getItem(LANGUAGE_STORAGE_KEY) === 'en' ? 'en' : 'fa'

const SettingsModal = () => {
    const dispatch = useBDMDispatch()
    const isOpen = useBDMSelector(selectModalsState).openSettingsModal
    const mode = useBDMSelector((state: RootState) => state.theme.mode)
    const [fontSize, setFontSize] = useState<FontSize>(getSavedFontSize)
    const [language, setLanguage] = useState<AppLanguage>(getSavedLanguage)
    const [isClearingHistory, setIsClearingHistory] = useState(false)
    const [isClearHistoryConfirmOpen, setIsClearHistoryConfirmOpen] = useState(false)
    const [captcha, setCaptcha] = useState({ first: 0, second: 0 })
    const [captchaAnswer, setCaptchaAnswer] = useState('')
    const [captchaError, setCaptchaError] = useState(false)
    const isCaptchaValid =
        captchaAnswer.trim() !== '' && Number(captchaAnswer) === captcha.first + captcha.second
    const contentRef = useRef<HTMLFormElement>(null)

    const applyFontSize = useCallback((size: FontSize) => {
        document.documentElement.style.setProperty('--font-scale', FONT_SIZE_SCALE[size])
        document.documentElement.dataset.fontSize = size
    }, [])

    const handleClose = useCallback(() => {
        const savedFontSize = getSavedFontSize()
        setFontSize(savedFontSize)
        applyFontSize(savedFontSize)
        setLanguage(getSavedLanguage())
        dispatch(setModalsState({ openSettingsModal: false }))
    }, [applyFontSize, dispatch])

    const handleSubmit = useCallback(async () => {
        try {
            const response = await ChatAPIs().updateSettings({
                fontSize,
                defaultLanguage: language,
            })

            if (!response.data.success) {
                throw new Error(response.data.message || 'ذخیره تنظیمات انجام نشد.')
            }

            localStorage.setItem(FONT_SIZE_STORAGE_KEY, fontSize)
            applyFontSize(fontSize)
            changeAppLanguage(language)
            dispatch(setModalsState({ openSettingsModal: false }))
        } catch (error) {
            addAToast(error instanceof Error ? error.message : 'ذخیره تنظیمات انجام نشد.', 'error')
        }
    }, [applyFontSize, dispatch, fontSize, language])

    useEffect(() => {
        if (isOpen) {
            contentRef.current?.focus()
        }
    }, [isOpen])

    useEffect(() => {
        applyFontSize(getSavedFontSize())
    }, [applyFontSize])

    const handleFontSizeChange = (size: FontSize) => {
        setFontSize(size)
        applyFontSize(size)
    }

    const handleLanguageChange = (nextLanguage: AppLanguage) => {
        setLanguage(nextLanguage)
        changeAppLanguage(nextLanguage)
    }

    const handleClearHistory = async () => {
        if (isClearingHistory) {
            return
        }

        if (Number(captchaAnswer) !== captcha.first + captcha.second) {
            setCaptchaError(true)
            return
        }

        setIsClearingHistory(true)
        try {
            const response = await ChatAPIs().clearGeneralHistory()
            if (!response.data.success) {
                throw new Error(response.data.message || 'پاک کردن تاریخچه انجام نشد.')
            }

            await dispatch(getCollectionLessHistories()).unwrap()
            addAToast(response.data.message || 'تاریخچه با موفقیت پاک شد.', 'success')
            setIsClearHistoryConfirmOpen(false)
        } catch (error) {
            addAToast(error instanceof Error ? error.message : 'پاک کردن تاریخچه انجام نشد.', 'error')
        } finally {
            setIsClearingHistory(false)
        }
    }

    const refreshCaptcha = () => {
        setCaptcha({
            first: Math.floor(Math.random() * 8) + 2,
            second: Math.floor(Math.random() * 8) + 2,
        })
        setCaptchaAnswer('')
        setCaptchaError(false)
    }

    const openClearHistoryConfirmation = () => {
        refreshCaptcha()
        setIsClearHistoryConfirmOpen(true)
    }

    return (
        <>
        <Modal
            open={isOpen}
            onClose={handleClose}
            className='settings-modal'
            BackdropProps={{
                sx: {
                    backdropFilter: 'blur(5px)',
                    backgroundColor: '#09090B4D',
                },
            }}
        >
            <form
                className='settings-modal__content'
                ref={contentRef}
                tabIndex={-1}
                onSubmit={(event) => {
                    event.preventDefault()
                    handleSubmit()
                }}
            >
                <div className='settings-modal__header'>
                    <div className='settings-modal__title'>
                        <img src={mode === 'light' ? settingIcon : settingIconWhite} />
                        <p className='settings-modal__title-p'>{t('chat-sidebar-settings-title')}</p>
                    </div>
                    <button
                        type='button'
                        className='settings-modal__close'
                        onClick={handleClose}
                        aria-label={t('close')}
                    >
                        <img src={mode === 'light' ? closeIcon : closeIconWhite} alt='close' />
                    </button>
                </div>
                <Divider className='divider-modals' sx={{ marginBottom: '16px' }} />

                {/* body */}
                <div className='settings-modal__body'>
                    <div className='wrapper-inputs'>
                        {/* font size */}
                        <div className='settings-item'>
                            <div className='settings-item__text'>
                                <p className='title'>{t('chat-settings-font-size-title')}</p>
                                <p className='desc'>{t('chat-settings-font-size-description')}</p>
                            </div>

                            <div className='font-size-options-setting'>
                                {([
                                    ['small', t('chat-settings-font-size-small')],
                                    ['medium', t('chat-settings-font-size-medium')],
                                    ['large', t('chat-settings-font-size-large')],
                                ] as const).map(([size, label]) => (
                                    <button
                                        key={size}
                                        type='button'
                                        className={fontSize === size ? 'active' : ''}
                                        aria-pressed={fontSize === size}
                                        onClick={() => handleFontSizeChange(size)}
                                    >
                                        {label}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <Divider className='divider-modals' />

                        {/* language */}
                        <div className='settings-item'>
                            <div className='settings-item__text'>
                                <p className='title'>{t('chat-settings-language-title')}</p>
                                <p className='desc'>{t('chat-settings-language-description')}</p>
                            </div>

                            <select
                                className='settings-select'
                                value={language}
                                onChange={(event) => handleLanguageChange(event.target.value as AppLanguage)}
                            >
                                <option value='fa'>{t('chat-settings-language-persian')}</option>
                                <option value='en'>{t('chat-settings-language-english')}</option>
                            </select>
                        </div>

                        <Divider className='divider-modals' />

                        {/* clear history */}
                        <div className='settings-item'>
                            <div className='settings-item__text'>
                                <p className='title'>{t('chat-settings-clear-history-title')}</p>
                                <p className='desc'>{t('chat-settings-clear-history-description')}</p>
                            </div>
                            <div>
                                <button
                                    className='settings-delete-btn'
                                    type='button'
                                    onClick={openClearHistoryConfirmation}
                                    disabled={isClearingHistory}
                                >
                                    <img src={trashIcon} />
                                    {t('chat-settings-clear-history-button')}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
                {/* actions */}
                <div className='settings-modal__btns'>
                    <Button
                        title={t('chat-settings-modal-btn-cancel')}
                        onClick={handleClose}
                        className='settings-modal__btns__cancel'
                        type='button'
                        tabIndex={1}
                    />
                    <Button
                        title={t('chat-settings-modal-btn-confirm')}
                        className='settings-modal__btns__confirm'
                        type='submit'
                        tabIndex={1}
                    />
                </div>
            </form>
        </Modal>
        <Modal
            open={isClearHistoryConfirmOpen}
            onClose={() => !isClearingHistory && setIsClearHistoryConfirmOpen(false)}
            className='clear-history-confirm-modal'
            closeAfterTransition
            BackdropProps={{
                sx: {
                    backdropFilter: 'blur(4px)',
                    backgroundColor: '#09090B66',
                },
            }}
        >
            <Grow in={isClearHistoryConfirmOpen} timeout={{ enter: 240, exit: 180 }}>
            <div className='clear-history-confirm-modal__content' dir='rtl' role='dialog' aria-modal='true' aria-labelledby='clear-history-confirm-title'>
                <div className='clear-history-confirm-modal__warning-icon' aria-hidden='true'>!</div>
                <h2 id='clear-history-confirm-title'>از پاک کردن تاریخچه مطمئن هستید؟</h2>
                <p>همه گفتگوهای عمومی شما حذف می‌شوند و این عمل قابل بازگشت نیست.</p>
                <label className='clear-history-confirm-modal__captcha'>
                    <div className='clear-history-confirm-modal__captcha-header'>
                        <span className='clear-history-confirm-modal__captcha-badge'>✓</span>
                        <span>تأیید امنیتی</span>
                        <button
                            type='button'
                            onClick={refreshCaptcha}
                            disabled={isClearingHistory}
                            aria-label='تغییر کپچا'
                            title='تغییر سؤال'
                        >
                            ↻
                        </button>
                    </div>
                    <div className='clear-history-confirm-modal__captcha-question' dir='ltr'>
                        {captcha.first} + {captcha.second} = ?
                    </div>
                    <span className='clear-history-confirm-modal__captcha-help'>پاسخ را برای تأیید حذف وارد کنید</span>
                    <input
                        type='text'
                        inputMode='numeric'
                        autoComplete='off'
                        autoFocus
                        value={captchaAnswer}
                        onChange={event => {
                            setCaptchaAnswer(event.target.value)
                            setCaptchaError(false)
                        }}
                        aria-invalid={captchaError}
                        disabled={isClearingHistory}
                    />
                    {captchaError && <small>پاسخ کپچا صحیح نیست.</small>}
                </label>
                <div className='clear-history-confirm-modal__actions'>
                    <button
                        type='button'
                        className='clear-history-confirm-modal__cancel'
                        disabled={isClearingHistory}
                        onClick={() => setIsClearHistoryConfirmOpen(false)}
                    >
                        انصراف
                    </button>
                    <button
                        type='button'
                        className='clear-history-confirm-modal__confirm'
                        disabled={isClearingHistory || !isCaptchaValid}
                        onClick={handleClearHistory}
                    >
                        {isClearingHistory ? 'در حال پاک‌سازی...' : 'بله، پاک کن'}
                    </button>
                </div>
            </div>
            </Grow>
        </Modal>
        </>
    )
}

export default SettingsModal
