import { useBDMSelector } from 'src/lib/store/hooks'
import FileItem from '../FileItem'
import { selectDriveUploads } from 'src/lib/slice/fileManagement/fileSlice'

const Files = () => {
  const files = useBDMSelector(selectDriveUploads)

  return (
    <div className='file-manager__upload__files-list'>
      {files.map(file => (
        <div className='file-manager__upload__file-item'>
          <FileItem {...file} key={file.id} />
        </div>
      ))}
    </div>
  )
}

export default Files
