import './style.scss'

import useAIModels from 'src/pages/Chat/lib/useAIModels'
import { Menu } from '@mui/material'
import darkStar from 'src/assets/darkStar.svg'
import WhiteStar from 'src/assets/WhiteStar.svg'
import arrowDownnIcon from 'src/assets/arrowDownnIcon.svg'
import arrowDownnIconWhite from 'src/assets/arrowDownnIconWhite.svg'
import { RootState } from 'src/lib/store'
import { useBDMSelector } from 'src/lib/store/hooks'
interface ModelBoxProps {
  alwaysVisible?: boolean
}

const ModelBox = ({ alwaysVisible = false }: ModelBoxProps) => {
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const {
    showModelMenu,
    currentModel,
    handleMenuClose,
    menuAnchorEl,
    handleMenuOpen,
    menuItems,
    canOpenMenu,
  } = useAIModels()

  if (!showModelMenu && !alwaysVisible) {
    return null
  }

  return (
    <>
      <div
        className={`bdm-chat-header-model-box  ${canOpenMenu ? '' : 'disable'}`}
        onClick={handleMenuOpen}
      >
        <img src={mode === 'light' ? darkStar : WhiteStar} />
        {currentModel}
        <img className='bdm-chat-header-model-box__arrow-down' src={mode === 'light' ? arrowDownnIcon : arrowDownnIconWhite} />
      </div>
      <Menu
        anchorEl={menuAnchorEl}
        open={Boolean(menuAnchorEl)}
        onClose={handleMenuClose}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
        transformOrigin={{ vertical: 'top', horizontal: 'right' }}
        PaperProps={{
          sx: { width: menuAnchorEl?.clientWidth ?? 172, marginTop: '8px', borderRadius: '8px', backgroundColor: 'var(--chat-human-messsage-msg)' },
        }}
        sx={{ boxShadow: 'none !important' }}
        className='chat-card-menu-wrapper'
      >
        <div className='chat-card-menu'>
          {menuItems.map(menuItem => (
            <span key={menuItem.title} className='chat-card-menu__btn__title' onClick={menuItem.action}>{menuItem.title}</span>
          ))}
        </div>
      </Menu>
    </>
  )
}

export default ModelBox
