import { jsPDF } from 'jspdf'
import { parseNerResult, type INerEntity } from '.'
import type { IChatMessage } from 'src/types/NewChat'
import kalamehBoldFontUrl from 'src/theme/Fonts/Kalameh/TTF/Kalameh-Bold.ttf'
import kalamehFontUrl from 'src/theme/Fonts/Kalameh/TTF/Kalameh-Regular.ttf'

const ENTITY_LABELS: Record<string, string> = {
  person: 'شخص',
  location: 'مکان',
  organization: 'سازمان',
  date: 'تاریخ',
  time: 'زمان',
  money: 'مبلغ',
  percent: 'درصد',
  product: 'محصول',
  event: 'رویداد',
  nationality: 'ملیت',
  misc: 'سایر',
}

const toPersianNumber = (value: number) => new Intl.NumberFormat('fa-IR').format(value)

const formatPercent = (score: number) =>
  new Intl.NumberFormat('fa-IR', { style: 'percent', maximumFractionDigits: 0 }).format(score)

const getEntityLabel = (entityGroup: string) =>
  ENTITY_LABELS[entityGroup] ?? entityGroup.replace(/_/g, ' ')

export const formatNerEntitiesAsText = (entities: INerEntity[]) => {
  const heading = 'موجودیت‌های شناسایی‌شده'
  const summary = `تعداد: ${toPersianNumber(entities.length)} مورد`
  const header = ['ردیف', 'موجودیت', 'نوع', 'میزان اطمینان'].join(' | ')
  const divider = ['---', '---', '---', '---'].join(' | ')
  const rows = entities.map((entity, index) =>
    [
      toPersianNumber(index + 1),
      entity.word,
      getEntityLabel(entity.entity_group),
      formatPercent(entity.score),
    ].join(' | '),
  )

  return [heading, summary, '', header, divider, ...rows].join('\n')
}

const formatDate = (value: string) => {
  const date = new Date(value)
  return Number.isNaN(date.getTime())
    ? ''
    : new Intl.DateTimeFormat('fa-IR', {
        dateStyle: 'long',
        timeStyle: 'short',
      }).format(date)
}

const removeMarkdown = (value: string) =>
  value
    .replace(/^\s*#{1,6}\s*/gm, '')
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/__(.*?)__/g, '$1')
    .replace(/`([^`]+)`/g, '$1')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/^\s*[*+-]\s+/gm, '• ')
    .replace(/\n{3,}/g, '\n\n')
    .trim()

const getJsonOutputText = (value: string) => {
  try {
    const parsed: unknown = JSON.parse(value)
    if (
      !parsed ||
      typeof parsed !== 'object' ||
      !Array.isArray((parsed as { outputs?: unknown }).outputs)
    ) {
      return null
    }

    const text = (parsed as { outputs: unknown[] }).outputs
      .map(output =>
        output &&
        typeof output === 'object' &&
        typeof (output as { text?: unknown }).text === 'string'
          ? (output as { text: string }).text.trim()
          : '',
      )
      .filter(Boolean)
      .join('\n\n')

    return text || null
  } catch {
    return null
  }
}

const getExportMessageContent = (message: IChatMessage) => {
  const nerResult = message.bot ? parseNerResult(message.message) : null
  if (nerResult) return formatNerEntitiesAsText(nerResult.entities)

  return removeMarkdown(getJsonOutputText(message.message) ?? message.message)
}

export const formatChatAsText = ({
  title,
  messages,
}: {
  title: string
  messages: IChatMessage[]
}) => {
  const divider = '─'.repeat(56)
  const entries = messages
    .map(message => {
      const content = getExportMessageContent(message)
      const attachments = message.attachments
        .map(file => file.filename || file.originalName)
        .filter(Boolean)
      if (!content && attachments.length === 0) return ''

      const role = message.bot ? 'دستیار' : 'کاربر'
      const date = formatDate(message.createdAt)
      const attachmentText = attachments.length ? `پیوست‌ها: ${attachments.join('، ')}` : ''
      return [divider, `${role}${date ? ` | ${date}` : ''}`, '', content, attachmentText]
        .filter(Boolean)
        .join('\n')
    })
    .filter(Boolean)

  return [
    `گزارش گفتگو: ${title}`,
    `تاریخ خروجی: ${formatDate(new Date().toISOString())}`,
    '',
    ...entries,
  ].join('\n')
}

const arrayBufferToBase64 = (buffer: ArrayBuffer) => {
  const bytes = new Uint8Array(buffer)
  const chunkSize = 0x8000
  let binary = ''

  for (let index = 0; index < bytes.length; index += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(index, index + chunkSize))
  }

  return window.btoa(binary)
}

const prepareFont = async (pdf: jsPDF) => {
  const [regularResponse, boldResponse] = await Promise.all([
    fetch(kalamehFontUrl),
    fetch(kalamehBoldFontUrl),
  ])
  if (!regularResponse.ok || !boldResponse.ok) throw new Error('فونت خروجی PDF بارگذاری نشد.')

  pdf.addFileToVFS('Kalameh-Regular.ttf', arrayBufferToBase64(await regularResponse.arrayBuffer()))
  pdf.addFileToVFS('Kalameh-Bold.ttf', arrayBufferToBase64(await boldResponse.arrayBuffer()))
  pdf.addFont('Kalameh-Regular.ttf', 'Kalameh', 'normal')
  pdf.addFont('Kalameh-Bold.ttf', 'Kalameh', 'bold')
  pdf.setFont('Kalameh', 'normal')
}

const rtl = (pdf: jsPDF, value: string) => pdf.processArabic(value)

export const downloadNerEntitiesAsPdf = async ({
  entities,
  filename,
}: {
  entities: INerEntity[]
  filename: string
}) => {
  const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' })
  await prepareFont(pdf)

  const pageWidth = pdf.internal.pageSize.getWidth()
  const margin = 16
  const tableWidth = pageWidth - margin * 2
  const columns = [14, 72, 42, tableWidth - 128]
  const rowHeight = 10
  let y = 20

  const addPage = () => {
    pdf.addPage()
    y = 20
  }
  const cell = (text: string, right: number, width: number, top: number, bold = false) => {
    pdf.setFont('Kalameh', bold ? 'bold' : 'normal')
    pdf.text(rtl(pdf, text), right - 3, top + 6.5, { align: 'right', maxWidth: width - 6 })
  }
  const drawHeader = () => {
    pdf.setFillColor(12, 47, 61)
    pdf.roundedRect(margin, y - 7, tableWidth, 9, 1.5, 1.5, 'F')
    let right = pageWidth - margin
    ;['ردیف', 'موجودیت', 'نوع', 'میزان اطمینان'].forEach((label, index) => {
      cell(label, right, columns[index], y - 7, true)
      right -= columns[index]
    })
    y += 2
  }

  pdf.setTextColor(20, 46, 58)
  pdf.setFontSize(18)
  pdf.setFont('Kalameh', 'bold')
  pdf.text(rtl(pdf, 'موجودیت‌های شناسایی‌شده'), pageWidth - margin, y, { align: 'right' })
  y += 8
  pdf.setFontSize(10)
  pdf.setTextColor(90, 104, 111)
  pdf.setFont('Kalameh', 'normal')
  pdf.text(rtl(pdf, `تعداد: ${toPersianNumber(entities.length)} مورد`), pageWidth - margin, y, {
    align: 'right',
  })
  y += 13
  pdf.setFontSize(10)
  pdf.setTextColor(255, 255, 255)
  drawHeader()

  entities.forEach((entity, index) => {
    if (y + rowHeight > pdf.internal.pageSize.getHeight() - margin) {
      addPage()
      pdf.setTextColor(255, 255, 255)
      drawHeader()
    }

    pdf.setDrawColor(221, 229, 232)
    pdf.rect(margin, y - 7, tableWidth, rowHeight)
    pdf.setTextColor(20, 46, 58)
    let right = pageWidth - margin
    ;[
      toPersianNumber(index + 1),
      entity.word,
      getEntityLabel(entity.entity_group),
      formatPercent(entity.score),
    ].forEach((value, columnIndex) => {
      cell(value, right, columns[columnIndex], y - 7)
      right -= columns[columnIndex]
    })
    y += rowHeight
  })

  pdf.save(`${filename}.pdf`)
}

export const downloadChatAsPdf = async ({
  title,
  messages,
  filename,
}: {
  title: string
  messages: IChatMessage[]
  filename: string
}) => {
  const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' })
  await prepareFont(pdf)

  const pageWidth = pdf.internal.pageSize.getWidth()
  const pageHeight = pdf.internal.pageSize.getHeight()
  const margin = 16
  const contentWidth = pageWidth - margin * 2
  let y = 20

  const nextPage = () => {
    pdf.addPage()
    y = 20
  }
  const write = (
    value: string,
    { bold = false, color = [20, 46, 58] as [number, number, number] } = {},
  ) => {
    const lines = pdf.splitTextToSize(value, contentWidth) as string[]
    const height = Math.max(7, lines.length * 6)
    if (y + height > pageHeight - margin) nextPage()
    pdf.setTextColor(...color)
    pdf.setFont('Kalameh', bold ? 'bold' : 'normal')
    pdf.setFontSize(bold ? 13 : 10)
    lines.forEach((line, index) => {
      pdf.text(rtl(pdf, line), pageWidth - margin, y + index * 6, { align: 'right' })
    })
    y += height
  }

  write(`گزارش گفتگو: ${title}`, { bold: true })
  write(`تاریخ خروجی: ${formatDate(new Date().toISOString())}`, { color: [90, 104, 111] })
  y += 5

  messages.forEach(message => {
    const content = getExportMessageContent(message)
    const attachments = message.attachments
      .map(file => file.filename || file.originalName)
      .filter(Boolean)
    if (!content && attachments.length === 0) return

    if (y + 20 > pageHeight - margin) nextPage()
    pdf.setDrawColor(221, 229, 232)
    pdf.line(margin, y, pageWidth - margin, y)
    y += 7
    write(
      `${message.bot ? 'دستیار' : 'کاربر'}${
        message.createdAt ? ` | ${formatDate(message.createdAt)}` : ''
      }`,
      {
        bold: true,
        color: message.bot ? [12, 92, 115] : [88, 102, 110],
      },
    )
    if (content) {
      write(content)
    }
    if (attachments.length) {
      write(`پیوست‌ها: ${attachments.join('، ')}`, { color: [90, 104, 111] })
    }
    y += 6
  })

  pdf.save(`${filename}.pdf`)
}
