import { createSlice, PayloadAction } from '@reduxjs/toolkit'
import { RoutesV2 } from 'src/lib/constants'
// import type { RootState } from 'src/lib/store'
import { INotification, DownloadFiles, BDMTab, TABS, IBDMSession } from 'src/types'

export interface IBDMState {
  tabs: Array<BDMTab>
  notifications: Array<INotification>
  notificationsTotal: number
  downloadFiles: Array<DownloadFiles>
  loading: boolean
  sessions: Array<IBDMSession>
  hasUnsavedChanges: boolean
}

export const initialState: IBDMState = {
  tabs: [],
  notifications: [],
  notificationsTotal: 0,
  downloadFiles: [],
  loading: false,
  sessions: [],
  hasUnsavedChanges: false,
}

export const bdmSlice = createSlice({
  name: 'bdm',
  initialState,
  reducers: {
    setTabs: (state, action: PayloadAction<Array<BDMTab>>) => {
      state.tabs = action.payload
    },
    addTab: (state, action: PayloadAction<{ tab: TABS; link?: string }>) => {
      const foundTabIndex = state.tabs.findIndex(tab => tab.tab === action.payload.tab)

      if (foundTabIndex !== -1) {
        const foundTabId = state.tabs[foundTabIndex].id
        state.tabs = state.tabs.map(tab =>
          tab.id === foundTabId ? { ...tab, active: true } : { ...tab, active: false },
        )
        return
      }
      // TODO: fix type error later
      // @ts-ignore
      let newTab = RoutesV2().find(route => route.tab === action.payload.tab)

      if (!newTab) {
        return
      }

      newTab = {
        ...newTab,
        active: true,
        id: state.tabs.length + 1,
        ...(action.payload.link && { link: action.payload.link }),
      }
      state.tabs = state.tabs.map(tab => ({ ...tab, active: false }))
      state.tabs.push(newTab)
    },
    removeTab: (state, action: PayloadAction<number>) => {
      if (state.tabs.length === 0) {
        return
      }

      state.tabs = state.tabs.filter(tab => tab.id !== action.payload)

      state.tabs = state.tabs.map(tab => {
        if (tab.id < action.payload) {
          return tab
        } else {
          return { ...tab, id: tab.id - 1 }
        }
      })
    },
    activeATab: (state, action: PayloadAction<number>) => {
      state.tabs = state.tabs.map(tab =>
        tab.id === action.payload ? { ...tab, active: true } : { ...tab, active: false },
      )
    },
    navigateToTab: (state, action: PayloadAction<{ tab: TABS; link?: string }>) => {
      // check based on id or tab and id (because we also  need more than on tab)
      const hasTab = state.tabs.find(tabItem => tabItem.tab === action.payload.tab)

      if (hasTab) {
        if (state.tabs.length === 0) {
          return
        }
        const tabIndex = state.tabs.findIndex(tab => tab.id === hasTab.id)

        if (tabIndex === -1) {
          return
        }

        const foundId = state.tabs[tabIndex].id

        state.tabs = state.tabs.map(tab =>
          tab.id === foundId ? { ...tab, active: true } : { ...tab, active: false },
        )
      } else {
        const foundTabIndex = state.tabs.findIndex(tab => tab.tab === action.payload.tab)

        if (foundTabIndex !== -1) {
          const foundTabId = state.tabs[foundTabIndex].id
          state.tabs = state.tabs.map(tab =>
            tab.id === foundTabId ? { ...tab, active: true } : { ...tab, active: false },
          )
          return
        }

        // TODO: fix type error later
        // @ts-ignore
        let newTab = RoutesV2().find(route => route.tab === action.payload.tab)

        if (!newTab) {
          return
        }

        newTab = {
          ...newTab,
          active: true,
          id: state.tabs.length + 1,
          ...(action.payload.link && { link: action.payload.link }),
        }

        state.tabs = state.tabs.map(tab => ({ ...tab, active: false }))

        state.tabs.push(newTab)
      }
    },
    navigateToTabV2: (
      state,
      action: PayloadAction<{ tab: TABS; link: string; title?: string }>,
    ) => {
      const tabIndex = state.tabs.findIndex(tabItem => tabItem.link === action.payload.link)

      if (tabIndex !== -1) {
        const foundTab = state.tabs[tabIndex]

        state.tabs = state.tabs.map(tab =>
          tab.id === foundTab.id ? { ...tab, active: true } : { ...tab, active: false },
        )
        return
      }

      // TODO: fix type error later
      // @ts-ignore
      let newTab = RoutesV2().find(route => route.tab === action.payload.tab)

      if (!newTab) {
        return
      }

      newTab = {
        ...newTab,
        id: state.tabs.length + 1,
        active: true,
        ...(action.payload.link && {
          link: action.payload.link,
        }),
        ...(newTab.multiple && {
          title: action.payload.title ? action.payload.title : newTab.title,
        }),
      }

      state.tabs = state.tabs.map(tab => ({ ...tab, active: false }))
      state.tabs.push(newTab)
    },
    updateTab: (state, action: PayloadAction<Partial<BDMTab>>) => {
      const foundTabIdx = state.tabs.findIndex(tab => tab.id === action.payload.id)
      if (foundTabIdx === -1) {
        return
      }
      state.tabs[foundTabIdx] = { ...state.tabs[foundTabIdx], ...action.payload }
    },
    setNotifications: (
      state,
      action: PayloadAction<{ notifications: Array<INotification>; total: number }>,
    ) => {
      state.notifications = action.payload.notifications
      state.notificationsTotal = action.payload.total
    },
    setDownloadFiles: (state, action: PayloadAction<Array<DownloadFiles>>) => {
      state.downloadFiles = action.payload
    },
    setLoading: (state, action: PayloadAction<boolean>) => {
      state.loading = action.payload
    },
    setSessions: (state, action: PayloadAction<Array<IBDMSession>>) => {
      state.sessions = action.payload
    },
    setHasUnsavedChanges: (state, action: PayloadAction<boolean | undefined>) => {
      state.hasUnsavedChanges = action.payload ?? true
    },
  },
})

export const {
  setTabs,
  addTab,
  removeTab,
  activeATab,
  navigateToTab,
  navigateToTabV2,
  setNotifications,
  setDownloadFiles,
  setLoading,
  updateTab,
  setSessions,
  setHasUnsavedChanges,
} = bdmSlice.actions

export default bdmSlice.reducer
