import './style.scss'
import { useEffect, useRef, useState } from 'react'

import defualtImage from 'src/assets/defualtImage.svg'
import imagePlus from 'src/assets/imagePlus.svg'
import imagePlusWhite from 'src/assets/imagePlusWhite.svg'
import plus from 'src/assets/PlusIcon.svg'
import Frame1 from 'src/assets/jpg/backgroundImage1.jpg'
import Frame2 from 'src/assets/jpg/backgroundImage2.jpg'
import Frame3 from 'src/assets/jpg/backgroundImage3.jpg'
import Frame4 from 'src/assets/jpg/backgroundImage4.jpg'
import ExportMinus from 'src/assets/exportMinus.svg'
import { Divider } from '@mui/material'
import trashIcon from 'src/assets/trashIcon.svg'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import { RootState } from 'src/lib/store'
import { t } from 'i18next'
import { selectBackgroundDraftSettings, setBackgroundDraftSettings } from 'src/pages/Chat/slice'
import ChatAPIs from 'src/api/chat'
import { addAToast } from 'src/lib/context'

type BackgroundFit = 'cover' | 'contain' | 'repeat' | 'center'

type BackgroundSettings = {
  enabled: boolean
  image: string | null
  fit: BackgroundFit
  overlay: string
  blur: boolean
  applyToAll: boolean
  userMessageBackgroundColor: string
  userMessageTextColor: string
}

const ThemeCustomizer = () => {
  const dispatch = useBDMDispatch()
  const initialSettings = useBDMSelector(selectBackgroundDraftSettings)
  const [selectedTheme, setSelectedTheme] = useState(initialSettings.enabled)
  const [isBlur, setIsBlur] = useState(initialSettings.blur)
  const [isApplyToAlld, setIsApplyToAll] = useState(initialSettings.applyToAll)
  const [backgroundFit, setBackgroundFit] = useState<BackgroundFit>(initialSettings.fit)
  const colorPickerRef = useRef<HTMLInputElement | null>(null)
  const [selectedColor, setSelectedColor] = useState('')
  const [selectedFrame, setSelectedFrame] = useState<string | null>(
    initialSettings.image,
  )
  const [selectedItemId, setSelectedItemId] = useState<string | null>(initialSettings.overlay)
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const frames = [Frame1, Frame2, Frame3, Frame4]
  const colors = ['#222222', '#60CF9B', '#FAB55A', '#F5827A', '#78ADCD']
  const fileInputRef = useRef<HTMLInputElement | null>(null)

  useEffect(() => {
    setSelectedTheme(initialSettings.enabled)
    setIsBlur(initialSettings.blur)
    setIsApplyToAll(initialSettings.applyToAll)
    setBackgroundFit(initialSettings.fit)
    setSelectedFrame(initialSettings.image)
    setSelectedItemId(initialSettings.overlay)
  }, [initialSettings])

  const isUploadedImage = Boolean(selectedFrame && !frames.includes(selectedFrame))

  const getOverlayValue = (id: string | null, color = selectedColor) => {
    if (!id || id === 'removeColor') return 'none'
    if (id === 'gradient') return 'gradient'
    if (id === 'newColor') return color ? `${color}66` : 'none'
    return `${colors[Number(id)]}66`
  }

  const saveBackgroundDraft = (overrides: Partial<BackgroundSettings> = {}) => {
    const settings: BackgroundSettings = {
      enabled: selectedTheme,
      image: selectedFrame,
      fit: backgroundFit,
      overlay: getOverlayValue(selectedItemId),
      blur: isBlur,
      applyToAll: isApplyToAlld,
      userMessageBackgroundColor: initialSettings.userMessageBackgroundColor,
      userMessageTextColor: initialSettings.userMessageTextColor,
      ...overrides,
    }
    dispatch(setBackgroundDraftSettings(settings))
  }

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) {
      try {
        const response = await ChatAPIs().uploadBackgroundImage(file)
        if (!response.data?.success) {
          throw new Error(response.data?.message || 'بارگذاری تصویر پس‌زمینه ناموفق بود')
        }

        const imageUrl = URL.createObjectURL(file)
        setSelectedFrame(imageUrl)
        setSelectedTheme(true)
        saveBackgroundDraft({ enabled: true, image: imageUrl })
      } catch (error) {
        addAToast(
          error instanceof Error ? error.message : 'بارگذاری تصویر پس‌زمینه ناموفق بود',
          'error',
        )
      }
    }
  }

  const handlePlusClick = () => {
    if (colorPickerRef.current) {
      colorPickerRef.current.click()
    }
  }
    const handleColorChange = (
        event: React.ChangeEvent<HTMLInputElement> | string,
        index: string | null,
    ) => {
        setSelectedItemId(index)
        if (typeof event !== 'string') {
        setSelectedColor(event.target.value)
        saveBackgroundDraft({ overlay: getOverlayValue('newColor', event.target.value) })
      } else {
        saveBackgroundDraft({ overlay: getOverlayValue(index) })
        }
    }

    const handleThemeToggle = () => {
        setSelectedTheme(prev => {
            const nextValue = !prev
            if (!nextValue) {
                setSelectedFrame(null)
                saveBackgroundDraft({ enabled: false, image: null })
            } else {
                saveBackgroundDraft({ enabled: true })
            }
            return nextValue
        })
    }

  const removeImage = () => {
    setSelectedFrame(null)
    saveBackgroundDraft({ enabled: false, image: null })
  }

  function getColorOverlayStyle() {
    if (selectedItemId === 'gradient') {
      return {
        background: 'linear-gradient(to right, rgba(54, 133, 181, 0.4), rgba(79, 24, 75, 0.4))',
      }
    } else if (selectedItemId === 'newColor') {
      return {
        backgroundColor: `${selectedColor}40`,
      }
    } else if (selectedItemId === 'removeColor') {
      return {
        backgroundColor: `transparent`,
      }
    } else {
      return {
        backgroundColor: `${colors[Number(selectedItemId)]}40`,
      }
    }
  }

  return (
    <div>
      <div className='background-item'>
        <div className='background-item__text'>
          <p className='title'>{t('chat-background-appearance-title')}</p>
          <p className='desc'>{t('chat-background-appearance-description')}</p>
        </div>

                <span
                    onClick={handleThemeToggle}
                    className={`theme-toggle__switch ${selectedTheme ? 'active' : ''}`}
                >
          <span className='theme-toggle__switch-thumb' />
        </span>
      </div>
      {selectedTheme && (
        <div className='select-theme'>
          <div className='select-theme__new-theme'>
            <div className='select-theme__upload'>
              <div className='image'>
                <img
                  className='img-uploaded'
                  src={selectedFrame ?? defualtImage}
                  alt='uploaded'
                  style={{
                    filter: selectedFrame && isBlur ? 'blur(2px)' : 'none',
                    transition: 'filter 0.3s ease',
                  }}
                />
                {isUploadedImage && <div className='color-overlay' style={getColorOverlayStyle()} />}
                {isUploadedImage && (
                  <button
                    type='button'
                    className='trash-btn'
                    onClick={removeImage}
                    title={t('chat-delete-image')}
                  >
                    <img src={trashIcon} alt='trash' />
                  </button>
                )}
              </div>
              <div className='upload-input'>
                <img src={mode === 'light' ? imagePlus : imagePlusWhite} />
                {t('chat-upload-image')}
                <input
                  type='file'
                  accept='image/*'
                  ref={fileInputRef}
                  onChange={handleFileChange}
                />
              </div>
            </div>
            <div className='select-theme__custom'>
              <div className='custom-item'>
                {t('chat-image-fit-mode')}
                <select className='settings-select' value={backgroundFit} onChange={event => { const fit = event.target.value as BackgroundFit; setBackgroundFit(fit); saveBackgroundDraft({ fit }) }}>
                  <option value='cover'>{t('chat-image-fit-fill')}</option>
                  <option value='contain'>{t('chat-image-fit-contain')}</option>
                  <option value='repeat'>{t('chat-image-fit-tile')}</option>
                  <option value='center'>{t('chat-image-fit-center')}</option>
                </select>
              </div>
              <Divider className='divider-modals' />
              <div className='custom-item'>
                {t('chat-overlay')}
                <div style={{ display: 'flex', gap: '4px' }}>
                  <div
                    onClick={() => handleColorChange('', 'removeColor')}
                    style={{
                      background: 'var(--background-profile-modal-input)',
                      display: 'flex',
                      justifyContent: 'center',
                      alignItems: 'center',
                    }}
                    className={`color-default ${
                      selectedItemId === 'removeColor' ? 'active-color' : ''
                    }`}
                  >
                    <img src={ExportMinus} />
                  </div>
                  {colors &&
                    colors.map((c, index) => {
                      return (
                        <div
                          onClick={() => handleColorChange(c, String(index))}
                          key={index}
                          style={{ background: c }}
                          className={`color-default ${
                            selectedItemId === String(index) ? 'active-color' : ''
                          }`}
                        ></div>
                      )
                    })}
                  <div
                    onClick={() =>
                      handleColorChange('linear-gradient(to right, #3685B5, #4F184B)', 'gradient')
                    }
                    style={{ background: `linear-gradient(to right, #3685B5, #4F184B)` }}
                    className={`color-default ${
                      selectedItemId === 'gradient' ? 'active-color' : ''
                    }`}
                  ></div>
                  <div
                    style={{ background: 'var(--background-profile-modal-input)' }}
                    className='add-color-theme'
                    onClick={handlePlusClick}
                  >
                    <img src={plus} alt='Add Color' />
                    <input
                      type='color'
                      ref={colorPickerRef}
                      onChange={$event => handleColorChange($event, 'newColor')}
                    />
                  </div>
                </div>
              </div>
              <Divider className='divider-modals' />
              <div className='custom-item'>
                {t('chat-blur')}
                <span
                  onClick={() => setIsBlur(prev => { const next = !prev; saveBackgroundDraft({ blur: next }); return next })}
                  className={`theme-toggle__switch ${isBlur ? 'active' : ''}`}
                >
                  <span className='theme-toggle__switch-thumb' />
                </span>
              </div>
              <Divider className='divider-modals' />
              <div className='custom-item'>
                {t('chat-apply-to-all')}
                <span
                  onClick={() => setIsApplyToAll(prev => { const next = !prev; saveBackgroundDraft({ applyToAll: next }); return next })}
                  className={`theme-toggle__switch ${isApplyToAlld ? 'active' : ''}`}
                >
                  <span className='theme-toggle__switch-thumb' />
                </span>
              </div>
            </div>
          </div>
          <div className='select-theme__default-theme'>
            <p className='title'>{t('chat-background-gallery')}</p>
            <div className='images'>
              {frames.map(frame => {
                return (
                  <button
                    type='button'
                    key={frame}
                    className={`theme-frame-card ${selectedFrame === frame ? 'is-active' : ''}`}
                                    onClick={() => {
                                        setSelectedFrame(frame)
                                        setSelectedTheme(true)
                                        saveBackgroundDraft({ enabled: true, image: frame })
                                    }}
                  >
                    <img src={frame} alt='' />
                  </button>
                )
              })}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

export default ThemeCustomizer
