const normalizeMessageTypeForBackend = (type: string) => {
  const typeMap: Record<string, string> = {
    TEXT: 'text',
    IMAGE: 'image',
    FILE: 'file',
    VOICE: 'voice',
    GIS: 'gis',
  }

  return typeMap[type.toUpperCase()] ?? type.toLowerCase()
}

const toSafeNonNegativeNumber = (value: unknown, fallback = 0) => {
  const number = Number(value)
  return Number.isFinite(number) && number >= 0 ? number : fallback
}

// set current collection (local action)
export const setCurrentCollection = createAsyncThunk(
  'collection/setCurrentCollection',
  async (collectionId: string, { rejectWithValue, getState }) => {
    try {
      const state = getState() as RootState

      const foundCollection = state.newChat.collections[collectionId]

      if (!foundCollection) {
        const msg = 'Collection not found'
        addAToast(msg, 'error')
        return rejectWithValue(msg)
      }

      if (
        state.newChat.currentCollection &&
        state.newChat.currentCollection?.collectionId === collectionId
      ) {
        return {
          currentCollection: state.newChat.currentCollection,
          currentGraph: state.newChat.currentGraph,
        }
      }

      return {
        currentCollection: foundCollection,
      }
    } catch (error) {
      const msg = error instanceof Error ? error.message : 'unknown error'
      return rejectWithValue(msg)
    }
  },
)

// gets list of collections
export const getCollections = createAsyncThunk(
  'collection/getCollections',
  async (_, { rejectWithValue, getState }) => {
    const state = getState() as RootState

    try {
      const res = await chatAPIs().getCollections()
      if (res.data.success) {
        const data = normalizeCollectionsData(
          res.data.data.collections,
          state.newChat.collections,
        )

        // app i =s not init
        if (!state.newChat.appInitalized) {
          return { ...data, currentCollection: undefined, currentGraph: undefined }
        }

        // TODO: move it to seprate function or use useEffect
        const currentCollectionId = state.newChat.currentCollection?.collectionId
        const updatedCurrentCollection = currentCollectionId
          ? data.collections[currentCollectionId]
          : null

        return { ...data, currentCollection: updatedCurrentCollection }

        // return data
      } else {
        const msg = res.data.message || 'Failed to fetch collections, try again!'
        addAToast(msg, 'error')
        return rejectWithValue(msg)
      }
    } catch (error) {
      const msg = error instanceof Error ? error.message : 'unknown error'
      return rejectWithValue(msg)
    }
  },
)

