// get list of messages for a history
export const getHistoryMessages = createAsyncThunk(
  'collection/getHistoryMessages',
  async (
    props: {
      historyId?: string
      collectionId?: string
    },
    { rejectWithValue, getState },
  ) => {
    const state = getState() as RootState

    const getMessagesHandler = async (params: {
      collectionId: string | null
      historyId: string
      limit: number
      offset: number
    }) => {
      try {
        const res = params.collectionId
          ? await chatAPIs().getMessages(params as IGetMessagesDTI)
          : await chatAPIs().getCollectionLessHistoryMessages(params as IGetHistoryMessagesDTI)

        if (res.data.success && res.data.data) {
          return res.data.data
        } else {
          return rejectWithValue({ message: 'Failed fetching messages', code: 'API_ERROR' })
        }
      } catch (error: any) {
        const msg = error instanceof Error ? error.message : 'unknown error'
        return rejectWithValue(msg)
      }
    }

    try {
      const currentCollection = state.newChat.currentCollection
      const currentHistory = state.newChat.currentHistory

      if (props.historyId && !props.collectionId) {
        const foundHistory = state.newChat.CLHistories[props.historyId]

        if (foundHistory) {
          const total = toSafeNonNegativeNumber(foundHistory.total)
          const offset = Math.max(0, total - CHAT_MESSAGE_LIST_OFFSET)
          const limit = CHAT_MESSAGE_LIST_OFFSET
          const hasMore = offset > 0

          const messages = await getMessagesHandler({
            collectionId: null,
            historyId: props.historyId,
            limit,
            offset,
          })

          if (!messages) {
            return rejectWithValue({ message: 'No messages returned', code: 'NO_DATA' })
          }

          return {
            messages,
            historyState: {
              initialized: true,
              total,
              hasMore,
              offset,
              limit,
            },
          }
        } else {
          return rejectWithValue({ message: 'History not found' })
        }
      } else if (props.historyId && props.collectionId) {
        const foundHistory = state.newChat.histories[props.historyId]
        const foundCollection = state.newChat.collections[props.collectionId]

        if (foundHistory && foundCollection) {
          const total = toSafeNonNegativeNumber(foundHistory.total)
          const offset = Math.max(0, total - CHAT_MESSAGE_LIST_OFFSET)
          const limit = CHAT_MESSAGE_LIST_OFFSET
          const hasMore = offset > 0

          const messages = await getMessagesHandler({
            collectionId: props.collectionId,
            historyId: props.historyId,
            limit,
            offset,
          })

          if (!messages) {
            return rejectWithValue({ message: 'No messages returned', code: 'NO_DATA' })
          }

          return {
            messages,
            historyState: {
              initialized: true,
              total,
              hasMore,
              offset,
              limit,
            },
          }
        } else {
          // if collection or history not found, throw error
          return rejectWithValue({ message: 'Collection or history not found', code: 'NOT_FOUND' })
        }
      } else if (currentHistory && currentCollection) {
        const { initialized, total, hasMore, offset, limit } = state.newChat.historyState
        const safeTotal = toSafeNonNegativeNumber(
          total,
          toSafeNonNegativeNumber(currentHistory.total),
        )
        const safeOffset = toSafeNonNegativeNumber(offset)
        const safeLimit = toSafeNonNegativeNumber(limit, CHAT_MESSAGE_LIST_OFFSET)
        const currentHistoryTotal = toSafeNonNegativeNumber(currentHistory.total)

        const nextOffset =
          !initialized || hasMore
            ? Math.max(0, safeTotal - safeOffset - safeLimit)
            : Math.max(0, currentHistoryTotal - CHAT_MESSAGE_LIST_OFFSET)

        const messages = await getMessagesHandler({
          collectionId: currentCollection.collectionId,
          historyId: currentHistory.historyId,
          offset: nextOffset,
          limit: safeLimit,
        })

        if (!messages) {
          return rejectWithValue({ message: 'No messages returned', code: 'NO_DATA' })
        }

        return {
          messages,
          historyState: {
            initialized: true,
            hasMore: nextOffset > 0,
            offset: nextOffset,
            total: safeTotal,
            limit: safeLimit,
          },
        }
        // is a context-less session
      } else if (currentHistory && !currentCollection) {
        const { initialized, total, hasMore, offset, limit } = state.newChat.historyState
        const safeTotal = toSafeNonNegativeNumber(
          total,
          toSafeNonNegativeNumber(currentHistory.total),
        )
        const safeOffset = toSafeNonNegativeNumber(offset)
        const safeLimit = toSafeNonNegativeNumber(limit, CHAT_MESSAGE_LIST_OFFSET)
        const currentHistoryTotal = toSafeNonNegativeNumber(currentHistory.total)

        const nextOffset =
          !initialized || hasMore
            ? Math.max(0, safeTotal - safeOffset - safeLimit)
            : Math.max(0, currentHistoryTotal - CHAT_MESSAGE_LIST_OFFSET)

        const messages = await getMessagesHandler({
          collectionId: null,
          historyId: currentHistory.historyId,
          offset: nextOffset,
          limit: safeLimit,
        })

        if (!messages) {
          return rejectWithValue({ message: 'No messages returned', code: 'NO_DATA' })
        }

        return {
          messages,
          historyState: {
            initialized: true,
            hasMore: nextOffset > 0,
            offset: nextOffset,
            total: safeTotal,
            limit: safeLimit,
          },
        }
      } else {
        return rejectWithValue({ message: 'Collection or history not found', code: 'NOT_FOUND' })
      }
    } catch (error: any) {
      const msg = error instanceof Error ? error.message : 'unknown error'
      return rejectWithValue(msg)
    }
  },
)

// set current history (local action)
export const setCurrentHistory = createAsyncThunk(
  'collection/setCurrentHistory',
  async (
    {
      historyId,
      collectionId,
    }: {
      historyId: string
      collectionId: string | null
    },
    { rejectWithValue, getState, dispatch },
  ) => {
    const state = getState() as RootState

    try {
      const foundHistory = collectionId
        ? state.newChat.histories[historyId]
        : state.newChat.CLHistories[historyId]
      if (!foundHistory) {
        return rejectWithValue('History not found')
      }

      // if not found, its a context less session
      const foundCollection = collectionId ? state.newChat.collections[collectionId] : null

      const result = await dispatch(
        getHistoryMessages({ collectionId: collectionId ?? undefined, historyId }),
      )

      const messagesResult = unwrapResult(result)

      return {
        currentCollection: foundCollection,
        currentHistory: foundHistory,
        ...messagesResult,
      }
    } catch (error) {
      const msg = error instanceof Error ? error.message : 'unknown error'
      return rejectWithValue(msg)
    }
  },
)

