// send message and also used to create a new session (general model)
export const aiChatAssistant = createAsyncThunk(
  'collection/aiChatAssistant',
  async (
    { payload: params, files }: ISendChatMessageDTI,
    { rejectWithValue, dispatch, getState },
  ) => {
    try {
      const initialProjectHistoryIds = new Set(
        params.collectionId
          ? (
              (getState() as RootState).newChat.collections[params.collectionId]
                ?.collectionHistory ?? []
            ).flatMap(history => [history.historyId, history.sessionId].filter(Boolean))
          : [],
      )
      // `pending-*` is a browser-only id used for immediate previews. It is
      // never a valid backend file id and must not be included in API payloads.
      const requestedFileIds =
        params.fileIds.length > 0
          ? params.fileIds
          : params.messageSchema.message.attachments.map(item => item._id)
      const fileIds = requestedFileIds.filter(fileId => !fileId.startsWith('pending-'))

      // if there is attachment, type is file, if not use provided version
      const type =
        fileIds.length > 0 || files?.length
          ? CHAT_MESSAGE_TYPES.FILE
          : params.messageSchema.message.type

      const req = {
        ...params,
        fileIds,
        messageSchema: {
          message: {
            ...params.messageSchema.message,
            attachments: [],
            type: normalizeMessageTypeForBackend(String(type)) as CHAT_MESSAGE_TYPES,
          },
        },
      }

      const res = await chatAPIs().AIChatAssistant({ payload: req, files })
      console.log(res?.data, 'res?.data')

      if (res?.data?.success) {
        // The async endpoint can acknowledge the request without returning a
        // data object. In that case the generated session id is also the id
        // used by the socket stream until the histories list is refreshed.
        const responseData = res.data.data
        const responseHistoryId = responseData?.historyId ?? params.historyId ?? params.sessionId
        const responseSessionId = responseData?.sessionId ?? params.sessionId
        const collectionId = responseData?.collectionId ?? params.collectionId ?? null
        if (collectionId) {
          await dispatch(getCollections())
        } else {
          await dispatch(getCollectionLessHistories())
        }
        const refreshedHistories = collectionId
          ? (getState() as RootState).newChat.collections[collectionId]?.collectionHistory ?? []
          : []
        const responseIds = [responseHistoryId, responseSessionId].filter(Boolean)
        const refreshedHistory = !params.historyId
          ? refreshedHistories.find(history =>
              [history.historyId, history.sessionId].some(id => id && responseIds.includes(id)),
            ) ??
            refreshedHistories.find(history =>
              [history.historyId, history.sessionId]
                .filter(Boolean)
                .every(id => !initialProjectHistoryIds.has(id)),
            )
          : undefined
        const historyId = refreshedHistory?.historyId ?? responseHistoryId
        const sessionId = refreshedHistory?.sessionId ?? responseSessionId
        const uploadedFileIds = responseData?.fileIds ?? []
        const uploadedAt = new Date().toISOString()
        const newAttachments = (files ?? []).map((file, index) => {
          const serverFileId = uploadedFileIds[index]
          const fileId = serverFileId ?? `pending-${params.messageSchema.message.id}-${index}`

          return {
            _id: fileId,
            fileId,
            filename: file.name,
            originalName: file.name,
            size: file.size,
            mimeType: file.type,
            state: serverFileId ? 'done' : 'pending',
            fullPath: '',
            uploadedAt,
            scopeType: collectionId ? 'COLLECTION' : 'GENERAL',
            collectionId,
            historyId,
          }
        })
        console.log(res.data, 'res.data.data')

        // The optimistic message already carries a pending placeholder for
        // each file in `files` (added at submit time so the count/preview
        // shows instantly). Drop those placeholders here so `newAttachments`
        // (their resolved replacements) doesn't get appended alongside them.
        const placeholderPrefix = `pending-${params.messageSchema.message.id}-`
        const carriedOverAttachments = params.messageSchema.message.attachments.filter(
          (file: IChatSessionFileUploadItem) => !file.fileId?.startsWith(placeholderPrefix),
        )

        return {
          ...params,
          historyId,
          sessionId,
          collectionId,
          created: responseData?.created ?? !params.historyId,
          waiting: responseData?.waiting ?? true,
          answerStatus: responseData?.answerStatus ?? params.answerStatus,
          fileIds: [...fileIds, ...uploadedFileIds],
          messageSchema: {
            message: {
              ...params.messageSchema.message,
              type,
              attachments: [...carriedOverAttachments, ...newAttachments],
            },
          },
        }
      } else {
        const msg = res?.data?.message || 'Failed to send the message, try again!'
        addAToast(msg, 'error')
        return rejectWithValue(msg)
      }
    } catch (error: any) {
      const msg =
        error?.response?.data?.message ||
        error?.data?.message ||
        (error instanceof Error ? error.message : 'Failed to send the message, try again!')
      addAToast(msg, 'error')
      return rejectWithValue(msg)
    }
  },
)

export const editMessage = createAsyncThunk(
  'collection/editMessage',
  async (params: IEditMessageDTI, { rejectWithValue, dispatch, getState }) => {
    try {
      const state = getState() as RootState
      const collectionId = state.newChat.currentHistory?.collectionId ?? undefined
      const requestParams = { ...params, ...(collectionId && { collectionId }) }
      const res = await chatAPIs().editMessage(requestParams)
      if (res.data.success) {
        if (res.data.message) {
          addAToast(res.data.message, 'success')
        }
        const messagesResult = await dispatch(
          getHistoryMessages({
            historyId: params.historyId,
            collectionId: collectionId ?? undefined,
          }),
        )
        const messagesData = unwrapResult(messagesResult) as {
          messages: IChatMessage[]
          historyState: IChatState['historyState']
        }
        return { ...params, ...messagesData }
      } else {
        const msg = res.data.message || 'Failed to edit the message, try again!'
        addAToast(msg, 'error')
        throw new Error(msg)
      }
    } catch (error) {
      const msg = error instanceof Error ? error.message : 'unknown error'
      return rejectWithValue(msg)
    }
  },
)

// upload file for a collection
export const uploadFile = createAsyncThunk(
  'collection/uploadFile',
  async (params: IUploadFileDTI, { rejectWithValue, dispatch }) => {
    try {
      const clonedParams = new FormData()
      for (const [key, value] of params.entries()) {
        clonedParams.append(key, value)
      }

      const fileIds = clonedParams.getAll('fileId') as string[]

      clonedParams.delete('fileId')

      const files = params.getAll('files') as File[]
      files.forEach((file, index) => {
        const fileId = fileIds[index]
        if (!fileId) {
          return
        }

        dispatch(
          addUploadFile({
            fileId,
            filename: file.name,
            filetype: file.type,
            filesize: sizeFormatter(file.size),
          }),
        )
      })

      const onUploadProgress = (event: AxiosProgressEvent) => {
        const loaded = event.loaded
        const total = event.total ?? 1
        const progress = Math.round((loaded * 100) / total)
        // set 100 on request done, since at that time result is clear
        fileIds.forEach(fileId => {
          dispatch(updateUploadFileProgress({ fileId, progress: progress === 100 ? 99 : progress }))
        })
      }

      const res = await chatAPIs().uploadFile(clonedParams, onUploadProgress)

      if (!res.data.success) {
        const msg = res.data.message ?? 'خطای ارسال فایل'
        addAToast(msg, 'error')
        return rejectWithValue({ msg, params })
      }
    } catch (error) {
      const msg = error instanceof Error ? (error.message as string) : 'unknown error'
      return rejectWithValue({ msg, params })
    }
  },
)

