// create collection session (for collection)
export const createSession = createAsyncThunk(
  'collection/createSession',
  async (params: ICreateSessionDTI, { rejectWithValue, dispatch }) => {
    try {
      const res = await chatAPIs().createSession(params)
      if (res.data.success) {
        dispatch(getCollections())
        await new Promise(res => setTimeout(res, 100))
        dispatch(
          setCurrentHistory({
            historyId: res.data.data.historyId,
            collectionId: params.collectionId,
          }),
        )
        return {
          historyId: res.data.data.historyId,
          collectionId: params.collectionId,
          newHistory: res.data.data,
        }
      } else {
        const msg = res.data.message || t<string>('create-collection-session-error')
        addAToast?.(msg, 'error')
        throw new Error(msg)
      }
    } catch (error) {
      const msg = error instanceof Error ? (error.message as string) : 'unknown error'
      return rejectWithValue(msg)
    }
  },
)

// get todays histories
export const getTodaysHistories = createAsyncThunk(
  'collection/serverTime',
  async (_, { rejectWithValue, getState }) => {
    const state = getState() as RootState
    try {
      const res = await userAPIs.getServerTime()
      if (res.data.success) {
        const trimmedDate = res.data.data.trim()
        const now = new Date(trimmedDate)
        const allHistories = [...state.newChat.historyList, ...state.newChat.CLHistoryList]
        const todaysHistories = allHistories.filter(history => isSameDay(history.createdAt, now))
        return { todaysHistories }
      } else {
        const msg = res.data.message || t<string>('create-collection-session-error')
        throw new Error(msg)
      }
    } catch (error) {
      const msg = error instanceof Error ? (error as Error).message : 'Unknown error'
      return rejectWithValue(msg)
    }
  },
)

// set collections from socket
export const setCollectionsFromSocket = createAsyncThunk(
  'collection/setCollectionsFromSocket',
  async (socketCollections: IChatCollection[], { rejectWithValue, getState }) => {
    const state = getState() as RootState
    try {
      const data = normalizeCollectionsData(socketCollections, state.newChat.collections)

      const currentCollectionId = state.newChat.currentCollection?.collectionId
      const updatedCurrentCollection = currentCollectionId
        ? data.collections[currentCollectionId]
        : null
      const currentHistoryId = state.newChat.currentHistory?.historyId
      const updatedCurrentHistory = currentHistoryId ? data.histories[currentHistoryId] : null
      const { added } = analyzeNewHistoryData({
        newHistory: data.histories,
        oldHistory: state.newChat.histories,
      })

      return {
        ...data,
        // currentGraph,
        currentCollection: updatedCurrentCollection,
        currentHistory: updatedCurrentHistory,
        newHistory: added.length > 0 ? added[0] : null,
      }
    } catch (error) {
      if (error instanceof Error) {
        return rejectWithValue(error.message as string)
      }
      return rejectWithValue('unknown error')
    }
  },
)

export const setChatStateFromParams = createAsyncThunk(
  'collection/setChatStateFromParams',
  async (chatStateParams: IChatState['chatStateParams'], { rejectWithValue, dispatch }) => {
    try {
      const { collectionId, historyId, isParamsSynced } = chatStateParams

      if (isParamsSynced) {
        return chatStateParams
      }

      // collection
      if (collectionId && !historyId) {
        dispatch(setCurrentCollection(collectionId))
      }

      // history
      if (historyId) {
        dispatch(setCurrentHistory({ collectionId: collectionId ?? null, historyId }))
      }

      return chatStateParams
    } catch (error) {
      if (error instanceof Error) {
        return rejectWithValue(error.message as string)
      }
      return rejectWithValue('unknown error')
    }
  },
)

