// get list of upload files for a collection
export const getUploadFiles = createAsyncThunk(
  'upload/get-upload-files',
  async (collectionId: string, { rejectWithValue }) => {
    try {
      const res = await chatAPIs().getUploadFile({ collectionId })
      if (res.data.success) {
        const uploadFiles: IChatState['uploadFiles'] = {}
        const collectionFiles = res.data.data
          .filter(isUserUploadedFile)
          .map(file =>
            normalizeCollectionFile({
              ...file,
              _id: file.fileId,
              collectionId,
            }),
          )

        collectionFiles.forEach(file => {
          uploadFiles[file.fileId] = {
            fileId: file.fileId,
            filename: file.originalName || file.filename,
            filetype: file.mimeType || getMimeType(file.originalName || file.filename),
            filesize: file.size.toString(),
            error: false,
            progress: 100,
          }
        })
        return { collectionId, uploadFiles, collectionFiles }
      } else {
        const msg = res.data.message || 'Failed to fetch upload files, try again!'
        addAToast(msg, 'error')
        throw new Error(msg)
      }
    } catch (error) {
      const msg = error instanceof Error ? (error.message as string) : 'unknown error'
      return rejectWithValue(msg)
    }
  },
)

