// update collection's prompt
export const getModelsList = createAsyncThunk(
  'model/getAIModelsList',
  async (_props, { rejectWithValue }) => {
    try {
      const res = await chatAPIs().getAIModelList()
      if (!res?.data?.success) {
        const message = res?.data?.message
        if (res?.data?.status === 401) {
          logout()
        }
        // HTTP failures are surfaced once by the shared API layer with the
        // backend's `response.data.message`; do not access `data` on them.
        return rejectWithValue(message)
      }
      return res.data.data.models
    } catch (error: any) {
      const status = error?.response?.status
      if (status === 401) {
        logout()
        return rejectWithValue('unauthorized')
      }
      return rejectWithValue(error?.response?.data?.message)
    }
  },
)

