import './style.scss'

import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import { selectDriveBreadcrumb, setDriveCrumbs } from 'src/lib/slice/fileManagement/fileSlice'
import { getRecentFiles } from 'src/lib/slice/fileManagement/thunks'

import Breadcrumbs from '@mui/material/Breadcrumbs'
import Link from '@mui/material/Link'
import { IBreadcrumb } from 'src/types/FileManagement'

import backIcon from 'src/assets/backIcon.svg'

interface IProps {
  title: string
  breadcrumb?: boolean
  displayMode?: 'table' | 'cards'
}

const PanelHeader = ({ title, breadcrumb = true }: IProps) => {
  const dispatch = useBDMDispatch()
  const crumbs = useBDMSelector(selectDriveBreadcrumb)

  const getData = (breadcrumb?: IBreadcrumb, idx = -1) => {
    if (breadcrumb?.folderId && idx >= 0) {
      dispatch(getRecentFiles({ folderId: breadcrumb.folderId }))
      dispatch(setDriveCrumbs(crumbs.slice(0, idx + 1)))
    } else {
      dispatch(getRecentFiles({}))
      dispatch(setDriveCrumbs([]))
    }
  }

  const handleBack = () => {
    if (crumbs.length > 1) {
      const parent = crumbs[crumbs.length - 2]
      getData(parent, crumbs.length - 2)
    } else {
      getData()
    }
  }

  return (
    <div className='file-manager-panel-header'>
      {/* {!breadcrumb && <span className='file-manager-panel-header__title'>{title}</span>} */}
      {breadcrumb && (
        <div className='file-manager-panel-breadcrumb'>
          {crumbs.length > 0 && (
            <img src={backIcon} className='file-manager-panel-back-btn' onClick={handleBack} />
          )}
          <Breadcrumbs aria-label='breadcrumb'>
            <Link
              onClick={() => getData()}
              underline='hover'
              color={crumbs.length === 0 ? 'text.primary' : 'inherit'}
              sx={{ cursor: 'pointer' }}
            >
              {title}
            </Link>
            {crumbs.map(({ folderId, name }, idx) => (
              <Link
                key={folderId ?? 'root'}
                underline='hover'
                color={idx === crumbs.length - 1 ? 'text.primary' : 'inherit'}
                sx={{ cursor: 'pointer' }}
                onClick={() => getData({ folderId, name }, idx)}
              >
                {name}
              </Link>
            ))}
          </Breadcrumbs>
        </div>
      )}
    </div>
  )
}

export default PanelHeader
