import { createAsyncThunk } from '@reduxjs/toolkit'
import { addAToast } from 'src/lib/context'
import {
  IFileItem,
  IFolderItem,
  IGetRecentFilesDTI,
  IBreadcrumb,
  ISubmitDanaCollectionsFilesDTI,
  IUploadItem,
} from 'src/types/FileManagement'
import fileManagerAPIs from 'src/api/fileManager'
import { RootState } from 'src/lib/store'
import { setUploadStatus, updateUploadProgress } from './fileSlice'
import { AxiosProgressEvent } from 'axios'

export const getRecentFiles = createAsyncThunk(
  'drive/getListOfFilesFolders',
  async (props: IGetRecentFilesDTI, { rejectWithValue, getState }) => {
    const state = getState() as RootState
    // TODO: get lates data based on breadcrumb
    // const breadcrumb = state.file.breadcrumb

    try {
      const res = await fileManagerAPIs().getRecentFiles(props)
      if (!res.data.success) {
        addAToast(res.data.message || 'خطا در دریافت لیست فایل ها', 'error')
        return rejectWithValue(res.data.message || 'failed fetching data')
      }

      const { data, limit, page, total } = res.data.data
      const files = data.filter(item => item.itemType === 'file') as IFileItem[]
      const folders = data.filter(item => item.itemType === 'folder') as IFolderItem[]
      let breadcrumb: IBreadcrumb | null = null

      if (props.folderId) {
        const foundFolder = state.file.folders.find(item => item.id === props.folderId)
        if (foundFolder) {
          breadcrumb = { folderId: foundFolder.id, name: foundFolder.name }
        }
      }

      return { data, files, folders, total, page, limit, breadcrumb }
    } catch (error) {
      const msg = error instanceof Error ? (error as Error).message : 'Unknown error'
      addAToast(msg, 'error')
      return rejectWithValue(msg)
    }
  },
)

export const submitDanaFiles = createAsyncThunk(
  'drive/submitDanaFiles',
  async (props: ISubmitDanaCollectionsFilesDTI, { rejectWithValue }) => {
    try {
      const res = await fileManagerAPIs().submitDanaCollectionsFiles(props)

      if (!res.data.success) {
        addAToast(res.data.message || 'خطا در ارسال فایل ها', 'error')
        return rejectWithValue(res.data.message || 'failed submitting data')
      }

      if (res.data.success && res.data.message) {
        addAToast(res.data.message, 'info')
      }
    } catch (error) {
      const msg = error instanceof Error ? (error as Error).message : 'Unknown error'
      addAToast(msg, 'error')
      return rejectWithValue(msg)
    }
  },
)

export const uploadFileItems = createAsyncThunk(
  'drive/uploadFile',
  async (files: IUploadItem[], { rejectWithValue, dispatch }) => {
    try {
      await Promise.all(
        files.map(async item => {
          if (!item.file) {
            return
          }

          const id = item.id
          const formData = new FormData()
          formData.append('files', item.file)
          formData.append('folderId', '')

          try {
            const onUploadProgress = (e: AxiosProgressEvent) => {
              const { loaded, total = 1 } = e
              const progress = Math.round((loaded * 100) / total)
              dispatch(updateUploadProgress({ id, progress }))
            }

            const res = await fileManagerAPIs().uploadFiles(formData, onUploadProgress)

            if (!res.data.success) {
              dispatch(setUploadStatus({ id, status: 'error', error: res.data.message }))
              addAToast(res.data.message || `خطا در ارسال ${item.name}`, 'error')
              return
            }

            const uploadedFile = res.data.data[0]
            dispatch(
              setUploadStatus({
                id,
                status: 'success',
                response: res.data,
                serverId: uploadedFile.id,
              }),
            )
          } catch (err) {
            const msg = err instanceof Error ? err.message : 'Unknown error'
            dispatch(setUploadStatus({ id, status: 'error', error: msg }))
            addAToast(msg, 'error')
          }
        }),
      )
    } catch (error) {
      const msg = error instanceof Error ? error.message : 'Unknown error'
      addAToast(msg, 'error')
      return rejectWithValue(msg)
    }
  },
)
