import { t } from 'i18next'
import Button from 'src/components/Button'
import { IBDMUser } from 'src/types'
import userPic from 'src/assets/userPic.svg'
import { Trans } from 'react-i18next'

const UsetMenu = ({
  show,
  handleNavigationToSettings,
  user,
  handleLogOut,
}: {
  show: boolean
  handleNavigationToSettings: () => void
  user?: IBDMUser
  handleLogOut: () => void
}) => {
  handleNavigationToSettings
  return show ? (
    <div className='bdm-header__menu'>
      <img
        src={userPic}
        alt='userpic'
        className='bdm-header__menu__img'
        onClick={handleNavigationToSettings}
        loading='lazy'
        width={80}
        height={80}
      />
      <p className='bdm-header__menu__name'>{user ? user.firstname + ' ' + user.lastname : ''}</p>
      <p className='bdm-header__menu__position'>{user ? t<string>(user.username) : ''}</p>
      <Button className='bdm-header__menu__log-out-btn' onClick={handleLogOut}>
        <Trans i18nKey={'menu-home-btn-title'} />
      </Button>
    </div>
  ) : null
}

export default UsetMenu
