// style
import './style.scss'

// utils
import { t } from 'i18next'
import { ChangeEvent, DragEvent, Fragment, useEffect } from 'react'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import {
  selectUploadFiles,
  selectCurrentCollection,
  selectLoadingState,
  selectHistoryAttachments,
  clearUploadFiles,
  setModalsState,
  selectModalsState,
  uploadFile,
  getUploadFiles,
  updateAttachment,
  replaceAttachment,
  deleteCollectionFile,
} from 'src/pages/Chat/slice'
import { generateLongId, normalizeUploadFile } from 'src/lib/utils'

import { submitDanaFiles } from 'src/lib/slice/fileManagement/thunks'

// components
// import ChatCard from '../ChatCard'
import Dialog from '@mui/material/Dialog'
import CircularProgress from '@mui/material/CircularProgress'
import Divider from '@mui/material/Divider'
import DialogContent from '@mui/material/DialogContent'
// import { isBDM } from 'src/lib/constants'
// icons
// import chatFileUploadIcon from 'src/assets/chatFileUploadIcon.svg'
import attachIcon from 'src/assets/attachIcon.svg'
import attachIconWhite from 'src/assets/attachIconWhite.svg'
import cloudUpload from 'src/assets/cloudUpload.svg'
import closeIcon from 'src/assets/closeIcon.svg'
import closeIconWhite from 'src/assets/closeIconWhite.svg'

import FileItem from './FileItem'
import FileManager from 'src/components/FileManager'
import { selectDriveSelectedFiles } from 'src/lib/slice/fileManagement/fileSlice'
import { RootState } from 'src/lib/store'
import { addAToast } from 'src/lib/context'

export const FILE_TYPES: Record<string, string> = {
  'text/csv': 'csv',
  'text/plain': 'text',
  'application/vnd.apache.parquet': 'parquet',
  'application/x-parquet': 'parquet',
  'application/vnd.ms-excel': 'excel',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'excel',
  'application/pdf': 'pdf',
  'image/png': 'image',
  'image/jpeg': 'image',
  'image/jpg': 'image',
}

const ChatFileUpload = () => {
  const dispatch = useBDMDispatch()
  const collectionId = useBDMSelector(selectCurrentCollection)?.collectionId
  const selectedFiles = useBDMSelector(selectDriveSelectedFiles)
  const isLoading = useBDMSelector(selectLoadingState).collectionFiles
  const isOpen = useBDMSelector(selectModalsState).uploadFile
  const allowMultipleAttachments = useBDMSelector(selectModalsState).allowMultipleAttachments
  const files = useBDMSelector(selectUploadFiles)
  const historyAttachments = useBDMSelector(selectHistoryAttachments)
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  // const handleClickOpen = async () => {
  //   dispatch(setModalsState({ uploadFile: true }))

  //   if (collectionId) {
  //     await dispatch(getUploadFiles(collectionId))
  //   }
  // }

  const handleClose = () => {
    dispatch(clearUploadFiles())
    dispatch(setModalsState({ uploadFile: false, allowMultipleAttachments: false }))
  }

  const handleUploadFiles = async (selectedFiles: File[]) => {
    const filesToUpload = (allowMultipleAttachments ? selectedFiles : selectedFiles.slice(0, 1)).map(
      normalizeUploadFile,
    )

    if (filesToUpload.length === 0) {
      return
    }

    if (!collectionId) {
      return
    }

    const formData = new FormData()

    filesToUpload.forEach(file => {
      formData.append('files', file)
      formData.append('fileId', generateLongId())
    })
    formData.append('collectionId', collectionId)

    const result = await dispatch(uploadFile(formData))
    if (uploadFile.fulfilled.match(result)) {
      await dispatch(getUploadFiles(collectionId))
    }
  }

  const handleSubmit = async (e: ChangeEvent<HTMLInputElement>) => {
    await handleUploadFiles(Array.from(e.target.files ?? []))
    // Allow selecting the same file again after an upload attempt.
    e.target.value = ''
  }

  const handleDragOver = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault()
    event.stopPropagation()
  }

  const handleDrop = async (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault()
    event.stopPropagation()

    if (!isLoading) {
      await handleUploadFiles(Array.from(event.dataTransfer.files))
    }
  }

  useEffect(() => {
    if (!isOpen) return

    // Prevent Chrome from navigating to a file when it is dropped outside the upload area.
    const preventFileNavigation = (event: globalThis.DragEvent) => event.preventDefault()
    window.addEventListener('dragover', preventFileNavigation)
    window.addEventListener('drop', preventFileNavigation)

    return () => {
      window.removeEventListener('dragover', preventFileNavigation)
      window.removeEventListener('drop', preventFileNavigation)
    }
  }, [isOpen])

  const handleConfirmDrive = async () => {
    const fileIds = (allowMultipleAttachments ? selectedFiles : selectedFiles.slice(0, 1)).map(
      item => item.id,
    )

    if (collectionId && fileIds.length > 0) {
      await dispatch(submitDanaFiles({ collectionId, fileIds })).unwrap()
      const { collectionFiles } = await dispatch(getUploadFiles(collectionId)).unwrap()
      const selectedUploadedFiles = collectionFiles.filter(file => fileIds.includes(file.fileId))
      const duplicateFiles = selectedUploadedFiles.filter(file =>
        historyAttachments.some(item => item.fileId === file.fileId || item._id === file.fileId),
      )
      const newFiles = selectedUploadedFiles.filter(file => !duplicateFiles.includes(file))

      if (duplicateFiles.length > 0) {
        addAToast('برخی از فایل‌ها را قبلاً انتخاب یا اضافه کرده‌اید.', 'warning')
      }

      if (newFiles.length > 0) {
        const filesToAttach = allowMultipleAttachments
          ? newFiles
          : newFiles.slice(0, 1)
        filesToAttach.forEach(file =>
          dispatch(allowMultipleAttachments ? updateAttachment(file) : replaceAttachment(file)),
        )
        handleClose()
      }
    }
  }

  const handleCancelDrive = async () => {
    if (collectionId) {
      await dispatch(getUploadFiles(collectionId))
    }
  }

  const handleSelectUploadedFile = (file: (typeof files)[string]) => {
    if (!collectionId || file.error || file.progress < 100) {
      return
    }

    if (historyAttachments.some(item => item.fileId === file.fileId || item._id === file.fileId)) {
      addAToast('این فایل را قبلاً انتخاب یا اضافه کرده‌اید.', 'warning')
      return
    }

    const attachment = {
        _id: file.fileId,
        fileId: file.fileId,
        filename: file.filename,
        originalName: file.filename,
        size: Number(file.filesize) || 0,
        mimeType: file.filetype,
        state: 'done',
        fullPath: '',
        uploadedAt: new Date().toISOString(),
        scopeType: 'COLLECTION',
        collectionId,
      }
    dispatch(allowMultipleAttachments ? updateAttachment(attachment) : replaceAttachment(attachment))
    handleClose()
  }

  const handleDeleteUploadedFile = async (fileId: string) => {
    if (collectionId) {
      await dispatch(deleteCollectionFile({ collectionId, fileId }))
    }
  }

  return (
    <Fragment>
      {/* <ChatCard
        title={t('chat-collection-upload-file-card-title')}
        description={t('chat-collection-upload-file-card-description')}
        icon={chatFileUploadIcon}
        onClick={handleClickOpen}
        disable={isBDM}
      /> */}
      {/* Dialog */}
      <Dialog PaperProps={{
        sx: {
          borderRadius: '16px',
        },
      }} open={isOpen} onClose={handleClose} maxWidth='md' tabIndex={1}>
        <DialogContent className="chat-chatbox-file-upload-dialog"
          sx={{ width: '724px', height: Object.values(files).length > 0 ? '589px' : '368px' }}>
          {/* header */}
          <div className='chat-chatbox-file-upload-header'>
            <div className='chat-chatbox-file-upload-actions'>
              <div className='chat-chatbox-file-upload-title'>
                <img src={mode === 'light' ? attachIcon : attachIconWhite} />
                {t('chat-file-upload-title')}
                {Object.values(files).length > 0 ? (
                  <div className='chat-chatbox-file-upload-box-head'>
                    <label
                      className={`chat-chatbox-file-upload-upload ${isLoading ? 'disabled' : ''}`}
                      htmlFor='chat-chatbox-file-upload-upload'
                    >
                      <p>{t('chat-collection-upload-file-card-title')}</p>
                    </label>

                    <input
                      type='file'
                      multiple={allowMultipleAttachments}
                      id='chat-chatbox-file-upload-upload'
                      accept='.csv, .txt, .png, .jpg, .jpeg, .pdf, .parquet, .xls, .xlsx'
                      hidden
                      onChange={handleSubmit}
                      disabled={isLoading}
                    />
                    <FileManager
                      source='dana-file'
                      onConfirm={handleConfirmDrive}
                      onCancel={handleCancelDrive}
                    />
                  </div>
                ) : <></>}
              </div>
            </div>

            <button
              type='button'
              className='profile-modal__close'
              onClick={handleClose}
              aria-label='close'
            >
              <img src={mode === 'light' ? closeIcon : closeIconWhite} alt='close' />
            </button>
          </div>

          <Divider className='divider-modals' sx={{ marginBottom: '16px' }} />

          {/* body */}
          <div
            className='chat-chatbox-file-upload-body'
            onDragOver={handleDragOver}
            onDrop={handleDrop}
          >
            {isLoading ? (
              <div className='chat-chatbox-file-upload-body__loading'>
                <CircularProgress />
              </div>
            ) : (
              <>
                {Object.values(files).length > 0 ? (
                  Object.values(files).map(file => (
                    <FileItem
                      key={file.fileId}
                      name={file.filename}
                      type={file.filetype}
                      size={parseFloat(file.filesize)}
                      progress={file.progress}
                      error={file.error}
                      onSelect={() => handleSelectUploadedFile(file)}
                      onDelete={() => handleDeleteUploadedFile(file.fileId)}
                    />
                  ))
                ) : (
                  <div className='chat-chatbox-file-upload-empty'>
                    <img className='chat-chatbox-file-upload-cloud-upload' src={cloudUpload} />
                    <div className='chat-chatbox-file-upload-empty-choose'>
                      {t('chat-file-upload-dropzone')}
                    </div>
                    <div className='chat-chatbox-file-upload-empty-format'>
                      {t('chat-file-upload-formats')}
                    </div>
                    <label
                      className={`chat-chatbox-file-upload-upload ${isLoading ? 'disabled' : ''}`}
                      htmlFor='chat-chatbox-file-upload-upload'
                    >
                      <p>{t('chat-collection-upload-file-modal-upload-btn-title')}</p>
                    </label>

                    <input
                      type='file'
                      multiple={allowMultipleAttachments}
                      id='chat-chatbox-file-upload-upload'
                      accept='.csv, .txt, .png, .jpg, .jpeg, .pdf, .parquet, .xls, .xlsx'
                      hidden
                      onChange={handleSubmit}
                      disabled={isLoading}
                    />
                    <div className='wrapper-chat-chatbox-file-manager'>
                      <FileManager
                        source='dana-file'
                        onConfirm={handleConfirmDrive}
                        onCancel={handleCancelDrive}
                      />
                    </div>
                  </div>
                )}
              </>
            )}

          </div>
          <div className='chat-chatbox-file-upload-footer'>
            <button onClick={handleClose} autoFocus className='chat-chatbox-file-upload-submit-btn'>
              {t('chat-collection-upload-file-modal-confirm-btn-title')}
            </button>
            <button onClick={handleClose} autoFocus className='chat-chatbox-file-upload-cancel-btn'>
              {t('chat-collection-upload-file-modal-confirm-btn-cancel')}
            </button>
          </div>
        </DialogContent>
      </Dialog>
    </Fragment>
  )
}

export default ChatFileUpload
