import './style.scss'

import { Fragment, useEffect, useState } from 'react'
import Dialog from '@mui/material/Dialog'
import DialogContent from '@mui/material/DialogContent'
import closeIcon from 'src/assets/closeIcon.svg'
import closeIconWhite from 'src/assets/closeIconWhite.svg'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import { selectCurrentCollection, selectModalsState, setModalsState, updateCollectionPrompt } from 'src/pages/Chat/slice'
import { Divider } from '@mui/material'
import { t } from 'i18next'
import { RootState } from 'src/lib/store'
import chatAPIs from 'src/api/chat'
import { ISettingsPrompt } from 'src/types/NewChat/api'
import { addAToast } from 'src/lib/context'

const ChatInstructions = () => {
  const dispatch = useBDMDispatch()
  const isOpen = useBDMSelector(selectModalsState).openInstruction
  const currenetCollection = useBDMSelector(selectCurrentCollection)
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const [name, setName] = useState('')
  const [prompt, setPrompt] = useState('');
  const [savedPrompts, setSavedPrompts] = useState<ISettingsPrompt[]>([])
  const [isLoadingPrompts, setIsLoadingPrompts] = useState(false)
  const [selectedPromptId, setSelectedPromptId] = useState('')
  const [isDeletingPrompt, setIsDeletingPrompt] = useState(false)
  const [isUpdatingPrompt, setIsUpdatingPrompt] = useState(false)
  useEffect(() => {
    setName(currenetCollection?.collectionName ?? '')
    setPrompt(currenetCollection?.prompt ?? '');
  }, [currenetCollection?.collectionName, currenetCollection?.prompt]);

  useEffect(() => {
    if (!isOpen) return

    let isMounted = true
    const getPrompts = async () => {
      setIsLoadingPrompts(true)
      try {
        const response = await chatAPIs().getSettingsPrompts()
        const data = response.data?.data
        const prompts = Array.isArray(data) ? data : data?.prompts
        if (isMounted && response.data?.success) {
          setSavedPrompts(prompts ?? [])
        }
      } finally {
        if (isMounted) setIsLoadingPrompts(false)
      }
    }

    getPrompts()
    return () => { isMounted = false }
  }, [isOpen])

  const disableSubmit = !name.trim() || !prompt.trim();

  const handleClose = () => {
    dispatch(setModalsState({ openInstruction: false }))
    setName('')
    setPrompt('')
    setSelectedPromptId('')
  }

  const handleSubmitData = () => {
    dispatch(updateCollectionPrompt({ name: name.trim(), prompt: prompt.trim() }))
    handleClose()
  }

  const handleDeletePrompt = async () => {
    if (!selectedPromptId || isDeletingPrompt) return

    setIsDeletingPrompt(true)
    try {
      const response = await chatAPIs().deleteSettingsPrompt(selectedPromptId)
      if (!response.data?.success) {
        throw new Error(response.data?.message || 'حذف پرامپت ناموفق بود.')
      }

      setSavedPrompts(previousPrompts => previousPrompts.filter(item => item.promptId !== selectedPromptId))
      setSelectedPromptId('')
      addAToast(response.data.message || 'پرامپت با موفقیت حذف شد.', 'success')
    } catch (error) {
      const message = error instanceof Error ? error.message : 'حذف پرامپت ناموفق بود.'
      addAToast(message, 'error')
    } finally {
      setIsDeletingPrompt(false)
    }
  }

  const handleUpdatePrompt = async () => {
    if (!selectedPromptId || !name.trim() || !prompt.trim() || isUpdatingPrompt) return

    setIsUpdatingPrompt(true)
    try {
      const response = await chatAPIs().updateSettingsPrompt(selectedPromptId, {
        name: name.trim(),
        prompt: prompt.trim(),
      })
      if (!response.data?.success) {
        throw new Error(response.data?.message || 'ویرایش پرامپت ناموفق بود.')
      }

      setSavedPrompts(previousPrompts => previousPrompts.map(item => (
        item.promptId === selectedPromptId ? { ...item, prompt: prompt.trim() } : item
      )))
      addAToast(response.data.message || 'پرامپت با موفقیت ویرایش شد.', 'success')
    } catch (error) {
      const message = error instanceof Error ? error.message : 'ویرایش پرامپت ناموفق بود.'
      addAToast(message, 'error')
    } finally {
      setIsUpdatingPrompt(false)
    }
  }

  return (
    <Fragment>
      {/* Dialog */}
      <Dialog PaperProps={{
        sx: {
          borderRadius: '16px',
        },
      }} open={isOpen} onClose={handleClose} maxWidth='md' tabIndex={1}>
        <DialogContent sx={{ width: '724px' }} className="chat-chatbox-instruction-dialog">
          {/* header */}
          <div className='chat-chatbox-instruction-header'>
            <div className='chat-chatbox-instruction-title-box'>
              <p className='chat-chatbox-instruction-title-text'>{t('chat-instructions-title')}</p>
            </div>
            <button
              type='button'
              className='profile-modal__close'
              onClick={handleClose}
              aria-label='close'
            >
              <img src={mode === 'light' ? closeIcon : closeIconWhite} alt='close' />
            </button>
          </div>
          <Divider className='divider-modals' sx={{ marginBottom: '16px' }} />
          {/* body */}
          <div className='chat-chatbox-instruction-body'>
            <label className='chat-chatbox-instruction-label' htmlFor='saved-settings-prompts'>پرامپت‌های ذخیره‌شده</label>
            <div className='chat-chatbox-instruction-saved-prompts'>
              <select
                id='saved-settings-prompts'
                className='chat-chatbox-instruction-name-input'
                value={selectedPromptId}
                disabled={isLoadingPrompts}
                onChange={event => {
                  const selectedPrompt = savedPrompts.find(item => item.promptId === event.target.value)
                  setSelectedPromptId(event.target.value)
                  if (selectedPrompt) setPrompt(selectedPrompt.prompt)
                }}
              >
                <option value=''>{isLoadingPrompts ? 'در حال دریافت پرامپت‌ها...' : 'یک پرامپت را انتخاب کنید'}</option>
                {savedPrompts.map(savedPrompt => (
                  <option key={savedPrompt.promptId} value={savedPrompt.promptId}>
                    {savedPrompt.prompt.length > 70 ? `${savedPrompt.prompt.slice(0, 70)}…` : savedPrompt.prompt}
                  </option>
                ))}
              </select>
              <button
                className='chat-chatbox-instruction-delete-btn'
                type='button'
                disabled={!selectedPromptId || isDeletingPrompt}
                onClick={handleDeletePrompt}
              >
                {isDeletingPrompt ? 'در حال حذف...' : 'حذف'}
              </button>
            </div>
            <label className='chat-chatbox-instruction-label' htmlFor='settings-prompt-name'>نام پرامپت</label>
            <input
              id='settings-prompt-name'
              className='chat-chatbox-instruction-name-input'
              value={name}
              onChange={e => setName(e.target.value)}
              placeholder='نام پرامپت را وارد کنید'
              maxLength={120}
            />
            <label className='chat-chatbox-instruction-label' htmlFor='settings-prompt-text'>متن پرامپت</label>
            <textarea
              id='settings-prompt-text'
              placeholder={t('chat-instructions-placeholder')}
              dir='auto'
              className='chat-chatbox-instruction-input'
              tabIndex={1}
              value={prompt}
              onChange={e => setPrompt(e.target.value)}
            ></textarea>
          </div>

          {/* footer */}
          <div className='chat-chatbox-instruction-footer'>
            <button tabIndex={1}
              disabled={disableSubmit} onClick={handleSubmitData} autoFocus className='chat-chatbox-instruction-submit-btn'>
              {t('chat-collection-upload-file-modal-confirm-btn-title')}
            </button>
            <button
              type='button'
              disabled={!selectedPromptId || disableSubmit || isUpdatingPrompt}
              onClick={handleUpdatePrompt}
              className='chat-chatbox-instruction-update-btn'
            >
              {isUpdatingPrompt ? 'در حال ویرایش...' : 'ویرایش پرامپت'}
            </button>
            <button onClick={handleClose} autoFocus className='chat-chatbox-instruction-cancel-btn'>
              {t('chat-collection-upload-file-modal-confirm-btn-cancel')}
            </button>
          </div>
        </DialogContent>
      </Dialog>
    </Fragment>
  )
}

export default ChatInstructions
