import { TIME_DIVISIONS } from 'src/lib/constants'

const formatter = new Intl.RelativeTimeFormat('fa-IR', {
  numeric: 'auto',
})

export default (date: string) => {
  let duration = (new Date(date).valueOf() - new Date().valueOf()) / 1000

  for (let i = 0; i < TIME_DIVISIONS.length; i++) {
    const division = TIME_DIVISIONS[i]
    if (Math.abs(duration) < division.amount) {
      return formatter.format(Math.round(duration), division.name as any)
    }
    duration /= division.amount
  }
}
