// style
import './style.scss'

import { sizeFormatter } from 'src/lib/utils'
import LinearProgress, { linearProgressClasses } from '@mui/material/LinearProgress'
import { IUploadItem } from 'src/types/FileManagement'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import {
  selectDriveAction,
  selectDriveSelectedFiles,
  selectFile,
} from 'src/lib/slice/fileManagement/fileSlice'

export const FILE_TYPES: Record<string, string> = {
  'text/csv': 'csv',
  'text/plain': 'text',
  'application/vnd.apache.parquet': 'parquet',
  'application/x-parquet': 'parquet',
}

const FileItem = ({ name, type, progress, size, status, serverId }: IUploadItem) => {
  const dispatch = useBDMDispatch()
  const action = useBDMSelector(selectDriveAction)
  const selectedFiles = useBDMSelector(selectDriveSelectedFiles)

  const isSelected = selectedFiles.some(item => item.id === serverId)
  const selectable = action === 'download'
  const fileType = name.toLowerCase().endsWith('.parquet') ? 'parquet' : FILE_TYPES[type] ?? 'unknown'

  const onSelectFile = () => {
    if (!selectable || !serverId) {
      return
    }

    dispatch(selectFile({ folderId: '', id: serverId, name, type }))
  }

  return (
    // TODO:handle hover and selected state
    <div
      className={`file-manager-file-item ${isSelected ? 'selected' : ''} ${selectable ? 'selectable' : ''
        } ${status}`}
      onClick={onSelectFile}
    >
      <div className={`file-manager-file-icon ${fileType}  ${status}`}></div>
      <p className='file-manager-file-name'>
        <span className='file-manager-file-name__size'>&nbsp;({sizeFormatter(size)}) </span>
        <span className='file-manager-file-name__name'>{name}&nbsp;</span>
      </p>
      <span className={`file-manager-file-close ${status}`}></span>
      {status === 'uploading' && (
        <div className='file-manager-file-porgress'>
          <LinearProgress
            variant='determinate'
            value={progress}
            dir='rtl'
            sx={{
              borderRadius: '0 0 4px 4px',
              [`&.${linearProgressClasses.colorPrimary}`]: {
                backgroundColor: 'transparent',
              },
              [`& .${linearProgressClasses.bar}`]: {
                borderRadius: 5,
                backgroundColor: '#B0D0FF',
              },
            }}
          />
        </div>
      )}
    </div>
  )
}

export default FileItem
