import './style.scss'

import { t } from 'i18next'
import { ChangeEvent, ReactNode, useMemo, useState } from 'react'
import { Trans } from 'react-i18next'
import useTabs from 'src/lib/hooks/useTabs'
import { useBDMSelector, useBDMDispatch } from 'src/lib/store/hooks'
import {
  closeDrive,
  openDrive,
  selectDriveIsOpen,
  selectDriveIsSubmittable,
} from 'src/lib/slice/fileManagement/fileSlice'
import { FileSource } from 'src/types/FileManagement'

import closeIcon from 'src/assets/closeIcon.svg'
import attachIcon from 'src/assets/attachIcon.svg'
import searchIcon from 'src/assets/searchIconSecondry.svg'

import Tab from '@mui/material/Tab'
import Tabs from '@mui/material/Tabs'
import Modal from '@mui/material/Modal'

import TabPanel from './components/TabPanel'
import Button from 'src/components/Button'

import DrivePanel from './MyDrive'
import UploadPanel from './Upload'
import RecentsPanel from './Recents'

import useCheckSubmittable from './hooks/useSubmittable'

interface IProps {
  source: FileSource
  onConfirm?: () => void
  onCancel?: () => void
  trigger?: ReactNode
}

const FileManager = ({ source, onCancel, onConfirm, trigger }: IProps) => {
  const dispatch = useBDMDispatch()

  const isOpen = useBDMSelector(selectDriveIsOpen)
  const isSubmittable = useBDMSelector(selectDriveIsSubmittable)

  const [search, setSearch] = useState('')

  const panels = useMemo(
    () => [
      {
        id: 1,
        title: t<string>('file-manager-recents-tab-title'),
        body: <RecentsPanel search={search} />,
        active: true,
      },
      {
        id: 0,
        title: t<string>('file-manager-drive-tab-title'),
        body: <DrivePanel search={search} />,
        active: true,
      },
      {
        id: 2,
        title: t<string>('file-manager-upload-tab-title'),
        body: <UploadPanel />,
        active: true,
      },
    ],
    [search],
  )

  const { handleTabChange, selectedTab, tabs } = useTabs(panels)

  useCheckSubmittable()

  /**
   * Handle search input
   */
  const handleSearch = (event: ChangeEvent<HTMLInputElement>) => {
    setSearch(event.target.value)
  }

  /**
   * File manager actions
   */
  const actions = useMemo(
    () => ({
      handleOpen() {
        setSearch('')
        dispatch(openDrive({ source }))
      },

      handleClose() {
        setSearch('')
        onCancel?.()
        dispatch(closeDrive())
      },

      handleConfirm() {
        setSearch('')
        onConfirm?.()
        dispatch(closeDrive())
      },
    }),
    [dispatch, source, onCancel, onConfirm],
  )

  /**
   * Render active tab panels
   */
  const renderedTabPanels = useMemo(
    () =>
      tabs
        .filter(tab => tab.active)
        .map(tab => (
          <TabPanel key={tab.id} value={selectedTab} index={tab.id}>
            {tab.body}
          </TabPanel>
        )),
    [tabs, selectedTab],
  )

  /**
   * Render active tabs
   */
  const renderedTabs = useMemo(
    () =>
      tabs
        .filter(tab => tab.active)
        .map(tab => (
          <Tab
            disableRipple
            key={tab.id}
            label={tab.title}
            className='file-manager__tabs__list__item'
          />
        )),
    [tabs],
  )

  return (
    <>
      {trigger ? (
        <div onClick={actions.handleOpen}>{trigger}</div>
      ) : (
        <div className='file-manager__actions__open-btn' onClick={actions.handleOpen} tabIndex={1}>
          {t('file-manager-select')}
        </div>
      )}

      <Modal open={isOpen} onClose={actions.handleClose} disableAutoFocus>
        <div className='file-manager'>
          <div className='file-manager__wrapper'>
            {/* Header */}
            <div className='file-manager__header'>
              <div className='file-manager__wrapper__box'>
                {/* Close */}
                <button
                  type='button'
                  className='file-manager__wrapper__box__close'
                  onClick={actions.handleClose}
                  aria-label={t('close')}
                >
                  <img src={closeIcon} alt={t('close')} />
                </button>

                {/* Search */}
                <label className='file-manager__wrapper__box__search'>
                  <span aria-hidden='true'>
                    <img src={searchIcon} alt='' />
                  </span>

                  <input
                    type='search'
                    value={search}
                    onChange={handleSearch}
                    placeholder={t('file-manager-search-placeholder')}
                    aria-label={t('file-manager-search-label')}
                  />
                </label>
              </div>

              {/* Title */}
              <div className='file-manager__title'>
                {t('file-manager-select-title')}
                <img src={attachIcon} alt='' />
              </div>
            </div>

            {/* Body */}
            <div className='file-manager__body'>
              {/* Tabs */}
              <div className='file-manager__tabs'>
                <Tabs
                  value={selectedTab}
                  className='file-manager__tabs__list'
                  onChange={handleTabChange}
                >
                  {renderedTabs}
                </Tabs>
              </div>

              {/* Tab content */}
              <div className='file-manager__tabpanel'>{renderedTabPanels}</div>

              {/* Actions */}
              <div className='file-manager__actions'>
                <Button
                  className='file-manager__actions__btn'
                  onClick={actions.handleConfirm}
                  disabled={!isSubmittable}
                >
                  <Trans i18nKey={t('file-manager-confirm-btn-title')} />
                </Button>

                <Button
                  className='file-manager__actions__btn file-manager__actions__btn--cancel'
                  onClick={actions.handleClose}
                >
                  <Trans i18nKey={t('file-manager-cancel-btn-title')} />
                </Button>
              </div>
            </div>
          </div>
        </div>
      </Modal>
    </>
  )
}

export default FileManager
