interface IProps {
  file: IFileItem
}

const FileCard = ({ file: { id, name, folderId, type } }: IProps) => {
  console.log(type, 'typeeeeeeeeeeeeeeeeeeee')

  const dispatch = useBDMDispatch()

  const action = useBDMSelector(selectDriveAction)
  const selectedFiles = useBDMSelector(selectDriveSelectedFiles)

  const selectable = action === 'download'
  const fileType = name.toLowerCase().endsWith('.parquet') ? 'parquet' : FILE_TYPES[type] ?? 'unknown'
  const isSelected = selectedFiles.find(file => file.id === id)

  const onClick = () => {
    if (selectable) {
      dispatch(selectFile({ id, folderId, name, type }))
    }
  }

  return (
    <div
      className={`file-manager-file-card ${selectable ? 'selectable' : ''} ${
        isSelected ? 'selected' : ''
      } `}
      onClick={onClick}
    >
      {/* haeder */}
      <div className='file-manager-file-card__title'>{name}</div>
      {/* icon */}
      <div className={'file-manager-file-card__icon ' + fileType}></div>
    </div>
  )
}

export default FileCard
