import { useMemo, useState } from 'react'

import './style.scss'
import { copyTextToClipboard } from './clipboard'
import { sanitizeEntities } from './sanitize'

export interface INerEntity {
  word: string
  entity_group: string
  score: number
}

interface INerResult {
  entities: INerEntity[]
}

const ENTITY_LABELS: Record<string, string> = {
  person: 'شخص',
  location: 'مکان',
  organization: 'سازمان',
  date: 'تاریخ',
  time: 'زمان',
  money: 'مبلغ',
  percent: 'درصد',
  product: 'محصول',
  event: 'رویداد',
  nationality: 'ملیت',
  misc: 'سایر',
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

const normalizeEntity = (value: unknown): INerEntity | null => {
  if (!isRecord(value)) return null

  const word = typeof value.word === 'string' ? value.word.trim() : ''
  const entityGroup =
    typeof value.entity_group === 'string'
      ? value.entity_group.trim()
      : typeof value.entityGroup === 'string'
      ? value.entityGroup.trim()
      : ''
  const score = typeof value.score === 'number' ? value.score : Number(value.score)

  if (!word || !entityGroup || !Number.isFinite(score)) return null

  return {
    word,
    entity_group: entityGroup.toLowerCase(),
    score: Math.min(1, Math.max(0, score)),
  }
}

const stripJsonFence = (value: string) => {
  const trimmed = value.trim().replace(/^\uFEFF/, '')
  const fence = String.fromCharCode(96).repeat(3)
  const withoutFence =
    trimmed.startsWith(fence) && trimmed.endsWith(fence) ? trimmed.slice(3, -3).trim() : trimmed

  return withoutFence.replace(/^json\s*/i, '')
}

/** Parses only the known NER response shape, so ordinary JSON answers stay unchanged. */
export const parseNerResult = (message: string): INerResult | null => {
  try {
    const payload: unknown = JSON.parse(stripJsonFence(message))
    if (!isRecord(payload)) return null

    const outputs = Array.isArray(payload.outputs) ? payload.outputs : null
    if (!outputs) return null

    let hasEntityCollection = false
    const entities = outputs.flatMap(output => {
      if (!isRecord(output) || !Array.isArray(output.entities)) return []
      hasEntityCollection = true
      return output.entities
        .map(normalizeEntity)
        .filter((item): item is INerEntity => item !== null)
    })

    return hasEntityCollection ? { entities: sanitizeEntities(entities) } : null
  } catch {
    return null
  }
}

const getEntityKind = (entityGroup: string) =>
  Object.prototype.hasOwnProperty.call(ENTITY_LABELS, entityGroup) ? entityGroup : 'misc'

const getEntityLabel = (entityGroup: string) =>
  ENTITY_LABELS[entityGroup] ?? entityGroup.replace(/_/g, ' ')

const formatPercent = (score: number) =>
  new Intl.NumberFormat('fa-IR', { style: 'percent', maximumFractionDigits: 0 }).format(score)

const NerEntitiesTable = ({ entities }: { entities: INerEntity[] }) => {
  const [copied, setCopied] = useState(false)
  const count = useMemo(
    () => new Intl.NumberFormat('fa-IR').format(entities.length),
    [entities.length],
  )

  const handleCopy = async () => {
    const header = ['موجودیت', 'نوع', 'اطمینان'].join('\t')
    const rows = entities.map(entity =>
      [entity.word, getEntityLabel(entity.entity_group), formatPercent(entity.score)].join('\t'),
    )
    const content = [header, ...rows].join('\n')

    const succeeded = await copyTextToClipboard(content)
    if (succeeded) {
      setCopied(true)
      window.setTimeout(() => setCopied(false), 1200)
    }
  }

  return (
    <section className='ner-result' aria-label='موجودیت‌های نامدار شناسایی‌شده'>
      <div className='ner-result__header'>
        <div>
          <h3 className='ner-result__title'>موجودیت‌های شناسایی‌شده</h3>
          <span className='ner-result__count'>{count} مورد</span>
        </div>
        {entities.length > 0 && (
          <button className='ner-result__copy' type='button' onClick={handleCopy}>
            {copied ? 'کپی شد' : 'کپی جدول'}
          </button>
        )}
      </div>

      {entities.length === 0 ? (
        <div className='ner-result__empty'>موجودیتی در متن پیدا نشد.</div>
      ) : (
        <div className='ner-result__table-scroll'>
          <table className='ner-result__table'>
            <thead>
              <tr>
                <th className='ner-result__index' scope='col'>
                  #
                </th>
                <th scope='col'>موجودیت</th>
                <th scope='col'>نوع</th>
                <th scope='col'>میزان اطمینان</th>
              </tr>
            </thead>
            <tbody>
              {entities.map((entity, index) => {
                const percent = formatPercent(entity.score)
                const kind = getEntityKind(entity.entity_group)

                return (
                  <tr key={entity.word + '-' + entity.entity_group + '-' + index}>
                    <td className='ner-result__index'>
                      {new Intl.NumberFormat('fa-IR').format(index + 1)}
                    </td>
                    <td className='ner-result__word'>{entity.word}</td>
                    <td>
                      <span className={'ner-result__badge ner-result__badge--' + kind}>
                        {getEntityLabel(entity.entity_group)}
                      </span>
                    </td>
                    <td>
                      <div className='ner-result__confidence' aria-label={'اطمینان ' + percent}>
                        <span>{percent}</span>
                        <span className='ner-result__confidence-track' aria-hidden='true'>
                          <span style={{ width: entity.score * 100 + '%' }} />
                        </span>
                      </div>
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
      )}
    </section>
  )
}

export default NerEntitiesTable
