import './style.scss'

import Menu from '@mui/material/Menu'
import collectionCloseCardIcon from 'src/assets/collectionCloseCardIcon.svg'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import {
  selectCollectionList,
  selectLoadingState,
  transferHistoryToCollection,
} from 'src/pages/Chat/slice'
import { useState } from 'react'
import { t } from 'i18next'

interface IProps {
  menuAnchorEl: HTMLElement | null
  menuIds: { collectionId?: string; historyId?: string }
  onClose: () => void
  onTransferred?: () => void
}

const TransferProject = ({
  menuAnchorEl,
  menuIds: { historyId, collectionId },
  onClose,
  onTransferred,
}: IProps) => {
  const dispatch = useBDMDispatch()
  const collectionList = useBDMSelector(selectCollectionList)
  const loadingState = useBDMSelector(selectLoadingState)
  const [transferringCollectionId, setTransferringCollectionId] = useState<string | null>(null)

  const handleTransfer = async (targetCollectionId: string) => {
    if (
      !historyId ||
      (targetCollectionId && targetCollectionId === collectionId) ||
      transferringCollectionId !== null
    ) {
      return
    }

    setTransferringCollectionId(targetCollectionId)
    const result = await dispatch(
      transferHistoryToCollection({
        historyId,
        sourceCollectionId: collectionId ?? '',
        targetCollectionId,
      }),
    )
    setTransferringCollectionId(null)

    if (transferHistoryToCollection.fulfilled.match(result)) {
      onClose()
      onTransferred?.()
    }
  }

  return (
    <Menu
      anchorEl={menuAnchorEl}
      open={Boolean(menuAnchorEl)}
      onClose={onClose}
      anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
      transformOrigin={{ vertical: 'top', horizontal: 'right' }}
      PaperProps={{
        sx: {
          transform: 'translateX(-15px) !important',
        },
      }}
      className='chat-transfer-project-toggle-wrapper'
    >
      <div className='chat-transfer-project-toggle'>
        {loadingState.collections && (
          <div className='chat-transfer-project-toggle__empty'>در حال دریافت پروژه‌ها...</div>
        )}
        {!loadingState.collections && collectionList.length === 0 && (
          <div className='chat-transfer-project-toggle__empty'>پروژه‌ای وجود ندارد</div>
        )}
        {!loadingState.collections &&
          collectionList.map(collection => (
            <button
              type='button'
              key={collection.collectionId}
              className='chat-transfer-project-toggle__item'
              onClick={() => handleTransfer(collection.collectionId)}
              disabled={
                collection.collectionId === collectionId || Boolean(transferringCollectionId)
              }
            >
              <img
                src={collectionCloseCardIcon}
                className='chat-transfer-project-toggle__item-icon'
              />
              <span>
                {transferringCollectionId === collection.collectionId
                  ? t('chat-transferring')
                  : collection.collectionName}
              </span>
            </button>
          ))}
      </div>
    </Menu>
  )
}

export default TransferProject
