import { useRef, useEffect } from 'react'
import { useSearchParams } from 'react-router-dom'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'

import {
  selectChatStateParams,
  selectAppInitalized,
  selectCollections,
  selectHistories,
  selectCLHistories,
  setChatStateFromParams,
  setCurrentCollection,
  setCurrentHistory,
} from 'src/pages/Chat/slice'

export const useChatState = () => {
  const dispatch = useBDMDispatch()
  const hasParamsSet = useRef(false)

  const chatStateParams = useBDMSelector(selectChatStateParams)
  const appInitialized = useBDMSelector(selectAppInitalized)
  const collections = useBDMSelector(selectCollections)
  const histories = useBDMSelector(selectHistories)
  const CLHistories = useBDMSelector(selectCLHistories)

  const [searchParams, setSearchParams] = useSearchParams()
  const historyId = searchParams.get('historyId') || undefined
  const collectionId = searchParams.get('collectionId') || undefined

  const onSetParams = ({
    historyId,
    collectionId,
  }: {
    historyId?: string
    collectionId?: string
  }) => {
    const params = new URLSearchParams(searchParams)

    historyId ? params.set('historyId', historyId) : params.delete('historyId')
    collectionId ? params.set('collectionId', collectionId) : params.delete('collectionId')

    setSearchParams(params)
  }

  // Sync store → URL
  useEffect(() => {
    if (!hasParamsSet.current || chatStateParams.isParamsSynced) {
      return
    }

    onSetParams({
      historyId: chatStateParams.historyId,
      collectionId: chatStateParams.collectionId,
    })

    dispatch(
      setChatStateFromParams({
        historyId: chatStateParams.historyId,
        collectionId: chatStateParams.collectionId,
        isParamsSynced: true,
      }),
    )
  }, [
    chatStateParams.collectionId,
    chatStateParams.historyId,
    chatStateParams.isParamsSynced,
  ])

  // update store, on first render
  useEffect(() => {
    if (hasParamsSet.current || !appInitialized) {
      return
    }

    const resetState = () => {
      onSetParams({ historyId: undefined, collectionId: undefined })
      dispatch(
        setChatStateFromParams({
          historyId: undefined,
          collectionId: undefined,
          isParamsSynced: true,
        }),
      )
    }

    const setValidState = () => {
      dispatch(
        setChatStateFromParams({
          historyId,
          collectionId,
          isParamsSynced: true,
        }),
      )
    }

    if (collectionId && !historyId) {
      const foundCollection = collections[collectionId]

      if (foundCollection) {
        dispatch(setCurrentCollection(collectionId))
        setValidState()
      } else {
        resetState()
      }
    } else if (historyId) {
      const foundHistory = collectionId ? histories[historyId] : CLHistories[historyId]
      const foundCollection = collectionId ? collections[collectionId] : null

      const isValid = foundHistory && (!collectionId || !!foundCollection)

      if (isValid) {
        dispatch(
          setCurrentHistory({
            historyId,
            collectionId: collectionId ?? null,
          }),
        )
        setValidState()
      } else {
        resetState()
      }
    }

    setValidState()

    hasParamsSet.current = true
  }, [historyId, collectionId, appInitialized, collections, histories, CLHistories])

  return {
    historyId,
    collectionId,
    onSetParams,
  }
}

export default useChatState
