import { configureStore, combineReducers } from '@reduxjs/toolkit'

// persist
import storage from 'redux-persist-indexeddb-storage'
import { PERSIST_PREFIX } from 'src/lib/constants'
import { persistReducer, persistStore } from 'redux-persist'

// reducers
import chatReducer from 'src/pages/Chat/slice/oldVersion'
import newChatReducer from 'src/pages/Chat/slice/slice'
import fileReducer from 'src/lib/slice/fileManagement/fileSlice'

import themeReducer from 'src/features/theme/themeSlice'


const persistConfig = {
  key: 'root',
  storage: storage('BDM'),
  version: 1,
  serialize: false,
  deserialize: false,
  whitelist: [],
  keyPrefix: PERSIST_PREFIX,
}

const rootReducer = combineReducers({
  chatFL: chatReducer,
  newChat: newChatReducer,
  file: fileReducer,
  theme: themeReducer,
})

const persistedReducer = persistReducer(persistConfig, rootReducer)

export const store = configureStore({
  reducer: persistedReducer,
  middleware: getDefaultMiddleware =>
    getDefaultMiddleware({
      serializableCheck: false,
    }).concat(),

  devTools: process.env.NODE_ENV !== 'production',
})

export const persistor = persistStore(store)

export type RootState = ReturnType<typeof store.getState>
export type AppDispatch = typeof store.dispatch
