const FAILED_MESSAGE_STORAGE_PREFIX = 'chat-failed-message:'

// A message whose send failed is kept in localStorage so it survives a refresh.
const saveFailedMessage = (draftKey: string, text: string) => {
  try {
    localStorage.setItem(FAILED_MESSAGE_STORAGE_PREFIX + draftKey, text)
  } catch {
    // storage unavailable: the in-memory draft still works
  }
}

const loadFailedMessage = (draftKey: string) => {
  try {
    return localStorage.getItem(FAILED_MESSAGE_STORAGE_PREFIX + draftKey) ?? ''
  } catch {
    return ''
  }
}

const clearFailedMessage = (draftKey: string) => {
  try {
    localStorage.removeItem(FAILED_MESSAGE_STORAGE_PREFIX + draftKey)
  } catch {
    // ignore
  }
}

