const MAX_FILES_PER_MESSAGE = 10
const MAX_CHAT_FILE_SIZE = 100_000_000
const EXCEL_FILE_EXTENSIONS = ['xls', 'xlsx']
const ALLOWED_CHAT_FILE_EXTENSIONS = [
  'pdf',
  'png',
  'jpg',
  'jpeg',
  'txt',
  'csv',
  'parquet',
  ...EXCEL_FILE_EXTENSIONS,
]
const OCR_FILE_EXTENSIONS = ['pdf', 'png', 'jpg', 'jpeg']
const STT_FILE_EXTENSIONS = ['mp3', 'wav', 'ogg', 'm4a', 'webm', 'flac']
const EXCEL_TRANSITION_DELAY = 2000
// const LETTER_WRITER_SUGGESTIONS = ['تشکرنامه', 'اعتراض رسمی', 'نامه معرفی', 'درخواست مرخصی']
const LETTER_WRITER_MODES = ['ایجاد نامه', 'کنترل کیفی', 'پاسخ به نامه'] as const
const LETTER_WRITER_OPERATION_VALUES: Record<
  typeof LETTER_WRITER_MODES[number],
  NonNullable<IAIChatAssistantDTI['letterOperation']>
> = {
  'ایجاد نامه': 'create',
  'کنترل کیفی': 'quality_control',
  'پاسخ به نامه': 'reply',
}

const wait = (delay: number) => new Promise(resolve => setTimeout(resolve, delay))

const getFileExtension = (fileName: string) => fileName.split('.').pop()?.toUpperCase() || 'FILE'

const getSelectedFileIcon = (fileName: string, mimeType = '') => {
  const extension = fileName.split('.').pop()?.toLowerCase()

  if (extension === 'csv' || mimeType === 'text/csv') return csvFileIcon
  if (['xls', 'xlsx'].includes(extension ?? '')) return excelFileIcon
  if (
    extension === 'parquet' ||
    ['application/vnd.apache.parquet', 'application/x-parquet'].includes(mimeType)
  ) {
    return parquetFileIcon
  }
  if (extension === 'pdf' || mimeType === 'application/pdf') return pdfFileIcon
  if (
    ['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg'].includes(extension ?? '') ||
    mimeType.startsWith('image/')
  ) {
    return imageFileIcon
  }
  if (['txt', 'md', 'markdown', 'json'].includes(extension ?? '') || mimeType === 'text/plain') {
    return textFileIcon
  }

  return unknownFileIcon
}

const formatAttachmentSize = (size?: number) => {
  if (!size) {
    return ''
  }

  return size < 1_000_000 ? `${Math.ceil(size / 1_000)} KB` : `${(size / 1_000_000).toFixed(1)} MB`
}

const ChatInput = ({ className }: IProps) => {
  const currenetHistory = useBDMSelector(selectCurrentHistory)
  const historyAttachments = useBDMSelector(selectHistoryAttachments)
  const historyMessages = useBDMSelector(selectMessages)
  const currentCollection = useBDMSelector(selectCurrentCollection)
  const collectionId = useBDMSelector(selectCurrentCollection)?.collectionId
  const loadingState = useBDMSelector(selectLoadingState)
  const modalsState = useBDMSelector(selectModalsState)
  const quickActionRequest = useBDMSelector(selectQuickActionRequest)
  const [text, setText] = useState('')
  const [drafts, setDrafts] = useState<Record<string, string>>({})
  const spanRef = useRef<HTMLSpanElement>(null)
  const textAreaRef = useRef<HTMLTextAreaElement>(null)
  const generalFileInputRef = useRef<HTMLInputElement>(null)
  const submitGuardRef = useRef(createChatSubmitGuard())
  const lastDraftKeyRef = useRef<string>('')
  const sessionIdsRef = useRef<Record<string, string>>({})
  const [isQuickActionsOpen, setIsQuickActionsOpen] = useState(false)
  const [isSummarySourceOpen, setIsSummarySourceOpen] = useState(false)
  const [isTranslationLangOpen, setIsTranslationLangOpen] = useState(false)
  const [isTranslationSourceOpen, setIsTranslationSourceOpen] = useState(false)
  const [selectedAction, setSelectedAction] = useState<TQuickAction | null>(null)
  const [fileConversationContexts, setFileConversationContexts] = useState<
    Record<string, boolean>
  >({})
  const [selectedSecondarySource, setSelectedSecondarySource] =
    useState<ISecondarySourceItem | null>(null)
  const [selectedTranslationLanguage, setSelectedTranslationLanguage] =
    useState<ITranslationLanguageItem | null>(null)
  const [pendingFiles, setPendingFiles] = useState<File[]>([])
  const [isSending, setIsSending] = useState(false)
  const [isExcelTransitioning, setIsExcelTransitioning] = useState(false)
  const [isLetterModelOpen, setIsLetterModelOpen] = useState(false)
  const [selectedLetterMode, setSelectedLetterMode] = useState<
    typeof LETTER_WRITER_MODES[number] | null
  >(null)
  const dispatch = useBDMDispatch()
  const navigate = useNavigate()

  const draftKey =
    currenetHistory?.historyId ??
    (currentCollection?.collectionId
      ? `collection:${currentCollection.collectionId}`
      : 'no-session')

  const selectionMode = selectedAction ? SERVICE_SELECTION_MODES[selectedAction] : undefined
  const hasFileAttachment = historyAttachments.length > 0 || pendingFiles.length > 0
  const trackedFileContext = fileConversationContexts[draftKey]
  // `files` is the persisted, session-level source of truth after a reload;
  // the local map bridges the time between a successful upload and the next
  // history refresh.
  const hasRagContext =
    Boolean(trackedFileContext) ||
    Boolean(currenetHistory?.files?.length) ||
    currenetHistory?.selectionMode === 'rag'
  const payloadSelectionMode = resolveSelectionMode({
    selectedMode: selectionMode,
    hasCurrentFileSelection: hasFileAttachment,
    hasRagContext,
  })
  const isFileChatMode = payloadSelectionMode === 'rag'
  const canSelectMultipleFiles = supportsMultipleFileSelection(payloadSelectionMode)
  const hasSelectedSourceFile =
    Boolean(selectedSecondarySource) &&
    selectedSecondarySource?.key !== 'manual' &&
    selectedSecondarySource?.key !== 'translation-manual'
  // Non-file actions use exactly one source. This includes a project file,
  // an attached file, and a file picked directly from the device.
  const hasSelectedFile =
    hasSelectedSourceFile || historyAttachments.length > 0 || pendingFiles.length > 0
  const hasServiceSource =
    hasFileAttachment || Boolean(selectedSecondarySource)
  const canSubmitServiceWithoutText =
    Boolean(selectionMode && hasServiceSource) &&
    (selectedAction !== 'translation' || Boolean(selectedTranslationLanguage))

  const disableSubmit =
    (!text.trim() &&
      historyAttachments.length === 0 &&
      pendingFiles.length === 0 &&
      !canSubmitServiceWithoutText &&
      !(selectedAction === 'excelYar' && selectedSecondarySource)) ||
    (!text.trim() &&
      hasFileAttachment &&
      (!selectedAction || selectedAction === 'selectFile')) ||
    isSending ||
    loadingState.chatResponse ||
    loadingState.chatStreaming ||
    loadingState.messages ||
    (selectedAction === 'letterWriter' && !selectedLetterMode)
  const isManualTextMode =
    selectedSecondarySource?.key === 'manual' ||
    selectedSecondarySource?.key === 'translation-manual'
  const isLetterWriterMode = selectedAction === 'letterWriter'
  const isLetterWriterExpanded = isLetterWriterMode && Boolean(selectedLetterMode)
  const isLetterCreateMode = isLetterWriterMode && selectedLetterMode === 'ایجاد نامه'

  useEffect(() => {
    if (currenetHistory?.selectionMode !== 'rag') {
      return
    }

    setFileConversationContexts(previous =>
      previous[draftKey] !== undefined ? previous : { ...previous, [draftKey]: true },
    )
  }, [currenetHistory?.selectionMode, draftKey])

  const getSessionId = () => {
    if (currenetHistory?.historyId) {
      return currenetHistory.historyId
    }

    if (!sessionIdsRef.current[draftKey]) {
      sessionIdsRef.current[draftKey] = generateLongId()
    }

    return sessionIdsRef.current[draftKey]
  }

  const onSubmit = async () => {
    if (disableSubmit || !submitGuardRef.current.lock()) {
      return
    }

    setIsSending(true)

    if (selectedAction === 'excelYar') {
      try {
        let file = pendingFiles[0]

        if (!file && selectedSecondarySource && collectionId) {
          const extension = selectedSecondarySource.title.split('.').pop()?.toLowerCase() ?? ''
          if (!['csv', 'xls', 'xlsx'].includes(extension)) {
            throw new Error(t('chat-error-excel-file-type'))
          }

          const preview = await ChatAPIs().previewFile({
            collectionId,
            fileId: selectedSecondarySource.key,
            fileName: selectedSecondarySource.title,
            limit: 10_000,
            offset: 0,
          })

          if (preview.type === 'rows') {
            file = new File([csvFormat(preview.data)], selectedSecondarySource.title, {
              type: 'text/csv',
            })
          } else if (preview.type === 'text') {
            file = new File([preview.data], selectedSecondarySource.title, {
              type: preview.mimeType,
            })
          } else {
            const blob = await fetch(preview.objectUrl).then(response => response.blob())
            file = new File([blob], selectedSecondarySource.title, { type: preview.mimeType })
            URL.revokeObjectURL(preview.objectUrl)
          }
        }

        if (!file) {
          throw new Error(t('chat-error-excel-file-required'))
        }

        const extension = file.name.split('.').pop()?.toLowerCase() ?? ''
        const previewRows =
          extension === 'csv' ? csvParse(await file.text()).map(row => ({ ...row })) : []
        const response = await ExcelAssistantAPIs().uploadWorkbook(file)

        if (!response?.data?.workbookId) {
          throw new Error(t('chat-error-excel-workbook-id'))
        }

        setIsExcelTransitioning(true)
        await wait(EXCEL_TRANSITION_DELAY)
        navigate(`/excel-assistant/workbooks/${response.data.workbookId}`, {
          state: { fileName: file.name, previewRows },
        })
      } catch (error) {
        addAToast(error instanceof Error ? error.message : t('chat-error-file-upload'), 'error')
      } finally {
        submitGuardRef.current.unlock()
        setIsSending(false)
        setIsExcelTransitioning(false)
      }
      return
    }

    // create history (in a collection) => collectionId and historyId
    // chat with a history (in a collection) => collectionId but not historyId
    // create history (collection-less) => neither collectionId nor historyId
    // chat history (collection-less) => => not collectionId but historyId
    // changed

    const translationLanguages: Record<ITranslationLanguageItem['enName'], string> = {
      FA: 'Persian',
      EN: 'English',
      FR: 'French',
      AR: 'Arabic',
      RU: 'Russian',
      ZH: 'Chinese',
      HE: 'Hebrew',
    }
    const baseServiceMessage =
      selectedAction === 'translation'
        ? selectedTranslationLanguage
          ? translationLanguages[selectedTranslationLanguage.enName]
          : ''
        : selectedAction && EMPTY_SERVICE_MESSAGE_ACTIONS.has(selectedAction)
        ? ''
        : text
    const serviceMessage = baseServiceMessage
    const messageId = generateLongId()
    // Show newly-picked files on the message immediately (as pending
    // placeholders) instead of waiting for the upload response, so the
    // attached-files count/preview is correct without delay.
    const pendingAttachmentPlaceholders: IChatSessionFileUploadItem[] = pendingFiles.map(
      (file, index) => ({
        _id: `pending-${messageId}-${index}`,
        fileId: `pending-${messageId}-${index}`,
        filename: file.name,
        originalName: file.name,
        size: file.size,
        mimeType: file.type,
        state: 'pending',
        fullPath: '',
        uploadedAt: new Date().toISOString(),
      }),
    )
    const message = createMessage({
      id: messageId,
      ...getMessageTextFields(serviceMessage, text),
      attachments: [...historyAttachments, ...pendingAttachmentPlaceholders],
      messageType: payloadSelectionMode,
    })
    const selectedSourceFileId =
      selectedSecondarySource &&
      selectedSecondarySource.key !== 'manual' &&
      selectedSecondarySource.key !== 'translation-manual'
        ? selectedSecondarySource.key
        : null
    const payloadCollectionId =
      currenetHistory?.collectionId ?? currentCollection?.collectionId ?? null
    const persistentGeneralFileIds =
      payloadCollectionId === null
        ? getGeneralChatFileIds(currenetHistory?.files, historyMessages)
        : []
    const payload = {
      collectionId: payloadCollectionId,
      historyId: currenetHistory?.historyId ?? null,
      sessionId: getSessionId(),
      fileIds: getRequestFileIds({
        selectionMode: payloadSelectionMode,
        persistentGeneralFileIds,
        currentAttachmentIds: historyAttachments.map(item => item._id || item.fileId),
        selectedSourceFileId,
      }),
      ...(payloadSelectionMode && { selectionMode: payloadSelectionMode }),
      ...(selectedAction === 'translation' &&
        selectedTranslationLanguage && {
          translate: translationLanguages[selectedTranslationLanguage.enName].toLowerCase(),
        }),
      ...(selectedAction === 'letterWriter' &&
        selectedLetterMode && {
          letterOperation: LETTER_WRITER_OPERATION_VALUES[selectedLetterMode],
        }),
      answerStatus: CHAT_ANSWER_STATUS.PENDING,
      messageSchema: { message },
    }

    // The request failed (server down, network error, ...): the thunk has
    // already shown the error toast and removed the optimistic message, so put
    // the user's text back in the input where they can edit or resend it.
    const restoreFailedMessage = () => {
      saveFailedMessage(draftKey, text)
      setText(text)
      setDrafts(prev => ({ ...prev, [draftKey]: text }))
      requestAnimationFrame(() => {
        if (spanRef.current && spanRef.current.innerText !== text) {
          spanRef.current.innerText = text
        }
        const inputElement = isManualTextMode ? textAreaRef.current : spanRef.current
        inputElement?.focus()
      })
    }

    try {
      const result = await dispatch(aiChatAssistant({ payload, files: pendingFiles }))
      const succeeded = aiChatAssistant.fulfilled.match(result)
      setPendingFiles(files => pendingFilesAfterSubmit(files, succeeded))

      if (succeeded) {
        const nextRagContext = resolveRagContextAfterSend({
          sentMode: payloadSelectionMode,
          hadFileContext: hasRagContext,
          hasCurrentFileSelection: hasFileAttachment,
        })
        const responseHistoryId = result.payload.historyId
        setFileConversationContexts(prev => ({
          ...prev,
          [draftKey]: nextRagContext,
          ...(responseHistoryId && { [responseHistoryId]: nextRagContext }),
        }))
        setText('')
        clearFailedMessage(draftKey)
        setDrafts(prev => ({ ...prev, [draftKey]: '' }))
        setSelectedAction(null)
        setSelectedSecondarySource(null)
        setSelectedTranslationLanguage(null)
        setIsQuickActionsOpen(false)
        setIsSummarySourceOpen(false)
        setIsTranslationLangOpen(false)
        setIsTranslationSourceOpen(false)
        setIsLetterModelOpen(false)
        setSelectedLetterMode(null)
      } else {
        restoreFailedMessage()
      }
    } catch (error) {
      restoreFailedMessage()
      throw error
    } finally {
      submitGuardRef.current.unlock()
      setIsSending(false)
    }
  }

  const handleInput = () => {
    if (!spanRef.current) {
      return
    }

    let value = spanRef.current.innerText

    if (value === '\n') {
      value = ''
    }

    setText(value)
    setDrafts(prev => ({ ...prev, [draftKey]: value }))
    setIsQuickActionsOpen(value.includes('@'))
  }

  useEffect(() => {
    const handleShortcut = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === '2') {
        e.preventDefault()
        setIsQuickActionsOpen(true)
        setSelectedSecondarySource(null)
        if (isManualTextMode) {
          textAreaRef.current?.focus()
        } else {
          spanRef.current?.focus()
        }
      }
    }

    window.addEventListener('keydown', handleShortcut)

    return () => {
      window.removeEventListener('keydown', handleShortcut)
    }
  }, [isManualTextMode])

  const handleTextareaChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value
    setText(value)
    setDrafts(prev => ({ ...prev, [draftKey]: value }))
  }

  const handleManualTextBlur = () => {
    if (!text.trim() && isManualTextMode) {
      setSelectedSecondarySource(null)
    }
  }

  const handleRemoveAction = (action: TQuickAction) => {
    if (selectedAction !== action) {
      return
    }
    setSelectedAction(null)
    if (SERVICE_SELECTION_MODES[action]) {
      setIsSummarySourceOpen(false)
      setSelectedSecondarySource(null)
    }
    if (action === 'letterWriter') {
      setIsLetterModelOpen(false)
      setSelectedLetterMode(null)
    }
    if (action === 'translation') {
      setIsTranslationLangOpen(false)
      setIsTranslationSourceOpen(false)
      setSelectedTranslationLanguage(null)
    }
  }

  const handleBackspaceInContentInput = (e: React.KeyboardEvent<HTMLSpanElement>) => {
    if (e.key !== 'Backspace' || text.trim()) {
      return false
    }

    if (selectedSecondarySource) {
      e.preventDefault()
      setSelectedSecondarySource(null)
      return true
    }

    // Follow the visual order of the selected chips: remove a source file
    // before its action. Uploaded files are attachments, not secondary
    // sources, so they need the same Backspace behavior.
    if (pendingFiles.length > 0) {
      e.preventDefault()
      setPendingFiles(files => files.slice(0, -1))
      return true
    }

    if (historyAttachments.length > 0) {
      e.preventDefault()
      const lastAttachment = historyAttachments[historyAttachments.length - 1]
      dispatch(removeAttachment(lastAttachment.fileId || lastAttachment._id))
      return true
    }

    if (selectedAction) {
      e.preventDefault()
      handleRemoveAction(selectedAction)
      return true
    }
    setText('')
    return false
  }

  const handleBackspaceClearAllInTextarea = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    const hasSelectedActions = Boolean(selectedAction || selectedSecondarySource)
    const hasAttachment = historyAttachments.length > 0 || pendingFiles.length > 0
    const isTextEmpty = !text.trim()

    if (e.key !== 'Backspace' || !hasAttachment || !hasSelectedActions || !isTextEmpty) {
      return false
    }

    e.preventDefault()
    if (pendingFiles.length > 0) {
      setPendingFiles(files => files.slice(0, -1))
      return true
    }

    const lastAttachment = historyAttachments[historyAttachments.length - 1]
    dispatch(removeAttachment(lastAttachment.fileId || lastAttachment._id))
    return true
  }

  const handleKeyDown = (e: React.KeyboardEvent<HTMLSpanElement>) => {
    if (handleBackspaceInContentInput(e)) {
      return
    }

    if (e.key === '@') {
      setIsQuickActionsOpen(true)
    }

    if (e.key === 'Enter') {
      if (e.shiftKey) {
        return
      }
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault()
        setText(prev => prev + '\n')
        return
      }
      e.preventDefault()
      if (!disableSubmit) {
        onSubmit()
      }
    }
  }

  const handleTextareaKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (handleBackspaceClearAllInTextarea(e)) {
      return
    }

    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
      e.preventDefault()
      if (!disableSubmit) {
        onSubmit()
      }
    }
  }

  const handlePaste = (event: React.ClipboardEvent<HTMLSpanElement>) => {
    event.preventDefault()
    const plainText = event.clipboardData.getData('text/plain')

    // Insert the plain text manually at the caret
    document.execCommand('insertText', false, plainText)
  }

  const handleRemoveAttachment = (attachment = historyAttachments[0]) => {
    dispatch(removeAttachment(attachment?.fileId || attachment?._id))
    if (selectedAction === 'ocr') {
      setIsSummarySourceOpen(true)
    }
  }

  const handleRemovePendingFile = (index: number) => {
    setPendingFiles(files => files.filter((_, itemIndex) => itemIndex !== index))
    if (selectedAction === 'ocr') {
      setIsSummarySourceOpen(true)
    }
  }

  const handleRemoveSelectedSource = () => {
    setSelectedSecondarySource(null)
    if (selectedAction === 'ocr') {
      setIsSummarySourceOpen(true)
    }
  }

  const handleOpenExistingAttachment = async () => {
    if (isManualTextMode || isLetterCreateMode || (!canSelectMultipleFiles && hasSelectedFile)) {
      return
    }

    if (selectedAction === 'excelYar') {
      generalFileInputRef.current?.click()
      return
    }

    if (selectedAction === 'ocr') {
      generalFileInputRef.current?.click()
      return
    }

    if (selectedAction === 'reportGenerator') {
      generalFileInputRef.current?.click()
      return
    }

    if (selectedAction === 'stt') {
      generalFileInputRef.current?.click()
      return
    }

    if (!collectionId && currenetHistory?.historyId) {
      generalFileInputRef.current?.click()
      return
    }

    if (!collectionId && !currenetHistory?.historyId) {
      generalFileInputRef.current?.click()
      return
    }

    dispatch(
      setModalsState({ uploadFile: true, allowMultipleAttachments: canSelectMultipleFiles }),
    )

    if (collectionId) {
      await dispatch(getUploadFiles(collectionId))
    }
  }

  const handleSelectPendingFiles = (event: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = Array.from(event.target.files ?? []).map(normalizeUploadFile)

    if (selectedFiles.length === 0) {
      return
    }

    const filesToAdd = canSelectMultipleFiles ? selectedFiles : selectedFiles.slice(0, 1)
    const allowedExtensions =
      selectedAction === 'excelYar'
        ? ['csv', 'xls', 'xlsx']
        : selectedAction === 'ocr'
        ? [...OCR_FILE_EXTENSIONS, ...EXCEL_FILE_EXTENSIONS]
        : selectedAction === 'reportGenerator'
        ? ['csv', ...EXCEL_FILE_EXTENSIONS]
        : selectedAction === 'stt'
        ? [...STT_FILE_EXTENSIONS, ...EXCEL_FILE_EXTENSIONS]
        : ALLOWED_CHAT_FILE_EXTENSIONS
    const invalidFile = filesToAdd.find(file => {
      const extension = file.name.split('.').pop()?.toLowerCase() ?? ''
      return !allowedExtensions.includes(extension)
    })

    if (invalidFile) {
      addAToast(
        selectedAction === 'excelYar'
          ? `فرمت فایل «${invalidFile.name}» مجاز نیست. فرمت‌های مجاز: CSV، XLS و XLSX`
          : selectedAction === 'ocr'
          ? `فرمت فایل «${invalidFile.name}» برای OCR مجاز نیست. فرمت‌های مجاز: PNG، JPG، JPEG، PDF، XLS و XLSX`
          : selectedAction === 'reportGenerator'
          ? `فرمت فایل «${invalidFile.name}» برای گزارش ساز مجاز نیست. فرمت‌های مجاز: CSV، XLS و XLSX`
          : selectedAction === 'stt'
          ? `فرمت فایل «${invalidFile.name}» برای تبدیل صوت به متن مجاز نیست. فرمت‌های مجاز: MP3، WAV، OGG، M4A، WEBM، FLAC، XLS و XLSX`
          : `فرمت فایل «${invalidFile.name}» مجاز نیست. فرمت‌های مجاز: PDF، PNG، JPG، JPEG، TXT، CSV، PARQUET، XLS و XLSX`,
        'error',
      )
    } else {
      const duplicateFiles = filesToAdd.filter(file =>
        pendingFiles.some(item => item.name === file.name && item.size === file.size) ||
        historyAttachments.some(
          item =>
            (item.filename || item.originalName) === file.name &&
            (!item.size || item.size === file.size),
        ),
      )
      const uniqueFiles = filesToAdd.filter(file => !duplicateFiles.includes(file))

      if (duplicateFiles.length > 0) {
        addAToast('این فایل را قبلاً انتخاب یا اضافه کرده‌اید.', 'warning')
      }

      const oversizedFile = uniqueFiles.find(file => file.size > MAX_CHAT_FILE_SIZE)

      if (uniqueFiles.length === 0) {
        // All selected files were already present in this chat.
      } else if (oversizedFile) {
        addAToast(`حجم فایل «${oversizedFile.name}» بیشتر از ۱۰۰ مگابایت است.`, 'error')
      } else if (canSelectMultipleFiles && pendingFiles.length + uniqueFiles.length > MAX_FILES_PER_MESSAGE) {
        addAToast(t('chat-error-too-many-files'), 'error')
      } else {
        setPendingFiles(previous =>
          canSelectMultipleFiles ? [...previous, ...uniqueFiles] : uniqueFiles,
        )
      }
    }

    event.target.value = ''
  }

  const handleSelectAction = (action: TQuickAction) => {
    if (selectedAction !== action) {
      // Attachments belong to the active mode only; never carry them into a
      // different service by accident.
      dispatch(removeAttachment())
      setPendingFiles([])
      setSelectedSecondarySource(null)
    }
    setSelectedAction(action)
    setIsLetterModelOpen(action === 'letterWriter')
    if (action === 'letterWriter') {
      setSelectedLetterMode(null)
    }
    if (action === 'translation') {
      setIsSummarySourceOpen(false)
    }
    if (action !== 'translation') {
      setIsTranslationLangOpen(false)
    }
  }

  const handleSelectSecondarySource = (source: ISecondarySourceItem | null) => {
    if (
      isLetterCreateMode &&
      source &&
      source.key !== 'manual' &&
      source.key !== 'translation-manual'
    ) {
      return
    }
    if (
      source &&
      source.key !== 'manual' &&
      source.key !== 'translation-manual' &&
      (selectedSecondarySource?.key === source.key ||
        historyAttachments.some(
          attachment =>
            attachment.fileId === source.key ||
            attachment._id === source.key ||
            attachment.filename === source.title ||
            attachment.originalName === source.title,
        ) ||
        pendingFiles.some(file => file.name === source.title))
    ) {
      addAToast('این فایل را قبلاً انتخاب یا اضافه کرده‌اید.', 'warning')
      return
    }

    if (source && isFileChatMode) {
      if (historyAttachments.length >= MAX_FILES_PER_MESSAGE) {
        addAToast(t('chat-error-too-many-files'), 'error')
        return
      }

      dispatch(
        updateAttachment({
          _id: source.key,
          fileId: source.key,
          filename: source.title,
          originalName: source.title,
          size: 0,
          mimeType: '',
          state: 'done',
          fullPath: '',
          uploadedAt: new Date().toISOString(),
          scopeType: 'COLLECTION',
          collectionId,
        }),
      )
      return
    }

    setSelectedSecondarySource(source)
  }

  useEffect(() => {
    if (!quickActionRequest) {
      return
    }

    handleSelectAction(quickActionRequest.action)
    handleSelectSecondarySource({
      key: quickActionRequest.source.key,
      title: quickActionRequest.source.title,
      icon: getSelectedFileIcon(
        quickActionRequest.source.title,
        quickActionRequest.source.mimeType,
      ),
    })
    setIsQuickActionsOpen(false)
    setIsSummarySourceOpen(false)
    setIsTranslationLangOpen(quickActionRequest.action === 'translation')
    dispatch(clearQuickActionRequest())
  }, [quickActionRequest, dispatch])

  const handleInputFocus = (fromTextarea = false) => {
    if (fromTextarea && isManualTextMode) {
      return
    }

    if (selectedAction === 'translation' && selectedTranslationLanguage && !selectedSecondarySource) {
      setIsTranslationLangOpen(false)
      setIsTranslationSourceOpen(true)
      return
    }

    const shouldOpenSummarySource =
      selectedAction === 'summarizing' ||
      selectedAction === 'namedEntities' ||
      selectedAction === 'keywords' ||
      selectedAction === 'meetingMinutes' ||
      selectedAction === 'reportGenerator' ||
      isFileChatMode ||
      selectedAction === 'ocr' ||
      selectedAction === 'stt' ||
      selectedAction === 'reasoning' ||
      selectedAction === 'excelYar'

    const reportSourceIsSelected =
      selectedAction === 'reportGenerator' &&
      (Boolean(selectedSecondarySource) || historyAttachments.length > 0 || pendingFiles.length > 0)

    if (shouldOpenSummarySource && !isSummarySourceOpen && !reportSourceIsSelected) {
      setIsSummarySourceOpen(true)
    }
  }

  const handleInputAreaClick = () => {
    if (selectedAction === 'ocr' && !hasSelectedFile) {
      setIsSummarySourceOpen(true)
    }
  }

  const handleSelectTranslationLanguage = (lang: ITranslationLanguageItem) => {
    setSelectedTranslationLanguage(lang)

    if (!currenetHistory) {
      return
    }

    const translateMap: Record<ITranslationLanguageItem['enName'], CHAT_TRANSLATE_OPTIONS | null> =
      {
        FA: CHAT_TRANSLATE_OPTIONS.FARSI,
        EN: CHAT_TRANSLATE_OPTIONS.ENGLISH,
        FR: null,
        AR: null,
        RU: null,
        ZH: null,
        HE: null,
      }

    const selectedTranslateOption = translateMap[lang.enName]

    if (!selectedTranslateOption) {
      return
    }

    const updatedTranslate = currenetHistory.translate.includes(selectedTranslateOption)
      ? []
      : [selectedTranslateOption]

    dispatch(
      setSessionTranslation({
        historyId: currenetHistory.historyId,
        collectionId: currenetHistory.collectionId ?? undefined,
        data: { translate: updatedTranslate },
      }),
    )
  }

  const actionMeta: Record<TQuickAction, { label: string; icon: string }> = {
    summarizing: { label: t('chat-action-summarize'), icon: summarizing },
    translation: { label: t('chat-action-translate'), icon: chatTranslateSelectIcon },
    keywords: { label: t('chat-action-keywords'), icon: keywords },
    namedEntities: { label: t('chat-action-named-entities'), icon: newInfoIcon },
    meetingMinutes: { label: t('chat-action-meeting-minutes'), icon: meetingMinutes },
    reportGenerator: { label: t('chat-action-report-generator'), icon: exportIcon },
    letterWriter: { label: t('chat-action-letter-writer'), icon: letterWriterIcon },
    ocr: { label: t('chat-action-ocr'), icon: pictureIcon },
    reasoning: { label: t('chat-action-reasoning'), icon: reasoningSelectIcon },
    selectFile: { label: t('chat-action-chat-with-file'), icon: fileIcon },
    excelYar: { label: t('chat-action-excel-assistant'), icon: excelYarIcon },
    stt: { label: t('chat-action-stt'), icon: sttIcon },
  }

  const translationFileItems: ISecondarySourceItem[] = historyAttachments.map(item => ({
    key: item.fileId || item._id,
    title: item.filename || item.originalName,
    icon: getSelectedFileIcon(item.filename || item.originalName, item.mimeType),
  }))

  useEffect(() => {
    if (!isManualTextMode && spanRef.current && spanRef.current.innerText !== text) {
      spanRef.current.innerText = text
    }
  }, [text, isManualTextMode])

  useEffect(() => {
    if (selectedAction) {
      return
    }
    if (
      selectedSecondarySource?.key === 'manual' ||
      selectedSecondarySource?.key === 'translation-manual'
    ) {
      setSelectedSecondarySource(null)
    }
  }, [selectedAction, selectedSecondarySource])

  useEffect(() => {
    const lastKey = lastDraftKeyRef.current
    if (lastKey && lastKey !== draftKey) {
      setDrafts(prev => ({ ...prev, [lastKey]: text }))

      const isTemporaryDraft =
        lastKey === 'no-session' || lastKey.startsWith('collection:')
      if (isTemporaryDraft) {
        setFileConversationContexts(prev => {
          const context = prev[lastKey]
          if (context === undefined) {
            return prev
          }

          const next = { ...prev, [draftKey]: context }
          delete next[lastKey]
          return next
        })
      }
    }
    setText(drafts[draftKey] || loadFailedMessage(draftKey))
    lastDraftKeyRef.current = draftKey
  }, [draftKey])

  useEffect(() => {
    if (!currenetHistory?.historyId) {
      return
    }

    delete sessionIdsRef.current['no-session']

    if (currentCollection?.collectionId) {
      delete sessionIdsRef.current[`collection:${currentCollection.collectionId}`]
    }
  }, [currenetHistory?.historyId, currentCollection?.collectionId])

  useEffect(() => {
    if (modalsState.createCollection || modalsState.createCollectionSession) {
      return
    }
    if (!currenetHistory && !currentCollection) {
      if (isManualTextMode) {
        textAreaRef.current?.focus()
      } else {
        spanRef.current?.focus()
      }
    }
  }, [
    currenetHistory,
    currentCollection,
    isManualTextMode,
    modalsState.createCollection,
    modalsState.createCollectionSession,
  ])

  const isLocked =
    selectedAction !== 'selectFile' &&
    selectedAction !== 'excelYar' &&
    selectedAction !== 'reportGenerator' &&
    selectedAction !== 'letterWriter' &&
    selectedAction &&
    selectedSecondarySource

  useEffect(() => {
    if (isLocked && spanRef.current) {
      spanRef.current.innerText = ''
    }
  }, [isLocked])
  const pendingAttachmentChips =
    (historyAttachments.length > 0 || pendingFiles.length > 0 || hasSelectedSourceFile) && (
    <div className='chat-chatbox-pending-files'>
      {hasSelectedSourceFile && selectedSecondarySource && (
        <div className='chat-chatbox-reply'>
          <div className='chat-chatbox-reply-icon'>
            <img src={selectedSecondarySource.icon} alt='' />
          </div>
          <div className='chat-chatbox-reply-info'>
            <p className='chat-chatbox-reply-msg'>{selectedSecondarySource.title}</p>
          </div>
          <button
            type='button'
            className='chat-chatbox-reply-close'
            onClick={handleRemoveSelectedSource}
            disabled={isSending}
            aria-label={`حذف ${selectedSecondarySource.title}`}
          >
            <img src={closeIcon} alt='' />
          </button>
        </div>
      )}
      {historyAttachments.map(attachment => (
        <div className='chat-chatbox-reply' key={attachment.fileId || attachment._id}>
          <div className='chat-chatbox-reply-icon'>
            <img
              src={getSelectedFileIcon(
                attachment.filename || attachment.originalName,
                attachment.mimeType,
              )}
              alt=''
            />
          </div>
          <div className='chat-chatbox-reply-info'>
            <p className='chat-chatbox-reply-msg'>
              {attachment.filename || attachment.originalName}
            </p>
            <span className='chat-chatbox-reply-meta'>
              {[
                getFileExtension(attachment.filename || attachment.originalName),
                formatAttachmentSize(attachment.size),
              ]
                .filter(Boolean)
                .join(' · ')}
            </span>
          </div>
          <button
            type='button'
            className='chat-chatbox-reply-close'
            onClick={() => handleRemoveAttachment(attachment)}
            disabled={isSending}
            aria-label={`حذف ${attachment.filename || attachment.originalName}`}
          >
            <img src={closeIcon} alt='' />
          </button>
        </div>
      ))}
      {pendingFiles.map((file, index) => (
        <div className='chat-chatbox-reply' key={`${file.name}-${file.size}-${index}`}>
          <div className='chat-chatbox-reply-icon'>
            <img src={getSelectedFileIcon(file.name, file.type)} alt='' />
          </div>
          <div className='chat-chatbox-reply-info'>
            <p className='chat-chatbox-reply-msg'>{file.name}</p>
            <span className='chat-chatbox-reply-meta'>
              {getFileExtension(file.name)} · {formatAttachmentSize(file.size)}
            </span>
          </div>
          <button
            type='button'
            className='chat-chatbox-reply-close'
            onClick={() => handleRemovePendingFile(index)}
            disabled={isSending}
            aria-label={`حذف ${file.name}`}
          >
            <img src={closeIcon} alt='' />
          </button>
        </div>
      ))}
    </div>
  )
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  // const handleLetterSuggestion = (suggestion: string) => {
  //   setText(suggestion)
  //   setDrafts(prev => ({ ...prev, [draftKey]: suggestion }))
  //   requestAnimationFrame(() => spanRef.current?.focus())
  // }

  return (
    <div className={`chat-chatbox-input-box ${className ? className : ''}`.trim()}>
      {isExcelTransitioning && (
        <div className='excel-transition-loading' role='status' aria-live='polite'>
          <div className='excel-transition-loading__card'>
            <img src={excelYarIcon} alt='' />
            <div className='excel-transition-loading__spinner' />
            <strong>در حال ورود به اکسل یار...</strong>
            <span>فایل شما آماده شد؛ لطفاً چند لحظه صبر کنید.</span>
          </div>
        </div>
      )}
      {!currenetHistory && (
        <div className='chat-chatbox-input-title'>{t<string>('chat-input-title')}</div>
      )}

      {/* {isLetterWriterMode && (
        <div className='chat-letter-writer-suggestions'>
          {LETTER_WRITER_SUGGESTIONS.map(suggestion => (
            <button
              key={suggestion}
              type='button'
              onClick={() => handleLetterSuggestion(suggestion)}
            >
              {suggestion}
            </button>
          ))}
        </div>
      )} */}
      <div className='chat-chatbox-input-wrapper'>
        <div
          className={`chat-chatbox-input ${isManualTextMode ? 'chat-chatbox-input--manual' : ''} ${
            isLetterWriterMode ? 'chat-chatbox-input--letter-writer' : ''
          } ${
            isLetterWriterExpanded ? 'chat-chatbox-input--letter-writer-expanded' : ''
          }`.trim()}
        >
          {isLetterWriterMode && isLetterModelOpen && (
            <div className='chat-letter-writer-models' role='dialog' aria-label={t('chat-letter-writer-modes')}>
              {LETTER_WRITER_MODES.map(letterMode => (
                <button
                  key={letterMode}
                  type='button'
                  className={selectedLetterMode === letterMode ? 'is-selected' : ''}
                  onClick={() => {
                    setSelectedLetterMode(letterMode)
                    setIsLetterModelOpen(false)
                    if (letterMode === 'ایجاد نامه') {
                      setIsSummarySourceOpen(false)
                      setSelectedSecondarySource(null)
                      setPendingFiles([])
                      dispatch(removeAttachment())
                      requestAnimationFrame(() => spanRef.current?.focus())
                    } else {
                      setIsSummarySourceOpen(true)
                    }
                  }}
                >
                  {t(`chat-letter-mode-${LETTER_WRITER_OPERATION_VALUES[letterMode]}`)}
                </button>
              ))}
            </div>
          )}
          {/* input */}
          <div
            className={`chat-chatbox-input-content ${
              isManualTextMode ? 'chat-chatbox-input-content--manual' : ''
            }`}
          >
            <div
              className={`chat-chatbox-input-entry ${
                isManualTextMode ? 'chat-chatbox-input-entry--manual' : ''
              } ${isLetterWriterExpanded ? 'chat-chatbox-input-entry--letter-writer' : ''}`}
                onClick={handleInputAreaClick}
            >
              {isManualTextMode ? (
                <>
                  <textarea
                    className='chat-chatbox-input-text chat-chatbox-input-textarea'
                    placeholder={t('chat-manual-text-placeholder')}
                    dir='auto'
                    ref={textAreaRef}
                    value={text}
                    onChange={handleTextareaChange}
                    onKeyDown={handleTextareaKeyDown}
                    onFocus={() => handleInputFocus(true)}
                    onBlur={handleManualTextBlur}
                    tabIndex={1}
                  />
                  <div className='chat-chatbox-input-manual-bottom'>
                    <QuickActions
                      isOpen={isQuickActionsOpen}
                      setIsOpen={setIsQuickActionsOpen}
                      hasAtMention={text.includes('@')}
                      isSummarySourceOpen={isSummarySourceOpen}
                      setIsSummarySourceOpen={setIsSummarySourceOpen}
                      isTranslationLangOpen={isTranslationLangOpen}
                      setIsTranslationLangOpen={setIsTranslationLangOpen}
                      isTranslationSourceOpen={isTranslationSourceOpen}
                      setIsTranslationSourceOpen={setIsTranslationSourceOpen}
                      onSelectAction={handleSelectAction}
                      onSelectSecondarySource={handleSelectSecondarySource}
                      onSelectTranslationLanguage={handleSelectTranslationLanguage}
                      translationFileItems={translationFileItems}
                      onOpenAttachUpload={handleOpenExistingAttachment}
                      selectedAction={selectedAction}
                      isFileChatMode={isFileChatMode}
                      hasSelectedSecondarySource={Boolean(selectedSecondarySource)}
                      hasSelectedFile={hasSelectedFile}
                      selectedFileIds={historyAttachments.map(file => file.fileId || file._id)}
                      fileSelectionDisabled={isLetterCreateMode}
                    />
                    {(selectedAction || selectedSecondarySource || pendingAttachmentChips) && (
                      <div className='chat-chatbox-input-selected-actions'>
                        {selectedAction && (
                          <div className='chat-chatbox-input-selected-actions__chip'>
                            <img src={actionMeta[selectedAction].icon} />
                            <span style={{ width: 'max-content' }}>
                              {selectedAction === 'translation' && selectedTranslationLanguage
                                ? `${actionMeta[selectedAction].label} (${t(selectedTranslationLanguage.name)})`
                                : actionMeta[selectedAction].label}
                            </span>
                            <img
                              src={closeIcon}
                              onClick={() => handleRemoveAction(selectedAction)}
                            />
                          </div>
                        )}
                        {isLetterWriterMode && selectedLetterMode && (
                          <div className='chat-chatbox-input-selected-actions__chip'>
                            <img src={letterWriterIcon} />
                            <span style={{ width: 'max-content' }}>{selectedLetterMode}</span>
                            <img
                              src={closeIcon}
                              onClick={() => {
                                setSelectedLetterMode(null)
                                setSelectedSecondarySource(null)
                                setIsSummarySourceOpen(false)
                                setIsLetterModelOpen(true)
                              }}
                            />
                          </div>
                        )}
                        {pendingAttachmentChips}
                      </div>
                    )}
                  </div>
                </>
              ) : (
                <>
                  <QuickActions
                    isOpen={isQuickActionsOpen}
                    setIsOpen={setIsQuickActionsOpen}
                    hasAtMention={text.includes('@')}
                    isSummarySourceOpen={isSummarySourceOpen}
                    setIsSummarySourceOpen={setIsSummarySourceOpen}
                    isTranslationLangOpen={isTranslationLangOpen}
                    setIsTranslationLangOpen={setIsTranslationLangOpen}
                    isTranslationSourceOpen={isTranslationSourceOpen}
                    setIsTranslationSourceOpen={setIsTranslationSourceOpen}
                    onSelectAction={handleSelectAction}
                    onSelectSecondarySource={handleSelectSecondarySource}
                    onSelectTranslationLanguage={handleSelectTranslationLanguage}
                    translationFileItems={translationFileItems}
                    onOpenAttachUpload={handleOpenExistingAttachment}
                    selectedAction={selectedAction}
                    isFileChatMode={isFileChatMode}
                    hasSelectedSecondarySource={Boolean(selectedSecondarySource)}
                    hasSelectedFile={hasSelectedFile}
                    selectedFileIds={historyAttachments.map(file => file.fileId || file._id)}
                    fileSelectionDisabled={isLetterCreateMode}
                  />
                  {(selectedAction || selectedSecondarySource || pendingAttachmentChips) && (
                    <div className='chat-chatbox-input-selected-actions'>
                      {selectedAction && (
                        <div className='chat-chatbox-input-selected-actions__chip'>
                          <img src={actionMeta[selectedAction].icon} />
                          <span style={{ width: 'max-content' }}>
                            {selectedAction === 'translation' && selectedTranslationLanguage
                              ? `${actionMeta[selectedAction].label} (${t(selectedTranslationLanguage.name)})`
                              : actionMeta[selectedAction].label}
                          </span>
                          <img src={closeIcon} onClick={() => handleRemoveAction(selectedAction)} />
                        </div>
                      )}
                      {isLetterWriterMode && selectedLetterMode && (
                        <div className='chat-chatbox-input-selected-actions__chip'>
                          <img src={letterWriterIcon} />
                          <span style={{ width: 'max-content' }}>{selectedLetterMode}</span>
                          <img
                            src={closeIcon}
                            onClick={() => {
                              setSelectedLetterMode(null)
                              setSelectedSecondarySource(null)
                              setIsSummarySourceOpen(false)
                              setIsLetterModelOpen(true)
                            }}
                          />
                        </div>
                      )}
                      {pendingAttachmentChips}
                    </div>
                  )}
                  {selectedAction !== 'ocr' && (
                    <span
                    className='chat-chatbox-input-text'
                    role='textbox'
                    contentEditable={
                      selectedAction === 'selectFile' ||
                      selectedAction === 'excelYar' ||
                      selectedAction === 'reportGenerator' ||
                      selectedAction === 'letterWriter' ||
                      selectedAction === 'summarizing' ||
                      !(selectedAction || selectedSecondarySource)
                    }
                    data-placeholder={
                      isLetterWriterMode
                        ? t('chat-letter-writer-placeholder')
                        : t('chat-input-placeholder')
                    }
                    dir='auto'
                    ref={spanRef}
                    defaultValue={text}
                    onInput={handleInput}
                    onPaste={handlePaste}
                    onKeyDown={handleKeyDown}
                    onFocus={() => handleInputFocus(false)}
                    onClick={() => handleInputFocus(false)}
                    tabIndex={1}
                    ></span>
                  )}
                </>
              )}
            </div>
          </div>
          {/* footer */}
          <div className='chat-chatbox-footer'>
            {/* <div className='chat-chatbox-chat-count'>{text.length}/4000</div> */}
            {/* <div className='chat-chatbox-chat-actions'>
              <ReasoningIcon />
            </div> */}
            <AttachIcon
              onClick={handleOpenExistingAttachment}
              disabled={
                isSending ||
                isManualTextMode ||
                isLetterCreateMode ||
                (!canSelectMultipleFiles && hasSelectedFile)
              }
            />
            <input
              ref={generalFileInputRef}
              type='file'
              hidden
              accept={
                selectedAction === 'excelYar'
                  ? '.csv,.xls,.xlsx'
                  : selectedAction === 'ocr'
                  ? '.png,.jpg,.jpeg,.pdf,.xls,.xlsx'
                  : selectedAction === 'reportGenerator'
                  ? '.csv,.xls,.xlsx'
                  : selectedAction === 'stt'
                  ? [...STT_FILE_EXTENSIONS, ...EXCEL_FILE_EXTENSIONS]
                      .map(extension => `.${extension}`)
                      .join(',')
                  : '.csv,.txt,.png,.jpg,.jpeg,.pdf,.parquet,.xls,.xlsx'
              }
              multiple={canSelectMultipleFiles && selectedAction !== 'excelYar'}
              disabled={isSending}
              onChange={handleSelectPendingFiles}
            />
            <button
              className={`${
                mode === 'dark' ? 'chat-chatbox-submit-btn-dark' : 'chat-chatbox-submit-btn'
              }`}
              disabled={disableSubmit}
              data-testid='chat-submit-button'
              data-disabled={disableSubmit}
              aria-disabled={disableSubmit}
              onClick={onSubmit}
              aria-busy={isSending}
            />
          </div>
        </div>
      </div>
    </div>
  )
}

export default ChatInput
