import './style.scss'

import { useState } from 'react'

import Accordion from '@mui/material/Accordion'
import AccordionSummary from '@mui/material/AccordionSummary'
import AccordionDetails from '@mui/material/AccordionDetails'

import openIcon from 'src/assets/arrowUpnIcon.svg'
import closeIcon from 'src/assets/arrowDownnIcon.svg'

interface IProps<T> {
  title: string
  items: T[]
  renderItem: (item: T, index: number) => React.ReactNode
}

function FileManagerAccordion<T>({ title, items, renderItem }: IProps<T>) {
  const [expanded, setExpanded] = useState(true)

  const handleExpandAccordion = (_: React.SyntheticEvent, isExpanded: boolean) => {
    setExpanded(isExpanded)
  }

  return (
    <div className='file-manager-accordion'>
      <Accordion expanded={expanded} onChange={handleExpandAccordion}>
        <AccordionSummary expandIcon={null}>
          <div className='file-manager-accordion-summary'>
            <img
              className='file-manager-accordion-summary__icon'
              src={expanded ? openIcon : closeIcon}
              alt={expanded ? 'close' : 'open'}
            />
            <p className='file-manager-accordion-summary__title'>{title}</p>
          </div>
        </AccordionSummary>
        <AccordionDetails>
          <div className='file-manager-accordion-details'>
            {items.map((item, index) => renderItem(item, index))}
          </div>
        </AccordionDetails>
      </Accordion>
    </div>
  )
}

export default FileManagerAccordion
