import { useState, useCallback, useEffect } from 'react'
import { useSearchParams } from 'react-router-dom'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import {
  selectSidebarState,
  selectCollectionList,
  setSidebarState,
  selectTodaysHistoryList,
  setModalsState,
  selectCLHistoryList,
  clearCurrentState,
  selectCurrentCollection,
  selectCurrentHistory,
} from 'src/pages/Chat/slice'

const useSidebar = () => {
  const dispatch = useBDMDispatch()
  const [, setSearchParams] = useSearchParams()
  const isSidebarOpen = useBDMSelector(selectSidebarState).isOpen
  const collectionList = useBDMSelector(selectCollectionList)
  const todaysHistoryList = useBDMSelector(selectTodaysHistoryList)
  const CLHistoryList = useBDMSelector(selectCLHistoryList)
  const currentCollection = useBDMSelector(selectCurrentCollection)
  const currentHistory = useBDMSelector(selectCurrentHistory)

  const [menuAnchorEl, setMenuAnchorEl] = useState<HTMLElement | null>(null)
  const [menuIds, setMenuIds] = useState<{ collectionId?: string; historyId?: string }>({})

  const handleOpenSidebar = useCallback(() => {
    dispatch(setSidebarState({ isOpen: true }))
  }, [dispatch])

  const handleCloseSidebar = useCallback(() => {
    dispatch(setSidebarState({ isOpen: false }))
  }, [dispatch])

  const handleNewSession = useCallback(() => {
    // Do not wait for the chat-state synchronization effect while a history
    // restore is pending; the restore loader is keyed by these URL params.
    setSearchParams(params => {
      const nextParams = new URLSearchParams(params)
      nextParams.delete('historyId')
      nextParams.delete('collectionId')
      return nextParams
    })
    dispatch(clearCurrentState())
  }, [dispatch, setSearchParams])

  const handleNewCollection = useCallback(() => {
    dispatch(setModalsState({ createCollection: true }))
  }, [dispatch])

  const handleToggleSidebar = useCallback(() => {
    isSidebarOpen ? handleCloseSidebar() : handleOpenSidebar()
  }, [isSidebarOpen, handleCloseSidebar, handleOpenSidebar])

  const handleCloseMenu = () => {
    setMenuAnchorEl(null)
    setMenuIds({})
  }

  const handleOpenMenu = (
    e: React.MouseEvent<HTMLElement>,
    menuIds: { collectionId?: string; historyId?:  string },
  ) => {
    e.stopPropagation()
    e.preventDefault()

    if (menuAnchorEl && menuAnchorEl !== e.currentTarget) {
      setMenuAnchorEl(null)
      setMenuIds({})
      requestAnimationFrame(() => {
        setMenuAnchorEl(e.currentTarget)
        setMenuIds(menuIds)
      })
      return
    }

    setMenuAnchorEl(e.currentTarget)
    setMenuIds(menuIds)
  }

  useEffect(() => {
    if (!menuAnchorEl) {
      return
    }

    const handleMouseDown = (event: MouseEvent) => {
      const target = event.target as HTMLElement | null
      if (
        target?.closest(
          '.chat-sidebar-card-toggle, .chat-history-card-toggle, .chat-transfer-project-toggle',
        )
      ) {
        return
      }
      handleCloseMenu()
    }

    document.addEventListener('mousedown', handleMouseDown)
    return () => {
      document.removeEventListener('mousedown', handleMouseDown)
    }
  }, [menuAnchorEl])

  return {
    isSidebarOpen,
    collectionList,
    todaysHistoryList,
    CLHistoryList,
    handleCloseSidebar,
    handleNewSession,
    handleNewCollection,
    handleToggleSidebar,
    currentCollection,
    currentHistory,
    menuAnchorEl,
    handleCloseMenu,
    handleOpenMenu,
    menuIds,
  }
}

export default useSidebar
