type JwtPayload = Record<string, unknown>

const normalizePermission = (value: string) =>
  value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '')

const addStrings = (target: Set<string>, value: unknown) => {
  if (typeof value === 'string') {
    value
      .split(/[\s,]+/)
      .filter(Boolean)
      .forEach(item => target.add(normalizePermission(item)))
    return
  }

  if (Array.isArray(value)) {
    value.forEach(item => addStrings(target, item))
  }
}

const decodeBase64Url = (value: string) => {
  const base64 = value.replace(/-/g, '+').replace(/_/g, '/')
  const padded = base64.padEnd(Math.ceil(base64.length / 4) * 4, '=')
  const binary = window.atob(padded)
  const encodedBytes = Array.from(
    binary,
    character => `%${character.charCodeAt(0).toString(16).padStart(2, '0')}`,
  ).join('')

  return decodeURIComponent(encodedBytes)
}

export const decodeJwtPayload = (token?: string): JwtPayload | null => {
  if (!token) return null

  try {
    const [, payload] = token.split('.')
    if (!payload) return null

    const decoded = JSON.parse(decodeBase64Url(payload))
    return decoded && typeof decoded === 'object' ? decoded : null
  } catch {
    return null
  }
}

const getPermissionNames = (payload: JwtPayload | null) => {
  const names = new Set<string>()
  if (!payload) return names

  addStrings(names, payload.roles)
  addStrings(names, payload.scope)
  addStrings(names, payload.scopes)
  addStrings(names, payload.modules)
  addStrings(names, payload.applications)

  const realmAccess = payload.realm_access
  if (realmAccess && typeof realmAccess === 'object') {
    addStrings(names, (realmAccess as JwtPayload).roles)
  }

  const resourceAccess = payload.resource_access
  if (resourceAccess && typeof resourceAccess === 'object') {
    Object.entries(resourceAccess as JwtPayload).forEach(([resourceName, access]) => {
      if (!access || typeof access !== 'object') return

      const roles = (access as JwtPayload).roles
      if (Array.isArray(roles) && roles.length > 0) {
        addStrings(names, resourceName)
        addStrings(names, roles)
      }
    })
  }

  const authorization = payload.authorization
  const authorizationPermissions =
    authorization && typeof authorization === 'object'
      ? (authorization as JwtPayload).permissions
      : undefined
  const permissions = [payload.permissions, authorizationPermissions]

  permissions.forEach(permissionList => {
    if (!Array.isArray(permissionList)) return

    permissionList.forEach(permission => {
      if (typeof permission === 'string') {
        addStrings(names, permission)
        return
      }
      if (!permission || typeof permission !== 'object') return

      const item = permission as JwtPayload
      addStrings(names, item.rsname)
      addStrings(names, item.resource_name)
      addStrings(names, item.name)
      addStrings(names, item.scopes)
    })
  })

  return names
}

export type ModulePermission = 'lc' | 'label' | 'bdm' | 'etl' | 'dm' | 'fm'

const MODULE_PERMISSION_ALIASES: Record<ModulePermission, string[]> = {
  lc: ['lc', 'linkchart'],
  label: ['label', 'labeling', 'labelling', 'tagging', 'data-labeling'],
  bdm: ['bdm', 'bigdata', 'bigdataprocessing'],
  etl: ['etl', 'preprocessing', 'preprocess'],
  dm: ['dm', 'datamanagement', 'filemanagement'],
  fm: ['fm', 'formbuilder', 'formmaker'],
}

export const getModuleAccess = (token?: string): Record<ModulePermission, boolean> => {
  const permissions = getPermissionNames(decodeJwtPayload(token))

  return Object.entries(MODULE_PERMISSION_ALIASES).reduce((access, [module, aliases]) => {
    access[module as ModulePermission] = aliases.some(alias =>
      permissions.has(normalizePermission(alias)),
    )
    return access
  }, {} as Record<ModulePermission, boolean>)
}
