export enum AI_CHAT_MESSAGE_TYPES {
  TEXT = 'text',
  ANALYTICS = 'analytics',
  IMAGE = 'image',
  GIS = 'gis',
  FILE = 'file',
  VOICE = 'voice',
  LOADING = 'LOADING',
}

export enum AI_CHAT_SESSION_STATE {
  PENDING = 'pending',
  DONE = 'done',
  FAILURE = 'failure',
}

export type BDMChartTypes = 'barChart' | 'lineChart' | 'pieChart'

export interface IAIAnalyseData {
  data: Array<{
    label: string
    value: number
  }>
  label_title: string
  chart_title: string
  value_title: string
}

export interface IAIMessageReply {
  message?: string
  messageId?: string
  analyse: Array<BDMChartTypes>
  data: Array<IAIAnalyseData>
}

export interface IAIMessage {
  id: string
  unread: boolean
  type: AI_CHAT_MESSAGE_TYPES
  message: string
  bot: boolean // true means model's repsonse
  avatar: string
  liked: boolean
  disLiked: boolean
  starred: boolean
  createdAt: string
  attachments: Array<string>
  comment: string
  delivered: boolean
  reply: Array<IAIMessageReply>
}

export interface IAISession {
  user_name: string
  ai_session_name: string
  ai_session_id: number
  context_loaded_in_ai: boolean // default false
  state: AI_CHAT_SESSION_STATE
  createdAt: string
  updatedAt: string
  collectionName: string // {nodeName}_{node/edge id}_{ai_session_id}
  waiting?: boolean
  streamWaiting?: boolean
  isknowledgeGraph?: boolean
}
export interface IAIHistory extends IAISession {
  messages: Array<IAIMessage>
}
