const PARQUET_MIME_TYPE = 'application/vnd.apache.parquet'

/** Ensure Parquet uploads have a stable MIME type across browsers and operating systems. */
const normalizeUploadFile = (file: File): File => {
  if (!file.name.toLowerCase().endsWith('.parquet') || file.type === PARQUET_MIME_TYPE) {
    return file
  }

  return new File([file], file.name, {
    type: PARQUET_MIME_TYPE,
    lastModified: file.lastModified,
  })
}

export default normalizeUploadFile
