export interface IAgTableTextFilter {
  filterType: 'text'
  type:
  | 'contains'
  | 'notContains'
  | 'equals'
  | 'notEqual'
  | 'startsWith'
  | 'endsWith'
  | 'blank'
  | 'notBlank'
  | null
  filter: string
}

export interface IAgTableNumberFilter {
  filterType: 'number'
  type:
  | 'equals'
  | 'notEqual'
  | 'greaterThan'
  | 'greaterThanOrEqual'
  | 'lessThan'
  | 'lessThanOrEqual'
  | 'inRange'
  | 'blank'
  | 'notBlank'
  | null
  filter: number
  filterTo?: 15 // used for inRange type
}

export interface IAgTableDateFilter {
  filterType: 'number'
  type: 'equals' | 'notEqual' | 'lessThan' | 'greaterThan' | 'inRange' | 'blank' | 'notBlank' | null
  dateFrom: string // ex: "2024-06-10 00:00:00"
  dateTo: string | null // used for inRange type
}

