import './style.scss'

import ChatInstructions from '../ChatInstruction'
import ChatFileUpload from '../ChatFileUpload'

import { useBDMSelector } from 'src/lib/store/hooks'
import { selectCurrentCollection } from 'src/pages/Chat/slice'

const ChatOptions = () => {
  const currenetCollection = useBDMSelector(selectCurrentCollection)

  if (!currenetCollection) {
    return null
  }

  return (
    <div className='chat-chatbox-options'>
      <ChatInstructions />
      <ChatFileUpload />
    </div>
  )
}

export default ChatOptions
