import './style.scss'
import { t } from 'i18next'
import type { Ref } from 'react'
import { Trans } from 'react-i18next'
import Tooltip from '@mui/material/Tooltip'

interface IBDMFilterTextInput {
  id?: string
  value?: number | string
  type?: 'text' | 'number'
  onChange?: any
  onFocus?: any
  placeholder?: string
  label?: string
  className?: string
  autoComplete?: string
  disabled?: boolean
  onBlur?: (value: string) => void
  tooltip?: string
  required?: boolean
  min?: string
  max?: string
  step?: string
  dir?: string
  tabIndex?: number
  autoFocus?: boolean
  inputRef?: Ref<HTMLInputElement>
  icon?: string
}

const TextInput = (props: IBDMFilterTextInput) => {
  const {
    id,
    value,
    type = 'text',
    autoComplete = 'off',
    dir = 'auto',
    onFocus,
    onChange,
    placeholder,
    label,
    className,
    tooltip,
    min,
    max,
    step,
    required = false,
    onBlur,
    disabled,
    tabIndex,
    autoFocus,
    inputRef,
    icon,
    ...rest
  } = props

  return (
    <div className={`bdm-filter-text-input ${className ? className : ''}`.trim()}>
      {label && (
        <Tooltip title={tooltip ?? ''}>
          <label htmlFor={id} className='bdm-filter-text-input__label'>
            <Trans i18nKey={label} />
          </label>
        </Tooltip>
      )}
      <div
        className='bdm-filter-text-input__wrapper'
        onMouseDown={event => {
          if (!disabled && event.target !== event.currentTarget.querySelector('input')) {
            event.currentTarget.querySelector<HTMLInputElement>('input')?.focus()
          }
        }}
      >
        {
          icon ?
            <img src={icon} /> : null
        }
        <input
          {...rest}
          id={id}
          dir={dir}
          value={value}
          type={type}
          onInput={onFocus}
          onChange={onChange}
          placeholder={t<string>(placeholder ?? '')}
          autoComplete={autoComplete}
          className={`bdm-filter-text-input__input-box ${disabled ? ' input-disabled' : ''}`.trim()}
          disabled={disabled}
          required={required}
          onBlur={value => onBlur?.(value.target.value)}
          min={min}
          max={max}
          step={step}
          tabIndex={tabIndex}
          autoFocus={autoFocus}
          ref={inputRef}
        />
      </div>
    </div>
  )
}

export default TextInput
