import './style.scss'

import Skeleton from '@mui/material/Skeleton'

const SKELETON_MESSAGE_COUNT = 6

const MessageListSkeleton = () => {
  return (
    <div className='message-list-skeleton'>
      {[...Array(SKELETON_MESSAGE_COUNT)].map((_, idx) => (
        <Skeleton
          key={idx}
          variant='rectangular'
          className='message-list-skeleton__item'
          animation='wave'
        />
      ))}
    </div>
  )
}

export default MessageListSkeleton
