import { createSlice, PayloadAction } from '@reduxjs/toolkit'
import { GraphData, LinkObject, NodeObject } from 'react-force-graph-2d'
import {
  IChatFLSessionSummary,
  IChatFLMessage,
  IChatFLSessionDetail,
  ILanguageAssistantInActiveGraph,
  ILanguageAssistantActiveGraph,
} from 'src/types/ChatFL'
import { CHAT_MESSAGE_LIST_OFFSET } from 'src/lib/constants'

export interface ILanguageAssistantState {
  history: Array<IChatFLMessage> | null
  historyState: {
    initialized: boolean
    total: number // total messages
    hasMore: boolean // has more messages
    offset: number // start (index)
    limit: number // size
  }
  currentSession: IChatFLSessionDetail | null
  rawGraphList: Array<ILanguageAssistantInActiveGraph>
  rawActiveGraph: ILanguageAssistantActiveGraph | null
  activeGraph: GraphData | null // processed for graph module
  mouseLoc: { x: number; y: number }
  contextMenuState: { isOpen: boolean; node?: NodeObject | LinkObject }
  graphLayout: string | null
  stream: Record<number, [IChatFLMessage, IChatFLMessage]>
  responseWaitingSessions: Array<string>
  loadingState: {
    sessions: boolean
    history: boolean
    chatResponse: boolean
    chatStreaming: boolean
  }
  sidebarState: { isOpen: boolean }
  sessions: Array<IChatFLSessionSummary> | null
  // collections: IChatFLCollection[] | null
}

export const initialState: ILanguageAssistantState = {
  sessions: null,
  history: null,
  historyState: {
    initialized: false,
    total: 0,
    hasMore: true,
    offset: 0,
    limit: CHAT_MESSAGE_LIST_OFFSET,
  },
  currentSession: null,
  rawGraphList: [],
  rawActiveGraph: null,
  activeGraph: null,
  mouseLoc: { x: 0, y: 0 },
  contextMenuState: { isOpen: false, node: undefined },
  graphLayout: null,
  // stream related
  stream: {},
  sidebarState: {
    isOpen: false,
  },
  responseWaitingSessions: [],
  loadingState: {
    sessions: false,
    history: false,
    chatResponse: false,
    chatStreaming: false,
  },
}

export const chatFLSlice = createSlice({
  name: 'chatFL',
  initialState,
  reducers: {
    setSessions: (state, action: PayloadAction<Array<IChatFLSessionSummary>>) => {
      state.sessions = action.payload
    },
    setGraphList: (state, action: PayloadAction<Array<ILanguageAssistantInActiveGraph>>) => {
      state.rawGraphList = action.payload
    },
    setActiveGraph: (
      state,
      action: PayloadAction<{
        activeGraph: ILanguageAssistantState['activeGraph']
        rawActiveGraph?: ILanguageAssistantState['rawActiveGraph']
      }>,
    ) => {
      if (action.payload.rawActiveGraph) {
        state.rawActiveGraph = action.payload.rawActiveGraph
      }
      state.activeGraph = action.payload.activeGraph
    },
    setCurrentSession: (state, action: PayloadAction<IChatFLSessionDetail | null>) => {
      if (!action.payload || !state.sessions) {
        state.currentSession = null
        return
      }
      const foundSession =
        state.sessions.find(session => session.ai_session_id === action.payload?.ai_session_id) ??
        null

      if (!foundSession) {
        state.currentSession = null
        return
      }

      state.currentSession = action.payload
    },
    setHistory: (state, action: PayloadAction<Array<IChatFLMessage> | null>) => {
      state.history = action.payload
    },
    setMouseLoc: (state, action: PayloadAction<ILanguageAssistantState['mouseLoc']>) => {
      state.mouseLoc = action.payload
    },
    setContextMenuState: (
      state,
      action: PayloadAction<ILanguageAssistantState['contextMenuState']>,
    ) => {
      state.contextMenuState = action.payload
    },
    addMessage: (state, action: PayloadAction<IChatFLMessage>) => {
      state.history = [...(state.history || []), action.payload]
    },
    appendHistory: (state, action: PayloadAction<Array<IChatFLMessage>>) => {
      state.history = [...action.payload, ...(state.history ?? [])]
    },
    setStream: (state, action: PayloadAction<ILanguageAssistantState['stream']>) => {
      state.stream = action.payload
    },
    updateMessage: (state, action: PayloadAction<IChatFLMessage>) => {
      if (!state.history || state.history.length === 0) {
        state.history = [action.payload]
        return
      }

      const foundIdx = state.history.findIndex(msg => msg.id === action.payload.id)

      if (foundIdx === -1) {
        state.history.push(action.payload)
        return
      }

      state.history = state.history.map(msg =>
        msg.id === action.payload.id ? action.payload : msg,
      )
    },
    setSessionsLoadingState: (state, action: PayloadAction<boolean>) => {
      state.loadingState.sessions = action.payload
    },
    setHistoryLoadingState: (state, action: PayloadAction<boolean>) => {
      state.loadingState.history = action.payload
    },
    setChatResponseLoadingState: (state, action: PayloadAction<boolean>) => {
      state.loadingState.chatResponse = action.payload
    },
    setChaStreamingLoadingState: (state, action: PayloadAction<boolean>) => {
      state.loadingState.chatStreaming = action.payload
    },
    addSessionResponseWaiting: (state, action: PayloadAction<Array<string>>) => {
      const updateList = Array.from(new Set([...state.responseWaitingSessions, ...action.payload]))
      state.responseWaitingSessions = updateList
    },
    removeSessionResponseWaiting: (state, action: PayloadAction<Array<string>>) => {
      if (action.payload.length === 0) {
        return
      }
      action.payload.forEach(sessionId => {
        const idx = state.responseWaitingSessions.indexOf(sessionId)
        delete state.responseWaitingSessions[idx]
      })
    },
    updateGraphLayout: (
      state,
      action: PayloadAction<{
        graphData: ILanguageAssistantState['activeGraph']
        graphLayout: ILanguageAssistantState['graphLayout']
      }>,
    ) => {
      state.activeGraph = action.payload.graphData
      state.graphLayout = action.payload.graphLayout
    },
    setHistoryState: (state, action: PayloadAction<ILanguageAssistantState['historyState']>) => {
      state.historyState = action.payload
    },
    resetHistory: state => {
      state.history = null
      state.historyState = { initialized: false, total: 0, hasMore: true, offset: 0, limit: 0 }
    },
    resetStore: () => initialState,
  },
})

export const {
  setSessions,
  setCurrentSession,
  setHistory,
  setGraphList,
  setActiveGraph,
  setMouseLoc,
  setContextMenuState,
  updateMessage,
  addMessage,
  resetStore,
  setStream,
  setSessionsLoadingState,
  setHistoryLoadingState,
  setChatResponseLoadingState,
  setChaStreamingLoadingState,
  addSessionResponseWaiting,
  removeSessionResponseWaiting,
  updateGraphLayout,
  setHistoryState,
  resetHistory,
  appendHistory,
} = chatFLSlice.actions


export default chatFLSlice.reducer
