// style
import './style.scss'

// components
import Sidebar from './components/Siderbar'
import ChatHistoryScreen from './components/ChatHistoryScreen'
import ChatProjectScreen from './components/ChatProjectScreen'
import ChatRestoreLoader from './components/ChatRestoreLoader'

// utils
import gsap from 'gsap'
import { useEffect, useRef } from 'react'
import { useLocation } from 'react-router-dom'
import { useGSAP } from '@gsap/react'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import {
  selectBackgroundSettings,
  selectAppInitalized,
  selectCurrentHistory,
  selectLoadingState,
  selectSidebarState,
  setBackgroundSettings,
} from 'src/pages/Chat/slice'
import { RootState } from 'src/lib/store'
import ChatAPIs from 'src/api/chat'
import { changeAppLanguage } from 'src/lib/utils/i18n'
import { shouldShowChatRestoreLoading } from './chatRestoreLoading'


gsap.registerPlugin(useGSAP)

const ChatBox = () => {
  const dispatch = useBDMDispatch()
  const sidebarRef = useRef<HTMLDivElement | null>(null)
  const containerRef = useRef<HTMLDivElement | null>(null)
  const isSidebarOpen = useBDMSelector(selectSidebarState).isOpen
  const currentHistory = useBDMSelector(selectCurrentHistory)
  const appInitialized = useBDMSelector(selectAppInitalized)
  const messagesLoading = useBDMSelector(selectLoadingState).messages
  const backgroundSettings = useBDMSelector(selectBackgroundSettings)
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const location = useLocation()
  const requestedHistoryId = new URLSearchParams(location.search).get('historyId') ?? undefined
  const showRestoreLoading = shouldShowChatRestoreLoading({
    requestedHistoryId,
    appInitialized,
    messagesLoading,
    currentHistory,
  })
  useGSAP(
    () => {
      if (isSidebarOpen) {
        gsap.to(sidebarRef.current, {
          width: 270,
          autoAlpha: 1,
        })
      } else {
        gsap.to(sidebarRef.current, {
          width: 88,
          autoAlpha: 1,
        })
      }
    },
    {
      dependencies: [isSidebarOpen],
      scope: containerRef,
    },
  )
  useEffect(() => {
    const controller = new AbortController()

    const loadBackgroundSettings = async () => {
      try {
        const response = await ChatAPIs(controller.signal).getBackground()
        if (response.data.success && response.data.data) {
          const settings = response.data.data
          let image: string | null = null
          let enabled = settings.enabled

          if (settings.enabled) {
            image = await ChatAPIs(controller.signal).getBackgroundImage()

            if (!image && !controller.signal.aborted) {
              enabled = false

              // Repair the invalid server state so /background/image is not
              // requested and answered with 409 again on every page load.
              try {
                await ChatAPIs(controller.signal).updateBackground({
                  ...settings,
                  enabled: false,
                })
              } catch {
                // Keep the local empty state usable even if persistence fails.
              }
            }
          }

          dispatch(
            setBackgroundSettings({
              ...settings,
              enabled,
              image,
            }),
          )
        }
      } catch (error) {
        if (!controller.signal.aborted) {
          console.error('Failed to load chat background settings', error)
        }
      }
    }

    loadBackgroundSettings()
    return () => controller.abort()
  }, [dispatch])

  useEffect(() => {
    const controller = new AbortController()

    const loadSettings = async () => {
      try {
        const response = await ChatAPIs(controller.signal).getSettings()

        if (!response.data.success || !response.data.data) return

        const { fontSize, defaultLanguage } = response.data.data
        const fontScale = { small: '0.7', medium: '1', large: '1.4' }[fontSize]

        localStorage.setItem('chat-font-size', fontSize)
        document.documentElement.style.setProperty('--font-scale', fontScale)
        document.documentElement.dataset.fontSize = fontSize
        changeAppLanguage(defaultLanguage)
      } catch (error) {
        if (!controller.signal.aborted) {
          console.error('Failed to load settings', error)
        }
      }
    }

    loadSettings()
    return () => controller.abort()
  }, [])

  return (
    <div
      className={`chat-chatbox ${showRestoreLoading ? 'chat-chatbox--restoring' : ''} ${
        backgroundSettings.enabled && backgroundSettings.image
          ? 'chat-chatbox-new'
          : mode === 'light'
          ? 'chat-chatbox-default'
          : 'chat-chatbox-default-dark'
      }`}
      style={{
        backgroundImage:
          backgroundSettings.enabled && backgroundSettings.image
            ? `url("${backgroundSettings.image}")`
            : '',
        backgroundSize: backgroundSettings.fit === 'contain' ? 'contain' : backgroundSettings.fit === 'repeat' ? 'auto' : backgroundSettings.fit,
        backgroundRepeat: backgroundSettings.fit === 'repeat' ? 'repeat' : 'no-repeat',
        backgroundPosition: 'center',
        '--custom-chat-background-image':
          backgroundSettings.enabled && backgroundSettings.image
            ? `url("${backgroundSettings.image}")`
            : '',
        '--custom-chat-background-size': backgroundSettings.fit === 'contain' ? 'contain' : backgroundSettings.fit === 'repeat' ? 'auto' : backgroundSettings.fit,
        '--custom-chat-background-repeat': backgroundSettings.fit === 'repeat' ? 'repeat' : 'no-repeat',
        '--custom-chat-background-position': backgroundSettings.fit === 'center' ? 'center' : 'center',
        '--custom-chat-background-overlay': backgroundSettings.overlay === 'none' || backgroundSettings.overlay === 'removeColor' ? 'linear-gradient(transparent, transparent)' : backgroundSettings.overlay === 'gradient' ? 'linear-gradient(90deg, rgba(54, 133, 181, .4), rgba(79, 24, 75, .4))' : `linear-gradient(${backgroundSettings.overlay}, ${backgroundSettings.overlay})`,
        '--custom-chat-background-blur': backgroundSettings.blur ? '4px' : '0px',
        '--chat-custom-message-background': backgroundSettings.userMessageBackgroundColor,
        '--chat-custom-message-text': backgroundSettings.userMessageTextColor,
        height: '100vh',
        borderRadius: '0px',
      } as React.CSSProperties}
      ref={containerRef}
    >
      {showRestoreLoading ? (
        <ChatRestoreLoader />
      ) : currentHistory ? (
        <ChatHistoryScreen />
      ) : (
        <ChatProjectScreen />
      )}
      <Sidebar ref={sidebarRef} />
    </div>
  )
}

export default ChatBox
