import axiosWrapper, { getHeaders } from 'src/api'
import {
  ICreateOrEditDTI,
  ICreateOrEditDTO,
  IDeleteUserDTI,
  IDeleteUserDTO,
  IGetProfileDTO,
  IGetUserListDTO,
  ISetPasswordDTI,
  ISetPasswordDTO,
  IRestartSessionDTI,
  IMainDTO,
  IGetValidSessionsDTO,
} from 'src/types'
import { IGetTimeServerDTO } from 'src/types/NewChat/api'

const userAPIs = {
  getUserList: () => {
    return axiosWrapper<IGetUserListDTO>({
      method: 'GET',
      url: 'dashboard/get-users',
      headers: getHeaders(),
    })
  },
  getProfile: () => {
    return axiosWrapper<IGetProfileDTO>({
      url: `dashboard/get-profile`,
      method: 'GET',
      headers: getHeaders(),
    })
  },
  createOrEdit: (params: ICreateOrEditDTI) => {
    return axiosWrapper<ICreateOrEditDTO>({
      method: 'PUT',
      url: params.isEdit ? `dashboard/${params.data.id}/edit-user` : 'dashboard/create-user',
      headers: getHeaders(),
      data: params.data,
      hasToast: true,
    })
  },
  setPassword: (params: ISetPasswordDTI) => {
    return axiosWrapper<ISetPasswordDTO>({
      method: 'PUT',
      url: `dashboard/${params.userId}/set-new-password`,
      headers: getHeaders(),
      data: params.data,
    })
  },
  remove: (params: IDeleteUserDTI) => {
    return axiosWrapper<IDeleteUserDTO>({
      method: 'DELETE',
      url: `dashboard/${params.userId}/delete-user`,
      headers: getHeaders(),
    })
  },
  getValidSessions: () => {
    return axiosWrapper<IGetValidSessionsDTO>({
      method: 'POST',
      url: 'sessions/get-valid-sessions',
      headers: getHeaders(),
    })
  },
  restartSession: (params: IRestartSessionDTI) => {
    return axiosWrapper<IMainDTO>({
      method: 'POST',
      url: 'sessions/restart-session',
      headers: getHeaders(),
      data: params,
    })
  },
  getServerTime: () => {
    return axiosWrapper<IGetTimeServerDTO>({
      method: 'POST',
      url: 'time',
      headers: getHeaders(),
    })
  },
}

export default userAPIs
