import './style.scss'

import { MouseEvent } from 'react'
import { CHAT_HISTORY_STATE, IChatHistory } from 'src/types/NewChat'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import { selectCurrentHistory, setCurrentHistory } from 'src/pages/Chat/slice'
import LinearProgress from '@mui/material/LinearProgress'

// icons
import dotsMenuIcon from 'src/assets/dotsMenuIcon.svg'
import dotsMenuIconWhite from 'src/assets/dotsMenuIconWhite.svg'
import pinIconActive from 'src/assets/pinIconActive.svg'
import pinIconActiveWhite from 'src/assets/pinIconActiveWhite.svg'
import { RootState } from 'src/lib/store'

interface IProps {
  history: IChatHistory
  isMenuOpen?: boolean
  onNavigate?: () => void
  onOpenMenu: (
    e: MouseEvent<HTMLElement>,
    menuIds: { collectionId?: string; historyId?: string },
  ) => void
}


const HistoryCard = ({ onOpenMenu, history, isMenuOpen = false, onNavigate }: IProps) => {
  const dispatch = useBDMDispatch()
  const currentHistory = useBDMSelector(selectCurrentHistory)
  const mode = useBDMSelector((state: RootState) => state.theme.mode)
  const isSelected = Boolean(
    currentHistory &&
      [currentHistory.historyId, currentHistory.sessionId].some(
        id => id && [history.historyId, history.sessionId].includes(id),
      ),
  )
  // const isDone = history.state === CHAT_HISTORY_STATE.DONE
  const isFailure = history.state === CHAT_HISTORY_STATE.FAILURE
  const isPending = history.state === CHAT_HISTORY_STATE.PENDING
  const isPinned = Boolean(history.pinned ?? history.isPinned)

  const clss = `chat-chatbox-history-card ${isSelected ? 'is-selected' : ''} ${isMenuOpen ? 'is-menu-open' : ''
    } ${isPending ? 'is-pending' : ''
    } ${isFailure ? 'is-failure' : ''}`

  const handleSelectHistory = () => {
    dispatch(
      setCurrentHistory({
        historyId: history.historyId,
        collectionId: history.collectionId,
      }),
    )
    onNavigate?.()
  }

  const handleMenu = (e: MouseEvent<HTMLElement>) => {
    e.preventDefault()
    e.stopPropagation()

    onOpenMenu(e, {
      historyId: history.historyId ?? undefined,
      collectionId: history.collectionId ?? undefined,
    })
  }


  return (
    <>
      <div className={clss} onClick={handleSelectHistory} onContextMenu={handleMenu}>
        <div className='chat-chatbox-history-card__title'>
          <p>{history.historyName}</p>
          {isPinned && (
            <img
              className='chat-chatbox-history-card__pin-icon'
              src={mode === 'light' ? pinIconActive : pinIconActiveWhite}
              width={14}
              height={14}
              alt='سنجاق‌شده'
            />
          )}
        </div>

        <span className='chat-chatbox-history-card-menu-icon' onClick={handleMenu}>
          <img src={mode === 'light' ? dotsMenuIcon : dotsMenuIconWhite} width={16} height={16} alt='menu' loading='lazy' />
        </span>

        {isPending && (
          <div className='chat-chatbox-history-card-status'>
            <LinearProgress sx={{ height: '1px' }} color='inherit' />
          </div>
        )}
      </div>
    </>
  )
}

export default HistoryCard
