import './style.scss'
import { useEffect } from 'react'
import { useParams } from 'react-router-dom'
import { useBDMDispatch, useBDMSelector } from 'src/lib/store/hooks'
import { getModelsList, selectAIModels } from 'src/pages/Chat/slice'
import { useThemeSync } from 'src/shared/theme/useTheme'
import WorkbookUpload from './components/WorkbookUpload'
import WorkbookWorkspace from './components/WorkbookWorkspace'

const ExcelAssistant = () => {
  useThemeSync()
  const { workbookId } = useParams()
  const dispatch = useBDMDispatch()
  const models = useBDMSelector(selectAIModels) ?? []

  useEffect(() => {
    if (!models.length) {
      dispatch(getModelsList())
    }
  }, [dispatch, models.length])

  return workbookId ? <WorkbookWorkspace /> : <WorkbookUpload />
}

export default ExcelAssistant
